-- Généré par tools/fetch-wowhead-quests.py, ne pas éditer à la main.
-- Texte officiel des quêtes par locale (Wowhead, WoW Forever), clé = questID :
--   title, summary (texte d'objectif), desc (description longue), objectives (lignes).
-- Lu par Journal.lua (J:QuestView) quand le client ne fournit pas le texte. Rien n'est traduit.
local ADDON_NAME, AF = ...

AF.Data = AF.Data or {}
AF.Data.QuestText = {
  deDE = {
    [17] = { title = "Reagenzsuche in Uldaman", summary = "Bringt zwölf magenta Funguskappen nach Thelsamar zu Ghak Healtouch.", desc = "Ich habe von einer neu entdeckten Pflanze gehört, den magenta Funguskappen. Sie wachsen in Büscheln tief drinnen in der Uldaman-Grabungsstätte; vielleicht kann man sie auch anderswo finden, aber bisher ist das der einzige mir bekannte Ort, an dem sie gedeihen. Ich möchte ihren potenziellen Nutzen für die Alchimie erforschen und dafür brauche ich Euch.\n\nFindet die magenta Funguskappen-Büschel und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pflanzen stoßen vielleicht Giftsporen aus, wenn man sie anstößt.\n\nWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!", objectives = { "Magenta Funguskappe x 12" } },
    [65] = { title = "Die Bruderschaft der Defias", summary = "Gryan Stoutmantle möchte, dass Ihr in Seenhain mit Wiley sprecht.", desc = "Die Bruderschaft der Defias nennt sich die Bande von Schuften, von der die braven Leute von Westfall aus dem Land vertrieben werden. Ihr müsst für mich diese Bande bespitzeln. Wir müssen erfahren, wer der Kopf der Gruppe ist und wo sie ihr Versteck hat. In Seenhain findet Ihr im Gasthaus einen Schurken namens Wiley, der mir noch einen Gefallen schuldet.\n\nBegebt Euch nach Seenhain im Rotkammgebirge, östlich von Elwynn, und findet heraus, was Ihr könnt." },
    [132] = { title = "Die Bruderschaft der Defias", summary = "Bringt Wileys Nachricht nach Westfall zu Gryan Stoutmantle.", desc = "Was ich Euch jetzt erzähle, könnte mich das Leben kosten. Die Bande der Defias plant irgendwas Großes. Das Letzte, was ich gehört habe, war, dass sie mit unterschiedlichen Gnollen, Kobolden und sogar Goblins zusammenarbeiten.\n\nBringt Stoutmantle diese Nachricht. Darin steht alles, was ich zu dem Thema sagen kann." },
    [135] = { title = "Die Bruderschaft der Defias", summary = "Bringt Wileys Nachricht nach Stormwind zu Mathias Shaw.", desc = "Ich möchte zu gern wissen, was Wiley meinte, als er die Steinmetze erwähnte. Vielleicht ist ihm da nur etwas rausgerutscht. Könnten die Defias irgendwas mit den Steinmetzen zu tun haben? Nur ein Mann weiß das mit Sicherheit: Mathias Shaw, Kopf von SI:7. Zeigt ihm Wileys Nachricht und stellt fest, ob er noch etwas zu diesem immer verzwickter werdenden Rätsel beitragen kann. Falls Ihr Probleme habt, Shaw zu finden, seht in der Kaserne in der Altstadt nach." },
    [141] = { title = "Die Bruderschaft der Defias", summary = "Bringt Shaws Bericht nach Westfall zu Gryan Stoutmantle.", desc = "Die Gilde der Steinmetze wurde von einem Mann namens Edwin van Cleef geführt. Van Cleef war dafür verantwortlich, dass Stormwind wieder aufgebaut wurde, nachdem die Orcs es im Ersten Krieg dem Boden gleichgemacht hatten. Anscheinend waren van Cleef und seine Leute nicht zufrieden damit, wie der König sie behandelte, nachdem der Wiederaufbau vollendet war. Das könnte den einen oder anderen Sachverhalt erklären.\n\nIch habe Eurem Meister in Westfall einen ausführlicheren Bericht geschrieben. Bringt ihn sofort zu ihm!" },
    [142] = { title = "Die Bruderschaft der Defias", summary = "Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Stoutmantle.", desc = "Wir müssen herausfinden, wo genau sich das Versteck der Defias befindet. <Name>, meine Späher berichten mir, dass ein Bote der Defias auf der Straße zwischen Moonbrook, dem Goldküstensteinbruch und dem Jangoschacht gesehen worden ist. Ich möchte, dass Ihr ihn fangt. Wenn er Widerstand leistet, tötet ihn und bringt mir alles, was er bei sich trägt.", objectives = { "Eine mysteriöse Nachricht" } },
    [155] = { title = "Die Bruderschaft der Defias", summary = "Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Stoutmantle zurück.", desc = "Stoutmantle denkt also wirklich, ein <Volk> wie Ihr könne mich beschützen? Tja, Ihr werdet wohl reichen müssen. Bringt am besten ein paar Freunde mit.\n\nIhr wisst ja, wie's läuft, oder? Ihr haltet mir den Rücken frei und ich bringe Euch zum Versteck der Defias. Aber Ihr solltet besser in meiner Nähe bleiben, denn die Bande der Defias will jetzt meinen Kopf. Wenn die mich mit Euch sehen, werden sie versuchen, mich umzubringen.\n\nSagt mir einfach Bescheid, wenn Ihr und irgendwelche Freunde, die Ihr noch zusammentrommeln könnt, bereit seid loszuziehen.", objectives = { "Begleitet den Verräter der Defias, um herauszufinden, wo van Cleef sich versteckt hält." } },
    [166] = { title = "Die Bruderschaft der Defias", summary = "Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Stoutmantle.", desc = "Jetzt gibt es für Euch nur noch eine Aufgabe zu erledigen. Edwin van Cleef muss getötet werden. Zwar stimmt es mich traurig, einen Menschen zum Tode zu verurteilen, doch es ist zum Besten des Volkes von Westfall, wenn van Cleef ein für alle Mal aus dem Verkehr gezogen wird. Bringt mir den Kopf des Schurken, sobald die Tat getan ist.", objectives = { "Van Cleefs Kopf" } },
    [167] = { title = "Oh Bruder...", summary = "Bringt Großknecht Thistlenettles Forscherliga-Abzeichen nach Stormwind zu Wilder Thistlenettle.", desc = "Wir waren tief unten in einer großen Mine in Westfall, deren Eingang unter einer Scheune in Moonbrook versteckt lag. Keine Ahnung, wo dieses elende Diebesgesindel herkam. Egal, jedenfalls stürzte der Minentunnel über uns ein. Ich hab's nach draußen geschafft, aber die anderen ... na ja ... von den anderen hat seither niemand mehr etwas gehört.\n\nIhr seht aus, als könntet Ihr vielleicht etwas mehr Glück haben, wenn Ihr dort hineingeht. Wenn Ihr nach meinem Bruder suchen könntet, wäre ich Euch dankbar. Er trug immer sein Forscherliga-Abzeichen bei sich. Wenn Ihr ihn selbst nicht finden könnt, dann würde zumindest das Abzeichen mir etwas Seelenfrieden verschaffen.", objectives = { "Thistlenettles Abzeichen" } },
    [168] = { title = "Die Suche nach Andenken", summary = "Beschafft 4 Gewerkschaftsausweise und bringt sie nach Stormwind zu Wilder Thistlenettle.", desc = "Viele meiner Freunde starben an jenem schrecklichen Tag, als der Minentunnel einstürzte. Wenn Eure Abenteuer Euch in jenen Abschnitt der Mine in Moonbrook führen sollten, dann haltet doch bitte die Augen offen nach jedem Zeichen, anhand dessen man sie identifizieren könnte. Wenn Ihr zum Beispiel ihre Gewerkschaftsausweise finden solltet, so bringt sie mir, dann sehe ich zu, dass ihre Familien informiert werden und damit wenigstens eine Art Schlussstrich unter diesen schrecklichen Unfall ziehen können.", objectives = { "Gewerkschaftsausweis eines Minenarbeiters x 4" } },
    [214] = { title = "Rote Seidenkopftücher", summary = "Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt.", desc = "Es ist kein Geheimnis, dass das Markenzeichen der Defiasbande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass das Material, aus dem diese Kopftücher gemacht sind, den Rang des Bandenmitglieds bezeichnet.\n\nJetzt, wo wir das wissen, möchte ich, dass Ihr so viele hochrangige Mitglieder der Defias eliminiert, wie Ihr könnt. Die Bandenmitglieder mit der höchsten Position findet Ihr zweifellos in van Cleefs Geheimversteck. Wenn Ihr fertig seid, bringt mir 10 rote Seidenkopftücher zum Beweis, dass sie tot sind, dann werde ich Euch belohnen. Viel Glück, <Name>.", objectives = { "Rotes Seidenkopftuch x 10" } },
    [261] = { title = "Auf dem Scharlachroten Pfad", summary = "Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück.", desc = "Ich werde offen mit Euch sein. Wir sind im Krieg mit der Geißel. Sie ist ein Übel, das unser Volk verdirbt und unser Land infiziert. Sie muss aufgehalten werden, bevor sie uns übermannt und unsere Welt mit Schatten überzieht. Wir vom scharlachroten Kreuzzug haben geschworen, die Geißel mit Leib und Seele zu bekämpfen.\n\nWenn Ihr auf unserer Seite steht, dann nehmt Euren Mut zusammen und beweist Eure Zugehörigkeit - zerstört die untoten Verheerer von Desolace im südlich gelegenen Tal der Knochen.\n\nTut dies, und der Kreuzzug wird Euch mit offenen Armen aufnehmen.", objectives = { "Untoter Verheerer x 30" } },
    [303] = { title = "Der Dunkeleisenkrieg", summary = "Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet.", desc = "Der Krieg tobt daheim ebenso wie in der Fremde. Während mächtige Zwergenkrieger im Namen der Allianz in weit abgelegenen Gegenden ihr Leben lassen, fallen unsere eigenen Gebiete den bösen Taten der Dunkeleisenzwerge zum Opfer. Sie haben den Thandol-Übergang verwüstet. Dun Modr fiel kurz darauf.\n\nIhr müsst Kräfte sammeln und die Front zurückdrängen. Wenn Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge töten könnt, dann kommen die Reserven vielleicht rechtzeitig, um den Vormarsch zu beenden.\n\nUnd jetzt beeilt Euch!", objectives = { "Dunkeleisenzwerg x 15", "Tunnelgräber der Dunkeleisenzwerge x 5", "Saboteur der Dunkeleisenzwerge x 5", "Demolierer der Dunkeleisenzwerge x 5" } },
    [373] = { title = "Der nie verschickte Brief", summary = "Bringt den Brief nach Stormwind zum Stadtarchitekten Baros Alexston.", desc = "Als Ihr Edwin van Cleef durchsucht, findet Ihr unter anderem einen nie verschickten Brief. Er ist adressiert an \"Baros Alexston, Stadtarchitekt von Stormwind, Rathaus, Kathedralenplatz\".\n\nEr scheint erst vor kurzem geschrieben und versiegelt worden zu sein." },
    [377] = { title = "Verbrechen und Strafe", summary = "Ratsherr Millstipe von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt.", desc = "Als wäre die Vernachlässigung der Einwohner des Dämmerwalds nicht schlimm genug, nein, die jüngste Entscheidung des Oberhauses, Dextren Ward in Stormwind ins Gefängnis zu werfen, anstatt den Schurken - wie durch Lord Ebonlockes Urteil gefordert - zu enthaupten, ist ein Schlag ins Gesicht für den Rat von Dunkelhain.\n\nWard wurde dabei erwischt, wie er Leichen aus dem Friedhof an Morbent Fel verkaufte, ein Verbrechen, auf das der Tod steht. Und dennoch fordert Stormwind seine Gefangensetzung.\n\nErmordet Ward im Verlies von Stormwind - bringt mir seine Hand - und ich werde Euch belohnen.", objectives = { "Hand von Dextren Ward" } },
    [378] = { title = "Tief empfundener Zorn", summary = "Motley Garmason in Dun Modr verlangt Kam Deepfurys Kopf.", desc = "Ihr habt Eure Loyalität zu König Magni bewiesen, <Klasse>. Und Euer Hass auf den Dunkeleisenabschaum ist genau so groß wie mein eigener.\n\nEs gibt da eine Aufgabe, die ich selbst beenden möchte, aber ich bin durch meine Ehre verpflichtet, bei Longbraid zu bleiben. Jedoch hat Roggo Informationen gesammelt, die belegen, dass Kam Deepfury einer der Verschwörer beim Angriff auf den Thandol-Übergang war. Durch Deepfurys Pläne verlor Longbraid seine Sippe.\n\nDeepfury wird aus politischen Gründen im Verlies von Stormwind festgehalten. Ich will ihn tot sehen, <Name>. Für Longbraid! Bringt mir seinen Kopf!", objectives = { "Deepfurys Kopf" } },
    [386] = { title = "Verbrechen lohnt sich nicht", summary = "Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen.", desc = "Targorr der Schreckliche diente als oberster Exekutor unter Gath'llzogg. Er ging grausam vor, selbst nach den Standards der dreckigen Orcs. Menschen, die tapfer gekämpft hatten, um das Königreich zu verteidigen, wurden nur zu seiner Belustigung gefoltert. Heute wird er im Verlies von Stormwind gefangen gehalten und wurde zum Tode verurteilt. Dennoch stimmt irgendetwas nicht. Einer dieser bürokratischen Adeligen hat seine Exekution ausgesetzt. Ich bin mir sicher, hier wird eine Schandtat geplant.\n\nMacht Targorr dem Schrecklichen ein Ende, <Name>. Reist zum Verlies und enthauptet ihn, bevor man uns überlistet.", objectives = { "Targorrs Kopf" } },
    [387] = { title = "Niederschlagung des Aufstandes", summary = "Aufseher Thelwater aus Stormwind will, dass Ihr im Verlies 10 gefangene Defias, 8 eingekerkerte Defias und 8 Aufrührer der Defias tötet.", desc = "Der Aufstand muss niedergeschlagen werden! Ich brauche Eure Hilfe. Wenn jemand mitbekommt, dass das Gefängnis überrannt wurde, verliere ich meinen Job! Solch übles Spiel habe ich noch nie erlebt. Aber was jetzt zählt ist, die Gefangenen zur Sicherheit Stormwinds niederzuringen.\n\nDie Strafe für Auflehnung lautet Tod. Tötet einige dieser Abweichler! Das sollte die Angelegenheit wieder unter Kontrolle bringen.", objectives = { "Gefangener Defias x 10", "Eingekerkerter Defias x 8", "Aufrührer der Defias x 8" } },
    [388] = { title = "Die Farbe von Blut", summary = "Nikova Raskol von Stormwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt.", desc = "Verbitterung fließt wie ein kalter Fluss durch meine Adern. Mein Enkel, Mac, war so ein guter Junge. Gerade mal 14 Jahre alt. Als die Armee an die Front geschickt wurde, griff Mac zu den Waffen, um die Stadt zu verteidigen. Er war eine Wache im Verlies, wo diese elenden Defias eingesperrt sind. Mac wies ein paar der Gefangenen dafür zurecht, dass sie ihre Wolldecken zerrissen, um Schals daraus zu machen, die ein Symbol ihrer Bande darstellen. Dafür wurde Mac hinterhältig erstochen.\n\nIch will Rache. Bringt mir 10 ihrer kostbaren Wollkopftücher. Sie haben die Farbe von Blut.", objectives = { "Rotes Wollkopftuch x 10" } },
    [389] = { title = "Bazil Thredd", summary = "Sprecht mit Aufseher Thelwater im Verlies.", desc = "Van Cleef und ich waren beide Mitglieder der Steinmetzgilde. Unser Hauptprojekt war der Wiederaufbau Stormwinds nach dem Krieg.\n\nAls wir unsere Aufgabe erfüllt hatten, wurden wir betrogen. Die Adligen verweigerten uns die Bezahlung für unsere Arbeit. Einigen der älteren Steinmetze wurden Posten in der Regierung angeboten, aber van Cleef lehnte aus Loyalität zu den übrigen Steinmetzen ab. Er führte eine Revolte an und verließ, Rache schwörend, die Stadt.\n\nSein Helfer, Bazil Thredd, könnte vielleicht mehr über van Cleefs Pläne wissen. Er wird im Verlies gefangen gehalten." },
    [391] = { title = "Aufstand im Verlies", summary = "Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwater im Verlies.", desc = "Lasst uns eine Sache klarstellen, <Name>: Ich traue Euch nicht. Aber wie die Sache im Moment aussieht, werdet Ihr ohnehin keinen Unterschied machen.\n\nAlso wird das folgendermaßen ablaufen: Geht da runter und redet mit Thredd. Wenn Ihr wirklich auf unserer Seite seid, dann eliminiert ihn und bringt mir seinen Kopf, wenn Ihr fertig seid. Und falls sich herausstellt, dass Ihr auf seiner Seite seid und nicht herauskommt... werdet Ihr zusammen mit dem Rest dieser Würmer sterben, wenn wir Euch finden.", objectives = { "Kopf von Bazil Thredd" } },
    [704] = { title = "Agmonds Schicksal", summary = "Bringt Ausgrabungsleiter Ironband am Loch Modan 4 verzierte Steinurnen.", desc = "Der letzte Bericht, den ich von Agmond erhalten habe, ist sehr beunruhigend, umso mehr, da er jetzt tot ist! Er erwähnte, dass seine Buddler an der Grabungsstätte vor Uldaman \"uralte Urnen\" entdeckt hätten. Ich fürchte, dass die dort gefundenen Urnen die Troggs erzürnt haben, ebenso wie die Götzen, die ich dort fand.\n\nIch möchte, dass Ihr uns die Urnen bringt, damit wir sie untersuchen können. Geht zur Grabungsstätte Uldaman, sammelt die Urnen ein und kehrt dann zu mir zurück.", objectives = { "Verzierte Steinurne x 4" } },
    [707] = { title = "Ironband sucht Euch!", summary = "Sprecht auf Ironbands Ausgrabungsstätte am Loch Modan mit Ausgrabungsleiter Ironband.", desc = "<Name>. Ich habe Berichte von Ausgrabungsleiter Ironband von der Ausgrabungsstätte am Loch Modan erhalten - er braucht jemanden, der ihm die Rennerei auf einer unserer anderen Ausgrabungen abnimmt.\n\nIch habe keine weiteren Details, aber wenn Ihr Euch ein bisschen die Füße vertreten wollt, dann sprecht mit Ironband." },
    [709] = { title = "Lösung der Verdammnis", summary = "Bringt Theldurin dem Verirrten die Schrifttafel von Ryun'eh.", desc = "Oh je! Oh je! Unheil naht! Hört auf mich! Unheil!\n\nNein, ich darf nicht darüber sprechen... darf nicht ihre Namen aussprechen, sie könnten mich hören! Aber wenn wir mehr über sie lernen, ja, mehr... dann könnten wir vielleicht lernen, wie man sie aufhalten kann!\n\nVielleicht.\n\nGeht nach Uldaman. Nein! Ich hab's gesagt! Ihr müsst... die Schrifttafel von... Ryun'eh finden. Ja, findet sie! Und bringt mich nicht dazu, diesen Namen noch einmal auszusprechen!\n\nSie ist verborgen an diesem Ort, in einer uralten Truhe. Da ist sie versteckt... in einer Truhe, die gefertigt wurde, lang bevor Zwerge solche Werke vollbrachten.", objectives = { "Schrifttafel von Ryun'eh" } },
    [720] = { title = "Ein Hoffnungsschimmer", summary = "Sucht Ausgrabungsleiter Ryedol und teilt ihm mit, dass Hammertoe Grez noch am Leben ist.", desc = "<Text wurde mit Kreide auf die Karte gekritzelt.>\n\n\"Ryedol,\nSie bringen mich nach Uldaman. Schickt Hilfe.\n- Hammertoe\"" },
    [721] = { title = "Ein Hoffnungsschimmer", summary = "Sucht in Uldaman nach Hammertoe Grez.", desc = "<Name>, geht Ihr ihn suchen? Sucht Ihr Hammertoe in Uldaman?\n\nWenn diese dreckigen Zwerge der Schattenschmiede ihn als Geisel genommen haben, um herauszubekommen, was er über die Titanenausgrabungen weiß, könnte ganz Ironforge in großer Gefahr sein.\n\nSeit langer Zeit schon trachten die Dunkeleisenzwerge nach Magie, um noch mächtigere Golems zu erschaffen. Hammertoe hatte dasselbe vor, aber natürlich nur, um sie aufzuhalten.\n\nVielleicht lassen sie ihn am Leben, bis sie herausbekommen haben, was er weiß; Ihr müsst Euch beeilen, wenn Ihr ihn retten wollt!" },
    [722] = { title = "Amulett der Geheimnisse", summary = "Sucht Hammertoes Amulett und bringt es ihm nach Uldaman.", desc = "Ihr seid mutig... (((hustet))) dass Ihr Euch wegen mir nach Uldaman wagt, <Klasse>.\n\nWenn Ihr wirklich hier seid, um dem... ollen Hammertoe zu helfen, dann... (((hustet)))... müsst Ihr nach... meinem Amulett suchen.\n\nGrubenschatten hat es... Magregan Grubenschatten. Muss hier irgendwo sein... in den Ruinen, das ist sicher. Das Amulett wird sie... (((hustet)))... genau zu den Rollen führen, wenn sie keiner aufhält. Es ist an Euch, <Name>. Bitte... holt das Amulett.\n\nDie Rollen werden es den Dunkeleisenzwergen ermöglichen, noch mächtigere Golems zu erschaffen. Ich weiß es einfach. Spür's in meinen Knochen.", objectives = { "Hammertoes Amulett" } },
    [723] = { title = "Ein Funken Hoffnung", summary = "Bringt Ausgrabungsleiter Ryedol im Ödland Hammertoes Amulett.", desc = "<Hammertoe fasst an seine Wunden und braucht einen Moment, um sich zu sammeln, bevor er weiterspricht.>\n\nFindet Ryedol, <Name>. Bringt ihm mein Amulett. <hustet> Er... <hustet>... wird wissen, was zu tun ist; er weiß, dass ich nach den Wurzeln unseres Volks suchte, und er... <hustet>... weiß, dass es meine Aufgabe war, den Schattenschmiedeklan aufzuhalten. Sie dürfen die Rollen nicht finden... <hustet>" },
    [724] = { title = "Ein Funken Hoffnung", summary = "Bringt Historiker Karnik in Ironforge Hammertoes Amulett.", desc = "Okay, okay... Wer könnte wissen, was zu tun ist?\n\nHistoriker Karnik! Genau!\n\nEr lebt in Ironforge. Er kann helfen. Er und Hammertoe haben zusammengearbeitet, um in Uldaman nach den verschollenen Artefakten zu suchen.\n\nSchätze, die Zwerge der Schattenschmiede haben rausgefunden, dass die beiden mehr wussten, als sie sagten.\n\nErzählt Karnik, was mit Hammertoe geschehen ist, und gebt ihm das Amulett - er wird Euch dann sagen, was als Nächstes zu tun ist." },
    [725] = { title = "Kunde über die Bedrohung breitet sich aus", summary = "Sucht Berater Belgrum und gebt ihm die Notiz.", desc = "<Name>, lauft los und findet so schnell wie möglich Berater Belgrum; sagt ihm, was Ihr gesehen habt, und fragt ihn, wie wir weiter vorgehen sollen. Diese Notiz wird ihm alles Weitere erklären.\n\nIn der Zwischenzeit werde ich mir die Zeit nehmen, um mit Hammertoes Geist zu sprechen. Vielleicht weiß er etwas, das uns helfen könnte, die Aktivitäten der Zwerge der Schattenschmiede hier im Ödland zu unterbinden. Wir können nur beten." },
    [726] = { title = "Kunde über die Bedrohung breitet sich aus", summary = "Sprecht mit Historiker Karnik.", desc = "<Berater Belgrum erreicht das Ende der Notiz und für einen Moment weiten sich seine Augen.>\n\nAch, das sind schlimme Nachrichten.\n\n<Name>, bitte kehrt zu Historiker Karnik zurück und sagt ihm, dass er im Auftrag des Königs schnell und entschlossen gemäß dieser Information handeln soll. Er muss die Aktivitäten der Zwerge der Schattenschmiede im Ödland unterbinden." },
    [738] = { title = "Sucht Agmond", summary = "Sucht Agmond.", desc = "Ausgrabungsleiter Agmond hatte die Verantwortung über unsere Ausgrabungsstätten im Ödland, im Südwesten. Ich sagte \"hatte\", weil... also, ich habe schon seit Wochen nichts mehr von ihm gehört. Ich möchte, dass Ihr Agmond sucht, damit er mir Bericht erstatten kann.\n\nZuletzt hörte ich, dass sich Agmond in der südlichsten Grabungsstätte im Ödland aufhalten würde - einer winzigen Unternehmung hinter der Festung Angor. Ich würde dort mit der Suche beginnen." },
    [739] = { title = "Murdaloc", summary = "Tötet Agmonds Mörder Murdaloc. Tötet 12 Knochenknacker der Steingrufttroggs. Erstattet Ausgrabungsleiter Ironband am Loch Modan Bericht.", desc = "Agmonds Spuren führen nach Westen. Anhand der Blutspuren auf den Felsen und im Sand ist unschwer zu erraten, dass sich der Zwerg ein ganzes Stück weit geschleppt haben muss.\n\nUnd hier ist er dann gestorben.\n\nBei näherer Betrachtung ist das Wort \"Murdaloc\" erkennbar, das grob aus Sandsteinen des Ödlands zusammengestückelt wurde.\n\nDirekt neben Agmonds toter Hand.", objectives = { "Murdaloc", "Knochenknacker der Steingrufttroggs x 12" } },
    [762] = { title = "Ein Botschafter des Bösen", summary = "Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Ironforge einen Beweis seines Tod.", desc = "Ragnaros persönlich schickte den Gesandten Infernus zur Festung Angor, damit er dort die Suche der Zwerge der Schattenschmiede nach in Uldaman verschollenen Artefakten organisiert.\n\nUnser Volk hat bereits einen enormen Verlust erlitten, aber in letzter Zeit hat sich die Lage offensichtlich noch verschlimmert. Ich wage kaum zu schätzen, wie viele Artefakte sie finden und gegen Ironforge einsetzen könnten.\n\nUnser Ziel ist einfach, <Klasse>. Kehrt ins Ödland zurück und beseitigt den Botschafter Infernus. Sobald die Bedrohung aus der Welt geschafft ist, kehrt mit einem Beweis Eures Sieges zu Berater Belgrum zurück.\n\nEs liegt jetzt in Euren Händen.", objectives = { "Botschafter Infernus' Armschienen" } },
    [865] = { title = "Raptorhörner", summary = "Sammelt 5 intakte Raptorhörner von Bluthornsensenklauen und bringt sie Mebok Mizzyrix in Ratchet.", desc = "Die Raptoren des Brachlandes sind intelligenter als die Raptoren anderer Länder. Und ich glaube, dass ihre ganze Intelligenz in ihren Hörnern sitzt! Wenn dem so ist, könnte ich ihre Hörner zu Pulver zermahlen und benutzen, um \"Klugheitstränke\" zu kreieren. Dafür würde ich ein Vermögen bekommen!\n\nUnd Ihr könntet mir helfen; sucht und bringt mir intakte Raptorhörner von Bluthornsensenklauen. Sie durchstreifen den Süden sowie den Norden des Brachlandes an der Grenze zum Wald von Ashenvale.", objectives = { "Intaktes Raptorhorn x 5" } },
    [870] = { title = "Die vergessenen Teiche", summary = "Berichtet Tonga Runetotem von Euren Entdeckungen. -", desc = "Vor langer Zeit war das Brachland ein üppiger Ort voller Leben. Aber Krieg und Katastrophen verheerten das Land, verbrannten es und jetzt ist es nur noch eine ausgedörrte Hülse. So ist es nun einmal und es macht mich traurig.\n\nIn den letzten Jahren jedoch sind Oasen im Brachland entstanden und das Leben blüht wieder auf. Und wir Druiden spüren eine Macht von ganz tief unten an die Oberfläche dringen.\n\nWir müssen ihre Quelle finden. Reist zu den vergessenen Teichen nordwestlich von Crossroads. Sucht in den dortigen Gewässern nach einer Quelle der Macht und kommt dann hierher zurück.", objectives = { "Erkundet die Wasser der vergessenen Teiche." } },
    [877] = { title = "Die brackige Oase", summary = "Kehrt zu Tonga in Crossroads zurück, nachdem Ihr die brackige Oase untersucht habt.", desc = "Erdrisse wie jene, die Ihr bei den vergessenen Teichen gefunden habt, könnte es auch bei anderen Oasen im Brachland geben. Wenn es so ist, sind diese Risse vielleicht die Lebensquelle dieser Oasen.\n\nWir müssen das überprüfen.\n\nHier, nehmt diese Samen. Sie sind tot und unfruchtbar, aber bringt sie dennoch zur brackigen Oase im Südosten. Falls es dort einen Riss gibt, legt die Samen hinein und ... wartet ab.", objectives = { "Probiert die getrockneten Samenkörner aus.", "Rezept: Milde Schildkrötensuppe" } },
    [880] = { title = "Veränderte Wesen", summary = "Bringt Tonga Runetotem in Crossroads 8 veränderte Schnappkieferschalen.", desc = "Eure Entdeckungen sind erstaunlich, <Name>. Diese Oasen haben Eigenschaften, die von einer Quelle außerhalb stammen müssen. Oder vielleicht von einer inwärtigen.\n\nIch muss wissen, auf welche Weise diese Felsspalten die Wildtiere beeinflussen, die vom Wasser der Oasen trinken.\n\nJagt Oasen-Schnappkiefer in der blühenden Oase und der brackigen Oase. Bringt mir ihre Schalen, damit ich sie untersuchen kann.", objectives = { "Veränderte Schnappkieferschale x 8" } },
    [914] = { title = "Anführer der Giftzähne", summary = "Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Thunder Bluff zu Nara Wildmane.", desc = "Die Druiden in den Höhlen des Wehklagens, die Druiden des Giftzahns, sind eine Verirrung der Natur. Einst gehörten sie einem Orden edler Druiden an, deren Plan es war, das Brachland zu heilen, doch jetzt trachten sie danach, das Land ihren eigenen verderbten Träumen gleichzumachen.\n\nDie Druiden des Giftzahns haben vier Anführer, und jeder besitzt einen Traumedelstein. Selbst jetzt noch verfolgen mich ihre Gesichter! Besiegt die Anführer und bringt mir ihre Edelsteine, dann wird das Brachland endlich wieder Frieden haben.\n\nGeht, <Name>. Sie halten sich tief in den Höhlen des Wehklagens verborgen.", objectives = { "Edelstein von Kobrahn", "Edelstein von Anacondra", "Edelstein von Pythas", "Edelstein von Serpentis" } },
    [959] = { title = "Ärger auf den Docks", summary = "Kranführer Bigglefuzz in Ratchet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt.", desc = "Upps!\n\nWie Ihr seht, ist mir ein kleines Malheur passiert! Die Morgenlieferung aus Booty Bay war umfangreich. Wirklich gewaltig! Noch nie habe ich so viele Kisten gesehen. Tja, ich wollte die Sache etwas beschleunigen, deshalb habe ich begonnen mehr abzuladen, als ich auf einmal bewältigen konnte. Und dann ist alles zusammengebrochen.\n\nBevor ich wusste, was überhaupt los war, sah ich diese Nervensäge Zausel den Verrückten mit einer Flasche 99-jährigem Portwein wegrennen. Hab ihn bis zu den Höhlen des Wehklagens verfolgt. Da wollte ich auf keinen Fall rein.\n\nVielleicht seid Ihr ja mutig genug, um nach ihm zu suchen?", objectives = { "99 Jahre alter Portwein" } },
    [962] = { title = "Schlangenflaum", summary = "Die Apothekerin Zamah in Thunder Bluff möchte, dass Ihr zehn Schlangenflaum für sie sammelt.", desc = "Die Königliche Apothekervereinigung, die in der großen Undercity Lordaerons ansässig ist, hat mich geschickt, um eine ganz besondere Aufgabe zu erledigen, <Name>. Vielleicht möchtet Ihr mich und damit auch die dunkle Fürstin bei unseren Bemühungen, die Verlassenen weiterzubringen, unterstützen.\n\nIch studiere seit kurzem eine rare Pflanzenart namens Schlangenflaum. Ich denke, dass dieses Kraut in größeren Mengen außerordentliches Potenzial besitzt.\n\nLeider findet man Schlangenflaum nur in den dunkelsten Winkeln der Höhlen des Wehklagens, einem gefährlichen Höhlensystem im Brachland.", objectives = { "Schlangenflaum x 10" } },
    [971] = { title = "Wissen in der Tiefe", summary = "Bringt das 'Lorgalis-Manuskript' zu Gerrig Bonegrip in Ironforge.", desc = "Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die Schlafenden erwecken können.\n\nEs kursieren Gerüchte um einen alten Teil einer Lehre, das 'Lorgalis-Manuskript', das sich tief unten in den Blackfathom-Tiefen in Ashenvale befinden soll. Dieser Ort ist die ehemalige Heimat längst verstorbener Elfen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht in den Blackfathom-Tiefen nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht ... nach dem Ende aller Tage.", objectives = { "Lorgalis-Manuskript" } },
    [1013] = { title = "Das Buch von Ur", summary = "Bringt dem Bewahrer Bel'dugur im Apothekarium in Undercity das Buch von Ur.", desc = "<Name>, in der Burg Shadowfang gibt es ein Buch, das Buch von Ur, das ich unbedingt in meiner Sammlung haben möchte. Ur war einst ein großer Magier aus Dalaran bevor die Geißel kam. Seine Studien anderer Welten sind von großem Wert für... bestimmte Kreise der Verlassenen.\n\nBetretet die Burg Shadowfang und sucht das Buch. Bringt es mir, dann kann ich unserer dunklen Fürstin von Euren Diensten berichten...", objectives = { "Das Buch von Ur" } },
    [1014] = { title = "Arugal muss sterben", summary = "Tötet Arugal und bringt Dalar Dawnweaver in dem Grabmal seinen Kopf.", desc = "Arugal lebt immer noch in der Burg Shadowfang. Wir können Silberwald erst dann als strategische Festung für die dunkle Fürstin beanspruchen, wenn Arugal erschlagen ist.\n\nIch werde mich darum kümmern, seine Magie zu neutralisieren, <Name>. Ich überlasse es jedoch Euch, für Arugals Tod zu sorgen, den er mehr als verdient.\n\nReist zur Burg Shadowfang und setzt Arugals üblen Zaubern ein für alle Mal ein Ende. Bringt mir den Kopf dieses niederträchtigen Hexers!", objectives = { "Arugals Kopf" } },
    [1048] = { title = "In das Scharlachrote Kloster", summary = "Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Varimathras in Undercity.", desc = "Während die dunkle Fürstin sich um die dringende Angelegenheit des Vormarsches des Lichkönigs im Norden kümmert, sorge ich dafür, dass Dinge, die uns unmittelbar betreffen, entsprechend geregelt werden.\n\nDie Menschenplage, die sich selbst Scharlachroter Kreuzzug nennt, hat sich als der schärfste Dorn in unserem Fleisch erwiesen. Tirisfal wimmelt förmlich von diesen kleinen roten Ameisen.\n\nBegebt Euch zum Kloster, <Klasse>, und vernichtet Hochinquisitor Whitemane und seine obersten Offiziere.", objectives = { "Hochinquisitor Whitemane", "Scharlachroter Kommandant Mograine", "Herod", "Hundemeister Loksey" } },
    [1049] = { title = "Kompendium der Gefallenen", summary = "Holt das 'Kompendium der Gefallenen' aus dem Kloster in Tirisfal und bringt es zu Sage Truthseeker in Thunder Bluff.", desc = "Der irdene Ring hatte nur die besten Absichten, was unsere geplagten Brüder betraf. Aber wer weiß schon, welche Absichten jene verfolgen, die dem Ältestenrat Dinge einflüstern?\n\nDie Geschichte der Verlassenen, mit denen wir uns verbündet haben, ist von Lug und Trug durchzogen. Zu übereilt gingen wir unseren Pakt ein. Vielleicht hätte Cairne gut daran getan, die Warnungen aus Orgrimmar zu beherzigen.\n\nTief im Inneren des Scharlachroten Klosters liegt das 'Kompendium der Gefallenen' verborgen, das von irren menschlichen Zeloten bewacht wird. Ihr Tun ist von ihrem Wahnsinn geprägt, aber ihre Forschungen könnten nützlich für uns sein.", objectives = { "Kompendium der Gefallenen" } },
    [1050] = { title = "Mythologie der Titanen", summary = "Holt die 'Mythologie der Titanen' aus dem Kloster und bringt die der Bibliothekarin Mae Paledust in Ironforge.", desc = "Die Zukunft ist unausweichlich! Wir stürzen ihr entgegen wie Regentropfen, die auf das große Meer prasseln.\n\nAber vielleicht erfahren wir, indem wir die Vergangenheit studieren, was uns erwartet, und könnten uns besser auf das Unbekannte vorbereiten.\n\nBevor Lordaeron von all diesen schrecklichen Dingen heimgesucht wurde, gab es eine Bastion des Wissens, die in Tirisfal versteckt lag. Gerüchten zufolge soll es in der Bibliothek des alten Klosters ein Buch mit dem Titel 'Mythologie der Titanen' gegeben haben.\n\nBringt es mir, dann können wir vielleicht gemeinsam die Geheimnisse der Vergangenheit entschlüsseln!", objectives = { "Mythologie der Titanen" } },
    [1051] = { title = "Vorrels Rache", summary = "Bringt Monika Sengutz in Tarrens Mühle den Ehering von Vorrel Sengutz.", desc = "Trotz meines freien Willens kann ich der dunklen Fürstin nicht mehr dienen. Ich fühle, dass meine Zeit in Azeroth zu Ende geht. Meine Lebenskraft ist zerschmettert.\n\nDas hat mir Befrager Vishas angetan! Wochenlang quälte er mich! Nahm mir meinen Ehering und gab ihn seiner Frau. Dieser Bastard!\n\nRache ... Ich will Rache!\n\nDer eingebildete Narr prahlte immer mit seiner ach so kostbaren Frau Nancy, die am Lordameresee lebte. Spürt diese Frau auf, erschlagt sie und bringt meiner Frau Monika in Tarrens Mühle meinen Ehering.\n\nDies ist mein letzter Wille ...", objectives = { "Vorrels Ehering" } },
    [1052] = { title = "Auf dem Scharlachroten Pfad", summary = "Bringt Raleigh dem Andächtigen in Southshore Bruder Antons Empfehlungsschreiben.", desc = "Wir vom scharlachroten Kreuzzug erheben Anspruch auf die Festungen zwischen Hearthglen und Tirisfal. Wir sind recht stolz auf unsere Bastionen der Säuberung in ganz Lordaeron.\n\nIhr habt Euch gegen die Untoten in Desolace bewiesen. Doch die wahre Bedrohung durch die Seuche liegt in Lordaeron.\n\nBegebt Euch nach Southshore in den östlichen Königreichen. Sucht dort nach einem Kreuzzügler namens Raleigh der Andächtige. Gebt ihm dieses Empfehlungsschreiben, das mein Siegel trägt, dann wird er Euch zu einem ehrwürdigen Ort in unserem scharlachroten Kloster führen." },
    [1053] = { title = "Im Namen des Lichts", summary = "Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Southshore.", desc = "Einst diente ich dem Scharlachroten Kreuzzug mit Ehre, Treue und Stolz. Ich hielt das Ziel, das sie verfolgten, für edel: Azeroth von den Untoten befreien.\n\nAls ich jedoch im Kloster in Tirisfal weilte, erkannte ich, dass sie langsam den Bezug zur Wirklichkeit verloren. Jetzt halten sie jeden für verseucht, der nicht das Wams des Kreuzzuges trägt. Unschuldige Männer und Frauen wurden gefoltert, weil sie angeblich verseucht waren.\n\nDer Scharlachrote Kreuzzug muss im Namen des Lichts zerschlagen werden. Ihr, <Name>, müsst ihr wahnwitziges Regime beenden.", objectives = { "Hochinquisitor Whitemane", "Scharlachroter Kommandant Mograine", "Herod", "Hundemeister Loksey" } },
    [1098] = { title = "Todespirscher in Shadowfang", summary = "Sucht die Todespirscher Adamant und Vincent.", desc = "Als Vorbereitung auf einen Überfall auf Shadowfang wurden zwei Todespirscher in die Burg geschickt, um Informationen zu sammeln. Das war vor mehreren Tagen und sie sind noch nicht wieder zurück, aber wir brauchen ihren Bericht, wenn wir auf einen erfolgreichen Angriff hoffen wollen!\n\nDas ist Eure Aufgabe, <Name>. Geht zu Burg Shadowfang im Süden und sucht die Todespirscher Adamant und Vincent. Findet sie und helft ihnen, falls es erforderlich ist.\n\nDiese Mission ist nicht nur gefährlich, sondern auch lebenswichtig, <Name>. Versagt bitte nicht." },
    [1100] = { title = "Lonebrows Tagebuch", summary = "Lest Henrig Lonebrows Tagebuch.", desc = "Ihr öffnet langsam das verwitterte Tagebuch des Henrig Lonebrow..." },
    [1101] = { title = "Die Greisin des Krals", summary = "Bringt Falfindel Waywarder in Thalanaar Razorflanks Medaillon.", desc = "Armer Heralath! Und dieser Zwerg... Lonebrow. Was war er doch für eine mutige Seele.\n\nSo viel Heldenmut darf nicht umsonst gewesen sein. Diese Greisin... Charlga Razorflank... muss aufgehalten werden.\n\nSicher, es wird gefährlich werden, den Kral zu bespitzeln. Wir haben keine Zeit, um Darnassus zu informieren. <Name>, stellt eine Gruppe zusammen, um die Greisin zu erschlagen.\n\nBringt mir Razorflanks Medaillon zum Beweis ihres Ablebens.", objectives = { "Razorflanks Medaillon" } },
    [1102] = { title = "Ein schreckliches Schicksal", summary = "Bringt Auld Stonespire in Thunder Bluff Razorflanks Herz.", desc = "Es war edel von unserem Anführer Cairne, unser Volk hier in Thunder Bluff zu vereinen.\n\nIch kann jenen jedoch nicht vergeben, die uns so leicht aus dem Land unserer Vorfahren vertrieben haben. Jahrhundertelang lebte mein Volk im südlichen Brachland. Das Land war uns heilig. Aber wir wurden von zahllosen Feinden vertrieben.\n\nEin schreckliches Schicksal erwartet die Greisin Charlga Razorflank, die im Kral von Razorfen eine abscheuliche Armee zusammenzieht.\n\nBringt mir Razorflanks Herz, damit ich in Frieden sterben kann, <Name>.", objectives = { "Razorflanks Herz" } },
    [1109] = { title = "Go, Go, Guano!", summary = "Bringt dem Apothekermeister Faranell in Undercity 1 Häufchen Kral-Guano.", desc = "Wie Ihr seht, <Name>, befassen wir uns mit einigen sehr... interessanten Experimenten in der Königlichen Apothekervereinigung.\n\nAls Meister hier ist es meine Aufgabe, die anspruchsvollsten unserer alchimistischen Versuche zu überwachen. So viel Arbeit und nur so wenig Zeit!\n\nIhr seht weit gereist aus, <Klasse>. Vielleicht könnt Ihr mir helfen.\n\nIch brauche eine rare Substanz. Es ist dieses widerliche Zeug, das von einer raren Fledermausart stammt, die man nur in einem Dreckloch namens Kral von Razorfen findet. Bringt mir den Guano der Kral-Fledermäuse, damit wir mit unserer Arbeit beginnen können...", objectives = { "Kral-Guano" } },
    [1113] = { title = "Herzen des Eifers", summary = "Apothekermeister Faranell in Undercity möchte 20 Herzen des Eifers.", desc = "Warum ich eine rare Art von Guano benötige, fragt Ihr Euch? Also bei diesem Experiment möchte ich wissen, wie zwei diametral entgegengesetzte chemische Substanzen aufeinander wirken, besonders wenn beide mit einem höchst toxischen Agens kombiniert werden, um die ... garstigsten Resultate zu erzielen.\n\nIn der Nordostspitze von Tirisfal liegt das Scharlachrote Kloster. Dort versammeln sich die wahnsinnigen Jünger des Scharlachroten Kreuzzuges. Tötet sie und bringt mir ihre übereifrigen Herzen.\n\nUnser Gebräu wird äußerst tückisch sein!", objectives = { "Herz des Eifers x 20" } },
    [1139] = { title = "Die verlorene Tafel des Willens", summary = "Sucht die Tafel des Willens und bringt sie zu Berater Belgrum in Ironforge.", desc = "Wir haben den Schattenschmiedeklan ausgebremst, indem wir ihn von der Blackrockspitze abgeschnitten haben, doch Hammertoes Mission wurde noch nicht erfüllt. Sein Tod darf nicht umsonst gewesen sein. Er träumte davon, die Schrifttafel des Willens zu finden: eine Steintafel, graviert mit Magie durch die Titanen selbst, die helfen, ihren Schöpfungen Leben einzuhauchen und ihnen damit einen eigenen Willen ermöglichen. So jedenfalls heißt es in den Legenden.\n\nDennoch müssen wir die Tafel bergen, ehe der Schattenschmiedeklan sie finden kann.\n\nKehrt nach Uldaman zurück, sucht die Tafel und kommt unverzüglich wieder her.", objectives = { "Schrifttafel des Willens" } },
    [1142] = { title = "Die Sterblichkeit schwindet", summary = "Sucht und bringt Treshalas Anhänger zu Treshala Fallowbrook in Darnassus.", desc = "Ich habe nicht mehr lange zu leben... so... so... schwach.\n\n... der t-t-tapfere Zwerg Lonebrow hat jemanden geschickt, Falfindel zu w-w-warnen...\n\nAber bevor ich... s-s-sterbe...\n\n... meine Frau Treshala... ihr Anhänger des Bundes mit mir... gestohlen... von einem der n-n-niederträchtigen Angreifer...\n\nB-B-Bitte sucht ihn... und bringt ihn Treshala in Darnassus zurück...\n\n... mit der Nachricht meines einsamen... Todes.", objectives = { "Treshalas Anhänger" } },
    [1144] = { title = "Willix der Importeur", summary = "Führt Willix den Importeur aus dem Kral von Razorfen hinaus.", desc = "Endlich ist Hilfe eingetroffen!\n\nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.\n\nWisst Ihr, ich bin Unternehmer. Immer am abkupfern, wie man so sagt. Ich habe Wind davon bekommen, dass Mebok Mizzyrix gut für Rotlaubknolle aus diesem Schweinepferch hier bezahlt. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!\n\nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, sollte es Euer Schaden nicht sein.", objectives = { "Helft Willix dem Importeur bei der Flucht aus dem Kral von Razorfen." } },
    [1149] = { title = "Test des Glaubens", summary = "Wenn Ihr festen Glaubens seid, dann springt von den Planken über Tausend Nadeln.", desc = "Ihr habt mich also gesucht, oder führt Euch das Schicksal zu mir? Einerlei. Ihr seid jetzt hier, und so wird Eure Reise erneut beginnen.\n\nDas Sein besteht aus vielen Aspekten: Geist, Körper, Verstand. Einige davon kann man anhand der Traditionen einer Kultur bewerten. Von anderen können wir nur hoffen, dass sie in uns selbst existieren. Wenn Ihr einverstanden seid, möchte ich einige der Aspekte in Euch testen.\n\nWenn Ihr besteht, werdet Ihr stärker werden. Wenn Ihr scheitert, werdet Ihr die Weite des Nether begreifen.\n\nAls Erstes ein Test des Glaubens.", objectives = { "Der Kessel" } },
    [1150] = { title = "Test der Belastbarkeit", summary = "Bringt Grenkas Klaue zu Dorn Plainstalker in Tausend Nadeln.", desc = "Ich sehe mit Freuden, dass Euer Mut im Lichte Eurer bisherigen Taten unerschütterlich bleibt. Da Euer Glaube stark ist, wird es Zeit, Euren Körper zu testen.\n\nAls Erstes ein Test der Belastbarkeit. Geht mit Freunden zum Bau der Wildfedern westlich vom Freiwindposten. Steigt in die Tiefen ihres Unterschlupfes hinab und zerstört ihre Nahrungsvorräte. Damit solltet Ihr deren Zorn angestachelt haben. Wenn Ihr lange genug überlebt, wird Grenka Blutkreischer Euch persönlich heimsuchen. Tötet sie und bringt mir ihre Klaue, um den Test abzuschließen.", objectives = { "Grenkas Klaue", "Lendenstück" } },
    [1151] = { title = "Test der Kraft", summary = "Bringt Fragmente von Rok'Alim zu Dorn Plainstalker in Tausend Nadeln.", desc = "Zu Zeiten der Alten Götter bewohnten Elementare einen Großteil dieser Welt. Sie beteten die Alten Götter an, und die Götter fesselten die Elementare durch ihre Macht an diese Welt. Als die Alten Götter verbannt wurden, verblassten die Elementare in unserer Welt und kehren jetzt auf Geheiß mächtiger Magier zurück.\n\nAber es gibt Ausnahmen. Einige Elementar waren mächtig genug, aus eigenen Stücken hier zu bleiben. Solch ein Elementar ist Rok'Alim.\n\nSucht Rok'Alim in Tausend Nadeln und tötet ihn, um Eure Kraft zu beweisen.", objectives = { "Fragmente von Rok'Alim" } },
    [1152] = { title = "Test der Lehre", summary = "Sucht Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge.", desc = "Eure Zeit bei mir neigt sich dem Ende zu. Ich bin wissend, aber den Test der Lehre kann ich Euch nicht stellen. Es gilt, Lektionen zu erlernen und Orte zu besuchen, die in der Zuständigkeit anderer liegen.\n\nWenn Ihr bereit seid, dann sucht Braug Dimspirit auf - er ist ein höchst weiser Schamane. Er wird Euch weiter testen, also achtet auf seine Worte, <Name>.\n\nWenn Ihr bereit seid, dann sucht den Tunnel, der das Steinkrallengebirge mit Ashenvale verbindet. Dort in der Nähe lebt Braug. Und seid vorsichtig, <Name>, die Nachtelfen versuchen vielleicht, Euren Test zu behindern." },
    [1154] = { title = "Test der Lehre", summary = "Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück.", desc = "Ihr habt Dorns Tests bestanden und wollt jetzt Eure nächste Prüfung absolvieren. Sehr gut. Bisher sind alle Eure Herausforderungen kindisch gewesen. Es ist leicht, Euren Körper zu testen - bei Eurem Verstand sieht das schon anders aus.\n\nIch werde es mit einfachen Worten erklären: sucht das Buch, das ich Euch nenne, lest es und beantwortet meine Fragen nach seinem Inhalt.\n\nWas für ein Buch, werdet Ihr fragen? Das 'Vermächtnis der Aspekte'. Man findet es in den Tiefen des Dor'danil-Grabhügels im südlichen Ashenvale, wo es von den toten Druiden und deren Tötern bewacht wird.", objectives = { "Vermächtnis der Aspekte" } },
    [1159] = { title = "Test der Lehre", summary = "Sucht Parqual Fintallas in Undercity.", desc = "Gut gemacht, <Name>. Ihr habt den ersten Teil des Tests der Lehren bestanden, aber es bleibt noch eine Frage zu beantworten. Aber es ist nicht an mir, diese Frage zu stellen.\n\nBesucht Parqual Fintallas in Lordaeron. Er war ein bedeutender Historiker der Menschen, bevor die Seuche ihn erwischte. Jetzt sucht er immer noch Erleuchtung, freilich einer ganz anderen Art.\n\nEr wird eine weitere Forderung an Euch stellen, bevor er Euch etwas fragt, aber Ihr habt Euch bisher meisterhaft geschlagen - ich bin sicher, Ihr werdet dieses Hindernis überwinden." },
    [1160] = { title = "Test der Lehre", summary = "Sucht Die Anfänge der Bedrohung durch die Untoten und bringt es zu Parqual Fintallas in Undercity.", desc = "Ich sage Euch, was Ihr suchen müsst und werde Euch sogar meine Frage stellen, aber nicht, weil Ihr Euch beweisen wollt. Wissen ist weit wichtiger als Kraft. Auch wenn andere Euch in ihren Fähigkeiten überlegen sein mögen, Euer Wissen über die Welt ist wertvoller.\n\nGeht zu dem Kloster im Norden Tirisfals. In der dortigen Bibliothek steht ein Buch mit dem Titel Die Anfänge der Bedrohung durch die Untoten. Es wurde von den jetzt verderbten Paladinen benutzt, um sie in meiner Art des Kampfes auszubilden.\n\nBringt es mir.", objectives = { "Anfänge der Bedrohung durch die Untoten" } },
    [1198] = { title = "Auf der Suche nach Thaelrid", summary = "Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf.", desc = "Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.\n\nMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.\n\nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.\n\nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.\n\nSucht und unterstützt Thaelrid für mich, <Name>." },
    [1199] = { title = "Die Twilight fallen", summary = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus", desc = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass die Twilight-Hammer sich mit den Naga verbündet haben und sich in der Blackfathom-Tiefe an den Küsten von Ashenvale zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen die Hammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", objectives = { "Twilightanhänger x 10" } },
    [1200] = { title = "Schurkerei in Blackfathom", summary = "Bringt den Kopf des Twilight-Lords Kelris zu Dämmerungsbehüter Selgorm in Darnassus.", desc = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'Mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Selgorm in Darnassus seinen Kopf, <Name>.", objectives = { "Kelris Kopf" } },
    [1221] = { title = "Blaulaubknollen", summary = "Schnappt Euch eine Kiste mit Löchern. Schnappt Euch einen Schnüffelnasenleitstecken. Schnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es. Benutzt im Kral von Razorfen die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht. Bringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratchet.", desc = "Blaulaubknollen gelten auf der ganzen Welt als Delikatesse! Aber sie sind rar, sehr rar. Man findet sie nur hier im Brachland, tief in der Erde des Krals von Razorfen.\n\nUnd selbst dann sind sie fast nicht zu finden, wenn man nicht weiß, wo man suchen muss! Darum habe ich diese Schnüffelnasenziesel abgerichtet, damit sie sie für mich aufstöbern. Sie haben unheimlich empfindliche Nasen und riechen eine Knolle aus fünfzig Schritt Entfernung.\n\nEs wird nicht einfach sein, aber wenn Ihr mir ein paar Knollen bringt, bezahle ich Euch gut dafür.", objectives = { "Blaulaubknolle x 6", "Kiste mit Löchern", "Schnüffelnasenbesitzeranleitung", "Schnüffelnasenleitstecken" } },
    [1275] = { title = "Erforschung der Verderbnis", summary = "Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme.", desc = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Blackfathom-Tiefe, an der Küste von Ashenvale, werdet Ihr sowohl Satyrn als auch Naga finden.\n\nEs ist eine lange Reise, <Name>.", objectives = { "Verderbter Hirnstamm x 8" } },
    [1360] = { title = "Wiederbeschaffte Schätze", summary = "Holt Krom Stoutarms wertvollen Besitz aus seiner Truhe in der nördlichen Bankenhalle von Uldaman und bringt den Schatz zu ihm nach Ironforge.", desc = "Ich hatte selbst eine gute Arbeitsstelle als Buddler an der Uldaman-Ausgrabungsstätte im Ödland... das heißt, bis diese verfluchten Troggs auftauchten. Ich konnte gerade noch mit heiler Haut entkommen, das war alles. In dem Chaos habe ich meinen wertvollsten Besitz zurückgelassen. Natürlich ist er in meiner Truhe sicher vor den Troggs, aber die befindet sich mitten unter ihnen.\n\nIch wäre in Eurer Schuld, sowohl in Ehre als auch in Münze, wenn Ihr sie für mich besorgen könntet! Eine Truhe mit meinem Namen darauf befindet sich am Ende der nördlichen Bankenhalle. Dorthin müsst Ihr gelangen.", objectives = { "Krom Stoutarms Schatz" } },
    [1424] = { title = "Tränenteich", summary = "Fel'Zerul in Stonard möchte, dass Ihr 10 Artefakte der Atal'ai sammelt.", desc = "Der Kriegshäuptling schickt uns, die seltsamen Vorkommnisse im Tempel von Atal'Hakkar zu untersuchen.\n\nDie Trolle des Stammes der Atal'ai sind ein Stamm dunkler Zauberkundiger, die dafür bekannt sind, verbotene Magie auszuüben. Ihr könnt Euch vorstellen, wie erstaunt wir waren, als wir hier eintrafen und feststellten, dass der Tempel versunken war.\n\nDie grünen Großdrachen hüten nun die Stelle und spielen sich als Beschützer von Azeroth auf.\n\nWir müssen herausfinden, was geschehen ist. Forscht rund um den Tränenteich und sammelt Artefakte der Atal'ai. Damit kann ich dieses Rätsel lösen.", objectives = { "Artefakt der Atal'ai x 10" } },
    [1429] = { title = "Der Verbannte der Atal'ai", summary = "Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland.", desc = "Während Ihr den Gefahren des Tränenteichs getrotzt habt, kehrte einer meiner Späher mit einer in Blut und auf getrocknetem Fleisch geschriebenen Rolle zurück. Es scheint sich um ein Urteil gegen einen der Priester des Stammes der Atal'ai zu handeln.\n\nDer Priester wurde zu etwas Schlimmerem als dem Tod bei den Atal'ai verurteilt.\n\nEr wurde ins Hinterland zu den Trollen der Witherbark verbannt.\n\nIch bündle diese Artefakte. Ihr müsst den Verbannten suchen und ihren wahren Verwendungszweck herausfinden. Kommt wieder zu mir, wenn Eure Reise beendet ist." },
    [1444] = { title = "Rückkehr zu Fel'Zerul", summary = "Kehrt zu Fel'Zerul in Stonard zurück.", desc = "Jammal'an der Prophet verbannte mich aus dem Tempel von Atal'Hakkar. Einst empfand ich den Hohepriester als würdigen Anführer.\n\nSein unerschütterlicher Glaube an seine Prophezeiung wird den Untergang der Atal'ai herbeiführen. Wenn es nicht schon geschehen ist.\n\nAls ich meiner Besorgnis Ausdruck verlieh, hieß man mich einen Ungläubigen und verstieß mich aus dem Tempel.\n\nDie Artefakte, die Ihr zu mir brachtet, sind harmlos. Aber wenn Jammal'an die richtige Fetischverzauberung für das Beschwörungsritual gefunden hat, droht der Welt große Gefahr..." },
    [1445] = { title = "Der Tempel von Atal'Hakkar", summary = "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Stonard.", desc = "Also sprach er von Jammal'ans Prophezeiung?\n\nDer spirituelle Anführer der Atal'ai glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott dem Stamm der Atal'ai Unsterblichkeit gewähren.\n\nTörichte Arglist, um den Jüngsten Tag schneller herbeizuführen, wenn Ihr mich fragt.\n\nDoch Ihr sagt, der Verbannte sprach von verzauberten Fetischen? Das erfüllt mich mit großer Sorge. Wenn sie wahrhaftig der Schlüssel zu dem Ritual der Atal'ai sind, das dieses Durcheinander verursachte, müssen wir die Mächte verstehen, die in ihnen wohnen.\n\nBegebt Euch in den Tempel und werdet dieser Fetische habhaft!", objectives = { "Fetisch von Hakkar x 20" } },
    [1446] = { title = "Jammal'an der Prophet", summary = "Der Verbannte der Atal'ai im Hinterland möchte den Kopf von Jammal'an.", desc = "Meine Gefährten aus Witherbark mögen keine Fremden in ihrer Nähe.\n\nIch? Ich habe keine Heimat mehr. Mein Volk, der große Stamm der Atal'ai aus den Sümpfen des Elends, hat mich verbannt.\n\nJammal'an, unser spiritueller Anführer, hatte eine, wie wir uns ausdrücken, Prophezeiung. Er glaubt, die Beschwörung des Gottes Hakkar bringt den Atal'ai Unsterblichkeit.\n\nIch jedoch drängte auf Vorsicht. Wenn die Prophezeiung nun nichts weiter als Manipulation war?\n\nIch will Rache für meine Verbannung. Bringt mir Jammal'ans Kopf. Vielleicht ist mein Volk dann frei.", objectives = { "Jammal'ans Kopf" } },
    [1448] = { title = "Auf der Suche nach dem Tempel", summary = "Brohann Caskbelly in Stormwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht.", desc = "Es gab eine Zeit, da war ich jung und voller Kraft, wie Ihr, <Klasse>.\n\nDoch jetzt bin ich alt und vermag die Welt nicht mehr zu erforschen wie einst. Ach, was habe ich nicht alles gesehen!\n\nAber ein Geheimnis entzog sich mir stets. Als meinen letzten Auftrag schickte mich die Forscherliga auf die Suche nach dem Tempel von Atal'Hakkar. Er sollte Gerüchten zufolge in den Sümpfen des Elends liegen.\n\nMeines gebrechlichen Zustands wegen reiste ich auf einem Greif durch die Lüfte, fand den Tempel aber nie.\n\nHelft Ihr einem alten Zwerg? Vielleicht habt Ihr zu Fuß mehr Glück.", objectives = { "Klingenhügel", "Die Suche nach dem Tempel von Atal'Hakkar" } },
    [1449] = { title = "Ins Hinterland", summary = "Sprecht mit dem obersten Than, Falstad Wildhammer, in Aerie Peak im Hinterland.", desc = "Wie ich schon früher sagte, versuchte ich selbst, den Tempel aus der Luft zu finden. Ganz allein war ich freilich nicht.\n\nIch reiste zu dem berühmten Greifenhorst bei Aerie Peak im Hinterland. Dort versicherte ich mich der Hilfe eines ihrer besten Piloten. Der Pilot fiel von seinem Reittier in den Sumpf ...\n\nDen Namen des armen Burschen habe ich im Alter vergessen. Der Meister des Horsts kennt ihn zweifellos noch.\n\nBegebt Euch dorthin und sucht nach Falstad Wildhammer.\n\nWir müssen herausfinden, was dem Piloten zugestoßen ist." },
    [1450] = { title = "Greifenmeister Talonaxe", summary = "Sprecht mit Greifenmeister Talonaxe im Horst bei Aerie Peak.", desc = "Ihr seid also nur ein <besserer Botenjunge/besseres Botenmädchen> für einen alten Tattergreis der Forscherliga, hm?\n\nHört mir gut zu, <Klasse>. Ich habe keine Ahnung, mit wem Euer alter Kumpel da unten in Azeroth rumgeflogen ist. Seh ich etwa wie der Greifenmeister Talonaxe aus? Ja?\n\nWenn Ihr Euch für die Flugpläne interessiert, warum fragt Ihr dann nicht den Greifenmeister? Wenn Ihr noch länger untätig hier herumhängt, werde ich Euch richtige Arbeit geben.\n\nUnd jetzt trollt Euch." },
    [1451] = { title = "Rhapsody-Shindigger", summary = "Sucht Rhapsody Shindigger im Hinterland.", desc = "Rhapsody fand Gefallen am Schnaps. Versteht mich nicht falsch - alle Zwerge hier im Horst wissen ein gutes Bier zur passenden Stunde zu schätzen.\n\nAber der alte Shindigger brauchte den Fusel wie ein Greif den Himmel. Und das war echt ein Jammer. Niemand konnte so fliegen wie Rhapsody.\n\nDie ersten Probleme gab es, als er mit Eurem Freund Brohann von dieser Mission zurückkehrte. Danach ging es rapide bergab. Musste ihn rauswerfen.\n\nZuletzt hörte ich, er habe östlich von hier eine Brauerei eröffnet ..." },
    [1452] = { title = "Rhapsodys Kalimdor-Cocktail", summary = "Rhapsody Shindigger im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoc-Lebern und 3 Eisenfelllebern bringt.", desc = "Hicks!\n\nDieser irre Narr Brohann schickt Euch also? Wir haben ein tolles Abenteuer zusammen erlebt... Hicks!\n\nWenn ich Euch erzählen soll, was da unten im Sumpf passiert ist, brauch ich was Ordentliches zu trinken. Das war echt kein schöner Anblick. Hicks!\n\nIch sag Euch was... bringt mir, was ich brauche, um einen Kalimdor-Cocktail zu mixen, dann erzähl ich Euch davon.\n\nMan braucht dazu den Muskelmagen eines Roc aus Tanaris... etwas Groddoc- und Eisenfellleber aus Feralas...\n\nEin schöner kräftiger Kalimdor-Cocktail... dann kann ich plaudern!", objectives = { "Muskelmagen eines Roc x 3", "Eisenfellleber x 3", "Groddoc-Leber x 3" } },
    [1469] = { title = "Rhapsodys Geschichte", summary = "Bringt das Schrifttafelfragment der Atal'ai zu Brohann Caskbelly in Stormwind.", desc = "Vor dem Flug trank ich ein ganzes Fass Starkbier. Hicks!\n\nUnd was für ein Flug das war. Ich sauste herum und Brohann folgte mir. Aber ich hab keinen Tempel nicht gesehen. Hicks!\n\nJedenfalls sah ich keinen Tempel, bis mir schwindlig wurde und ich von meinem Reittier fiel. Ich fiel kopfüber ins Wasser und wurde in die Tiefe gesogen. Dort sah ich mich von einer Schar unheimlicher Trolle umringt. Ich schwamm, was das Zeug hielt! Und schaffte es sogar mit diesem Trollsouvenir da raus. Hier, bringt es Brohann und lasst ihn wissen, dass der Tempel tatsächlich da unten ist. Hicks!" },
    [1475] = { title = "Im Tempel von Atal'Hakkar", summary = "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Caskbelly in Stormwind.", desc = "Der Legende zufolge ist der Tempel von Atal'Hakkar ein heiliger Schrein, der dem alten Gott Hakkar dem Seelenschinder geweiht ist. Der Tempel, der von einem tückischen Trollstamm namens Atal'ai unterhalten wird, soll angeblich uneinnehmbar sein.\n\nDa der Tempel jetzt im Tränenteich versunken ist, dürfte es noch schwieriger sein, Artefakte zu bergen. Aber genau das müsst Ihr tun, <Name>.\n\nHelft mir dabei, indem Ihr die intakten Schrifttafeln der Atal'ai sammelt. Bringt sie mir und ich schicke der Forschergilde einen Helden zurück. Wir werden uns den Ruhm teilen.", objectives = { "Schrifttafel der Atal'ai x 10" } },
    [1486] = { title = "Deviatbälge", summary = "Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge.", desc = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.\n\nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Sie sind zwar von Natur aus böse, doch bin ich der Meinung, dass ihre Existenz hier in Kalimdor auch etwas Gutes haben kann. Ich glaube, ihre Bälge sind besonders gut für die Lederverarbeitung geeignet.\n\nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen unter uns hinab und holt einige Deviatschuppen.", objectives = { "Deviatbalg x 20" } },
    [1487] = { title = "Ausrottung der Deviat", summary = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet.", desc = "Naralex hatte ein edles Ziel.\n\nUnser großer Anführer trachtete danach, in den Smaragdgrünen Traum zu gelangen und dabei zu helfen, aus diesem kargen Land wieder den üppigen Wald zu machen, der hier einst wuchs. Aber etwas ist furchtbar schief gegangen.\n\nNaralex' Traum wurde zum Alptraum. Verderbte Kreaturen siedelten sich in den Höhlen an.\n\nWährend einige Jünger von Naralex versuchen, unseren Meister zu wecken, ist es mein Trachten, die Höhlen von diesen bösen Bestien zu befreien.\n\nWagt Euch in die Höhlen, <Name>, und löscht die Deviatbrut aus.", objectives = { "Deviatverheerer x 7", "Deviatviper x 7", "Deviatschlurfer x 7", "Deviatschreckensfang x 7" } },
    [1489] = { title = "Hamuul Runetotem", summary = "Sprecht mit Hamuul Runetotem.", desc = "Die Schalen, die Ihr mir gebracht habt, haben eine Besudelung, eine, die ich nie zuvor gesehen habe. Ich bin mir sicher, dass das Wasser der Oasen der Grund dafür ist. Ich spüre die Verwirrung, die sie über das Land bringen. Es ist, als würde das Land träumen und nicht erwachen können.\n\nDie Höhlen des Wehklagens müssen die Quelle dieser Besudelung sein. Doch ehe Ihr dorthin geht, solltet Ihr mit dem Druidenältesten Hamuul Runetotem sprechen. Ich ließ ihn über die Vorfälle im Brachland informieren. Er ist weise und kann Euch Rat geben.\n\nIhr findet ihn in Thunder Bluff auf der Anhöhe der Ältesten." },
    [1490] = { title = "Nara Wildmane", summary = "Sprecht mit Nara Wildmane.", desc = "Ich betrat das Land der Träume und träumte von einem Druidenkult, der in den Höhlen des Wehklagens haust. Ich sah, dass ihre Ziele einst edel waren, sie jedoch vom rechten Weg abkamen. Sie sind jetzt Diener der Besudelung, die das Brachland befallen hat.\n\nIch bin alt und meine Kraft verlässt mich. Ich konnte nicht lange an diesem Traumort verweilen und weiß wenig mehr von den besudelten Druiden. Aber Nara ist jung und starken Willens. Sie blieb in dem Traum zurück, als ich floh.\n\nSprecht mit Nara. Sie ist in jenem Zelt da drüben." },
    [1491] = { title = "Klugheitstränke", summary = "Bringt 6 Portionen Klageessenz zu Mebok Mizzyrix in Ratchet.", desc = "Nun gut, die Raptorenhörner haben nicht funktioniert. Aber das macht nichts... nicht alles klappt beim ersten Mal! Außerdem habe ich wohl etwas gefunden, das in meinen Klugheitstränken noch besser funktioniert!\n\nEs gibt eine Substanz, die Klageessenz genannt wird. Ich glaube, sie ist die Ursache für die seltsamen Pflanzen und Tiere im Brachland. Bringt mir etwas davon, dann erprobe ich es in meinem Trank!\n\nIch hörte, die Essenz reichert sich in Ektoplasmakreaturen in den Höhlen des Wehklagens im Westen an. Jagt diese Kreaturen und sammelt die Essenz.", objectives = { "Klageessenz x 6" } },
    [1649] = { title = "Der Foliant der Ehre", summary = "Sprecht mit Duthorian Rall in Stormwind.", desc = "Ehre, und alle Tugenden, die damit einhergehen, sind wie rare Mineralien: man muss sie ihres Wertes wegen bewundern, wenn man sie findet, aber man muss sich auch die Zeit nehmen, sie aufzuheben... zu veredeln. Mischt man sie richtig, entsteht eine starke Legierung, die manchmal selbst die heftigsten Hiebe nicht zerbrechen können.\n\nDiese Kraft, Euer Glauben, Eure Tapferkeit, müssen geprüft werden. Ihr müsst lernen, niemals den Glauben zu verlieren und erkennen, dass Ihr mit der Macht des Lichts Dinge überwinden könnt, vor denen andere klein beigeben müssen." },
    [1650] = { title = "Der Foliant der Ehre", summary = "Sucht Daphne Stilwell in Westfall.", desc = "Gut! Da Ihr nicht zögert, seid Ihr gewiss bereit und brennt darauf, Euch zu beweisen. So sei es.\n\nAm äußersten Ende von Longshore in Westfall steht ein kleines Haus über dem Ozean. Dort lebt ein Paar, die Stilwells. Jordan ist ein unglaublicher Schmied und für einige Zeit nach Ironforge gegangen, um sich mit den Zwergen zu treffen. Dadurch ist seine Frau Daphne allein und schutzlos.\n\nEs wird berichtet, dass die Defias fast das gesamte Gebiet übernommen haben. Gut möglich, dass Daphne Schutz vor den Bösewichtern braucht. Geht dorthin." },
    [1651] = { title = "Der Foliant der Ehre", summary = "Verteidigt Daphne Stilwell vor dem Angriff der Defias. Keiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt. Sprecht erneut mit Daphne Stilwell, wenn Ihr erfolgreich wart.", desc = "Ich wette, die kommen bald wieder, also macht Euch bereit.\n\nIch habe eine Schusswaffe im Haus. Ich hole sie und helfe Euch gern, aber Ihr werdet weitgehend auf Euch gestellt sein.\n\nIch habe keine Ahnung, wie viele sie schicken, aber es werden sicher mehr sein als die paar beim letzten Mal.\n\nBittet das Licht um jeden erdenklichen Segen, denn ... habt Ihr das gehört? Ich glaube, sie kommen.\n\nWir beziehen Position beim Haus!", objectives = { "Beschützt Daphne Stilwell." } },
    [1652] = { title = "Der Foliant der Ehre", summary = "Sprecht mit Duthorian Rall in Stormwind.", desc = "Kehrt bitte zu Duthorian zurück und lasst ihn wissen, dass ich hier vorerst sicher bin. Dafür muss ich Euch und der Kirche danken.\n\nEr wird eine Nachricht nach Ironforge schicken und meinen Jordan wissen lassen, dass er keinen Grund zur Furcht hat.\n\nOh, ich vermisse meinen Mann so sehr. Ich kann es kaum erwarten, bis er wieder da ist." },
    [1653] = { title = "Die Prüfung der Rechtschaffenheit", summary = "Sprecht mit Jordan Stilwell in Ironforge.", desc = "Ich zweifle nicht daran, dass Jordan Euch persönlich danken möchte, und da ich einen Boten brauche, der ihn wissen lässt, dass es seiner Frau gut geht, scheint Ihr mir die perfekte Wahl zu sein.\n\nJordan sollte ein Paladin des Lichts sein, bevor die Liebe zum Beruf seines Vaters ihn einen anderen Weg einschlagen ließ - er ist innig mit unserer Lebensweise vertraut und wird zu unseren Getreuesten gerechnet.\n\nEr müsste noch in Ironforge sein - tagsüber arbeitet er gern vor den Toren, wohl wegen der kühlen Bergluft." },
    [1654] = { title = "Die Prüfung der Rechtschaffenheit", summary = "Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Kor-Edelstein und bringt alles zusammen zu Jordan Stilwell in Ironforge.", desc = "Ich würde Euch gern eine Belohnung geben, wenn Ihr bereit seid, eine anzunehmen. Missversteht mich nicht, meine Großzügigkeit hängt davon ab, wie hilfreich Ihr sein könnt, aber ich denke, wir werden beide von einer derartigen Allianz profitieren.\n\nIch werde Euch eine Waffe schmieden, die Eurer Leistung würdig ist, ein Symbol der Paladinschaft und des Lichts, doch zuvor müsst Ihr die Gegenstände sammeln, die ich zu seiner Herstellung brauche. Ich habe schon angefangen, mir Notizen zu den Gegenständen zu machen, und brauche nur jemanden, der tapfer und geschickt genug ist, sie zu beschaffen. Was sagt Ihr dazu, <Klasse>?", objectives = { "Weißsteineichenholz", "Jordans aufbereitete Erzlieferung", "Jordans Schmiedehammer", "Geläuterter Kor-Edelstein" } },
    [1740] = { title = "Die Kugel von Soran'ruk", summary = "Sucht 3 Soran'ruk-Fragmente und 1 großes Soran'ruk-Fragment und bringt sie zu Doan Karhan im Brachland.", desc = "Wenn Dämonen der Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre Magier und Hexenmeister verteilt.\n\nViele wurden von ihren Bediensteten in Azeroth getragen. Selbst als Bruchstücke besitzen sie die Macht der darin gefangenen Dämonen.\n\nDie Kugel von Soran'ruk wurde in zwei Teile zerbrochen. Eines davon wurde abermals zerbrochen und von den Akolythen der Twilight-Hammer in der Blackfathom-Tiefe benutzt. Das andere, größere Teil besaß ein Hexer in der Burg Shadowfang. Sucht sie, dann kann ich sie zusammenfügen...", objectives = { "Soran'ruk-Fragment x 3", "Großes Soran'ruk-Fragment" } },
    [1947] = { title = "Reise in die Marschen", summary = "Sprecht mit Tabetha.", desc = "Jetzt ist es an der Zeit, Euch Euren Magierzauberstab zu verdienen. Um diese Aufgabe zu beginnen, solltet Ihr mit der Menschen-Einsiedlerin Tabetha in den Marschen von Dustwallow sprechen. Ihr findet ihre Hütte tief in den Marschen, westlich von Theramore.\n\nSprecht mit ihr, denn sie verfügt über umfangreiches Wissen. Tabethas Hütte befindet sich westlich von Theramore und direkt nördlich der Stonemaul Ruinen." },
    [1949] = { title = "Verborgene Geheimnisse", summary = "Sprecht mit Magus Tirth in der schimmernden Ebene.", desc = "Um Euren Zauberstab herzustellen, muss ich einige wichtige Stellen in einem bestimmten Buch lesen. Dieses Buch wurde von dem Magus Tirth geschrieben und heißt 'Rituale der Macht'.\n\nIch besitze kein Exemplar dieses Buchs und es ist in keiner der großen Bibliotheken der Welt zu finden. Daher müsst Ihr mit Tirth sprechen und es von ihm bekommen.\n\nViel Glück. Tirth war ein großer Magier und Gelehrter, aber heute verbringt er seine Zeit bei den Gnomen- und Goblinrennen auf der schimmernden Ebene und trinkt und spielt." },
    [1950] = { title = "Der Knüller schlechthin", summary = "Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück.", desc = "Ich kann Euch mit dem Buch helfen, doch vorher müsst Ihr mir helfen!\n\nDer Foliant, den Ihr sucht, befindet sich in meiner magisch versiegelten Geldkassette. Um sie zu öffnen, muss ein bestimmter Satz gesprochen werden, aber ich kann mich nicht mehr an ihn erinnern! Normalerweise merkt sich mein Assistent so etwas, aber der ist unauffindbar.\n\nWenn Ihr mein Buch möchtet, sucht meinen Lehrling! Fragt auf der Rennbahn - wenn Ihr Glück habt, hat ihn jemand gesehen. Schleppt ihn entweder hierher oder entlockt ihm wenigstens meinen magischen Satz, damit wir die Kassette aufbekommen!", objectives = { "Geheimen Satz gefunden" } },
    [1951] = { title = "Rituale der Macht", summary = "Bringt das Buch 'Rituale der Macht' zu Tabetha in den Marschen von Dustwallow.", desc = "Hm, wenn ich so darüber nachdenke, ich habe mein Buch nicht! Wisst Ihr, ich hatte Spielschulden, und um sie zu bezahlen, verkaufte ich das letzte Exemplar von 'Rituale der Macht' an ein Mitglied der Kleriker...\n\nEin Mitglied der Scharlachroten Bruderschaft. Er muss es zur Bibliothek im Scharlachroten Kloster in Tirisfal gebracht haben!\n\nWenn Ihr das Buch wollt, müsst Ihr in das Kloster gehen und es suchen. Und entschuldigt den ganzen Ärger. Ich bin neuerdings nicht mehr ich selbst...", objectives = { "Rituale der Macht" } },
    [1953] = { title = "Rückkehr in die Marschen", summary = "Sprecht mit Tabetha.", desc = "<Name>, es wird Zeit, dass Ihr mit Tabetha sprecht... der Einsiedlerin in den Marschen von Dustwallow. Sie wird Euch in der Herstellung einer mächtigen Magiergerätschaft unterweisen.\n\nTabethas Hütte liegt tief in den Marschen von Dustwallow, westlich von Theramore." },
    [1954] = { title = "Die Höllenkugel", summary = "Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow.", desc = "Als ersten Schritt müsst Ihr eine Kugel voll Macht beschaffen. Die Hexenmeister der Burning Blade haben hübsche, hochwertige Kugeln... zu dumm, dass sie Dämonen darin eingebunden haben! Aber das können wir ändern, ja.\n\nGeht nach Desolace und nehmt einem Beschwörer der Burning Blade eine Höllenkugel ab. Beschwörer findet Ihr bei Mannorocs Koven.\n\nKommt zu mir zurück, wenn Ihr die Kugel habt.", objectives = { "Höllenkugel" } },
    [1955] = { title = "Die Austreibung", summary = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", desc = "Jetzt, da wir eine Beschwörerkugel haben, müssen wir den Dämon darin austreiben. Ich kann es machen. Das ist der einfache Teil.\n\nIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, wenn er draußen ist.\n\nUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, springt er in die Kugel zurück und wir müssen von vorn anfangen!\n\nAlso macht Euch bereit. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.", objectives = { "Dämon der Kugel", "Kill the Demon of the Orb" } },
    [1956] = { title = "Macht in Uldaman", summary = "Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha.", desc = "Jetzt, nachdem der Dämon entfernt wurde, müssen wir eine Kraftquelle finden. Leider sind die besten Kraftquellen meistens die ältesten und die, an die man am schwersten rankommt. Ist schon lustig, wie einem das Schicksal manchmal mitspielt, wie?\n\nAlso müsst Ihr nach Uldaman und dort die Obsidianschildwache besiegen. Der Kerl ist groß, er ist zäh und seine Kraftquelle hat ganz schön Pep.\n\nIch wünsche Euch viel Glück, <Name>. Falls Ihr kein Glück haben solltet, tja... dann war es schön, Euch gekannt zu haben.", objectives = { "Obsidiankraftquelle" } },
    [2040] = { title = "Unterirdischer Angriff", summary = "Holt das Gnoam-Sprecklesprocket aus den Todesminen und bringt es Shoni der Schtillen in Stormwind.", desc = "Gnomeregan ist diesen elendigen Troggs in die Hände gefallen! Die Situation ist ernst, aber vielleicht könnt Ihr helfen, <Name>.\n\nTief in den Todesminen gibt es einen funktionierenden Goblinschredder. Sucht diesen Schredder und bringt die intakte Energieversorgung mit. Mit der Energieversorgung des Schredders können wir unseren gyrobohrmatischen Exkavationatoren die erforderliche Energie zuführen, um durch die felsigen, unterirdischen Grenzen von Gnomeregan zu brechen und einem Gnomenangriff den Weg zu ebnen!", objectives = { "Gnoam-Sprecklesprocket" } },
    [2198] = { title = "Die zerrissene Halskette", summary = "Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren.", desc = "Ihr habt eine befleckte Halskette gefunden, doch unter der Stumpfheit des Metalls lässt sich noch die feine und magische Handarbeit erkennen. Die Halskette ist beschädigt, in ihrer Fassung scheinen drei Edelsteine zu fehlen. Auf der Unterseite der Halskette kann man vage den Stempel des Stadtsiegels von Ironforge erkennen. Unter dem Siegel befinden sich drei winzige eingravierte Buchstaben: \"TdK\".\n\nWenn Ihr etwas über die Halskette in Erfahrung bringen wollt, müsst Ihr herausfinden, woher sie stammt. Vielleicht sind das Siegel und die Initialen ein Anfang ..." },
    [2202] = { title = "Reagenzsuche in Uldaman", summary = "Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld.", desc = "Ich habe von einer neu entdeckten Pflanze gehört, den magenta Funguskappen. Sie wachsen in Büscheln tief drinnen in der Uldaman-Grabungsstätte; vielleicht kann man sie auch anderswo finden, aber bisher ist das der einzige mir bekannte Ort, an dem sie gedeihen. Ich möchte ihren potenziellen Nutzen für die Alchimie erforschen und dafür brauche ich Euch.\n\nFindet die magenta Funguskappen-Büschel und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pflanzen stoßen vielleicht Giftsporen aus, wenn man sie anstößt.\n\nWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!", objectives = { "Magenta Funguskappe x 12" } },
    [2240] = { title = "Die geheime Kammer", summary = "Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht. -", desc = "Jetzt zur anstehenden Aufgabe:\n\nEs gibt eine geheime Kammer, die Kammer von Khaz'mul, die erforscht werden muss. Das Problem dabei ist, dass die Kammer hinter einer riesigen verschlossenen Tür liegt! Glücklicherweise weiß ich, wie man sie öffnet.\n\nIch habe alles in dem Tagebuch hier auf dem Tisch beschrieben. Meine Leute und ich sitzen hier zurzeit fest ... also müsst Ihr die Kammer von Khaz'mul für uns finden, <Name>.\n\nLest mein Tagebuch, erforscht die Kammer und meldet Euch dann bei Ausgrabungsleiter Stormpike in der Forscherliga in Ironforge.", objectives = { "Erforschung der geheimen Kammer" } },
    [2258] = { title = "Reagenzien-Suche im Ödland", summary = "Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter.", desc = "<Name>, ich könnte Eure Hilfe gebrauchen, wenn Ihr Euch dazu in der Lage fühlt. Ich bin ein angesehener Alchimist und benötige Eure Unterstützung, um einige Reagenzien zu beschaffen, die im Ödland zu finden sind.\n\nIch brauche folgende Gegenstände, um meine Vorräte aufzufüllen: 5 Bussard-Muskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter. Natürlich könnt Ihr diese Reagenzien direkt von den lieben Tieren selbst bekommen; aber wenn Ihr keine Kämpfernatur seid, dann sucht Euch besser Freunde, die kämpfen können.\n\nBringt mir diese Gegenstände, dann springen ein paar Münzen für Euch dabei raus. Was sagt Ihr?", objectives = { "Bussardmuskelmagen x 5", "Klippenkojotenfangzahn x 10", "Felselementarsplitter x 5" } },
    [2278] = { title = "Die Platinscheiben", summary = "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon.", desc = "Die Kernstücke dieser Schatzkammer sind vier riesige Platinscheiben, von denen jede mit zahlreichen Siegelzeichen unbekannter Herkunft bedeckt ist. Als Ihr sie berührt, beginnt Eure Hand zu kribbeln. Unmittelbar, nachdem Ihr die Scheiben berührt habt, erscheint das Gesicht eines großen Steinbeobachters.\n\n\"Willkommen. Ich bin ein Hüter des Wissens. Die Schöpfungssynthese der Irdenen wurde hier in den Scheiben von Norgannon für diese Welt aufgezeichnet und aufbewahrt.\"\n\nIhr habt eine Fülle an bislang unbekanntem Wissen über die Welt entdeckt!", objectives = { "Bringt in Erfahrung, welche Lehre der Steinbehüter zu bieten hat." } },
    [2283] = { title = "Wiederbeschaffung der Halskette", summary = "Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt.", desc = "Wir haben Arbeit für Euch, falls Ihr den Mut habt, Euch daranzuwagen.\n\nTief im Ödland befindet sich Uldaman, eine Grabungsstätte. Wir haben eine Geschichte gehört von so einem dummen Paladin, der kürzlich dort gestorben ist. Das würde uns ja alles nicht interessieren, aber er hatte eine sehr wertvolle Halskette bei sich. Angeblich sind drei große Edelsteine dabei: ein Rubin, ein Saphir und ein Topas.\n\nKurz gesagt: Wir wollen die Kette haben und wir bezahlen GUTES SILBER, um sie zu kriegen. Vielleicht ist sie beschädigt, aber das tut nichts zur Sache. Wir reparieren sie, wenn Kratzer daran sein sollten.", objectives = { "Zerrissene Halskette" } },
    [2342] = { title = "Wiederbeschaffte Schätze", summary = "Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity.", desc = "Die Fledermausgehege mit diesem Besen auszukehren, das ist keine Aufgabe, die eines Garretts würdig wäre! Aber ich habe mit diesem verfluchten Job ein wenig Geld verdient und ich bin bereit, es für Euch auszugeben, wenn ich damit nur meine Situation verbessern kann.\n\nDie Lieblingswaffe der Familie Garrett liegt weggeschlossen in unserer Truhe in der südlichen Bankenhalle von Uldaman. Das rührt noch von den Zeiten her, da wir Garretts dort als Buddler schufteten. Ohne sie werde ich für alle Zeiten hier festsitzen und im wahrsten Sinne des Wortes diesen höllischen Fledermäusen hinterherkehren.\n\nBeschafft den Schatz meiner Familie wieder und bringt ihn mir! Helft mir dabei, mein Geburtsrecht einzufordern!", objectives = { "Familienschatz der Garretts" } },
    [2398] = { title = "Die verschollenen Zwerge", summary = "Sucht in Uldaman nach Baelog.", desc = "Die Grabungsstätte von Uldaman war nicht immer so überlaufen. Wir Zwerge von Ironforge kontrollierten früher das Gebiet, aber... das war, bevor die Troggs kamen. Sie kamen so schnell und waren so zahlreich, dass nicht einmal die Macht der Zwerge sie aufhalten konnte.\n\nUm ehrlich zu sein, kam ihr Angriff so plötzlich, dass ich fürchte, dass vielleicht einige unserer Leute hinter den feindlichen Linien festsitzen.\n\nMein Freund Baelog hatte eine kleine Gruppe Zwerge tief hinunter in die Grabungsstätte geführt, kurz bevor die Troggs auftauchten. Wenn er und seine Gefährten noch leben, dann möchte ich, dass Ihr sie findet." },
    [2418] = { title = "Kraftsteine", summary = "Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum.", desc = "Vor einiger Zeit hatte ich einen kleinen Zwischenfall mit den Zwergen der Schattenschmiede. Sie brachten mich in die Festung Angor, um dort zwei Arten von seltsamen Steinen zu untersuchen, wie sie in Uldaman vorkommen. Ich habe entdeckt, dass die Steine langlebige und stabile Kraftquellen darstellen, wenn sie richtig behandelt werden. Es ist schon erstaunlich, was man alles in dieser alten Grabungsstätte finden kann!\n\nJedenfalls warfen sie mich aus der Festung Angor raus, nachdem ich ihnen das Geheimnis der Steine verraten hatte, und begannen, in Uldaman nach weiteren Steinen zu graben.\n\nIch will diese Steine für mich! Bringt mir beide Arten von Steinen und ich bezahle Euch gut dafür!", objectives = { "Dentrium-Kraftstein x 8", "An'Alleum-Kraftstein x 8" } },
    [2500] = { title = "Reagenzien-Suche im Ödland", summary = "Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar.", desc = "<Klasse>, ich möchte Eure Dienste in Anspruch nehmen. Ich bin ein angesehener Alchimist und benötige Eure Unterstützung, um einige Reagenzien zu beschaffen, die im Ödland zu finden sind.\n\nIch brauche folgende Gegenstände, um meine Vorräte aufzufüllen: 5 Bussard-Muskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter. Natürlich könnt Ihr Euch diese Reagenzien von den Viechern selbst holen; aber wenn Ihr keine Kämpfernatur seid, dann sucht Euch besser Freunde, die kämpfen können.\n\nBringt mir diese Gegenstände, dann springen ein paar Münzen für Euch dabei heraus.\n\nAlso, was sagt Ihr?", objectives = { "Bussardmuskelmagen x 5", "Klippenkojotenfangzahn x 10", "Felselementarsplitter x 5" } },
    [2768] = { title = "Wünschel-mato-Rute", summary = "Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle.", desc = "Sergeant Bly hat mich bestohlen! Er sagte, er wolle sie sich nur ausleihen, aber er hat meine geliebte Wünschel-mato-Rute gestohlen! Wo soll ich denn bitte ohne diese Rute wissen, wo ich neue Wasserlöcher graben muss?\n\nFindet Bly und bringt mir meine Rute! Ich habe gehört, er hätte seine Bande von zwielichtigen Abenteurern auf eine Schatzsuche nach Zul'Farrak im Westen geführt. Ich möchte wetten, dort findet Ihr ihn.\n\nHoffen wir, dass die Trolle ihn schon erledigt haben, denn falls Ihr Euch wegen der Rute mit ihm anlegen müsst, dann steht Euch ein schwerer Kampf bevor.", objectives = { "Wünschel-mato-Rute" } },
    [2770] = { title = "Gahz'rilla", summary = "Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe.", desc = "Tief im Inneren von Zul'Farrak, der Stadt der Sandtrolle in Tanaris, liegt ein hochheiliger Teich. An diesem Teich beschwören die Trolle eine gewaltige Bestie, Gahz'rilla! Der ist so wild, dass sogar seine Schuppen vor Energie knistern. Und genau diese Energie will ich in meinem Wagen einsetzen.\n\nBringt mir die energiegeladene Schuppe von Gahz'rilla!\n\nWie man Gahz'rilla allerdings beschwört, das verraten die Trolle niemandem. Wenn Ihr ihm begegnen wollt, müsst Ihr daher erst den Trollen das Geheimnis entreißen.", objectives = { "Gahz'rillas elektrisierte Schuppe" } },
    [2841] = { title = "Maschinenkriege", summary = "Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar.", desc = "Vor zwei Jahren noch hat man sich jedesmal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben sie eine neue Maschine gebaut, die besser ist als all unsere Schreddermodelle zusammen. Ich brauche die Blaupausen dafür, <Name>!\n\nDummerweise sind die Pläne in einem Safe bei Robogenieur Thermaplugg sicher verwahrt. Was die Sache noch erschwert: Nur Robogenieur Thermaplugg kennt die Kombination zu diesem Safe.\n\nTut, was Ihr tun müsst, um diese Kombination zu erlangen, <Name>. Dann öffnet den Safe und bringt mir diese Blaupausen!", objectives = { "Maschinenblaupausen", "Thermapluggs Safekombination" } },
    [2842] = { title = "Chefingenieur Scooty", summary = "Sprecht mit Scooty in Booty Bay.", desc = "In dem Moment, als wir durch Kernobee von der neuen Gnomen-Maschine hörten, haben Scooty und ich mit der Arbeit am Transpolyporter 6000 begonnen: dem schnellsten und verlässlichsten Weg nach Gnomeregan.\n\nEndlich ist er bereit, Passagiere aufzunehmen, <Name>. Wenn Ihr es einmal versuchen wollt, geht nach Booty Bay und redet mit Scooty am Windreiterhorst. Um nach Booty Bay zu gelangen, nehmt das Boot von Ratchet aus.\n\nNatürlich könnt Ihr auch versuchen, Euch durch die von Zwergen verseuchten Berge von Dun Morogh nach Gnomeregan durchzuschlagen!" },
    [2843] = { title = "Gnomer-weeeeg!", summary = "Wartet, bis Scooty den Goblin-Transponder kalibriert hat.", desc = "Solange Ihr den Transponder bei Euch habt, müsst Ihr lediglich auf diese Plattform hier treten und Ihr werdet nach Gnomeregan teleportiert.\n\nIhr werdet vielleicht ein paar ungewöhnliche Nebenwirkungen erleben, aber keine davon sollte dauerhaft sein... zumindest nicht mehr.\n\nIch hätte fast den wichtigsten Teil vergessen - die Rückkehr. Wenn Ihr wieder zurückkommen wollt, tretet einfach auf die Transpolyporter-Plattform in Gnomeregan!\n\nJetzt lasst uns diesen Transponder auf Euer Gewicht und Eure Größe einstellen.", objectives = { "Goblin-Transponder" } },
    [2846] = { title = "Tiara der Tiefen", summary = "Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow.", desc = "Vor langer Zeit besaß ich ein wunderschönes Schmuckstück, die Tiara der Tiefen. Diese war nicht nur schön, sondern enthielt auch große Macht für diejenigen, die damit umzugehen wussten.\n\nAls nun die Kunde von der Tiara die Wasserbeschwörerin Velratha erreichte, musste sie sie haben. Sie schickte Handlanger in mein Haus und die stahlen sie, während ich weg war. Diese Diebe!\n\nIch will meine Tiara wiederhaben! Geht nach Zul'Farrak, der Trollstadt in Tanaris, findet Velratha und ringt ihr die Tiara ab. Bringt sie mir zurück und Ihr steht in meiner Gunst.", objectives = { "Tiara der Tiefen" } },
    [2864] = { title = "Tran'rek", summary = "Sprecht mit Tran’rek in Gadgetzan.", desc = "Mein Vetter Tran’rek ist in Schwierigkeiten. Er versprach mir vor einer Woche eine Fuhre Skarabäuspanzerschalen und hat bisher nicht geliefert. Er ist mein Vetter, also würde ich es wirklich hassen, wenn ich jemanden nach Gadgetzan schicken müsste, um ihm etwas zu brechen.\n\nKönnt Ihr für mich mit Tran'rek sprechen? Lasst ihn wissen, dass er diese Lieferung zusammenbekommen muss, bevor ich irgendetwas Unüberlegtes mache.\n\nGadgetzan liegt im nördlichen Tanaris, in Kalimdor." },
    [2865] = { title = "Skarabäuspanzerschalen", summary = "Bringt Tran’rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen.", desc = "Die Skarabäen von Tanaris haben sehr harte Panzerschalen! Hart genug, um sie als Baumaterial für eine Menge Dinge zu verwenden. So viele Dinge!\n\nTatsächlich sind diese Panzer so nützlich... dass die Skarabäen beinahe bis zur Ausrottung gejagt wurden.\n\nIch weiß, wo es noch mehr Skarabäen gibt, und wenn Ihr mir versprecht, mir Ihre Panzerschalen zu bringen, sage ich Euch, wo sie sind. Versprochen?\n\nO.k., die Skarabäen haben eine Kolonie in Zul’Farrak. Ich schätze, die Trolle jagen sie nicht wegen ihrer Panzerschalen.\n\nAber Ihr könnt das tun! Geht nach Zul’Farrak und besorgt mir unbeschädigte Skarabäuspanzerschalen!", objectives = { "Unbeschädigte Skarabäusschale x 5" } },
    [2904] = { title = "Eine schöne Bescherung", summary = "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay.", desc = "<Kernobee stöhn.t> Was... Was ist passiert?\n\nDas Letzte, an das ich mich erinnere, ist, wie ich von einer Gruppe Dunkeleisenzwerge gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde.\n\nHolt mich hier raus, <Name>!\n\nSo ist der Plan: Bringt mich zum Ausgang; Wenn wir es lebend hier herausschaffen, geht nach Booty Bay und lasst Scooty wissen, dass ich nach Ratchet gegangen bin, um Tinkerwiz zu warnen, dass die Dunkeleisenzwerge in die Herstellung dieser Supermaschine verwickelt sind.\n\nGehen wir!", objectives = { "Rettung von Kernobee" } },
    [2922] = { title = "Rettet Techbots Hirn!", summary = "Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge.", desc = "Als unsere geliebte Stadt Gnomeregan fiel, muss ein verirrter Funke mein armes Geschöpf, Techbot, völlig durcheinander gebracht haben. Früher half er mir und meinen Kollegen mit seinen zahllosen Dingsdas und seiner endlosen Speicherkapazität, aber sein positronisches Gehirn wurde polarisiert. Es ist jetzt negatronisch... und Techbots Verhalten wurde umgekehrt. Er wütet jetzt in ganz Gnomeregan!\n\nDoch vielleicht kann man ihn noch retten. Wenn Ihr seinen Speicherkern auffinden und zu mir bringen könnt, kann ich die Ursache der Polarisierung möglicherweise finden und meinen armen Techbot reparieren.", objectives = { "Techbots Speicherkern" } },
    [2923] = { title = "Tüftlermeister Overspark", summary = "Sprecht mit Tüftlermeister Overspark in Ironforge.", desc = "Tüftlermeister Overspark ist ob des Schicksals seiner mechanischen Schöpfung, Techbot, ziemlich bestürzt. Ich erinnere mich an Techbot als ein freundliches und hilfsbereites Werkzeug der Gnome, aber Overspark erzählte mir, er hätte eine Fehlfunktion.\n\nWirklich traurig. Aber mit etwas Glück kann er vielleicht repariert werden!\n\nSprecht mit Tüftlermeister Overspark in Tüftlerstadt, Ironforge. Er würde sich über Eure Hilfe freuen." },
    [2924] = { title = "Grundlegende Artifixe", summary = "Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe.", desc = "Ein beinahe universell einsetzbares mechanisches Bauteil - das grundlegende Artifix - war den Tüftlern und Schmieden von Gnomeregan von großem Nutzen. Doch während der panischen Flucht aus unserer Stadt hat niemand daran gedacht, einige von diesen Geräten mitzunehmen! Und ich brauche eine ganze Menge davon für eine Arbeit, die ich in Kürze in Angriff nehmen werde.\n\nBitte, geht nach Gnomeregan und bringt mir einige grundlegende Artifixe. Ihr werdet sie in den tieferen Bereichen unserer Stadt finden, in \"Künstliche Extrapolatoren\" genannten Behältern.\n\nDanke, <Name>, und bitte beeilt Euch!", objectives = { "Grundlegendes Artifix x 12" } },
    [2926] = { title = "Gnogaine", summary = "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück.", desc = "Seit dem Unfall redet Gnoarn nur noch davon, Gnomeregan vom Troggbefall zu befreien und ein Heilmittel für die Erkrankung, die die Stadt verseucht, zu finden, <Name>.\n\nZum Glück sind Razzle und ich gerade dabei, ein solches Heilmittel zu entwickeln... oder vielleicht auch ein Rezept für wirklich starken Rum. Genau wissen wir das aber erst, wenn wir es ausprobiert haben! Logischerweise benötigen wir zum Test unserer Theorie ein paar Dinge, vor allem Ablagerungen von den bestrahlten Troggs in Gnomeregan. Füllt diese Phiole mit dem grünen Leuchten und bringt sie zurück!", objectives = { "Volle bleierne Sammelphiole" } },
    [2927] = { title = "Der Tag danach", summary = "Sprecht mit Ozzie Togglevolt in Kharanos.", desc = "Ihr glaubt doch wohl nicht, dass ich schon immer so kahlköpfig war, oder? Nein, <werter Herr/holde Dame>! Das Strahlungsleck in Gnomeregan rief diesen tragischen Haarverlust hervor. Vor jenem Tag hatte ich den einzigen Gnomen-Afro in ganz Azeroth.\n\n<Gnoarn schüttelt drohend die Faust.>\n\nVerdammt seien diese verdammten dreckigen Troggs, verdammt seien sie alle!\n\nVielleicht ist es noch nicht zu spät, <Name>. Wir können sie vielleicht immer noch retten - die Stadt, meine ich! Sprecht mit Ozzie Togglevolt in Kharanos. Er und sein Partner Razzle arbeiten an einer Lösung." },
    [2928] = { title = "Gyrobohrmatische Exkavation", summary = "Bringt 24 robomechanische Innereien zu Shoni nach Stormwind.", desc = "Es ist schrecklich, <Name>. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrobohrmatischen Exkavationatoren nach Dun Morogh zu bringen.\n\nWir brauchen Ersatzteile, <Name>. Und welch besseren Ort als Gnomeregan könnte es geben, um Ersatzteile für unsere Fahrzeuge zu besorgen? Es heißt, dass Bots und Mechs dort herumlaufen wie Vieh auf der Weide.\n\nIhr müsst für mich nach Gnomeregan gehen und diese Roboter auseinander nehmen. Bringt mir ihre Innereien. Zwei Dutzend sollten ausreichen.", objectives = { "Robomechanische Gedärme x 24" } },
    [2929] = { title = "Der große Verrat", summary = "Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist.", desc = "Ich habe Thermaplugg vertraut, <Volk>. Ich hätte nie vermutet, dass er mich und das ganze Gnomen-Volk verraten würde. Und wofür? Macht? Reichtum? Alles Dinge, die er mit der Zeit auch so erlangt hätte. Jetzt sind wir aus unserer Heimat verdrängt worden und dieser Wahnsinnige ist dafür verantwortlich. Der König des Nichts ...\n\nWir werden Gnomeregan zurückerobern, <Name>. Wir werden nicht ruhen, bis die Stadt wieder unter unserer Kontrolle steht. Wenn Ihr Euch unserem Kampf anschließen wollt, habe ich eine einfach Bitte an Euch: Tötet den Verräter. Vernichtet Robogenieur Thermaplugg.", objectives = { "Robogenieur Thermaplugg" } },
    [2930] = { title = "Datenrettung", summary = "Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte.", desc = "Als wir aus Gnomeregan flohen, haben wir so viele Daten zurückgelassen! Lebenswichtige Informationen!\n\nIch brauche die Daten auf einer Prismalochkarte aus einem Matrix-Prägographen 3005-D, einem Hochsicherheitsterminal, tief in Gnomeregan. Ihr müsst auf dieses Terminal zugreifen, aber dafür braucht Ihr die Zugangsberechtigung ... und um die zu erhalten, müsst Ihr erst Zugang zu den Terminals niedrigerer Sicherheitsstufen - Modelle A, B und C - haben. DAFÜR wiederum braucht Ihr Sicherheitslochkarten, angefangen mit einer weißen ... Und wir haben alle Lochkarten in der Stadt vergessen.\n\nDas ist eine Katastrophe! Könnt Ihr helfen?", objectives = { "Prismalochkarte" } },
    [2933] = { title = "Giftflaschen", summary = "Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle.", desc = "Diese Flaschen enthalten ein übles grünes Gift.\n\nWenn man die Anzahl der Flaschen in diesem Dorf bedenkt, müssen die Witherbarks ihn für sehr wichtig halten. Vielleicht will einer der Apotheker im nahe gelegenen Tarrens Mühle eine Probe davon." },
    [2934] = { title = "Unbeschädigter Giftbeutel", summary = "Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel.", desc = "Ich benötige eine frische Probe von dem Gift, den Ihr mir gebracht habt. Die Spinnen, von denen er gesammelt wurde, dürften im Hinterland leben. Jagt sie, bis Ihr einen unbeschädigten Giftbeutel findet, und bringt ihn mir. Ihr findet viele Spinnen nahe der Trollstadt Shadra'Alor.\n\nUnd trödelt nicht rum, <Name>, denn der Giftbeutel muss frisch sein, wenn Ihr ihn abliefert.", objectives = { "Unbeschädigter Giftbeutel" } },
    [2935] = { title = "Konsultiert Meister Gadrin", summary = "Sprecht mit Meister Gadrin in Sen'jin.", desc = "Das Gift der Brutwachen war nicht so potent wie das Gift, den Ihr mir ursprünglich gebracht habt. Er muss von einer anderen Spinne gewesen sein.\n\nIch will eine frische Probe dieses Gifts. Um herauszufinden, woher er kam, müsst Ihr Euch mit einem Troll unterhalten, der die Witherbark gut kennt - Meister Gadrin im Dorf Sen’jin. Reist nach Durotar und sprecht mit Gadrin. Wenn wir Glück haben, weiß er, woher die Witherbarks ihr Gift bekommen." },
    [2936] = { title = "Der Spinnengott", summary = "Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Witherbark zu erfahren, und kehrt dann zu Meister Gadrin zurück.", desc = "Die Witherbarks verehren einen Spinnengott und von ihm bekommen sie ihr wirkungsvolles Gift. Wenn Ihr also ihr Gift wollt, müsst Ihr ihren Gott beschwören!\n\nUm das zu tun, müsst Ihr seinen wahren Namen wissen und dieser Name steht auf einer Tafel, die in Tanaris, in der Trollstadt von Zul’Farrak, in einer Gruft vergraben ist, die von Theka dem Märtyrer bewacht wird.\n\nBesiegt Theka und findet und lest diese Tafel, um den Namen des Spinnengottes herauszufinden. Wenn Ihr ihn kennt, kehrt zu mir zurück.", objectives = { "Findet den Namen des Spinnengottes." } },
    [2945] = { title = "Schmutzverkrusteter Ring", summary = "Findet einen Weg, den schmutzverkrusteten Ring zu säubern.", desc = "Ihr habt bei einer der Leichen der Dunkeleisenzwerge etwas entdeckt, das wie ein Ring aussieht. Es ist jedoch schwer zu sagen, was für ein Ring das ist. Das Ding ist derart mit Dreck und Verkrustungen überzogen, dass man es unmöglich an einen Finger stecken kann. Ihr glaubt, unter den Verkrustungen Edelmetall schimmern und vielleicht sogar einen Edelstein glitzern zu sehen.\n\nWenn Ihr diesen Ring verwenden wollt, müsst Ihr nach etwas suchen, das die Verkrustungen entfernt." },
    [2951] = { title = "Der Funkelmat 5200!", summary = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", desc = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", objectives = { "Schmutzverkrustetes Objekt" } },
    [2962] = { title = "Das einzige Heilmittel ist mehr grünes Leuchten", summary = "Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen. Ozzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist.", desc = "Eure Probe war nicht nur von unzureichender Menge, sondern auch noch verunreinigt.\n\nWas wir brauchen, ist mehr von dem grünen Leuchten. Die Troggs sind offensichtlich nicht stark genug verstrahlt, um unseren Ansprüchen zu genügen. Ihr werdet nach Gnomeregan gehen und etwas der radioaktiven Ablagerung direkt von der Quelle besorgen müssen. Ich spreche von den bestrahlten Brühschleimern, Lauerern und Schrecken. Seid gewarnt, diese Art von Ablagerung ist schwer abzufüllen. Es könnte Euch mehrere Versuche mit der Phiole kosten, bis Ihr eine geeignete Probe bergen könnt.", objectives = { "Hochwirksame radioaktive Ablagerung" } },
    [2988] = { title = "Käfige der Witherbark", summary = "Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück.", desc = "Der Sohn unseres mächtigsten Greifen ist verschwunden! Sturmschwinges Erbe, Scharfschnabel, ging vor ein paar Tagen bei der Jagd mit seinen Eltern verloren und wir glauben, dass die Trolle ihn geschnappt haben.\n\nIhr müsst uns helfen! Durchsucht die Käfige in den beiden Dörfern der Witherbarktrolle, um herauszufinden, ob Scharfschnabel dort ist.", objectives = { "Überprüft den ersten Käfig.", "Überprüft den zweiten Käfig.", "Überprüft den dritten Käfig." } },
    [2989] = { title = "Der Altar von Zul", summary = "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück. -", desc = "Scharfschnabel war nicht bei den Witherbarktrollen. Vielleicht haben ihn die Vilebranchtrolle geholt. Geht zum Altar von Zul am Westrand des Territoriums der Vilebranch und sucht nach dem Greifenjungen.", objectives = { "Durchsucht den Altar von Zul." } },
    [2990] = { title = "Thadius Grimshade", summary = "Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande.", desc = "Bringt diese Feder zum Rutengänger Thadius Grimshade. Er verließ vor Jahren Aerie Peak, um sich dunklerem Wissen zuzuwenden, aber in seinem Herzen ist er immer noch ein Wildhammer!\n\nUnd vielleicht können uns seine Talente dabei helfen, Scharfschnabel zu finden.\n\nDiese Feder stammt aus dem Nest, in dem das Greifenjunge schläft. Wenn Ihr sie Thadius gebt, kann er mit etwas Glück seine Rutengangmagie verwenden, um Scharfschnabel zu finden.\n\nViel Glück, <Name>. Ihr werdet Thadius in den verwüsteten Landen finden, im Magierturm der Burg Nethergarde." },
    [2991] = { title = "Nekrums Medaillon", summary = "Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon.", desc = "Ich werde herausfinden, wo Euer Greif ist, aber erst müsst Ihr etwas für mich tun. Es gibt da einen Troll in Zul'Farrak, Nekrum der Ausweider, der ein Medaillon besitzt, das ich wirklich gern studieren würde. Bringt mir das Medaillon und ich werde meine Kräfte dafür verwenden, Scharfschnabel zu finden.\n\nZul’Farrak ist jenseits des Ozeans, im Westen, in der Wüste von Tanaris.", objectives = { "Nekrums Medaillon" } },
    [3042] = { title = "Trollaushärter", summary = "Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan.", desc = "Die Trolle der Sandfury von Zul'Farrak stellen ein Aushärtungsmittel aus Sandstein her, und ich kann dies verwenden, um die von mir hergestellten Waren auszuhärten, ja, so ist es! Von Kennern wird es hoch gepriesen; wenn Ihr mir also einen guten Vorrat dieses Härters bringt, werde ich Euch reich belohnen.\n\nZul'Farrak liegt nordwestlich von Gadgetzan. Viel Glück.", objectives = { "Trollaushärter x 20" } },
    [3341] = { title = "Das Ende bringen", summary = "Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt.", desc = "Im Brachland liegt ein schreckliches Dickicht aus ineinander verschlungenen Ranken, Hügel von Razorfen genannt. Unsere ersten Beobachtungen haben zwar auf keine große Bedrohung schließen lassen, aber die neuesten Funde geben doch allen Grund zur Sorge...\n\nDie Stacheleber der Hügel von Razorfen haben sich mit der Geißel zusammengetan. Ein Lich namens Amnennar der Kältebringer beherrscht sie jetzt und nutzt die Macht seines riesigen Bewusstseins, um jede ihrer Bewegungen zu kontrollieren.\n\nAmnennar verfügt über eine direkte telepathische Verbindung zu Ner'zhul. Diese Bindung müssen wir durchtrennen, <Name>. Dem Kältebringer muss ein Ende gemacht werden.", objectives = { "Schädel des Kältebringers" } },
    [3373] = { title = "Die Essenz des Eranikus", summary = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.", desc = "Als Ihr den Edelstein berührt, ertönt eine tiefe Stimme in Eurem Geist.\n\n\"Sterbliches Wesen, hört diese Bitte. Ich bin Eranikus vom grünen Drachenschwarm, der Hüter dieses verfluchten Tempels. Meine Aufgabe, sicherzustellen, dass die Trolle nie wieder ihre Monstrosität von einem Gott in diese Welt bringen, ist nun fehlgeschlagen. Während ich diesen Edelstein mit einem Teil meiner magischen Essenz fülle, fühle ich, wie mein Traum sich zum Chaos hinbewegt. Ich bitte Euch... legt diesen Edelstein in den Essenzborn in meinem Unterschlupf und lasst unsere Magie dort den Makel von meiner Psyche nehmen, sodass ich endlich ruhen kann.\"" },
    [3380] = { title = "Der versunkene Tempel", summary = "Sucht Marvon Rivetseeker in Tanaris.", desc = "Es gibt rastlose Geister in dieser Welt, <Name>. Es sind Geister, die durch ihre Einsamkeit besudelt wurden und an ein altes Übel gebunden sind...\n\nIch habe von einem Ort gehört, der tief unter der Erdoberfläche liegt... größere Mächte als ich jemals gesehen habe, haben ihn dorthin verbannt.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt, sucht einen Goblin namens Marvon Rivetseeker auf. Er hat viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er sein Heim in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen." },
    [3441] = { title = "Göttliche Vergeltung", summary = "Lasst Kalaran Windblade seine Geschichte erzählen.", desc = "Hört meine Geschichte, Abenteurer.", objectives = { "Kalarans Geschichte" } },
    [3442] = { title = "Die fehlerlose Flamme", summary = "Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Kalaran Windblade.", desc = "Ihr habt die richtige Entscheidung getroffen, <Name>.\n\nWir müssen dort zuschlagen, wo wir den größten Schaden anrichten: an den vier Wachpostentürmen.\n\nWenn die vier Wachpostentürme in Flammen stehen, starten wir eine Offensive, bevor sie reagieren können.\n\nIhr benötigt das passende Werkzeug, um die Türme in Brand zu setzen. Für die Herstellung des Werkzeugs wird einiges an Materialien benötigt.\n\nBringt mir vier Herzen der Flamme und vier Kugeln Golemöl, und ich werde die Fackel der fehlerlosen Flamme herstellen können.\n\nIhr solltet Euch also zuerst die Golems und Elementare dieses Landes vornehmen.", objectives = { "Herz der Flamme x 4", "Golemöl x 4" } },
    [3443] = { title = "Das Schmieden des Schafts", summary = "Bringt 8 mit Thorium beschichtete Dolche zu Kalaran Windblade.", desc = "Um die fehlerlose Flamme halten zu können, brauchen wir noch einen Schaft und eine Ummantelung. Ihr müsst zunächst einen geeigneten Schaft finden.\n\nDie Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge des Kessels benutzen Waffen aus verzaubertem Thorium, eine besonders stabile Legierung. Wenn Ihr mir acht mit Thorium beschichtete Dolche bringen könnt, kann ich die Legierung aufbrechen und einen Schaft schmieden.", objectives = { "Thoriumbeschichteter Dolch x 8" } },
    [3444] = { title = "Der runde Stein", summary = "Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.", desc = "Ich habe einst die furchteinflößenden Kammern des Versunkenen Tempels betreten. Das Böse an jenem Ort durchdringt alle, die eintreten. Mit Mühe und Not habe ich es geschafft, irgendwie meinen Weg wieder nach draußen zu finden, indem ich durch den Brühschlamm watete, der jetzt den Boden bedeckt. Ich kann mich nur daran erinnern, dass ich durch einen großen, kreisrunden Raum gestolpert bin, der angefüllt war mit Schlangenstatuen ...\n\nKürzlich habe ich einen runden Stein entdeckt, der anscheinend das gleiche Schlangensymbol trägt. Ich habe ihn verpackt und in meine Werkstatt nach Ratchet geschickt. Bringt ihn her und ich kann Euch vielleicht mehr erzählen.", objectives = { "Steinkreis" } },
    [3446] = { title = "In die Tiefen", summary = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.", desc = "Im Tempel fand ich einen kreisrunden Raum mit sechs Altaren, und am Rand eines jeden stand eine Schlangenstatue. Neugierig drückte ich gegen eine von ihnen, um zu sehen, was passieren würde. Es war eine Falle! Durch die Explosion wurde ich fast getötet. Als ich da auf einem Vorsprung lag, sah ich nach unten und bemerkte, dass eine weitere Statue unten im Raum stand; es war ein Altar der Art ... Hakkar, ich glaube, so wurde er genannt.\n\nIch denke, dass dieser Altar das Geheimnis ist ... Ihr müsst dieses Zeichen zum Altar in den Versunkenen Tempel bringen." },
    [3447] = { title = "Das Geheimnis des Kreises", summary = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt.", desc = "Meine Erinnerungen sind verworren, aber ich werde Euch alles sagen, was ich weiß. Der Kreis der Statuen im Versunkenen Tempel mag ja gefährlich sein, ich glaube dennoch, dass sie das Geheimnis eines noch größeren Schatzes in sich bergen.\n\nVom Hauptaltar aus konnte ich eine Reihe von Lichtern aktivieren. Ich glaube, dass Ihr, wenn Ihr die Bedeutung dieser Lichter herausfindet, auch die weiteren Geheimnisse lüften könnt, die sich in diesem Raum verstecken.\n\nAber ich warne Euch, <Name>. In dem Tempel ist etwas unermesslich Böses. Es ist anzunehmen, dass alles Wertvolle äußerst streng bewacht wird." },
    [3452] = { title = "Die Ummantelung der Flamme", summary = "Bringt ein Symbol von Ragnaros zu Kalaran Windblade.", desc = "Wir brauchen noch ein letztes Teil, um die Fackel zu formen.\n\nIn den Bergen nordwestlich von hier könnt Ihr ein großes Lager der Twilight-Hammer finden. Es heißt, dass sie Symbole und Götzenbilder zur Verehrung ihres Gottes mit sich herumtragen. Diese Symbole und Götzenbilder besitzen vielleicht genügend Verzauberung, um daraus eine magische Ummantelung herzustellen. Bringt mir ein einziges Symbol von Ragnaros und ich werde versuchen, die Magie aus dem Gegenstand zu extrahieren, um die Ummantelung zu erschaffen.", objectives = { "Symbol von Ragnaros" } },
    [3453] = { title = "Die Fackel der Vergeltung", summary = "Wartet bis Kalaran Windblade die Fackel der Vergeltung vollendet hat.", desc = "Gebt mir einen Augenblick, um die Teile zusammenzufügen und die notwendigen Verzauberungen anzuwenden.", objectives = { "Fackelerschaffung" } },
    [3454] = { title = "Die Fackel der Vergeltung", summary = "Nehmt die Fackel der Vergeltung.", desc = "Die Fackel muss jetzt an ihren Besitzer gebunden werden. Nehmt die Fackel auf, <Name>." },
    [3462] = { title = "Knappe Maltrake", summary = "Sprecht mit dem Knappen Maltrake.", desc = "Sprecht mit meinem Gesandten, dem Knappen Maltrake. Er wird Euch weiter unterweisen, wie die Fackel der Vergeltung zu benutzen ist." },
    [3463] = { title = "Setzt sie in Brand!", summary = "Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", desc = "Hört gut zu, <Name>. Obgleich die vier Türme niemals zerstört werden können, könnt Ihr dennoch die Fackel der Vergeltung benutzen, um sie für lange Zeit in Brand zu setzen. Ein Feuer, das kein Element und keine Macht löschen kann.\n\nWährend sie in Flammen stehen, kann keine Wache oder Wachposteneinheit die Posten besetzen, und so ist ihre erste Verteidigungslinie außer Kraft gesetzt.\n\nIhr müsst in jeden Turm eindringen und die Fackel der Vergeltung innerhalb ihrer Befestigung verwenden. Nehmt Euch in Acht vor den Elitewachposteneinheiten der Dunkeleisenzwerge, <Name>.", objectives = { "Westturm in Flammen", "Südturm in Flammen", "Ostturm in Flammen", "Nordturm in Flammen" } },
    [3481] = { title = "Plunder...", summary = "Öffnet die Truhe.", desc = "Die Truhe scheint verschlossen zu sein." },
    [3520] = { title = "Kreischergeister", summary = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", desc = "Ich suche die Geister der Talkreischer von Feralas. Sie sind die Cousins eines alten, alten Gottes und ihre Geister sind mit ihm verbunden.\n\nNehmt diesen Dornbuschzauberstab und reist nach Feralas. Sucht und besiegt die Talkreischer in Süd- und Mittel-Feralas, und schwingt meinen Dornbuschzauberstab dann über ihre gefallenen Körper. Dadurch wird ihr Geist dazu gebracht, sich zu zeigen. Berührt den Geist und sammelt seine Essenz.\n\nKommt mit meinem Dornbuschzauberstab und der gesammelten Essenz zu mir zurück, und ich werde Euch mehr von dem alten Gott erzählen, von dem ich sprach.", objectives = { "Gesammelte Kreischergeister x 3" } },
    [3523] = { title = "Geißel der Niederungen", summary = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.", desc = "Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht. Ja, richtig gehört, ich sagte Geißel; sie haben anscheinend mit den Stachelebern hier eine Art Vereinbarung getroffen, und dieser Alptraum ist das Ergebnis.\n\nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber Ihr scheint ein Typ zu sein, dem das nicht viel ausmacht." },
    [3525] = { title = "Ausschalten des Götzen", summary = "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen. Beschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten.", desc = "In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; die Bestien... verzehren die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und verhindern, dass sie ihn erneut nutzen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. Wenn sie mich erschlagen, dann ist alles aus.\n\nSteht Ihr mir bei?", objectives = { "Belnistrasz beschützen, während er das Ritual durchführt, um den Götzen auszuschalten" } },
    [3527] = { title = "Die Prophezeiung von Mosh'aru", summary = "Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.", desc = "Die alte Prophezeiung von Mosh'aru berichtet von einer Methode, die Essenz des Gottes Hakkar zu bewahren. Sie wurde auf zwei Schrifttafeln niedergeschrieben und zu der Troll-Stadt Zul'Farrak gebracht, westlich von Gadgetzan.\n\nBringt mir die Mosh'aru-Schrifttafeln!\n\nDie erste Schrifttafel hat der Troll Theka der Märtyrer, der schon lange tot ist. Man sagt, dass seine Verfolger zu Skarabäen verflucht wurden und nun an seinem Schrein herumhuschen.\n\nDie zweite Schrifttafel hat die Wasserbeschwörerin Velratha, in der Nähe des hochheiligen Teiches von Gahz'rilla.\n\nWenn Ihr die Schrifttafeln habt, bringt sie zu mir.", objectives = { "Erste Mosh'aru-Schrifttafel", "Zweite Mosh'aru-Schrifttafel" } },
    [3528] = { title = "Der Gott Hakkar", summary = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.", desc = "Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen.\n\nBringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth. Ruft die Macht des Eies an, um den toten Gott aufzuwecken.\n\nEr wird seine Diener gegen Euch ausschicken. Besiegt seine Bluttrinker und nehmt ihr Hakkari-Blut an Euch; dann benutzt das Blut, um die ewigen Flammen auszulöschen, die Hakkars Geist halten. Erst wenn alle Flammen gelöscht sind, wird der Avatar von Hakkar unsere Welt betreten.\n\nBesiegt ihn und gebt seine Essenz in das Ei von Hakkar.", objectives = { "Gefülltes Ei von Hakkar", "Essenz von Hakkar" } },
    [3636] = { title = "Das Licht bringen", summary = "Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet.", desc = "Die Geißel ist eine dauerhafte Bedrohung für die Allianz. Ich bin sicher, Euch ist diese Tatsache vertraut. Kürzlich erst stießen wir auf einige sehr seltsame Funde, <Name>.\n\nIm Brachland gibt es ein fürchterliches Dickicht von Dornsträuchern, das Hügel von Razorfen heißt. Früher war es die Heimat von einfachen Stachelebern, aber nun ist offensichtlich, dass ein Pakt mit der Geißel geschlossen wurde, die viel schlimmere Kreaturen hervorbrachte... Sie werden jetzt von dem Lich, Amnennar dem Kältebringer, beherrscht.\n\nStellt Euch auf die Seite des Lichts, <Name>, und macht diesem bösen Verbund ein Ende.", objectives = { "Amnennar der Kältebringer" } },
    [3701] = { title = "Die glimmenden Ruinen von Thaurissan", summary = "Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.", desc = "Begebt Euch zu den glimmenden Ruinen von Thaurissan in der brennenden Steppe und sammelt so viele Informationen wie möglich.\n\nEs heißt, dass geheimnisvolle Relikte in den Ruinen verstreut seien. Vielleicht solltet Ihr Eure Suche dort beginnen, <Name>. Nehmt Euch vor den Thaurissan-Wächtern in Acht: Es sind Auftragsmörder, die die Ruinen bewachen und die dort möglicherweise noch immer begrabenen Geheimnisse beschützen, wie auch immer sie aussehen mögen.", objectives = { "Informationen besorgt x 12" } },
    [3702] = { title = "Die glimmenden Ruinen von Thaurissan", summary = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.", desc = "Würdet Ihr gern einen Überblick über die Geschichte der Dunkeleisenzwerge erhalten?", objectives = { "Die Geschichte von Thaurissan" } },
    [3765] = { title = "Verderbnis in der Fremde", summary = "Reist zu Gershala Nightwhisper in Auberdine.", desc = "Stormwind - geschäftiger Dreh- und Angelpunkt der Aktivität.\n\nIch bin weit gereist, um Hilfe zu suchen. Man hört häufig, dass mutige Abenteurer durch die Straßen dieser Stadt ziehen.\n\nMein Bruder Gershala benötigt Hilfe in Dunkelküste. Er lebt in der Küstenstadt Auberdine.\n\nDie Reise ist lang und abenteuerlich. Daher suche ich nach Hilfe. Es sollte ein erfahrener <Klasse> sein, so wie Ihr." },
    [3801] = { title = "Dunkeleisenerbe", summary = "Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten.", desc = "Seid gegrüßt, <Name>. Ich bin Franclorn Forgewright. Ja, der Franclorn Forgewright, der für die Stonewrought-Methode der Architektur verantwortlich ist. Ihr habt zweifellos während Eurer Abenteuer in unserer vom Krieg zerrissenen Welt eines meiner Werke durchquert oder habt auf einem gestanden.\n\nIhr fragt Euch wahrscheinlich, warum ich hier bin und was ich von Euch möchte - beides berechtigte Fragen.\n\nIch brauche natürlich Eure Hilfe. Im Austausch für Eure Hilfe gewähre ich Euch den Schlüssel zu den Tiefen meiner verfluchten Stadt." },
    [3802] = { title = "Dunkeleisenerbe", summary = "Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright.", desc = "Ihr findet Fineous Darkvire jenseits des Rings des Gesetzes in der Halle des Handwerks. Tötet den elenden Wicht und nehmt Ironfel an Euch.\n\nBringt Ironfel zum Schrein von Thaurissan und legt den Hammer an seinen rechtmäßigen Ort: in die Hände der Statue, die mir zu Ehren aufgestellt wurde.\n\nSobald dieses getan ist, öffnet sich das Fach, in dem ich den Hauptschlüssel verborgen habe. Wichtiger jedoch ist: Ironfel wird für alle Zeiten in meinen Händen bleiben. Sollte jemand versuchen, den Hammer zu entfernen, werden Statue und Hammer bersten und für immer verloren sein.", objectives = { "Ironfel" } },
    [3906] = { title = "Disharmonie der Flamme", summary = "Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt.", desc = "Die Ältesten haben eine Störung der Elemente gespürt. Die Dunkeleisenzwerge haben einen üblen Geist in unsere Welt beschworen, durch den unser Land von einer ewigen Dürre heimgesucht werden könnte. Die Disharmonie der Flamme muss untersucht werden.\n\nBegebt Euch zum Blackrock und dann durch die Flammenschlucht in den Steinbruch. Dort werdet Ihr diesen Herrn des Feuers finden: Übermeister Pyron.\n\nMacht der Störung ein Ende und kehrt dann zu mir zurück.", objectives = { "Übermeister Pyron" } },
    [3907] = { title = "Disharmonie des Feuers", summary = "Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart.", desc = "Ich kann die Verderbtheit in der Luft, die Euch umgibt, riechen, <Name>. Es gibt einen anderen, versteckt in den Tiefen von Blackrock, der diese Verderbtheit kontrolliert.\n\nDer Wind und die Erde schreien seinen Namen hinaus: Lord Incendius. Doch irgendjemand ... irgendetwas ... gebietet über dieses Wesen. Er ist nichts weiter als ein Abgesandter.\n\nSucht ihn und findet heraus, wo sich sein Meister versteckt hält. Kehrt zu mir zurück, sobald Ihr diese Information gesammelt habt.", objectives = { "Lord Incendius", "Schrifttafel von Kurniya" } },
    [3981] = { title = "Kommandant Gor'shak", summary = "Sucht Kommandant Gor'shak in den Blackrocktiefen. Ihr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen.", desc = "Der arme Gargal... er wurde davon völlig überrascht. BUMM! Der tödliche Pfeil traf ihn genau oben an seinem Kopf. Er war vorher schon kein Genie, aber jetzt...\n\n<Galamav zieht eine Grimasse.>\n\nAls wir den Pfeil herauszogen, sahen wir, dass eine zusammengerollte Notiz an seinem Schaft befestigt war. Die Notiz war ein primitiv gezeichnetes Bild eines Orcs hinter Gittern mit der Unterschrift von Commander Gor'shak.\n\nFalls er noch am Leben sein sollte, dort unten in den Tiefen, dann müsst Ihr ihn finden.\n\nEine Falle, sagt Ihr? Ach nee, Dumpfhuf! Deswegen geht ja auch Ihr und nicht wir!" },
    [3982] = { title = "Was ist los?", summary = "Verteidigt Gor'shak.", desc = "Ich wurde unter der Schirmherrschaft von Thrall hierher geschickt. Glaubt Ihr wirklich, diese Clowns könnten mich fangen? Ich habe mich fangen lassen, um so Informationen sammeln zu können.\n\n<Gor'shak flüstert.>\n\nDie Prinzessin von Ironforge wurde von Imperator Thaurissan entführt. Prinzessin Bronzebeard befindet sich in dieser Stadt! Ich wette, dem alten Magni ist fast das Herz stehen geblieben, als er diese Neuigkeiten gehört hat.\n\n<Gor'shak lacht.>\n\nPssst! Hört Ihr das? Es kommen Wachen! VERTEIDIGT EUCH!", objectives = { "Den Ansturm überleben" } },
    [4001] = { title = "Was ist los?", summary = "Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar. Ihr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten.", desc = "Bisher war meine Kommunikation mit dem Zwerg Kharan in der Zelle auf der anderen Seite der Halle nur sehr eingeschränkt möglich. Doch ich konnte ihn immerhin davon überzeugen, dass ich - oder besser - dass wir ihm nichts Böses wollen.\n\nGeht und redet mit ihm und erfahrt so viel über die Prinzessin und ihre Entführer wie nur möglich. Bringt diese Informationen dann dem Kriegshäuptling.\n\nThrall will nicht, dass der Prinzessin ein Leid geschieht. Er hat irgendeinen großen Plan, und der umfasst auch, dass sie wieder sicher nach Ironforge zurückgebracht wird. Kharan weiß das alles schon ... Geht!", objectives = { "Kharans Informationen" } },
    [4002] = { title = "Das östliche Königreich", summary = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen.", desc = "Ihr bringt ganz ausgezeichnete Nachrichten, <Name>.\n\nAls Kriegshäuptling ist es meine Aufgabe, das zu tun, was das Beste für die Horde ist. Zu garantieren, dass die nachfolgenden Generationen nicht in einer hoffnungslosen Existenz gefangen sein werden.\n\nJetzt ist uns die einzigartige Chance, die Allianzen der Zukunft zu formen, in den Schoß gefallen. Wenn wir jetzt den Zwergen helfen, könnte dies unsere Beziehungen zum östlichen Königreich enorm verbessern. Und aus genau diesem Grund dürft Ihr nicht versagen!\n\nSeid Ihr bereit?" },
    [4003] = { title = "Die königliche Rettung", summary = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber.", desc = "Der Schlag gegen die Dunkeleisenzwerge wird, wenn er denn erfolgreich verläuft, eine Schockwelle durch ihr ganzes Königreich jagen.\n\nPrinzessin Bronzebeard ist unter der Kontrolle von Imperator Thaurissan. Um sie zu befreien, müsst Ihr den Imperator töten. Doch seid gewarnt, denn Eure Aufgabe ist doppelt gefährlich. Zweifellos wird Euch Prinzessin Bronzebeard angreifen, solange sie noch der Kontrolle des Imperators unterliegt.\n\nIHR DÜRFT IHR KEIN LEID ZUFÜGEN!", objectives = { "Imperator Dagran Thaurissan" } },
    [4022] = { title = "Eine Kostprobe der Flamme", summary = "Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windblade erhalten habt.", desc = "Der Klan ist sich Eurer Arbeit in der sengenden Schlucht bewusst.\n\nZeigt sie mir, <Volk>. Die abgestreifte Drachenhaut, Schwachkopf!", objectives = { "Abgestreifte Haut des schwarzen Drachenschwarms", "Beweis erbracht" } },
    [4024] = { title = "Eine Kostprobe der Flamme", summary = "Begebt Euch in die Blackrocktiefen und tötet Bael'Gar. Ihr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen. Bringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.", desc = "Ich möchte die sengenden Flammen des Feuerberges schmecken. Die flüssigen Feuer des Blackrock über mich strömen lassen. Diese Essenz, diese sengende Hitze ist es, nach der ich mich sehne.\n\nIn den Tiefen des Blackrock haust Bael'Gar: ein Wesen aus reinstem Feuer, geboren aus den Flammen des Ragnaros. Tötet Bael'Gar und bringt mir aus seinen glimmenden Überresten einen Teil seines inneren Feuers.\n\nVerwendet die Drachenhaut für seine Überreste, um die innere Flamme sicher entnehmen zu können.\n\nSeid erfolgreich und Ihr werdet belohnt.", objectives = { "Eingeschlossene feurige Essenz" } },
    [4061] = { title = "Aufstieg der Maschinen", summary = "Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter. Euch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter.", desc = "Wir stießen bereits bei unseren ersten Streifzügen in der sengenden Schlucht auf die Maschinen. Weitere Nachforschungen ergaben, dass sie aus der brennenden Steppe, eventuell auch aus den Blackrocktiefen, stammen. Und dafür brauchen wir Euch, <Name>.\n\nEure erste Aufgabe besteht darin, Euch in die brennende Steppe zu begeben und dort einige Elementarsplitter von den Felsautomatons und den geringen Felsgeschöpfen der Gegend zu beschaffen. Sobald Ihr eine ausreichende Menge gesammelt habt, kehrt zu mir zurück, dann werde ich herausfinden, woher sie wirklich stammen.", objectives = { "Gerissener Elementarsplitter x 10" } },
    [4062] = { title = "Aufstieg der Maschinen", summary = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus. Ihr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert.", desc = "G.L.A.\n\nDas sind die Buchstaben, die in die Elementarsplitter eingeprägt sind. Unter den Initialen findet sich eine Markierung für einen Rang oder etwas in der Art. Die Maschinen, die Ihr in der brennenden Steppe zerstört habt, hatten den 'Rang IV'. Ich nehme an, das ist ein eher niedriger Rang.\n\nBringt diese Splitterprobe in das Lager im Osten zu Lotwil Veriatus. Er ist ein Gelehrter und vor allem für seine Arbeit auf dem Gebiet der Elementarforschung bekannt. Vielleicht kann er uns bei unserer Suche helfen." },
    [4063] = { title = "Aufstieg der Maschinen", summary = "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt.", desc = "Das kann doch nicht Argelmach sein... Argelmach wurde vor zehn Jahren getötet. Warum ich das so genau weiß? Weil ich derjenige war, der ihn getötet hat.\n\nEr war ein abscheulicher Zwerg und wild entschlossen, mein Lebenswerk zu verderben und es für seine teuflischen Zwecke zu benutzen. Wie es scheint, finden die Tückischen immer einen Weg, ihrer gerechten Strafe zu entgehen.\n\nWenn dies Argelmachs Werk ist, dann muss er zerstört werden. Ich brauche Proben seiner jüngsten Schöpfungen. Mit den richtigen Proben kann ich vielleicht diesem Aufstand ein Ende machen. Die Schöpfungen bewachen Argelmach in den Blackrocktiefen.", objectives = { "Argelmachs Kopf", "Intakter Elementarkern x 10" } },
    [4081] = { title = "SOFORT TÖTEN: Dunkeleisenzwerge", summary = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren! Kriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", desc = "Auf Befehl von Kriegsherr Goretooth, Kommandant des Expeditionskorps von Kargath:\n\nAlle Streitkräfte, über die General Zornesschmied in den Blackrocktiefen verfügt, müssen ausgelöscht werden.\n\nZornesschmieds Männer sind rücksichtslose Killer und verantwortlich für den Massenmord an der 109. Division des Expeditionskorps von Kargath. Alle Helden, die diesen gefühllosen Bestien gegenübertreten wollen, werden aufgefordert, extreme Vorsicht walten zu lassen.\n\nJede Person, die die erste Kampfreihe von General Zornesschmieds Streitkräften in den Blackrocktiefen vernichtet, wird einen Tribut erhalten.", objectives = { "Gardist der Zorneshämmer x 15", "Aufseher der Zorneshämmer x 10", "Fußsoldat der Zorneshämmer x 5" } },
    [4082] = { title = "SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge", summary = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren! Kriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", desc = "Auf Befehl von Kriegsherr Goretooth, Kommandant des Expeditionskorps von Kargath:\n\nDer Leiter der Aufklärungseinheit des KEK, Großmeister Lexlort, kam mit Neuigkeiten über den Verbleib einiger hochrangiger Führungskräfte der Dunkeleisenzwerge zurück. Hinter dem verschlossenen Tor, nahe dem Herzen der Stadt, bilden sie ihre Streitkräfte darin aus, unsere Männer auszulöschen. Geht in die Blackrocktiefen und vernichtet sie!\n\nWer diese Mission erfüllt, erhält einen Tribut.", objectives = { "Sanitäter der Zorneshämmer x 10", "Soldat der Zorneshämmer x 10", "Offizier der Zorneshämmer x 10" } },
    [4121] = { title = "Gefährliche Zwickmühle", summary = "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht. Euch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen. Ihr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen.", desc = "Glaubt Ihr wirklich, dass Ihr es mit mir als Gefangenem zum vereinbarten Treffpunkt schafft? Habt Ihr wirklich gedacht, Ihr könntet in eine schwer bewachte Festung der Blackrock eindringen und völlig unbemerkt ihren wertvollsten Besitz entführen?\n\nMan wird Euch vernichten!", objectives = { "Thoriumfesseln", "Gefangenentransport" } },
    [4122] = { title = "Grark Lorkrub", summary = "Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden. Wenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.", desc = "Ich habe ihn durch die ganze sengende Schlucht, durch den Berg und in die brennende Steppe hinein verfolgt. Der Verräter wurde auf frischer Tat dabei ertappt, wie er den Blackrockorcs wichtige Informationen über die tagtäglichen Vorgänge bei uns lieferte. Ich spreche von Grark Lorkrub.\n\nEr sitzt jetzt in der brennenden Steppe, sicher unter deren Schutz - glaubt er jedenfalls.\n\nNehmt diese Fesseln, <Name>. Findet Grark, legt ihm die Fesseln an und führt ihn durch den Blackrock. Wenn Ihr das tut, ist ein Tribut Euer." },
    [4123] = { title = "Das Herz des Berges", summary = "Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe.", desc = "Schon seit Jahren suche ich einen ganz bestimmten Edelstein. Er wird das 'Herz des Berges' genannt und ist so groß wie Eure Faust! Die Dunkeleisenzwerge haben den Stein in ihrem Gewölbe weggeschlossen und ich kann machen, was ich will, sie wollen ihn mir einfach nicht verkaufen!\n\nAlso muss ich Gewalt anwenden.\n\nKämpft Euch zum unteren Gewölbe der Blackrocktiefen durch, brecht in den geheimen Safe dort ein und holt Euch das Herz. Dazu müsst Ihr den Wachmann Stahlgriff besiegen, aber der taucht erst auf, wenn Ihr jeden Reliktkasten im Gewölbe geöffnet habt!\n\nViel Glück.", objectives = { "Das Herz des Berges" } },
    [4126] = { title = "Hurley Pestatem", summary = "Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept.", desc = "Die Dunkeleisenzwerge, angeführt von dem Bösewicht Hurley Pestatem, haben eines der besten Rezepte der Donnerbräus gestohlen, jenes für das Donnerbräu Lagerbier. Diese Schurken! Sie verdienen ein solch edles Gebräu nicht!\n\n<Name>, ich habe eine schwierige Aufgabe für Euch. Geht zu den Blackrocktiefen in der brennenden Steppe, zerstört alle Fässer mit Donnerbräu Lagerbier, die Ihr finden könnt, und bringt unser Donnerbräurezept zurück!\n\nBitte, bringt das Rezept unbedingt zurück, und wenn Ihr dafür die ganzen Blackrocktiefen umkrempeln müsstet!", objectives = { "Verlorenes Donnerbräurezept" } },
    [4128] = { title = "Ragnar Donnerbräu", summary = "Sprecht mit Ragnar Donnerbräu.", desc = "Hallo, <Name>. Wie ich hörte, soll Ragnar Donnerbräu außer sich vor Wut sein, dass jemand sein Bier gestohlen hat. Er sucht nach wackeren Abenteurern und ist gewillt, sie reichlich zu entlohnen.\n\nSprecht mit Ragnar, wenn Ihr Interesse habt. Ihr findet ihn in der Brauerei Donnerbräu in Kharanos in Dun Morogh." },
    [4132] = { title = "Operation: Tod dem Zornesschmied", summary = "Begebt Euch zu den Blackrocktiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Goretooth zurück, sobald Ihr diese Aufgabe erledigt habt.", desc = "Ihr habt bemerkenswerte Arbeit geleistet, <Name>. Jetzt ist es an der Zeit, Euch auf Eure letzte Mission zu schicken.\n\nGeneral Zornesschmied, der für die Koordination der Angriffe auf die 109. Division des KEK und die massive Dezimierung unserer Truppen verantwortliche Dunkeleisenzwerg, muss zur Rechenschaft gezogen werden.\n\nDies wird zweifellos Eure schwerste Mission werden, aber solltet Ihr erfolgreich sein, wird man Euch reich entlohnen.", objectives = { "General Zornesschmied" } },
    [4133] = { title = "Vivian Lagrave", summary = "Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath.", desc = "Schattenmeisterin Vivian Lagrave benötigt Eure Dienste. Sie lebt im Ödland, im Orc-Außenposten Kargath, wo sie dem Gerücht nachgeht, nach dem die Dunkeleisenzwerge der Blackrocktiefen angeblich ein bestimmtes Gebräu herstellen.\n\nSprecht mit Vivian. Sie erwartet Euch." },
    [4134] = { title = "Verlorenes Donnerbräurezept", summary = "Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept.", desc = "Es geht das Gerücht umher, dass der Dunkeleisenzwerg Hurley Pestatem ein Rezept zum Brauen von Bier gestohlen habe. Dieses Bier, das Donnerbräu Lagerbier, soll angeblich jeden, der es trinkt, mit großer Kraft und Mut erfüllen. Wir möchten dieses Getränk gern untersuchen. Vielleicht finden wir ja noch andere Anwendungsgebiete für seine Vorzüge... Anwendungsgebiete, die eher im Einklang mit den Zielen der Verlassenen sind.\n\nDurchforstet die Blackrocktiefen, findet Hurley, nehmt das Donnerbräurezept von ihm und bringt es mir.\n\nUnd um ihn zu finden, müsst Ihr ihn möglicherweise locken, indem Ihr sein wertvolles Bier bedroht.", objectives = { "Verlorenes Donnerbräurezept" } },
    [4136] = { title = "Ribbly Screwspigot", summary = "Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf.", desc = "Mein Bruder Ribbly hat unserer Familie schon immer auf der Tasche gelegen, unser Geld genommen und es für eine Dummheit nach der anderen ausgegeben.\n\nTja, seine letzte Dummheit muss wohl seine bislang schlimmste gewesen sein, denn Baron Revilgaz von Booty Bay hat ein Kopfgeld auf den armen Ribbly ausgesetzt. Ich kann Euch gar nicht sagen, wie glücklich das die Screwspigots macht! Endlich ist unser kleiner Ribbly mal etwas wert!\n\nEr versteckt sich jetzt allerdings ganz weit unten in den Blackrocktiefen. Sucht ihn doch bitte und bringt ihn zu mir!\n\nUnd falls er nicht mitkommen will, ist das auch kein Problem ... bringt mir einfach seinen Kopf.", objectives = { "Ribblys Kopf" } },
    [4141] = { title = "Muigin und Larion", summary = "Sammelt 15 Blutblüten und kehrt zu Muigin zurück.", desc = "Seht Ihr Larion da drüben? Es ist SEINE Schuld, dass wir hier sind!\n\nIch hab ihm noch gesagt, dass wir in die falsche Richtung gehen, aber hat er auf mich gehört? Und stellt Euch vor, jetzt spricht er nicht mehr mit mir. Na ja, erlauben wir uns doch ein kleines Späßchen mit ihm, bis er es sich anders überlegt.\n\nSind Euch die seltsamen pflanzenartigen Kreaturen in dieser Gegend hier aufgefallen? Die machen nichts als Ärger, wirklich, aber ich glaube, wenn man sie ordentlich abrichten würde, könnte man sie dazu bringen, Befehlen zu gehorchen.\n\nAls Erstes bräuchte ich allerdings ein paar davon, um sie zu studieren. Meint Ihr, Ihr könntet mir ein paar bringen?", objectives = { "Blutblüte x 15" } },
    [4142] = { title = "Ein Besuch bei Gregan", summary = "Bringt Gregan Brewspewer in Feralas eine Blutblüte.", desc = "Ich weiß nicht so recht, was ich davon halten soll, <Name>. Die Pflanzen... sie scheinen ein gewisses Maß an Intelligenz zu besitzen.\n\nAllerdings bin ich auf diesem Gebiet kein Experte. Aber ich kenne einen!\n\nGeht nach Nord-Feralas und sucht einen Freund von mir auf, er heißt Gregan Brewspewer. Er kennt sich mit solchen Dingen bestens aus.\n\nGregan kann uns bestimmt weiterhelfen. Ihr findet ihn draußen in der Wildnis, denn für das Großstadtleben hat er nicht viel übrig." },
    [4143] = { title = "Der Dunst des Bösen", summary = "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Un'Goro Krater.", desc = "Um ehrlich zu sein, <Name>, solche Pflanzen habe ich auf meinen Reisen noch nie gesehen. Vielleicht sollte ich mal einen Ausflug zu diesem Krater machen...\n\nEgal, ich weiß vermutlich, was Muigin benötigt - Dunst der Atal'ai. Das ist ein abscheuliches Zeug, sehr schwer zu sammeln, aber es ist genau das, was er benötigt, um diese kleinen Monster unter Kontrolle zu bringen.\n\nIhr müsst zum Tempel von Atal'Hakkar in den Sümpfen des Elends gehen. Den Dunst der Atal'ai bekommt Ihr von Tieflauerern, Düsterwürmern oder Brühschlammern, die man dort findet. Viel Glück, <Name>!", objectives = { "Dunst der Atal'ai x 5" } },
    [4145] = { title = "Larion und Muigin", summary = "Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marshals Zuflucht.", desc = "Seht Ihr Muigin da drüben? Es ist SEINE Schuld, dass wir uns verirrt haben!\n\nIch kannte den richtigen Weg, aber er bestand darauf, eine Abkürzung zu nehmen, und so sind wir hier gelandet!\n\nUnd um die Lage noch zu verschlimmern, schickt er mir jetzt auch noch seine verrückten Pflanzen, um mich zu ärgern. Ich bin so wütend, dass ich bis auf weiteres kein Wort mehr mit ihm reden werde, aber diese Quälgeister sind wirklich unerträglich.\n\nWarum versuchen wir nicht als Erstes, seinen Bestand ein bisschen zu dezimieren? Geht hinaus und jagt einige Blutblüten und kehrt dann zu mir zurück.", objectives = { "Blutblütenpeitscher x 5", "Blutblütenfalle x 5", "Blutblütenschinder x 5", "Blutblütendrescher x 5" } },
    [4146] = { title = "Schrumpf-Treibstoff", summary = "Bringt Larion in Marshals Zuflucht den ungeladenen Schrumpfer und 5 Proben Dunst der Atal'ai.", desc = "Ihr habt Glück, <Name>! Während Marvon fort war, habe ich an einigen meiner eigenen Experimente gearbeitet, eines davon ist ein Käferschrumpfer mit kurzer Reichweite. Nur noch ein paar kleine Änderungen, dann ist er perfekt, um damit diese Blutblütenplagen zu beseitigen.\n\nIhr könnt gern einen meiner Schrumpfer-Prototypen haben, aber Ihr benötigt noch etwas Treibstoff dafür. Den für den Schrumpfer benötigten Dunst der Atal'ai findet Ihr im Tempel von Atal'Hakkar. Ihr bekommt ihn von Tieflauerern, Düsterwürmern oder Brühschlammern.", objectives = { "Dunst der Atal'ai x 5" } },
    [4147] = { title = "Marvons Werkstatt", summary = "Reist zu Marvon Rivetseekers Werkstatt in Ratchet.", desc = "Ich habe herausgefunden, was Muigin so treibt. Er züchtet da drüben doch tatsächlich diese verdammten Dinger!\n\nIch glaube, die einzige Lösung des Problems besteht darin, mit... nein, nicht mit ihm zu sprechen... Was für ein Blödsinn! Die Lösung ist zurückzuschlagen!\n\nWir brauchen die Hilfe meines Freundes Marvon, der in Ratchet eine Werkstatt hat. Er kann bestimmt irgendein Gerät zusammenbasteln, das uns helfen wird." },
    [4182] = { title = "Drachkin-Bedrohung", summary = "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.", desc = "Das Leben in der brennenden Steppe ist voller Konflikte.\n\nSeht Euch nur mal diesen Ort an! Wir wissen nur sehr wenig darüber, was mit diesen Gebäuden geschehen ist, aber wir wissen, dass all das hier irgendwann vor der großen Explosion einmal Teil der Rotkammbergkette war.\n\nAber genug gejammert! Wir haben ein Problem, <Name>. Vielleicht sind Euch die Drachkin am Fuß dieses Bergkamms aufgefallen. Wir brauchen Hilfe, um sie zurückzuschlagen. Tötet so viele, wie Ihr könnt, und kommt dann zu mir zurück. Wenn Ihr erfolgreich seid, können wir uns vielleicht noch über andere Dinge unterhalten.", objectives = { "Schwarzer Brutling x 15", "Schwarze Großdrachenbrut x 10", "Schwarzdrache", "Schwarzwyrmkin x 4" } },
    [4183] = { title = "Die wahren Meister", summary = "Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus.", desc = "Bislang nahmen wir an, dass die Blackrockorcs das Ergebnis ihrer primitiven Erziehung seien. Was wir jedoch hier, in ihrem Heimatland, entdeckt haben, erzählt uns eine ganz andere Geschichte.\n\nAngetrieben werden sie zwar tatsächlich von Kampfrausch und Streitlust, aber der schwarze Drachenschwarm ist es, der die Orcs von Blackrock beherrscht. Wir vermuten, dass es auch der schwarze Drachenschwarm ist, der ihre Wut und Feindseligkeit schürt.\n\nBringt diesen Brief zu Magistrat Solomon. Er wird wissen, was zu tun ist.\n\n<Helendis gibt Euch einen versiegelten Brief.>" },
    [4184] = { title = "Die wahren Meister", summary = "Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor. Bolvar residiert in der Burg Stormwind.", desc = "Das sind schlimme Neuigkeiten, <Name>. Zu entdecken, dass unsere Todfeinde nicht mehr als Marionetten einer viel größeren Bedrohung sind, ist wahrlich entmutigend. Es ist unmöglich, dass Seenhain einen Angriff durch die Blackrockorcs UND den schwarzen Drachenschwarm überleben könnte. Wenn Seenhain dieser Gefahr anheim fällt, dann fällt bald auch Dunkelhain, und was dann? Goldhain? Auch Stormwind?\n\nIhr müsst diese Information unbedingt sofort Hochlord Bolvar Fordragon in Stormwind überbringen! Wenn dies nicht die Unterstützung Stormwinds rechtfertigt, dann ist alles verloren." },
    [4185] = { title = "Die wahren Meister", summary = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.", desc = "Solomon malt da ein recht düsteres Bild aus. Aber wir können es uns leider nicht leisten, unsere dünn gesäten Truppen aufgrund von reinen Vermutungen nach Seenhain zu schicken. Ich brauche einen Beweis für diese Behauptungen, bevor ich handeln kann.\n\nSprecht mit Lady Prestor, <Name>. Sie ist eine kluge Frau und weiß viel über Großdrachen und Drachkin. Vielleicht kann sie ein bisschen Licht in die Sache bringen.", objectives = { "Rat von Lady Prestor" } },
    [4186] = { title = "Die wahren Meister", summary = "Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus.", desc = "Ich ernenne Euch hiermit zum kommissarischen Deputy von Stormwind, <Name>.\n\nKehrt zu Magistrat Solomon in Seenhain zurück und übergebt ihm diesen Erlass." },
    [4201] = { title = "Der Liebestrank", summary = "Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Blackrocktiefen.", desc = "Oh, wie schmerzhaft doch die Liebe ist! Mein geliebter Gefreiter Rocknot ist immun gegen meinen Charme. Er verschmäht mich! Es ist zum Verrücktwerden!\n\nIhr müsst mir helfen! Wir Sukkubi wissen viel über die Liebe und ich kann einen Trank herstellen, der den eisernen Panzer um Rocknots Herz erweichen könnte. Dazu benötige ich folgende Dinge: das Kraut Gromsblut, Riesensilbervenen von den Klippenriesen Azsharas sowie Wasser aus dem Golakka-Quellen-Krater in Un'Goro. Ihr könnt das Wasser in diese Phiole füllen.\n\nBitte, <Name>, verhelft einer armen Seele zum Glück!", objectives = { "Gromsblut x 4", "Riesensilbervene x 10", "Nagmaras gefüllte Phiole" } },
    [4223] = { title = "Die wahren Meister", summary = "Sprecht mit Marshal Maxwell in der brennenden Steppe.", desc = "<Magistrat Solomon seufzt.>\n\nIhr müsst in die brennende Steppe zurückkehren, <Name>. Als Deputy von Stormwind erwartet man von Euch, dass Ihr Euch bei Marshal Maxwell meldet. Viel Glück." },
    [4224] = { title = "Die wahren Meister", summary = "Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt. Ihr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen.", desc = "Was? Ihr dachtet, Ihr wärt der Erste? Wie viele Soldaten müssen wir noch verlieren, bevor Stormwind handelt?\n\nWir hatten riesige Mengen an Informationen über die Blackrockbedrohung zusammengetragen, doch dann verloren wir unseren befehlshabenden Offizier, Marshal Windsor. Zusammen mit Marshal Windsor gingen auch all unsere wertvollen Informationen verloren.\n\nWas wir brauchen, ist diese Dokumentation. Sprecht mit dem struppigen John, <Name>. Er war mit Windsor zusammen, als sie von einem Stoßtrupp der Blackrock überfallen wurden. Er wurde zuletzt in einer Höhle im Norden gesehen.", objectives = { "Die Geschichte des struppigen John" } },
    [4241] = { title = "Marshal Windsor", summary = "Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist. Ihr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt.", desc = "Dieser nichtsnutzige Feigling behauptet also, Windsor sei noch am Leben, was?\n\nMacht Euch bereit, Deputy, Ihr werdet ausziehen, um ihn zu suchen. Falls Windsor noch am Leben ist, müsst Ihr ihn zurückholen. Sollte er tot sein, brauche ich einen Beweis dafür.\n\n<Maxwell lacht.>\n\nIch wette, das könnt Ihr langsam schon nicht mehr hören, was?" },
    [4242] = { title = "Verlorene Hoffnung", summary = "Überbringt Marshal Maxwell die schlechten Neuigkeiten.", desc = "Bolvar ist ein Dummkopf. Ich war gerade dabei, ihm seinen kostbaren 'Beweis' zu beschaffen, um ihm diesen in den Hals stopfen zu können.\n\nEr ist ein blinder Blödmann. Selbst wenn der Beweis ihn in die Nase beißt, würde er ihn nicht sehen.\n\nWas meine Informationen angeht, die sind verloren. Unwiderbringlich.\n\nSollte ich Ironfoe jemals finden und es aus diesem Labyrinth herausschaffen, wird mein erster Halt Stormwind sein, damit ich diesem Reptil meinen Hammer über den Schädel ziehen kann.\n\nGeht jetzt, <Name>." },
    [4262] = { title = "Übermeister Pyron", summary = "Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück. Ihr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?", desc = "Die letzten fünf meiner Magier, die ausgezogen waren, um sich auf dem Blackrock umzusehen, kamen knusprig geröstet zurück, mit einem dauerhaften orangefarbenen Gnomen-Afro - oder noch schlimmer.\n\n<Jalinda nimmt etwas Asche vom Boden auf und lässt sie vom Wind davontragen.>\n\nEin besonders mieses Individuum, Übermeister Pyron, scheint hier eine Menge Ärger zu verursachen. Dieser Elementar muss vernichtet werden, damit unser Expeditionsteam in die Blackrocktiefen reisen kann!\n\nEr bewacht den Eingang am Blackrocksteinbruch.", objectives = { "Übermeister Pyron" } },
    [4263] = { title = "Incendius!", summary = "Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!", desc = "Seid Ihr sicher, dass Pyron 'Incendius' sagte, als er starb?\n\n<Jalinda schluckt schwer.>\n\nLord Incendius soll angeblich einer von Ragnaros Dienern sein! Oje, oje... was sollen wir jetzt nur tun?\n\nMeint Ihr, Ihr könntet noch eine weitere Mission bewältigen? Ich habe niemand anderen, den ich schicken könnte, <Name>!\n\nWir werden niemals eine Gruppe hineinbringen, solange Incendius Pyron aus der Asche immer wieder neu erstehen lässt.\n\nIhr müsst Lord Incendius suchen und vernichten!", objectives = { "Lord Incendius" } },
    [4264] = { title = "Eine zusammengeknüllte Notiz", summary = "Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung.", desc = "Die Notiz ist mit Flecken übersät. Der Text ist kaum noch lesbar, aber Ihr könnt Folgendes erkennen:\n\n... süße Ironie...\n\n... der Sturz der zerbrochenen Allianz...\n\n... ohne General Angerfords Sorgfalt hätten wir das Schema der Verschlüsselung niemals herausgefunden...\n\n... Argelmach hat Windsors Notizen fast entschlüsselt.\n\nUnser Lord wird sich aus den Tiefen erheben und alle zerschmettern, die noch übrig sind...\n\nImperator Dagran Thaurissan" },
    [4282] = { title = "Ein Funken Hoffnung", summary = "Holt Marshal Windsors verloren gegangene Informationen zurück. Marshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden.", desc = "<Marshal Windsor wedelt aufgeregt mit der Notiz herum.>\n\nWisst Ihr, was das bedeutet, <Name>?\n\nVielleicht ist doch noch nicht alles verloren! Soweit ich das erkennen kann, wird die Information von zwei Dunkeleisenzwergen verwahrt: General Zornesschmied und dem Golemlord Argelmach. Ich habe das Gefühl, als würden sie die Information nicht einfach so herausrücken, wenn wir sie freundlich darum bitten.\n\nAlso hoffe ich, dass Ihr auf einen Kampf vorbereitet seid.\n\nZieht aus und findet die beiden Bösewichte! Vernichtet sie und bringt mir meine verloren gegangenen Informationen zurück.", objectives = { "Marshal Windsors verlorene Informationen", "Marshal Windsors verlorene Informationen" } },
    [4286] = { title = "Feine Sachen", summary = "Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen.", desc = "Käpt'n Winky sagt mir, dass die Dunkeleisenzwerge in den Tiefen das ganze gute Zeug haben. Stimmt's nicht, Winky?\n\n<Oralius versucht, so gut es geht, einen Piraten zu imitieren.>\n\nHARRR, KUMPEL! DAS STIMMT!\n\nDa hört Ihr's. Ihr müsst Euch dorthin begeben und mir etwas von dem guten Zeug besorgen.\n\nGeht da rein und holt es Euch!", objectives = { "Dunkeleisengürteltasche x 20" } },
    [4322] = { title = "Gefängnisausbruch!", summary = "Helft Marshal Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marshal Windsor zurück, wenn Ihr Erfolg hattet.", desc = "Wir müssen hier weg, <Name>. Helft mir, meine Ausrüstung aus dem Vorratsbereich zu holen und meine Freunde zu befreien. Falls wir hier rauskommen, dann müsst Ihr Euch weiter nach Morgans Wacht durchschlagen und mit Marshal Maxwell sprechen. Er wird Euch weitere Anweisungen geben.", objectives = { "Gefängnisausbruch!" } },
    [4324] = { title = "Yuka Screwspigot", summary = "Sprecht mit Yuka Screwspigot in der brennenden Steppe.", desc = "Mein Bruder Ribbly war sein ganzes Leben lang zu nichts nütze; aber jetzt, glaube ich, hat er endlich einen gewissen Wert! Aber... wir werden Eure Hilfe brauchen, um aus Ribblys Wert Kapital zu schlagen.\n\nMeine Schwester Yuka hat ihn wochenlang gesucht und endlich in der brennenden Steppe gefunden. Sie hat mich wissen lassen, dass sie ein paar Helfer brauchen könnte.\n\nAlso, was meint Ihr? Wollt Ihr uns helfen? Falls ja, sprecht mit meiner Schwester. Ihr findet sie im Flammenkamm versteckt, in einer Höhle nordwestlich des Schreckensfelsens." },
    [4341] = { title = "Kharan Mighthammer", summary = "Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer. Der König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten.", desc = "Seid Ihr in den rauchenden Ruinen von Thaurissan gewesen? Seid Ihr dort zufällig einem erbärmlichen Tölpel namens Kharan Mighthammer begegnet? Dem Zwerg, der eigentlich über mein kleines Mädchen wachen sollte?\n\n<Der König schluchzt.>\n\nUnd jetzt ist sie verschwunden, <Name>!\n\nIch habe meine Leute die gesamte Steppe durchkämmen lassen. Doch der einzige Hinweis, den sie über den Verbleib meiner Tochter finden konnten, war, dass sie vielleicht in den Tiefen ist. Möglicherweise ist sie sogar schon tot!\n\nAngeblich wird Kharan dort als Gefangener festgehalten ... findet ihn! Ich will Antworten!" },
    [4361] = { title = "Der Überbringer schlechter Botschaften...", summary = "Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten.", desc = "Ihr müsst König Magni diese Informationen bringen, <Name>. Er wird wissen, was zu tun ist!" },
    [4362] = { title = "Das Schicksal des Königreichs", summary = "Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan.", desc = "Es scheint, als habe mein alter Widersacher, Dagran Thaurissan, mich und das ganze Königreich Ironforge in seiner Gewalt.\n\nVielleicht seid Ihr meine letzte Hoffnung, <Name>. Ihr müsst meine Tochter Moira retten!\n\nEs gibt nur einen Weg, wie der Zauber, mit dem Thaurissan Moira belegt hat, wirklich zuverlässig gebrochen werden kann: Ihr müsst ihn töten.\n\nAber, <Name>, meiner Tochter dürft Ihr kein Leid zufügen! Vergesst nicht, dass sie Thaurissans Kontrolle unterliegt! Alles, was sie vielleicht sagt oder tut, geschieht aufgrund von Thaurissans bösem Zauber!", objectives = { "Imperator Dagran Thaurissan" } },
    [4701] = { title = "Stellt sie ab", summary = "Begebt Euch zur Blackrockspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs.", desc = "Zweifellos habt Ihr die Worgs schon gesehen, die die Orcs der Blackrock befehligen.\n\nEs ist seltsam... ganz egal, wie viele wir vernichten, es scheinen nie weniger zu werden. Meine Späher haben berichtet, dass die Worgs gezüchtet, trainiert und schließlich von der Blackrockspitze exportiert werden: der Hauptstadt der Blackrockorcs. Ihr müsst Euch zur Blackrockspitze begeben und der Quelle dieser Bedrohung auf den Grund gehen. Ihr auf den Grund gehen... und sie vernichten.\n\nViel Glück, <Name>. Möge Cenarius Euch beschützen...", objectives = { "Halycon" } },
    [4724] = { title = "Die Herrin der Meute", summary = "Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte.", desc = "Manche sagen, die vom Blackrockklan kontrollierten Worgs seien durch eine übernatürliche Macht erschaffen worden. Andere wiederum sagen, es seien gar keine echten Worgs, sondern eine Art dämonische Hunde, die den Orcs von einem gefallenen Grubenlord überlassen wurden.\n\nDie Wahrheit ist wesentlich weniger weit hergeholt, aber nicht weniger erschreckend. Die Worgs von Blackrock stammen von Halycon und ihrem Partner. Halycon ist die gewaltige Höhlenmutter der Worgs. Und ihr Partner? Es hat noch niemand überlebt, der etwas über diesen Partner sagen konnte.\n\nTrefft die Worgs dort, wo es ihnen am meisten wehtut. Vernichtet Halycon ... aber, <Name>, seid auf der Hut.", objectives = { "Halycon" } },
    [4726] = { title = "Brutlingessenz", summary = "Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.", desc = "Schon seit Wochen studiere ich die Drachkin der brennenden Steppe und ich glaube, mir ist endlich ein Durchbruch gelungen! Ich habe ein Gerät gebaut - ich habe es \"Draco-Incarcinatrix 900\" getauft -, mit dem ich die Essenz von Großdrachenwelpenbrutlingen einfangen kann!\n\nOder zumindest glaube ich das.\n\nHier, nehmt das Gerät und zappt damit einen Brutling in der brennenden Steppe. Wenn Ihr den Brutling dann besiegt, während er sich noch unter dem Einfluss des Geräts befindet, dann sollte eigentlich seine Essenz freigesetzt werden.\n\nWenn dem so ist, dann prima! Bringt mir ein paar Proben zurück, damit ich sie studieren kann.", objectives = { "Brutlingessenz x 8" } },
    [4729] = { title = "Kiblers Exotische Tiere", summary = "Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler.", desc = "Wahrscheinlich fragt Ihr Euch, was ich hier draußen mache. Schaut Euch die Käfige an! Liegt es nicht auf der Hand?\n\nIch liebe Tiere, aber ich bin Händler von Beruf. Ich spüre exotische Tiere für die Reichen und Berühmten auf und dann zähme ich die Bestien, damit sie sich auch wie brave Tiere verhalten.\n\nJetzt fragt Ihr Euch wahrscheinlich, was Ihr für Kibler tun könnt. Die Antwort ist einfach: Nehmt den Bestienkäfig hier und beschafft mir ein paar Worgwelpen. Dafür zähme ich Euch auch einen Worg!", objectives = { "Gefangener Worgwelpe" } },
    [4734] = { title = "Ei-Frosten", summary = "Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst.", desc = "Ich habe hart an einem neuen Gerät gearbeitet, <Name> - dem Eiszilloskop! Es ist so konstruiert, dass es einen Strahl kalter Energie auf das Ei eines schwarzen Großdrachen abgibt und es einfriert! Könnt Ihr das für mich ausprobieren?\n\nIch habe gehört, dass die Großdrachen weit oben auf der Blackrockspitze einen Horst haben, wo sie ihre Eier ausbrüten. Da müsst Ihr hin, um das Eiszilloskop zu testen, und dann müsst Ihr mir sagen, wie es funktioniert hat!\n\nUnd seid unbesorgt. Gefrorene Dracheneier sollten harmlos sein. Bloß bei den ungefrorenen müsst Ihr Euch Sorgen machen!", objectives = { "Test des Eiszilloskop-Prototypen" } },
    [4735] = { title = "Eiersammlung", summary = "Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.", desc = "<Name>, ich bin endlich bereit für echte Dracheneier! Hier, nehmt dieses kollektronische Modul. Es ist so konstruiert, dass es ein Drachenei extrahiert und für den Transport vorbereitet. Kehrt zum Horst zurück und verwendet das Modul, um Eier einzusammeln.\n\nAber vergesst nicht, sie vorher einzufrieren, sonst schlüpfen sie vielleicht aus, ehe Ihr sie einsammeln könnt!\n\nWenn Ihr genug Eier habt, dann bringt sie mir.", objectives = { "Eingesammeltes Großdrachen-Ei x 8" } },
    [4742] = { title = "Siegel des Aufstiegs", summary = "Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück. Vaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten.", desc = "Wie Ihr sehen könnt, befinden sich an dem unverzierten Siegel drei leere Sockel. Jeder dieser Sockel muss mit einem Edelstein gefüllt werden, der die Befehlsgewalt der Führungsspitze darstellt. Und schließlich muss Oberanführer Wyrmthalak, der Meister der unteren Zitadelle, das Siegel in den Flammen des schwarzen Drachenschwarms schmieden.\n\nEines müsst Ihr wissen, sterbliches Wesen: Die Wahrscheinlichkeit, dass einer der drei Generäle der unteren Zitadelle zu einer bestimmten Zeit einen der Edelsteine trägt, ist äußerst gering. Ihr dürft in Eurer Wachsamkeit nicht nachlassen. Bleibt entschlossen!", objectives = { "Edelstein der Felsspitzoger", "Edelstein der Gluthauer", "Edelstein der Blutäxte", "Unverziertes Siegel des Aufstiegs" } },
    [4764] = { title = "Doomriggers Schnalle", summary = "Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle.", desc = "Hoch droben auf der Blackrockspitze gibt es eine Kammer, die einst 'Halle des Glücks' genannt wurde. Dort bewahrten die Dunkeleisenzwerge ihre Relikte, Trophäen und Kunstobjekte auf.\n\nDoch das ist schon lange her. Man sagt, dass die Halle eingestürzt sei und jetzt für... weniger hehre Zwecke genutzt wird. Ich glaube jedoch, dass man dort immer noch so manch altes Zwergenrelikt finden kann.\n\nEines dieser Relikte ist Doomriggers Schnalle, deren Oberfläche so reich mit seltenen Edelsteinen verziert ist, dass angeblich jeder Zwerg bei ihrem Anblick in Verzückung geraten soll.\n\nDiese Schnalle ist Euer Ziel, <Name>.", objectives = { "Doomriggers Schnalle" } },
    [4766] = { title = "Mayara Brightwing", summary = "Sprecht mit Mayara Brightwing in der brennenden Steppe.", desc = "Eine meiner Agentinnen, Mayara Brightwing, wurde in die brennende Steppe entsandt, um die in Ruinen liegende Stadt Thaurissan zu erkunden. Diese zerstörte Stadt der Dunkeleisenzwerge könnte sehr wertvolle Objekte bergen... Objekte, die gar trefflich in unser Familienmuseum passen würden.\n\nMayara sagt, dass sie etwas gefunden hätte und nun Hilfe bräuchte, um es zu holen, allerdings befindet es sich nicht in Thaurissan. Stattdessen ist eine Exkursion zur Blackrockspitze nötig.\n\nIch weiß nichts Genaues, aber sprecht doch mit Mayara in der brennenden Steppe, falls Ihr interessiert seid." },
    [4768] = { title = "Die Darkstone-Schrifttafel", summary = "Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel.", desc = "Die Darkstone-Schrifttafel enthält die Niederschriften des vor langer Zeit verstorbenen Zwergs Urheld Darkstone. Er war ein äußerst fähiger Alchimist, den seine Zeitgenossen für verrückt hielten und der seine Forschungen daher für sich behielt.\n\nEr hielt jedoch alles auf Schrifttafeln fest und ich glaube, dass eine dieser Schrifttafeln auf der Blackrockspitze zu finden ist, in einer Kammer, die einst die 'Halle des Glücks' genannt wurde. Ich weiß nicht, wie man sie heute bezeichnet, denn nur wenige reisen nach Blackrock und kehren heil zurück.\n\nFalls Ihr jedoch gewillt seid, Euch den Gefahren dort zu stellen, und mir diese Schrifttafel bringt, erwartet Euch eine große Belohnung.", objectives = { "Darkstone-Schrifttafel" } },
    [4769] = { title = "Vivian Lagrave und die Darkstone-Schrifttafel", summary = "Sprecht mit Schattenmagierin Vivian Lagrave.", desc = "Vivian Lagrave aus Kargath im Ödland hat sich an mich gewandt. Aufgrund ihrer Studien ist sie davon überzeugt, dass es irgendwo auf der Blackrockspitze eine alte Niederschrift gibt, die nützlich für unsere Forschung sein könnte. Um dies zu bestätigen, benötigt sie jemanden, der diesen Text von der Blackrockspitze holt. Das ist keine leichte Aufgabe.\n\nFalls Ihr interessiert seid, sprecht in Kargath mit Vivian." },
    [4771] = { title = "Dämmerungstrickfalle", summary = "Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück.", desc = "Ich habe die Dämmerungstrickfalle in den Behälter gelegt, den Ihr uns gebracht habt, denjenigen, in dem sich die Dracheneier befanden. Euer Auftrag besteht darin, sie tief nach Scholomance hineinzubringen.\n\nDer untote Magier Vectus führt ein Team von Gelehrten der Geißel an... legt die Dämmerungstrickfalle in ihre Kammer, genannt der \"Vorführraum\". Sie wird dann mit den dort gefundenen Untoten reagieren und sie mit ein wenig Glück vernichten.\n\nDanach sollte es kein Problem sein, Vectus zu besiegen. Nicht wahr?", objectives = { "Vectus", "Dämmerungstrickfalle platzieren" } },
    [4787] = { title = "Das uralte Ei", summary = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris.", desc = "Mosh'arus Prophezeiung spricht von einem uralten Ei. Es ist ein Relikt aus einer Zeit, als die Trolle noch über riesige Reiche herrschten, und es hat die Kraft, die Essenz von Hakkar zu binden. Möglicherweise ist es das einzige Mittel, um unsere Welt vor diesem Bösen zu schützen.\n\nBringt mir das uralte Ei, <Name>. Man sagt, dass es tief verborgen in Jintha'Alor im Hinterland liegt, in einer Höhle hinter dem Amphitheater am obersten Punkt der Stadt.", objectives = { "Uraltes Ei" } },
    [4788] = { title = "Die letzten Schrifttafeln", summary = "Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.", desc = "Während ich die dritte und vierte Schrifttafel von Mosh'aru überprüfe, müsst ihr die fünfte und sechste finden! Es wird nicht einfach sein, da sie in den Händen der Trolle des Gluthauerstamms auf der Blackrockspitze sind. Die Spitze ist ein dunkler Berg aus Feuer zwischen der brennenden Steppe und der sengenden Schlucht.\n\nViel Glück, <Name>. Die Blackrockspitze ist kein Ort für anständige Leute ...", objectives = { "Fünfte Mosh'aru-Schrifttafel", "Sechste Mosh'aru-Schrifttafel" } },
    [4808] = { title = "Felnok Steelspring", summary = "Gebt Felnok Steelspring Tinkees Brief.", desc = "Ich habe noch eine weitere kleine Bitte an Euch.\n\nMeine anfänglichen Studien bezüglich der Essenz, die Ihr gesammelt habt, haben ergeben, dass es wohl möglich ist, Großdrachenwelpen-Eier einzufrieren und so zu konservieren! Ich möchte diese Theorie überprüfen, aber zuerst benötige ich speziell angefertigte Komponenten der Ingenieurskunst. Mein Kollege Felnok Steelspring kann sie herstellen.\n\nHier, bringt Felnok diesen Brief. Darin steht, was ich benötige. Ihr findet Felnok in Winterspring in der Stadt Everlook." },
    [4809] = { title = "Hörner der Eiswindschimären", summary = "Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre.", desc = "Ich habe fast alles, was Tinkee benötigt, aber mir fehlt eine wichtige Komponente, und das sind Eiswindschimärenhörner. Die Hörner der Eiswindschimären von Winterspring sind eine konzentrierte Kältequelle, aber man kann nur makellose, unbeschädigte Hörner verwenden! Ich brauche ein paar davon, um Tinkees Auftrag zu erfüllen.\n\nBringt mir unbeschädigte Hörner der Eiswindschimären, dann schnüre ich ein Päckchen für Tinkee zusammen.", objectives = { "Unbeschädigtes Horn einer Eiswindschimäre x 8" } },
    [4810] = { title = "Rückkehr zu Tinkee", summary = "Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen.", desc = "Gut, alles ist bereit und verpackt und transportfertig! Viel Glück auf Eurer Reise und richtet Tinkee aus, dass sie mir was schuldet!" },
    [4862] = { title = "Be-Öh-Es-Eh", summary = "Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler. Logischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden.", desc = "Ob Ihr es glaubt oder nicht, da draußen gibt es Leute, die gutes Geld selbst für die übelsten der abgerichteten Bestien ausgeben würden!\n\nIch würde ja Bijou zur Spitze schicken, um ein paar dieser Spitzenspinnen-Eier zu sammeln, aber ich habe seit Wochen nichts mehr von ihr gehört. Vielleicht könnt Ihr mir helfen?\n\nIch sag Euch was, <Name>. Geht zur Blackrockspitze und sammelt ein paar Spitzenspinnen-Eier für mich. Bringt sie mir, dann werde ich Euch nicht nur etwas Bargeld geben, sondern auch eines der Viecher für Euch abrichten!", objectives = { "Spitzenspinnenei x 15" } },
    [4866] = { title = "Muttermilch", summary = "Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.", desc = "Das dürfte eines der stärksten Gifte der Welt sein, <Volk>!\n\nIch habe bei meinen Ausflügen zur Spitze immer wieder gehört, wie die Leute von Blackrock davon sprachen, wie tödlich es sei. Sie nennen es 'Muttermilch', benannt nach Mutter Glimmernetz, der großen, grausamen Spinne in der Skitterwebhöhle.\n\nAlso, das müsst Ihr mir besorgen: eine frische Probe dieser Milch, die durch EURE Adern fließt. Mir einfach nur die Giftdrüse zu bringen, wäre nicht genug! Bringt sie dazu, Euch zu vergiften, und kommt dann zu mir zurück!\n\nDann... kann ich Euch melken!\n\n<Reibt sich voller Vorfreude die Hände.>", objectives = { "Gemolken" } },
    [4867] = { title = "Urok Schreckensbote", summary = "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.", desc = "Argh! Das Sprechen fällt schwer!\n\nNehmt diese Notiz! Holt mir mein Mojo.", objectives = { "Waroshs Mojo" } },
    [4903] = { title = "Befehl des Kriegsherrn", summary = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt.", desc = "Auf Befehl von Kriegsherr Goretooth müssen die nachfolgenden Bewohner der Blackrockspitze eliminiert werden:\n\nDie aufgeblasene Bedrohung, Hochlord Omokk.\n\nDer grausame und erbarmungslose Troll Kriegsmeister Voone.\n\nOberanführer Wyrmthalak, Zuchtmeister der geringen Stadt.\n\nDes Weiteren müsst Ihr alle wichtigen Dokumente zurückbringen, die Ihr möglicherweise findet.\n\nSeid erfolgreich und macht Euch Ehre.\n\nVersagt und seid vergessen.", objectives = { "Oberanführer Wyrmthalak", "Hochlord Omokk", "Kriegsmeister Voone", "Wichtige Blackrockdokumente" } },
    [4941] = { title = "Eitriggs Weisheit", summary = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat. Ihr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt.", desc = "Rend lebt?\n\nUnmöglich!\n\nEr soll doch schon vor Jahrzehnten getötet worden sein.\n\nBittet Etrigg, seine Weisheit mit Euch zu teilen, <Name>. Niemand kennt die Blackrock besser als er, und wenn es wahr ist, was hier geschrieben steht, muss Etrigg davon in Kenntnis gesetzt werden. Niemandem sollte das Recht auf Vergeltung versagt werden.\n\nIhr findet ihn in Orgrimmar.\n\nWenn Ihr mit Etrigg gesprochen habt, beratet Euch mit dem Kriegshäuptling, um von ihm zu erfahren, was er bezüglich dieses Problems zu unternehmen gedenkt.", objectives = { "Beratung mit Etrigg" } },
    [4974] = { title = "Für die Horde!", summary = "Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.", desc = "Nur weil der schwarze Drachenschwarm hinter ihm steht, wagt Rend es, solche Ansprüche zu stellen.\n\nIhr, <Name>, müsst einen Weg finden, die Hallen des Aufstiegs zu durchqueren. Dahinter findet Ihr den 'Kriegshäuptling' Rend Blackhand. Ihr müsst ihn vernichten... FÜR DIE HORDE!\n\n<Thrall schlägt mit der Faust auf seinen Thron.>\n\nWenn Ihr meine Gemächer das nächste Mal betretet, werdet Ihr seinen Kopf triumphierend in die Höhe halten und ihn Eurem Kriegshäuptling präsentieren. Gelingt Euch das, wird man Euch als Held der Horde ehren.", objectives = { "Rend Blackhands Kopf" } },
    [4981] = { title = "Agentin Bijou", summary = "Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist.", desc = "Trau niemals einem Goblin. Darauf läuft es doch hinaus, <Name>.\n\nSie heißt Bijou und ist eine unserer unzuverlässigsten Agentinnen. Ich habe herausgefunden, dass sie für irgendeinen zwielichtigen Tierhändler namens Kibler außerhalb der brennenden Steppe gearbeitet hat - sie hat uns schlicht und ergreifend hintergangen. Und was noch schlimmer ist, sie hat Gelder der Horde veruntreut, um ihre Machenschaften zu finanzieren.\n\nIch will, dass man sie mir lebend bringt!\n\nZuletzt wurde sie beim Betreten der Blackrockspitze gesehen. Findet sie und bringt sie her.\n\nUnd lasst Euch bloß nicht von ihr umgarnen, <Name>." },
    [5001] = { title = "Bijous Habseligkeiten", summary = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!", desc = "Normalerweise gebe ich mich nicht mit Euresgleichen ab, <Volk>, aber mir scheint, ich stecke hier in einer Zwickmühle. Wisst Ihr, meine Mission hier ist für die Horde von allergrößter Wichtigkeit. Die Informationen, die ich hier gesammelt habe, betreffen jedoch auch das Wohlergehen der Allianz. Ihr könnt mir glauben, ich bin wahrlich kein Freund der Allianz, aber die Gefahr durch die Blackrock ist größer als nur ein Haufen Orcs.\n\nIhr helft mir, meine Habseligkeiten zu finden, dann helfe ich Euch mit ein paar Informationen aus, die sich für Euresgleichen als nützlich erweisen könnten.\n\nAbgemacht?", objectives = { "Bijous Habseligkeiten" } },
    [5047] = { title = "Finkle Einhorn, zu Euren Diensten!", summary = "Sprecht mit Malyfous Darkhammer in Everlook.", desc = "Ihr findet Malyfous Darkhammer in Everlook, <Klasse>. Sagt ihm, dass Finkle absolut in Ordnung ist und dass der Anzug perfekt funktioniert.\n\nDann gebt ihm dies:\n\n<Finkle gibt Euch ein leuchtendes Fleischstück.>\n\nIch riss es aus den Innereien des Viechs während meines 'Urlaubs.'\n\nIch wette Malyfous könnte Euch eine recht genaue Einschätzung dessen geben, was er mit Teilen eines solchen Monsters tun kann!\n\nOh, ich schätze Ihr wisst nicht, wo Everlook ist, was? Geht nach Winterspring, <Bursche/Mädel>!" },
    [5065] = { title = "Die verlorenen Schrifttafeln von Mosh'aru", summary = "Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru.", desc = "Der Troll, mit dem Ihr gesprochen habt, hat Euch nicht die Wahrheit gesagt. Die beiden Schrifttafeln, die Ihr von ihm erhalten habt, sprachen davon, die Essenz von Hakkar zu bewahren, aber an dieser Legende ist noch mehr. Ich habe sie lange studiert und herausgefunden, dass es sechs Schrifttafeln von Mosh'aru gibt, nicht zwei! Sechs!\n\nUnd ich fürchte, dass uns die Geheimnisse, die die anderen enthalten, nicht gefallen werden.\n\nSucht die dritte und vierte Schrifttafel von Mosh'aru. Sie befinden sich in den Östlichen Pestländern, im Besitz der Moosschindertrolle. Sucht sie und bringt sie mir.", objectives = { "Dritte Mosh'aru-Schrifttafel", "Vierte Mosh'aru-Schrifttafel" } },
    [5089] = { title = "General Drakkisaths Befehl", summary = "Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe.", desc = "Dem Kadaver der besiegten Schlange entnehmt Ihr etwas, das wie ein Schreiben von einiger Bedeutung aussieht. Es ist ein Brief des Vorgesetzten, General Drakkisath, bezüglich des Protokolls.\n\nEuer Instinkt sagt Euch, dass Ihr ihn zu Marshal Maxwell bringen solltet." },
    [5102] = { title = "General Drakkisaths Niedergang", summary = "Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.", desc = "Wir kämpfen an zwei Fronten gegen diese Biester: Von unserer Hauptstadt Stormwind aus bekämpfen wir sie von innen, und hier, in der brennenden Steppe, tragen wir den Kampf an ihre Türschwelle. Wir müssen wachsam sein, <Name>. Niemand soll von unserem Zorn verschont werden, da keiner der Unseren verschont wurde, als der Feind bei unseren Heimen und Familien zuschlug.\n\nFindet diesen General Drakkisath und erledigt ihn!\n\nDie Aufgabe ist sicherlich nicht einfach, aber die Belohnungen werden großartig sein.", objectives = { "General Drakkisath" } },
    [5122] = { title = "Das Medaillon des Glaubens", summary = "Die Macht dieser Kapelle gibt mir die Kraft, der Verderbnis in meinem Herzen zu widerstehen. Wenn ich sie verlasse, werde ich zu einem Todesritter. Aber es gibt ein Medaillon, das Medaillon des Glaubens, das mir so viel Kraft geben wird, dass ich trotzdem gehen kann. Bitte, <Name>, findet das Medaillon für mich. Es wird von Malor dem Eifrigen bewacht, einem wahnsinnigen Mitglied der Scharlachroten Bruderschaft. Er lebt tief in der scharlachroten Bastion im westlichen Stratholme.", objectives = { "Medaillon des Glaubens" } },
    [5125] = { title = "Aurius' Abrechnung", summary = "<Name>, ich sterbe... aber meine Seele ist gerettet. Dafür schulde ich Euch mehr, als man mit Worten ausdrücken kann. Bitte, nehmt dies... und kämpft weiter so mutig, <Klasse>!" },
    [5126] = { title = "Lorax' Geschichte", summary = "Sprecht mit Lorax. Hört, was er zu sagen hat.", desc = "Der Satyr wandert auf und ab und spricht mit sich selbst. Möchtet Ihr ihn ansprechen?", objectives = { "Hört Euch Lorax' Geschichte an." } },
    [5127] = { title = "Die Dämonenschmiede", summary = "Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein. Ihr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden. Bringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring.", desc = "Lorax macht Geschäfte, aber er akzeptiert sie nicht von unbedeutenden Sterblichen.\n\nEinen Handel kann ich aber mit Euch machen... nehmt diese Pike, sie ist mit mächtigen Fel-Energien getränkt. Wenn Ihr Goraluk Hammerbruch findet, erschlagt ihn und treibt diese Pike durch sein sterbendes Herz. Er hat seine Seele verschachert und daher werde ich seine Seele bekommen. Bringt die Pike und die Brustplatte zurück, die der Dieb gestohlen hat, und ich werde Euch das beibringen, was er lernen sollte.", objectives = { "Seelenbefleckte Pike", "Ungeschmiedete runenbedeckte Brustplatte" } },
    [5160] = { title = "Die oberste Beschützerin", summary = "Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe.", desc = "Reist nach Kalimdor, <Volk>. Unser Schwarm ist in der frostigen Landschaft von Winterspring zu Hause. Wenn Ihr Winterspring erreicht habt, sucht die Höhlen von Mazthoril.\n\nAuf den eisigen Böden von Mazthoril werdet ihr Kobaltrunen finden. Haltet eine meiner Schuppen in der Hand und stellt Euch auf eine Rune. Ihr werdet dann zu Haleh transportiert, unserer obersten Beschützerin.\n\nGebt ihr die Schuppe, damit sie weissagen kann, was ich hier an diesem verlorenen Ort gesehen und gefühlt habe." },
    [5212] = { title = "Das Fleisch lügt nicht", summary = "Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.", desc = "Die Apotheker der Verlassenen sind nicht die einzigen Wesen auf dieser Welt, die in den Wissenschaften bewandert sind.\n\nIch erforsche die Seuche schon seit Jahren, <Volk>. Wir dachten zuerst, dass die Stärke der Seuche langsam schwand, aber was ich hier in den Pestländern entdeckt habe, ist alarmierend. Die Kraft der Seuche scheint zu wachsen!\n\nIch muss mehr Tests durchführen! Die mächtigste Quelle der Seuche ist das besudelte Fleisch der vor kurzem Infizierten. Begebt Euch nach Stratholme und bringt mir Proben, <Name>.", objectives = { "Verseuchte Fleischprobe x 20" } },
    [5213] = { title = "Der aktive Wirkstoff", summary = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück.", desc = "Ihr müsst tiefer nach Stratholme vordringen, <Name>.\n\nHinter den ersten Toren werdet Ihr die Ziggurats finden. Wir wissen, dass die Geißel große Macht aus diesen Gebäuden zieht. Durchsucht die Ziggurats und kehrt mit den Informationen zurück, die Ihr aufspürt.", objectives = { "Geißeldaten" } },
    [5214] = { title = "Der große Fras Siabi", summary = "Sucht Fras Siabis Raucherladen in Stratholme und bergt einen Kasten von Siabis Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.", desc = "Schrecklich... was mit Fras geschehen ist. Wisst Ihr, die Stadt wurde geplündert und Fras wollte seine wertvollen Dinge nicht zurücklassen. Das Letzte, woran ich mich erinnere, ist, dass er sagte: 'Ich werde jede einzelne Seite verbrennen, bevor ich zulasse, dass sie sie in ihre verdammten, schmutzigen Pfoten kriegen!'\n\nIch rauche ja auch ganz gern mal eine Zigarre, aber ich bin kein Idiot. Ich habe Fras und sein reizendes Geschäft an dem Tag verlassen. Ich nehme an, dass er in den Flammen unterging, aber wenn es eine Chance gibt, dass auch nur ein Kasten seines berühmten Tabaks noch intakt ist...\n\nWas sagt Ihr dazu, <Name>? Sucht Ihr einen Kasten für den alten Smokey?", objectives = { "Grimms Toller Tabak" } },
    [5243] = { title = "Häuser der Heiligen", summary = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.", desc = "Ich sehe meinen Untod als eine Krankheit an, <Volk>. Eine Krankheit, die einfach nur eine Behandlung erfordert; sie ist aber auch ein großer Segen für die Argentumdämmerung. Wie kann man die Heiden der Geißel besser schlagen als durch den Untod?\n\nIch werde von meinen Kollegen wegen der Opfer, die ich dargebracht habe, geachtet, aber das Lob bedeutet mir nichts.\n\nWenn Ihr daran interessiert seid, der Argentumdämmerung zu helfen, kann ich Euch einen Auftrag anbieten.\n\nBegebt Euch nach Stratholme und holt unsere Reserven an heiligem Wasser. Durchsucht die Vorratskisten.", objectives = { "Heiliges Wasser von Stratholme x 5" } },
    [5251] = { title = "Der Archivar", summary = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.", desc = "Alles, was zum Extremen getrieben wird, ist für unsere Welt gefährlich, <Name>. Nehmt zum Beispiel den Scharlachroten Kreuzzug. Glaubt Ihr, dass der blinde Fanatismus seiner Anhänger etwas Gutem dient? Wie viele Unschuldige haben sie im Namen des Lichts vernichtet?\n\nGotteslästerer, alle zusammen!\n\nEiner interessiert mich aber besonders, der Archivar Galford von Stratholme: ein Mann, der über die wertvollsten Dokumente des Kreuzzugs wacht. Vernichtet ihn und verbrennt seine Archive! Wenn Ihr erfolgreich seid, kehrt zu mir zurück und Ihr werdet belohnt.", objectives = { "Archivar Galford", "Verbranntes Archiv" } },
    [5262] = { title = "Die Wahrheit zeigt sich mit Macht", summary = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern.", desc = "Ihr versucht, Eure Gedanken zu sammeln, während sich der Staub in der Kammer wieder setzt. Ihr geht in Gedanken die Ereignisse durch, die sich gerade ereignet haben, und könnt dennoch die Schwere der Situation nicht verstehen.\n\nDer oberste Kreuzzügler des Scharlachroten Kreuzzugs ein Dämon? Und nicht nur irgendein Dämon, sondern der Bruder von Varimathras, Erzlord von Undercity?\n\nIhr verstaut den abgetrennten Kopf des Schreckenslords sorgfältig in Eurem Rucksack. Natürlich würde Euch niemand diese Geschichte ohne Beweise glauben.\n\nFürst Nicholas Zverenhoff muss sofort davon erfahren!" },
    [5263] = { title = "Übertroffen", summary = "Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.", desc = "Ihr zeigt eine natürliche Begabung für die Kunst der Zerstörung und Ihr folgt Befehlen. Es ist selten, dass beides zusammentrifft. In mir keimt immer mehr der Gedanke, dass Ihr ein hervorragendes Mittel göttlicher Gerechtigkeit darstellen könntet.\n\n<Zverenhoff verschränkt seine Hände vor seinem Gesicht.>\n\nDer Laufbursche von Kel'Thuzad regiert über Stratholme. Beweist mir, dass Ihr ein Held seid - mein Held. Vernichtet Baron Rivendare und kehrt mit seinem Kopf zu mir zurück.", objectives = { "Kopf von Baron Rivendare" } },
    [5281] = { title = "Die ruhelosen Seelen", summary = "Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde.", desc = "Da gibt es diejenigen, die tragisch beim Fall von Stratholme starben. Viele nahmen sich das Leben, entschieden sich dafür, sich lieber selbst in die Myriaden Flammen der glimmenden Stadt zu stürzen, statt einer der Geißel zu werden.\n\nNun ziehen sie als ruhelose Geister durch die Straßen von Stratholme.\n\nWir müssen ihnen helfen, <Name>!\n\nIch habe einen Partner namens Egan, der wunderbare Arbeit mit Geistern und Seelen geleistet hat. Sucht ihn auf. Er streift durch die Östlichen Pestländer, in der Nähe von Stratholme, und testet seine Neuheiten." },
    [5282] = { title = "Die ruhelosen Seelen", summary = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei! Befreit 15 ruhelose Seelen und kehrt zu Egan zurück.", desc = "Ich ziehe meine Macht - meinen Willen, weiter zu leben und zu atmen - aus dem ganzen Hass, den ich der Geißel entgegenbringe, und allem, was sie getan hat. Ich bin aber trotzdem kein Eiferer. Es gibt die, wie die Mitglieder des Scharlachroten Kreuzzugs, die die unschuldigen Untoten eher vernichten würden, als ihnen auch nur ein wenig Mitleid entgegenzubringen.\n\nDas bringt mich zu dem hier: meinem Blaster. Er wird die gequälten Seelen von Stratholme erlösen.\n\nWendet ihn auf die Geisterscheinungen an, die die geplünderten Straßen durchstreifen. Befreit ihre Seelen.", objectives = { "Befreite Seelen x 15" } },
    [5341] = { title = "Das Familienvermögen der Barovs", summary = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist.", desc = "In der Scholomance liegt das Familienvermögen der Barovs. Ich, Alexi Barov, bin einer der beiden letzten verbliebenen Erben des Hauses Barov. Mein Bruder Weldon ist der andere.\n\nWeldon, der jämmerliche Feigling, floh während des Krieges und hielt so an seiner wertlosen Existenz als Mensch fest.\n\nJetzt sucht er nach den Besitzurkunden, damit er das Vermögen für sich beanspruchen kann. Holt die Besitzurkunden, bevor mein Bruder es tut, und ich werde Euch reicher machen, als Ihr je zu träumen gewagt habt.", objectives = { "Die Besitzurkunde für Brill", "Die Besitzurkunde für Caer Darrow", "Die Besitzurkunde für Southshore", "Die Besitzurkunde für Tarrens Mühle" } },
    [5343] = { title = "Das Familienvermögen der Barovs", summary = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.", desc = "Mein lieber Bruder Alexi. Was für ein Narr war ich doch, sein Leben zu verschonen. Ich sah dem Feind ins Gesicht, einem der Untoten, und ließ ihn am Leben.\n\n<Weldon spuckt aus.>\n\nUnd jetzt sucht er nach MEINEM Erbe. Das darf einfach nicht sein.\n\nSucht die Besitzurkunden meiner Familie, bevor sie diesem niederträchtigen Bastard in seine knochigen Hände fallen, und ich werde Euch mit großem Reichtum belohnen. Sie liegen irgendwo in den Ruinen der Scholomance. Beeilt Euch!", objectives = { "Die Besitzurkunde für Brill", "Die Besitzurkunde für Caer Darrow", "Die Besitzurkunde für Southshore", "Die Besitzurkunde für Tarrens Mühle" } },
    [5382] = { title = "Doktor Theolen Krastinov, der Schlächter", summary = "Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.", desc = "Krastinov ist für den Tod von Tausenden verantwortlich. Er muss bestraft werden, die Gerechtigkeit muss ihren Lauf nehmen.\n\nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, <Name>.", objectives = { "Doktor Theolen Krastinov", "Verbrannte Überreste von Eva Sarkhoff", "Verbrannte Überreste von Lucien Sarkhoff" } },
    [5384] = { title = "Kirtonos der Herold", summary = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren. Kämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.", desc = "Das ist es, <Name>.\n\n<Eva zeigt auf die Phiole in der Tasche.>\n\nDas Blut von Unschuldigen. Das reinste Blut... damit wird Krastinovs Meister besänftigt.\n\nMit diesem Blut kann Kirtonos beschworen werden. Mit diesem Blut muss Kirtonos auch vernichtet werden.\n\nBringt dieses Blut auf die Veranda. Legt es auf die Kohlenpfanne. Kirtonos wird kommen - er kann nicht widerstehen. Wenn er erscheint, entfesselt die Wut und den Zorn von Tausenden unschuldigen Toten über ihm.\n\nWenn Ihr erfolgreich seid, werdet Ihr mehr verdienen als nur unsere Dankbarkeit.", objectives = { "Kirtonos der Herold" } },
    [5461] = { title = "Der Mensch Ras Frostraunen", summary = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduke zurück.", desc = "Die Untoten fürchten das Leben genauso sehr wie die Lebenden den Tod fürchten. Es ist nicht ungewöhnlich, dass ein denkender Untoter alle Überreste seines vorherigen Lebens vollständig zerstört, nachdem er zum Untoten wurde.\n\nLeider benötigen wir, um ein Artefakt zu erschaffen, das Ras Frostraunen wieder in einen Sterblichen zurückverwandeln kann, ein Andenken aus seinen Jahren unter den Lebenden.\n\nIhr müsst Euch zur zerstörten Stadt von Stromgarde begeben, Frostraunens Heim, und nach solch einem Gegenstand suchen. Möge das Glück mit Euch sein, <Name>.", objectives = { "Andenken der Erinnerung" } },
    [5462] = { title = "Der Sterbende Ras Frostraunen", summary = "Reist zur Hoffnung des Lichts in den Östlichen Pestländern und sucht Leonid Barthalomew den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt.", desc = "Das Andenken muss auf besudeltem Boden korrekt eingestellt werden.\n\nMan erzählt sich, dass Stratholme der Ort sei, an dem Frostraunen dem Lichkönig erlag. Auf diesem blutigen Boden gab er sein Leben - frei und mit einem Motiv -, um einer der Unsterbenden zu werden.\n\nDieser Ort muss gefunden werden.\n\nEs gibt einen untoten Dissidenten der Geißel, der durch die Bansheekönigin befreit wurde, aber der Sache der Argentumdämmerung gegenüber loyal ist. Sucht ihn: Leonid Barthalomew der Geachtete. Er könnte mehr wissen. Sucht die Hoffnung des Lichts auf, <Name>." },
    [5463] = { title = "Menethils Geschenk", summary = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden.", desc = "Ich sah zu, wie der Mensch Ras Frostraunen seine unsterbliche Seele dem Lichkönig verpfändete. Er setzte den Dolch an seiner eigenen Kehle an und durchschnitt sie mit einem Lächeln von einem Ohr zum anderen. Sein Körper brach in den Grenzen des Pentagramms zusammen. Der Lichkönig stand über dem gefallenen Magier, und mit einer einzigen Bewegung wurde Ras Frostraunen der Lich geboren.\n\n<Leonid blickt zu Boden und sieht Euch dann an.>\n\nJa, <Volk>, ich erinnere mich. Was Ihr sucht, hat einen Namen - Menethils Geschenk: Der vom Lichkönig gesegnete Boden - heiliger Boden für die Geißel." },
    [5464] = { title = "Menethils Geschenk", summary = "Bringt das seelengebundene Andenken zu Leonid Barthalomew in den Östlichen Pestländern.", desc = "Die Seele des Gefallenen hängt sich an das, was sein ehemaliges Leben repräsentiert, und verwandelt den Gegenstand in ein seelengebundenes Andenken. Ihr hebt den Gegenstand auf und verstaut ihn in Eurem Rucksack." },
    [5465] = { title = "Seelengebundenes Andenken", summary = "Kehrt zu Magistrat Marduke in Caer Darrow zurück. Zeigt ihm das seelengebundene Andenken.", desc = "Kehrt mit dem Andenken zu Marduke zurück, <Name>. Er wird Euch über die Anwendung instruieren." },
    [5466] = { title = "Der Lich Ras Frostraunen", summary = "Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke.", desc = "Es verbleibt noch eine Aufgabe, <Name>. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber.\n\nBenutzt die Macht des Andenkens gegen die Bestie - seid unerbittlich in Euren Taten! Haltet den Schlägen stand, mit denen das um sich schlagende Biest Euch sicherlich eindecken wird. Gebt dem Schmerz nicht nach!\n\nWenn das Ritual abgeschlossen ist, wird Ras wieder ein Sterblicher sein. An diesem Punkt muss er getötet werden. Schlagt ihn nieder und nehmt Euch seinen menschlichen Kopf.", objectives = { "Menschlicher Kopf von Ras Frostraunen" } },
    [5515] = { title = "Krastinovs Tasche der Schrecken", summary = "Sucht nach Jandice Barov in der Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.", desc = "Ein großes Gewicht wurde von unseren Herzen genommen, <Name>, aber Eure Aufgabe ist noch nicht vollendet. Krastinovs Meister, Kirtonos, lebt immer noch.\n\nBevor Ihr aber Kirtonos gegenübertretet, müsst Ihr Euch zuerst eine Methode besorgen, mit der Ihr ihn beschwören könnt.\n\nEs heißt, dass Jandice Barov das Blut Unschuldiger von Krastinov zu Kirtonos bringt.\n\nSucht sie in den versunkenen Katakomben der Scholomance und streckt sie nieder. Bringt alle Hinweise zurück, die Ihr findet.", objectives = { "Krastinovs Tasche der Schrecken" } },
    [5518] = { title = "Der Ogeranzug der Gordok", summary = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Thimblejack. Momentan ist er im Gordokflügel von Düsterbruch angekettet.", desc = "Wenn Ihr versuchen wollt gegen den König dieser Bruchbude zu kämpfen - und ich denke das Ihr genau das vorhabt - dann müsst Ihr erst mal an Captain Kromcrush vorbei. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen.\n\nEs stellt sich nur die Frage, wie? Nun, ich bin hier schon eine ganze Weile und ich denke, dass ich Euch einen Ogeranzug anfertigen kann, der ausreicht, um diese Kerle zu täuschen. Das einzige Problem wird seine Stabilität sein - zehn Minuten sind das Maximum. Besorgt mir alles was ich brauche und Ihr bekommt einen Ogeranzug. Ich warte hier solange...", objectives = { "Runenstoffballen x 4", "Unverwüstliches Leder x 8", "Runenfaden x 2", "Ogergerbemittel" } },
    [5522] = { title = "Leonid Barthalomew", summary = "Bringt die gefrorenen Eier zu Leonid Barthalomew in den Östlichen Pestländern.", desc = "Ich habe eine Botschaft von meinem Meister Vectus erhalten. Na ja, die Botschaft war nicht wirklich von Vectus... sie war von jemandem namens Leonid Barthalomew. Ich kenne Leonid nicht, aber er kannte meinen Meister, und niemand kennt meinen Meister, außer er lässt es zu.\n\nLeonid sagt, dass Vectus die Dracheneier will. Er möchte, dass Ihr sie ihm zur Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern bringt.\n\nDas tut weh! Warum Ihr? Vertraut Vectus mir nicht? Ach, egal... nehmt einfach die Eier und berichtet Leonid, dass ich getan habe, was unser Meister befahl." },
    [5525] = { title = "Befreit Knot!", summary = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat... Was erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", objectives = { "Gordokfesselschlüssel" } },
    [5526] = { title = "Die Splitter der Teufelsranke", summary = "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade.", desc = "Euer Wissen über Eldre'Thalas - Düsterbruch - in Feralas wird nun gebraucht, <Name>. Im Ostteil der zerstörten Stadt erstreckt sich das Herrschaftsgebiet von Alzzin dem Wildformer. Begebt Euch mit der gebotenen Eile und Tapferkeit dorthin.\n\nDie korrumpierte Frucht des Gedeihens - die Teufelsranke - sollte sich in Alzzins Nähe befinden. Wenn er fällt, versucht soviel wie möglich von der Essenz der Teufelsranke zu erlangen. Versiegelt diese in dem Reliquiar und bringt es zu mir.\n\nViel Glück und Cenarius' Kraft sei mit Euch!", objectives = { "Versiegeltes Reliquiar der Reinheit", "Teufelsrankensplitter" } },
    [5527] = { title = "Ein Reliquiar der Reinheit", summary = "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück.", desc = "Zuerst müssen wir einen Behälter finden, in dem eine sehr stark verderbte Substanz transportiert werden kann, ohne das der Träger Nebenwirkungen davonträgt. Meines Wissens nach, gibt es nur einen Gegenstand der geeignet ist, darin etwas so abscheuliches wie eine Teufelsranke aufzubewahren: ein Reliquiar der Reinheit.\n\nTief in der Einöde von Silithus befinden sich die Überreste des Nachtelfenpostens Südwind. Vor vielen, vielen Jahren gab es dort ein Reliquiar. Wenn wir Erfolg haben wollen, müsst Ihr die Ruinen durchsuchen, in der Hoffnung dort ein Reliquiar der Reinheit zu finden.", objectives = { "Reliquiar der Reinheit" } },
    [5528] = { title = "Der Gordokgeschmackstest", summary = "Ihr jetzt de' Big Boss hier. Also kriegen freie Kostproben meiner besseren Gebräue! Diese Tränke werden Euch verstärken UND Euch Schädel weghauen! Das ist da' guta Zeug, Chef... Ihr versuchen und dann Kreeg glauben!" },
    [5529] = { title = "Verseuchte Jungtiere", summary = "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück.", desc = "Die Argentumdämmerung hat kürzlich erfahren, dass die Geißel ihren eigenen verseuchten Drachenschwarm erschafft! Wir müssen sie stoppen - wenn die Geißel eine Großdrachenstreitmacht auf die Beine stellt, wird sie unbehelligt ganz Azeroth verwüsten!\n\nIhre Totenbeschwörer züchten verseuchte Großdrachen in der Scholomance, in der Mitte des Darrowmeresees.\n\nBegebt Euch zur Scholomance und tötet so viele Jungtiere wie nur möglich ... bevor sie größer werden können!", objectives = { "Verseuchtes Jungtier x 20" } },
    [5531] = { title = "Betina Bigglezink", summary = "Bringt die gefrorenen Eier zu Betina Bigglezink.", desc = "Die Eier, die Ihr gebracht habt, sollten in Experimenten der Geißel verwendet werden, um einen verseuchten Drachenschwarm zu erschaffen. Diese gefrorenen schwarzen Dracheneier wären für ihre Studien unersetzlich gewesen und hätten ihren Zeitplan sicherlich beschleunigt.\n\nNun ist es an der Zeit, dass wir ihre Forschung beenden.\n\nBringt die gefrorenen Eier zu Betina Bigglezink da draußen. Sie ist in Wissenschaft und Alchimie sehr bewandert und hat eine Waffe hergestellt, die wir gegen die Geißel einsetzen können. Mit Eurer Hilfe werden wir ihnen einen schweren Schlag versetzen." },
    [5542] = { title = "Dämonenhunde", summary = "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", desc = "Wenn Ihr hier bleiben wollt, bitte ich Euch nur, Euren Unterhalt zu verdienen. Wir haben hier viele Plagegeister, denen etwas 'Disziplin' gut tun würde.\n\nIhr könnt mit den Seuchenhunden und den kleinen Seuchenhunden beginnen.\n\nViel kann ich Euch im Gegenzug nicht anbieten, aber ein warmes Mahl und ein wenig Konversation wäre Euch garantiert, wenn Ihr erfolgreich seid.", objectives = { "Kleiner Seuchenhund x 20", "Seuchenhund x 5", "Rasender Seuchenhund x 5" } },
    [5543] = { title = "Blutgefärbter Himmel", summary = "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", desc = "Wehe jenen, die töricht genug sind, in die Pestländer zu wandern. Alle Arten der Verderbtheit bewohnen diese Wälder - von den fanatischen Anhängern des Scharlachroten Kreuzzugs, die jeden töten, der nicht das Zeichen der Kreuzzügler trägt, bis hin zur mordlustigen Geißel, die ihre Anzahl vergrößern will, indem sie ihre Ränge mit Untoten füllt.\n\nSogar die Tierwelt wurde in wilde, menschenfressende Bestien verwandelt. Ich bitte Euch, die zu vernichten, die vom Firmament aus zuschlagen: die Seuchenfledermäuse.", objectives = { "Seuchenfledermaus x 30" } },
    [5544] = { title = "Aassammlung", summary = "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", desc = "Meine Essensvorräte gehen zur Neige, <Volk>. Ich schäme mich zuzugeben, dass ich möglicherweise nicht genug Nahrung habe, um sie mit Euch zu teilen.\n\nKönnt Ihr einem alten Mann bei einer einfachen Aufgabe helfen? Hier in der Umgebung sind Aaswürmer die einzigen Tiere, die von den Verheerungen der Seuche unbeeinflusst blieben. Wenn sie auch ziemlich langweilig schmecken, kann das Fleisch der Würmer doch leicht monatelang aufbewahrt werden. Ich werde einige hundert Pfund benötigen, um meine Vorräte für den kommenden Winter aufzustocken!", objectives = { "Scheibe Aaswurmfleisch x 15" } },
    [5582] = { title = "Gesunde Großdrachenschuppe", summary = "Bringt die gesunde Großdrachenschuppe zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.", desc = "Dies ist eine Schuppe von einem verseuchten Großdrachen-Jungtier. Aber im Gegensatz zu den anderen pockennarbigen, eiternden Schuppen an dem kleinen Biest ist diese rare Schuppe gesund und unbeschädigt.\n\nBetina Bigglezink wird eine Probe davon für Forschungen haben wollen." },
    [5722] = { title = "Die Suche nach dem verloren gegangenen Ranzen", summary = "Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen.", desc = "Die Troggs sind nicht das Einzige, das Magatha im Ragefireabgrund interessierte. Sie hatte gehört, dass einer ihrer Diener, ein gewisser Maur Grimmtotem, im Abgrund etwas Sonderbares gefunden haben soll, nur leider schaffte er es nicht mehr, lebend herauszukommen, um ihr davon zu berichten. Sie möchte, dass Maurs Leiche - falls sie noch existiert - geborgen wird ... und auch jegliche Hinweise auf das, was er entdeckt haben könnte, als er versuchte, mit den Troggs zu sprechen.\n\nBringt Magatha Gegenstände, die sie interessieren könnten, dann wird sie sich bestimmt mit einer Belohnung nicht kleinlich zeigen.\n\nBegebt Euch noch einmal in den Abgrund im dunkelsten Teil von Orgrimmar." },
    [5723] = { title = "Die Kraft des Feindes wird auf die Probe gestellt", summary = "Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück.", desc = "Unter der Stadt Orgrimmar haben stämmige Kreaturen, als Troggs bekannt, damit begonnen, sich aus den Tiefen unterhalb der lavagefüllten Tunnel an die Oberfläche zu wühlen. Wie es ihrer grundgütigen Art entspricht, hatte Magatha Frieden mit diesen Kreaturen schließen wollen, doch die Troggs stürzten sich auf ihre Diplomaten und töteten sie. Magatha lässt sich eine solche Behandlung des Taurenvolks nicht gefallen und betrachtet die Kreaturen jetzt als eine Gefahr für die gesamte Horde.\n\nSie bittet Euch, der Gefahr durch die Troggs ein Ende zu machen, bevor sie die Horde von unten überwältigen. Geht zum Ragefireabgrund und vernichtet sie alle.", objectives = { "Ragefire-Trogg x 8", "Ragefire-Schamane x 8" } },
    [5724] = { title = "Wiederbeschaffung des verloren gegangenen Ranzens", summary = "Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff.", desc = "Unter dem Körper des Tauren findet Ihr einen Ranzen. Er hält ihn immer noch fest an sich gedrückt, als hätte er ihn beim Angriff der Troggs schützen wollen.\n\nIhr befreit den Ranzen aus seinem Klammergriff und verstaut ihn bei Eurer eigenen Ausrüstung, dann bereitet Ihr Euch darauf vor, die Tunnel zu verlassen und zu Rahauro in Thunder Bluff zurückzukehren." },
    [5725] = { title = "Die Macht der Zerstörung...", summary = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity.", desc = "Viele Angehörige der Legion bedenken ihre Anhänger mit Geschenken, wie Ihr bestimmt wisst. Manche dieser Geschenke wären nach Ansicht der Dunklen Fürstin besser in der Hand von Leuten aufgehoben, die... weniger Visionen haben.\n\nEine Sekte des Schattenrates, die sich Searingblade nennt und sich in den Höhlen unterhalb Orgrimmars versteckt, ist ein Musterbeispiel dafür. Die Fürstin sagte mir, dass Mitglieder der Searingblade in den Besitz zweier sehr mächtiger Zauberbücher gelangt seien... und sie möchte sich diese Bücher von ihnen 'borgen'. Ihr werdet sie ihr beschaffen.", objectives = { "Schattenzauber", "Zauberformeln aus dem Nether" } },
    [5726] = { title = "Verborgene Feinde", summary = "Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar.", desc = "Eines werde ich in meinen Reihen auf keinen Fall dulden, <Name>: Verräter. Ich wäre allerdings töricht, würde ich meine Trümpfe einfach so ausspielen. Die Geschwüre der Verderbnis in unserem Land würden nicht tief genug herausgeschnitten und die Infektion würde sich noch verschlimmern.\n\nAber Ihr, ein junger Abenteurer, könntet dorthin gehen, wo es meinen Agenten nicht möglich ist... könntet die Wahrheit ans Licht bringen... herausfinden, wer wirklich hinter dieser Bestie steckt.\n\nWenn Ihr mutig genug seid, geht zur Knochenhöhle östlich von Orgrimmar, besorgt mir die Insignie eines Offiziers der Burning Blade dort und kehrt zu mir zurück.", objectives = { "Insignien des Lieutenants" } },
    [5727] = { title = "Verborgene Feinde", summary = "Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück.", desc = "Und jetzt lasst uns sehen, ob die Insignie, die Ihr gefunden habt, der Mühe wert ist.\n\nIn der Stadt gibt es einen Hexenmeister, der seiner Meinung nach mein Vertrauen genießt. Er weiß allerdings nicht, dass ich gewahr bin, wem er wirklich die Treue hält. Tatsächlich ist er der Anführer der Burning Blade. Aber stürzt Euch jetzt nicht übereilt in einen Kampf mit ihm. Er könnte nützlich sein und wir werden ihn gegen unsere Feinde einsetzen.\n\nBringt diese Insignie zu ihm in die Kluft der Schatten hier in Orgrimmar. Sprecht mit ihm, seht, ob er Euch für einen der Ihren hält, und kommt dann zu mir zurück.", objectives = { "Findet heraus, wie Neeru Fireblade auf Euch als Mitglied der Burning Blade reagiert." } },
    [5728] = { title = "Verborgene Feinde", summary = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt.", desc = "Hmmm, Anführer der Searingblade... das beunruhigt mich zutiefst. Wenn sie es sind, die für Neeru zählen, dann sollten sie auch unser erstes Ziel sein. Dieser Satyr... Bazzalan, und der andere, den Neeru erwähnte... Was war er doch gleich, ein Hexenmeister? Sie müssen vernichtet werden.\n\nKehrt zur Kluft der Schatten zurück und begebt Euch in den Ragefireabgrund, <Name>. Findet diese beiden Anführer der Searingblade und tötet sie. Aber seid vorsichtig, damit Neeru nicht erfährt, wer das getan hat. Er muss Euch auch weiterhin für <seinen Kampfgenossen/seine Kampfgenossin> halten.", objectives = { "Bazzalan", "Jergosh der Herbeirufer" } },
    [5742] = { title = "Erlösung", summary = "Hört Euch an, was Tirion Fordring zu sagen hat.", desc = "Ihr habt sehr hart gearbeitet. Ruht Eure müden Knochen aus und erlaubt mir, mich korrekt vorzustellen.", objectives = { "Tirions Geschichte" } },
    [5761] = { title = "Vernichtung der Bestie", summary = "Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar.", desc = "Die vorrangige Aufgabe, die mir unser großer Kriegshäuptling übertragen hat, ist die Vernichtung der Kreaturen, die dafür verantwortlich sind, dass sich der dämonische Einfluss in der großen Stadt unseres Herrschers einnisten konnte. Die Burning Blade sind eine Gefahr, aber es gibt auch noch andere. Die Searingblade zum Beispiel, die sich im Ragefireabgrund niedergelassen haben, versuchen insgeheim unschuldige Mitglieder der Horde auf ihre Seite zu ziehen.\n\nUm sie aufzuhalten, muss ihr Anführer beseitigt werden - eine Teufelswache namens Taragaman der Hungerleider.\n\nTötet ihn, und sein Herz wird Thrall beschwichtigen, dessen bin ich mir sicher.", objectives = { "Herz von Taragaman dem Hungerleider" } },
    [5781] = { title = "Von vergessenen Erinnerungen", summary = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", desc = "Wenn Ihr Taelan helfen wollt, zurückzubekommen, was er verloren hat, müsst Ihr Gegenstände aus seiner Vergangenheit zusammentragen.\n\nDer Erste dieser Gegenstände ist ein Spielzeug, das ich ihm zu seinem 7. Geburtstag schenkte. Es war sein wertvollster Besitz. Ein winziger Kriegshammer, die exakte Kopie meines eigenen.\n\nAls man mich wegen Verrats verbannte, erzählte ihm seine Mutter, dass ich gestorben sei. Man brachte ihn zu meinem angeblichen Grab beim Tiefgewölbe, wo er den Hammer zusammen mit seiner Erinnerung an mich begrub - für immer.\n\nIhr müsst Euch zum Tiefgewölbe begeben und Taelans Hammer holen.", objectives = { "Taelans Hammer" } },
    [5845] = { title = "Von verlorener Ehre", summary = "Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", desc = "Der Orden der Silberhand wurde gar sehr geschwächt, als Uther sein gewaltsames Ende fand.\n\nDer Junge hat durchgehalten, so lange er konnte. Er wurde bis zum vom Krieg zerrissenen Weiler Northdale zurückgetrieben, und dort stellte er sich zu seinem letzten Kampf.\n\nWar noch irgendjemand aus dem Orden am Leben, fragte er sich - und spielte das überhaupt noch eine Rolle?\n\nMit diesem Gedanken im Kopf schmetterte Taelan die Standarte des Ordens zu Boden und entsagte allem, was er gelernt hatte. Auf dem blutgetränkten Boden Northdales ließ er seine Ehre zurück.\n\nIhr müsst nach Northdale reisen und das Symbol der verlorenen Ehre finden.", objectives = { "Symbol der verlorenen Ehre" } },
    [5846] = { title = "Von Liebe und Familie", summary = "Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte.", desc = "Als Taelan noch ein Kind war, unternahmen wir mit der Familie oft Ausflüge nach Caer Darrow. Bei unserem letzten Besuch malte ein Künstler namens Renfray ein Porträt von uns, wie wir am Strand posierten. Das ist die schönste Erinnerung, die ich an Taelan und Karandra habe. Denn es war just dieser Moment, wo ich meine Frau und meinen Sohn in den Armen hielt, dass ich eine Liebe und Verbundenheit mit meiner Familie spürte, die ich seitdem nie wieder erlebt habe.\n\nFalls dieses Gemälde noch existiert, müsst Ihr es finden.\n\nBegebt Euch zur in Trümmern liegenden Insel Caer Darrow und seht nach, ob das Gemälde des Künstlers noch da ist." },
    [5848] = { title = "Von Liebe und Familie", summary = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind. Bringt das Gemälde zu Tirion Fordring.", desc = "Das Gemälde... Es hing jahrelang an der Wand meiner Werkstatt - in der Kaserne des Ordens.\n\nNachdem Tirions Prüfung vorüber war, wusste ich, dass ich das Gemälde nicht mehr dort für alle sichtbar hängen lassen konnte. So versteckte ich es an einem Ort, an dem es niemand vermuten würde.\n\nGeht nach Stratholme und begebt Euch tief in die heutige scharlachrote Bastion. Sucht dort nach einem Gemälde, auf dem unsere Zwillingsmonde abgebildet sind. Kratzt die Farbe weg, bis mein Meisterwerk zum Vorschein kommt, 'Von Liebe und Familie'.\n\nMöge das Licht Eure Taten leiten.", objectives = { "Von Liebe und Familie" } },
    [6133] = { title = "Das Ersuchen des Waldläuferlords", summary = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge. Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten.", desc = "Die Hochelfen der Quel’danil-Lodge haben etwas, das mir gehört, <Klasse>: Ein Dokument, das mein Leben als Sterblicher schildert.\n\nBevor Ihr fragt, Ihr seid wahrscheinlich nicht befugt, derlei Informationen zu bekommen. Macht einfach, was ich Euch sage, Wurm: Holt den Lebenslauf zurück.\n\nUnd, Schwachkopf, richtet so viel Not und Elend an, wie Ihr könnt. Lasst sie leiden ...", objectives = { "Pfadschreiter x 8", "Waldläufer x 8", "Waldmann x 8", "Quel'Thalas-Registratur" } },
    [6135] = { title = "Dämmerschwinge, oh, wie ich Euch hasse...", summary = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller. Man sagt, dass Dämmerschwinge nördlich von hier durch das Land streift.", desc = "Bisher habt Ihr die Missionen abgeschlossen, die ich Euch aufgab, wenn Ihr auch nicht unbedingt ein Ausbund an Pünktlichkeit seid.\n\nIhr denkt wahrscheinlich, dass Ihr bereit für eine Herausforderung seid. Ja... ja, Schwachkopf, vielleicht seid Ihr wirklich für anspruchsvollere Missionen bereit.\n\nDämmerschwinge, der Albinofledermausdämon, streift nördlich von hier durch das Land. Spürt ihn auf und besiegt ihn. Kehrt mit einem Büschel seines weißen Fells zu mir zurück und Ihr sollt eine Belohnung erhalten.", objectives = { "Fellflicken von Dämmerschwinge" } },
    [6163] = { title = "Ramstein", summary = "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos.", desc = "Ich war überwältigt. Ich stand in dieser Siedlung... und blieb standhaft bei der Verteidigung von Lordaeron. Der Hof und alles darauf wurde von einer gigantischen Welle der Geißel belagert.\n\nDer Dreck. Der Schmutz. Er stand über mir und die Eingeweide hingen ihm aus einem klaffenden Loch in der Brust.\n\nIch erwachte als Geißel. Lange Zeit war ich hilflos. Meine Gedanken waren mit denen des Lichkönigs verschmolzen.\n\nSie kam zu mir... irgendwo, irgendwie wusste ich es. Frei.\n\nDoch jetzt muss ich meine Rache haben - Rache an dem, der mir das Leben genommen hat. Vernichtet ihn.", objectives = { "Kopf von Ramstein dem Verschlinger" } },
    [6402] = { title = "Treffen in Stormwind", summary = "Reist nach Stormwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marshal Windsor über Eure Ankunft informiert.", desc = "Ihr sollt Euch an den Toren von Stormwind mit Windsor treffen.\n\nWas Windsor Euch eröffnen wird, wird das gesamte Königreich in den Grundfesten erschüttern!\n\nVersucht aber nicht, allein dorthin zu gehen, <Name>. Ihr müsst eine ganze Armee zusammenscharen! Versammelt Eure Mitstreiter. Zu den Waffen!" },
    [6403] = { title = "Die große Maskerade", summary = "Folgt Reginald Windsor durch Stormwind. Schützt ihn vor Gefahren!", desc = "Das war vielleicht ein Abenteuer. Ich schulde Euch großen Dank. Vielleicht, wenn alles gesagt und getan ist...\n\nWie Ihr zweifellos schon bemerkt haben werdet, sind Lady Prestor und Onyxia ein und dieselbe Person. Sie ist die Brut von Deathwing, Zwillingsschwester des Tyrannen der Spitze, Nefarian.\n\nViel zu lange schon hat sie ihren gierigen Blick auf unser Königreich gerichtet. Sogar der Hochlord steht schon unter dem Bann ihrer Zaubertricks - eine Marionette. Heute wird damit Schluss gemacht... Der Bann wird gebrochen.\n\nSorgt Euch nicht, denn gemeinsam werden wir siegen!\n\nSeid Ihr bereit?", objectives = { "Reginalds Marsch" } },
    [6501] = { title = "Das Großdrachenauge", summary = "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert.", desc = "Ich habe leider nicht mehr als ein Fragment des zertrümmerten Medaillons zu bieten.\n\nIhr müsst einen anderen aus dem Geblüt der Großdrachen finden, der bereit ist, Euch zu helfen, einen neuen Schlüssel zu schmieden. Sobald Ihr diesen Schlüssel habt, müsst Ihr zum Drachensumpf in den Marschen von Dustwallow reisen. Dort findet Ihr ihr Lager, <Name>.\n\nWo Ihr weitere Klans finden könnt, die gewillt wären, Euch zu helfen? Das weiß ich leider nicht ... Es soll angeblich welche geben. Einige sollen sogar unter uns leben und arbeiten, getarnt als Angehörige der humanoiden Völker. Ich wünsche Euch Glück." },
    [6502] = { title = "Drachenfeueramulett", summary = "Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Blackrockspitze.", desc = "Das ist ein Stück des Großdrachen. Eine Schuppe - verzaubert und transformiert. Als Ganzes hätte sie Zugang zum Hort der Bestie verschafft. Zertrümmert ist sie nutzlos.\n\nEs ist möglich, den Gegenstand zu reparieren, aber dazu wäre das Blut eines schwarzen Großdrachenhelden erforderlich. Es gibt einen... Er ist bekannt als General Drakkisath, Herrscher über die Drachenbrutarmeen von Nefarian. Vielleicht habt Ihr schon von ihm gehört?\n\nBringt mir sein Blut, <Volk>, dann verzaubere ich das Fragment in etwas, das Euch Zugang zu Onyxias Hort verschaffen wird.", objectives = { "Blut des schwarzen Großdrachenhelden" } },
    [6521] = { title = "Eine unheilige Allianz", summary = "Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity.", desc = "Malcin behauptet, dass er sich abseits der Hügel von Razorfen aufhalte. Dieser Botschafter muss getötet werden - seine Mission in den Augen des Lichkönigs ein glatter Fehlschlag sein.\n\nSeine Anwesenheit dort erklärt vieles von dem, was wir über diese Gegend herausgefunden haben - einige der Stacheleber sind beängstigend stark geworden und zeigen erste Symptome der Seuche. Das muss in der Tat ein Anzeichen dafür sein, dass sie irgendeine Übereinkunft getroffen haben.\n\nSucht Malcin und tötet ihn, <Name>. Kommt zurück, wenn Ihr das erledigt habt.", objectives = { "Kopf von Botschafter Malcin" } },
    [6522] = { title = "Eine unheilige Allianz", summary = "Bringt die kleine Rolle zu Varimathras nach Undercity.", desc = "Milady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf weiteres abseits der Hügel von Razorfen aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin" },
    [6561] = { title = "Blackfathom-Schurkerei", summary = "Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff.", desc = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Bashana in Thunder Bluff seinen Kopf, <Name>.", objectives = { "Kelris Kopf" } },
    [6562] = { title = "Ärger in der Tiefe", summary = "Sprecht in Ashenvale mit Je'neu Sancrea.", desc = "Je'neu Sancrea braucht Hilfe. Er befindet sich im Zoram'gar-Außenposten in Ashenvale. Der Nachtelfenwald liegt im Norden des Steinkrallengebirges. Ihr erreicht ihn, indem Ihr über die Scherwindklippe oder nördlich durchs Brachland reist. Der Zoramstrand liegt weit im Westen des Waldes. Seid vorsichtig, <Name>. Dort gibt es Mächte, denen Eure Anwesenheit nicht gefallen wird." },
    [6563] = { title = "Die Essenz von Aku'mai", summary = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale.", desc = "Im Eingangsbereich des Tunnels der Blackfathom-Tiefe findet man überall an den Höhlenwänden große Saphiransammlungen. Kürzlich ist aufgefallen, dass die Naga diese Kristalle abbauen. Bis wir herausgefunden haben, warum sie das tun, sollten wir die Naga einstweilen davon abhalten. Die Kristalle besitzen große Elementarkraft und wenn sie unangemessen eingesetzt werden, könnte man daraus eine mächtige arkane Komponente herstellen.\n\nWerdet Ihr mir helfen, <Name>? Die Blackfathom-Tiefe liegt am Zoramstrand nördlich unseres Außenpostens.", objectives = { "Saphir von Aku'Mai x 20" } },
    [6564] = { title = "Treue zu den Alten Göttern", summary = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale.", desc = "Die zerknitterte Notiz trägt eine kaum leserliche Handschrift:\n\n\"Ja, sagt allen Priesterinnen, dass sie mir die Kristalle bringen sollen. Die Wasserelementare sind stark in ihnen und sie werden unseren Aquamanten bei ihren Beschwörungen ungemein dienlich sein.\n\nIndem wir die Kraft dieser Kristalle beherrschen, beschwichtigen wir Aku'mai. Eines Tages werden wir genug Macht haben, um Aku'mai zu uns zurückzuholen. Dann wird die Welt wieder zur Ära ihrer einstigen Größe zurückkehren! Eine Ära, in der die Alten Götter herrschen!\"" },
    [6565] = { title = "Treue zu den Alten Göttern", summary = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück.", desc = "Dieser Anhänger der Twilight-Hammer darf seinen Plan nicht in die Tat umsetzen. Die Twilight-Hammer verstehen die Geister der Natur nicht. Sie glauben an die Alten Götter - Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden. Dieser Lorgus darf keinen Erfolg haben. Ihr müsst ihn aufhalten, <Name>. Ich kann mich leider nicht selbst darum kümmern ... ich bin zu schwach.\n\nGeht zur Blackfathom-Tiefe, findet ihn und tötet ihn. Kommt zu mir nach Zoram'gar zurück, wenn Ihr es geschafft habt.", objectives = { "Lorgus Jett" } },
    [6566] = { title = "Was der Wind erzählt", summary = "Hört Thrall zu.", desc = "Schön, Euch wiederzusehen, <Name>. Der Wind führt Kunde aus den östlichen Königreichen mit sich.\n\nSetzt Euch und lauscht.", objectives = { "Thralls Geschichte" } },
    [6567] = { title = "Der Champion der Horde", summary = "Sucht Rexxar auf. Der Kriegshäuptling hat Euch erklärt, wo Ihr ihn finden könnt. Sucht die Wege von Desolace zwischen dem Steinkrallengebirge und Feralas ab.", desc = "Ich habe Kunde von einem meiner Helden erhalten, dass es einen Weg zum Hort des Großdrachen geben könnte. Ihr müsst ihn suchen.\n\nRexxar streift durch die wüste Einöde von Desolace, immer auf Reisen zwischen dem Steinkrallengebirge und Feralas. Er erwartet Euch." },
    [6568] = { title = "Nachricht von Rexxar", summary = "Überbringt Myranda der Vettel in den westlichen Pestländern Rexxars Nachricht.", desc = "Was wisst Ihr über Illusionen, <Name>? Denn wisset, Ihr müsst eine Illusion erschaffen, um die Verteidigungslinien des schwarzen Drachenschwarms zu umgehen.\n\nIch kenne jemanden, der vielleicht bereit ist, Euch bei Eurem Täuschungsmanöver zu helfen. Sie hat unsereins in der Vergangenheit geholfen, wenn sie ein Unterfangen für würdig erachtete.\n\nIn den Westlichen Pestländern findet Ihr Myranda die Vettel, eine Meisterin der Illusionen... und eine Verbannte der Lordaeron-Allianz. Reist dorthin und nehmt diese Nachricht mit." },
    [6569] = { title = "Oculus-Illusionen", summary = "Reist zur Blackrockspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt.", desc = "Ihr möchtet also einer vom schwarzen Drachenschwarm werden, was, <Volk>?\n\nDie Erschaffung einer Illusion, wie Ihr sie wünscht, ist eine Kleinigkeit, aber die für den Zauber erforderlichen Komponenten sind ziemlich schwierig zu beschaffen. Rexxar und der Kriegshäuptling haben Euch mit dieser Mission betraut, also muss Myranda wohl annehmen, dass Ihr fähig dazu seid.\n\nReist zur oberen Zitadelle der Blackrockspitze und tötet genug Mitglieder der schwarzen Drachenbrut, um eine Eurer Taschen mit deren Augen zu füllen.\n\nKehrt zu Myranda zurück, wenn Ihr genügend von dem Reagenz gesammelt habt.", objectives = { "Schwarzes Drachenbrutauge x 20" } },
    [6570] = { title = "Aschenschwinge", summary = "Reist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge.", desc = "Ich habe dieses Medaillon mit der Magie versehen, die notwendig ist, um eine Illusion zu erschaffen und sie innerhalb der Einfriedung des Höhlenbaus von Aschenschwinge aufrechtzuerhalten.\n\nAschenschwinge ist ein uralter Drache, ein alter Torhüter Nefarians, der die schwere Bürde auf seinen Schultern trägt, jene der Drachenbrut auf die Probe zu stellen, die in den Rang einer Elitewache Onyxias aufsteigen wollen.\n\nReist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr dort seid, legt Ihr das Amulett an und folgt Eurem Schicksal, wo immer es Euch auch hinführen mag!" },
    [6582] = { title = "Die Prüfung der Schädel, Scryer", summary = "Ihr müsst Scryer, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge. Ihr wisst, dass Scryer in Winterspring zu finden ist.", desc = "Wir alle sind Kinder der Deathwing, Welpe. Wir müssen die Herrschaft über die niederen Aspekte durchsetzen.\n\nWenn Ihr wirklich eines Aufstiegs würdig seid, werden die Geringeren des Drachenschwarms vor Euch niedersinken.\n\nFindet deren Champions und vernichtet sie im Namen unseres Vaters!\n\nBegebt Euch nach Winterspring und spürt den mächtigen Blaudrachen Scryer auf. Zerschmettert ihn und alle anderen des blauen Drachenschwarms, die sich Euch in den Weg stellen. Entreißt ihm seinen Schädel und bringt ihn mir.", objectives = { "Der Schädel des Wahrsagers" } },
    [6583] = { title = "Die Prüfung der Schädel, Somnus", summary = "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück.", desc = "Genau wie unser Vater die Aspekte zerschmettert, müssen wir danach trachten, Chaos und Zerstörung unter ihren Kindern anzurichten.\n\nIhr müsst Eure Leistungsfähigkeit im Kampf gegen die schlaflosen Träumer auf die Probe stellen: die Kinder des Gründrachenschwarms.\n\nBegebt Euch zu den Sümpfen des Elends und spürt Somnus auf, den Drachenchampion des Gründrachenschwarms. Lasst Eurem Hass freien Lauf und bezwingt das Insekt ... Kommt mit seinem Schädel zu mir zurück ...", objectives = { "Der Schädel des Somnus" } },
    [6584] = { title = "Die Prüfung der Schädel, Chronalis", summary = "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge.", desc = "Die Zeitbehüter, Kinder Nozdormusss - Lord der Jahrhunderte...\n\nEs sind derer drei, die die Höhlen der Zeit bewachen, aber nur einer, an dem der schwarze Drachenschwarm interessiert ist: Chronalisss, der Zeitverschieber, bevorzugter Drachling Nozdormusss.\n\nBesssiegt diesssen Champion, denn das wäre ein Schlag, der sssogar den stoischen Sand der Zzzeit erschüttern würde. Kehrt mit seinem Schädel zu mir zzzurück.", objectives = { "Der Schädel des Chronalis" } },
    [6585] = { title = "Die Prüfung der Schädel, Axtroz", summary = "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des Roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück.", desc = "Es war in den Bergen von Grim Batol, wo unser Vater gegen die vereinte Macht der Aspekte wütete. Die feige Tat des Verräters Alexstrasza verschaffte den übrigen Aspekten genug Zeit, um dem Zorn des Vaters zu entkommen.\n\nWasss für ein schändlicher Akt ...\n\nDer Rotdrachenschwarm bewacht heute Grim Batol und ihr Lieutenant Axtroz muss vernichtet werden. Bringt mir Axtroz' Schädel. Für den Vater, Welpe!", objectives = { "Der Schädel des Axtroz" } },
    [6601] = { title = "Aufstieg...", summary = "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Blackrockspitze nicht funktioniert. Vielleicht solltet Ihr Rexxar aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist.", desc = "Ein Medaillon, aus den Schädeln Eurer Feinde gefertigt. Ihr kennt dieses Medaillon, nicht wahr? Zweifellos habt Ihr gesehen, wie Eure Ältesten es trugen.\n\nNehmt es, Welpe. Begebt Euch zur Spitze zurück und zeigt es General Drakkisath. Der General wird das Medaillon mit der letzten Verzauberung versehen und das Schmuckstück auf Euren Geist abstimmen.\n\nIhr werdet das fertige Medaillon als Ehrenabzeichen tragen, als Symbol für Euren Aufstieg in unsere am höchsten geschätzten Reihen: Wächter der Brutmutter.\n\nGeht!" },
    [6602] = { title = "Blut des schwarzen Großdrachen-Helden", summary = "Begebt Euch zur Blackrockspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rexxar.", desc = "Ihr werdet dem General einen Besuch abstatten, jawohl, aber nicht als einer des schwarzen Drachenschwarms.\n\nWisst Ihr, Zeremonie ist für den schwarzen Drachenschwarm nur ein anderer Begriff für Aderlass.\n\nDas ruhende Amulett benötigt nur das Blut des Generals, um wieder aktiv zu sein. Das ist einer ihrer primitiven, ausfallsicheren Mechanismen.\n\nKehrt zur Blackrockspitze zurück und vernichtet Drakkisath. Bringt sein Blut hierher zurück, dann aktiviere ich den Schlüssel zu Onyxias Hort.", objectives = { "Blut des schwarzen Großdrachenhelden" } },
    [6626] = { title = "Ein Hort des Bösen", summary = "Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück.", desc = "Die Verlassenen geben ihre... Krankheit... nicht weiter, soweit ich das sehe. Dieser Diplomat scheint Untote als Möchtegernanhänger zu betrachten. Ich glaube langsam, dass er der Geißel angehört.\n\nUm ihn mache ich mir allerdings momentan keine Gedanken, sondern um die wachsende Schar um ihn herum. Tag für Tag kriechen sie aus den Schatten und betteln ihn nahezu um mehr Macht an.\n\nIch bin nicht stark genug, um sie allein zu bekämpfen, <Name>. Was meint Ihr? Hättet Ihr Lust, auf die Jagd zu gehen?", objectives = { "Schlachtwache von Razorfen x 8", "Dornenwirker von Razorfen x 8", "Kultistin der Totenköpfe x 8" } },
    [6627] = { title = "Test der Lehre", summary = "Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid.", desc = "Ihr habt mir das Buch gebracht, und jetzt ist es an der Zeit für Eure Befragung. Seid Ihr bereit?\n\nZeit spielt keine Rolle, <Klasse>, also fühlt Euch nicht unter Druck gesetzt. Ihr könnt Euch mit der Antwort so viel Zeit lassen, wie Ihr möchtet.", objectives = { "Beantwortet Braug Dimspirits Frage richtig." } },
    [6804] = { title = "Vergiftetes Wasser", summary = "Wendet den Aspekt von Neptulon auf die vergifteten Elementare der östlichen Pestländer an. Bringt 12 disharmonische Armschienen, sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara.", desc = "Eine Truppe von Elementarspähern wurde in die östlichen Pestländer von Lordaeron entsandt und die Krankheit dieses Orts verdrehte und infizierte sie. Die Wasserlords können diese Beleidigung unserer Reinheit nicht dulden!\n\nNehmt diese Phiole. Darin befindet sich ein Quäntchen eines Aspekts von Neptulon. Wenn das auf die verseuchten Elementare angewendet wird, bekämpft es das Gift in ihren Körpern und heilt sie! Ihr innerer Konflikt wird sie allerdings in den lodernden Wahnsinn treiben.\n\nBesiegt die disharmonischen Wogen und bringt mir ihre Armschienen der Bindung.", objectives = { "Disharmonische Armschienen x 12" } },
    [6805] = { title = "Stürmer und Rumpler", summary = "Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück.", desc = "Wir, die Elementare des Wassers, führen Krieg mit den Wesen der niederen Elemente. Wenn Ihr in diesem Konflikt wirklich unser Verbündeter seid, dann beweist mir Eure Überzeugung!\n\nWeit im Süden, im Wüstenland Silithus, treiben sich die Diener der Luft und Erde in einer Felsenecke herum, die Kristalltal genannt wird. Sie schützen Gegenstände der Macht vor kleineren Wesen und Sterblichen, und obwohl ich nicht weiß, warum sie das tun, will ich ihre Bemühungen zunichte machen.\n\nBegebt Euch zum Kristalltal in Silithus und besiegt unsere Feinde. Kehrt danach zu mir zurück.", objectives = { "Staubstürmer x 15", "Wüstenrumpler x 15" } },
    [6821] = { title = "Auge des Glutsehers", summary = "Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara.", desc = "Ihr habt mir gezeigt, dass Ihr unsere Feinde besiegen und Missionen ausführen könnt, um die Sache der Wasserlords weiter voranzutreiben. Aber bisher seid Ihr nur niederen Feinden gegenübergetreten... wenn Ihr gegen einen mächtigen Feind geschickt werdet, könnt Ihr dann siegen?\n\nDas ist Eure neue Aufgabe.\n\nHoch droben auf der Blackrockspitze haben die Orcs einen Diener des Feuers gefangen genommen, die Feuerwache Glutseher. Sucht den Ort seiner Gefangenschaft, erschlagt seine Häscher und erschlagt dann den Glutseher. Bringt mir sein Auge. Das wird mir Euren Wert zeigen.", objectives = { "Auge des Glutsehers" } },
    [6921] = { title = "Inmitten der Ruinen", summary = "Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", desc = "Die Twilight-Hammer sind in die Mondschreinruinen der Blackfathom-Tiefe eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen. Wenn dem kein Einhalt geboten wird, gehört ihnen diese Region bald ganz und gar.\n\n<Name>, geht nach Blackfathom und findet den Fathom-Stein der Ruinen. Er dürfte irgendwo in deren Nähe im Wasser liegen. Darin ist ein Fathom-Kern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", objectives = { "Fathomkern" } },
    [6922] = { title = "Baron Aquanis", summary = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", desc = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.\n\nWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring. Er befindet sich im Zoram'gar-Außenposten der Horde in Ashenvale." },
    [6981] = { title = "Der leuchtende Splitter", summary = "Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann. Liefert dann den Splitter ab, wie Ihr angewiesen wurdet.", desc = "Der Splitter ist von einem glänzenden Grün, und obwohl er massiv ist, scheint etwas wie Rauch knapp unterhalb der Oberfläche herumzuwirbeln. Ihr fühlt den Zwang, in die Tiefen des Kristalls zu schauen, aber gleichzeitig fühlt Ihr auch, dass etwas sehr Beunruhigendes von ihm ausgeht.\n\nVielleicht solltet Ihr in Ratchet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.", objectives = { "Sprecht mit jemandem in Ratchet über den leuchtenden Splitter." } },
    [7028] = { title = "Dunkles Böses", summary = "Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace.", desc = "Die Kristallhöhlen von Terramok liegen im Westen, tief in Maraudon... Das ist ein uralter Ort mit einer langen Geschichte. Und ich will einiges davon in die Hände bekommen, <Klasse>. Relikte alter Götter liegen hinter den riesigen Türen verborgen.\n\nWenn Ihr bereit seid, dem dunklen Bösen zu trotzen, das sich in Maraudon findet, wird es Euer Schade bestimmt nicht sein. Sammelt die theradrischen Kristallschnitzereien ein, die Ihr aufstöbern könnt, und bringt sie mir.\n\nSobald ich die Schnitzereien habe, kann ich sie... studieren. Diese Mächte haben schon zu lange geruht...", objectives = { "Theradrische Kristallschnitzerei x 25" } },
    [7029] = { title = "Schlangenzunges Verderbnis", summary = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon. Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird. Heilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Vark Battlescar in Shadowprey zurück.", desc = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert.\n\nNehmt diese Phiole, <Name>. Füllt sie am orangefarbenen Kristallteich, den Ihr in den Höhlen findet. Die Beschichtung in der Phiole wird den Toxinen entgegenwirken und sie in einen Heilstoff verwandeln.\n\nSucht die Schlangenstrunkranken in den orangefarbenen Höhlen und wendet die geläuterte Flüssigkeit auf sie an. Die Pflanze wird damit von der Verderbnis gereinigt, doch Ihr müsst wissen, dass Schlangenzunge sie immer noch kontrolliert. Er kann sie gegen Euch einsetzen...", objectives = { "Geheilte Schlangenstrunkranken x 8", "Gefüllte himmelblaue Phiole" } },
    [7041] = { title = "Schlangenzunges Verderbnis", summary = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon. Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird. Heilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Talendria an der Nijelspitze zurück.", desc = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert.\n\nNehmt diese Phiole, <Name>. Füllt sie am verderbten orangefarbenen Kristallteich, den Ihr in den Höhlen findet. Die Beschichtung in der Phiole wird den Toxinen entgegenwirken und sie in einen Heilstoff verwandeln.\n\nSucht die Schlangenstrunkranken in den orangefarbenen Höhlen und wendet die geläuterte Flüssigkeit auf sie an. Die Pflanze wird damit von der Verderbnis gereinigt, doch Ihr müsst wissen, dass Schlangenzunge sie immer noch kontrolliert. Er kann sie gegen Euch einsetzen...", objectives = { "Geheilte Schlangenstrunkranken x 8", "Gefüllte himmelblaue Phiole" } },
    [7044] = { title = "Legenden von Maraudon", summary = "Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten. Findet einen Weg, um mit Celebras zu sprechen.", desc = "Ein dunkler Satyr namens Lord Schlangenzunge hat sein Böses in diesen verschlungenen Höhlen verbreitet und die Gedanken aller im Inneren vergiftet. Er residiert noch jenseits der lila Kristalle.\n\nSchlangenzunge hat des Weiteren ein lebendes Symbol seiner Verderbnis namens Noxxion geschaffen, das sich hinter den orangefarbenen Kristallen befindet. Zusammen haben sie die beiden Teile des Szepters meines Bruders gestohlen. Celebras, mein Bruder ... wandert blind im Inneren umher, verflucht durch die Verderbnis.\n\nIhr müsst ihm helfen! Findet die Stücke und sprecht mit meinem Bruder ... irgendwie.", objectives = { "Celebriandiamant", "Celebriangriff" } },
    [7046] = { title = "Das Szepter von Celebras", summary = "Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt. Sprecht mit ihm, nachdem das Ritual vollendet ist.", desc = "Mein Szepter war einst eine Quelle der Hoffnung für mich. Seine Macht ermöglichte mir die Freiheit, schnell durch diese Höhlen zu reisen. Ich hatte gehofft, dem Geist meines Onkels Frieden bringen zu können... Das ist eine Aufgabe, die ich nun an Euch übergebe.\n\nDamit die beiden Teile wieder eins werden können, benötige ich Eure Hilfe bei der Durchführung des Rituals. Folgt mir bitte und hört auf meine Anweisungen, während ich die Energie kanalisiere, die erforderlich ist, um den Griff wieder mit dem Diamanten zu vereinigen.\n\nZusammen werden wir das Szepter von Celebras wieder erschaffen!", objectives = { "Stellt das Szepter von Celebras her" } },
    [7064] = { title = "Verderbnis von Erde und Samenkorn", summary = "Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Shadowprey in Desolace zurück.", desc = "Tief in Maraudon lebt eine böse Kreatur des Chaos - Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den alten Göttern verwandt ist. Vor langer Zeit gingen sie und Zaetar, der erstgeborene Sohn von Cenarius, eine Beziehung ein. Aus ihrer gemeinsamen Zeit entsprangen Wesen, die unter den Menschen von Kalimdor als Zentauren bekannt wurden. Diese undankbaren Kreaturen töteten Zaetar und bewachen nun seine Überreste. Meine Aufgabe besteht darin, jemanden zu finden, der mächtig genug ist, um Theradras zu erschlagen, damit wir Zaetars Überreste holen können, bevor wir in das Steinkrallengebirge zurückkehren.", objectives = { "Prinzessin Theradras" } },
    [7065] = { title = "Verderbnis von Erde und Samenkorn", summary = "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück.", desc = "In den Tiefen von Maraudon lebt eine Kreatur des Chaos und des Bösen, <Name>. Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den alten Göttern verwandt ist. Vor langer Zeit stattete Zaetar, der erstgeborene Sohn von Cenarius, ihr einen Besuch ab. Die Nachkommen ihrer ... Beziehung sind jene Kreaturen, die unter dem Namen Zentauren bekannt sind. Diese undankbaren Kreaturen töteten Zaetar und Theradras bewacht nun seine Überreste. Meine Aufgabe besteht darin, jemanden zu finden, der mächtig genug ist, um Theradras zu erschlagen, damit wir Zaetars Überreste holen können, bevor wir in das Steinkrallengebirge zurückkehren.", objectives = { "Prinzessin Theradras" } },
    [7066] = { title = "Samenkorn des Lebens", summary = "Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens.", desc = "Diese missratenen Zentauren - meine Söhne und Töchter - brauchen ihren Vater.\n\nSeht Euch um - dieser Ort hallt wider von Hoffnung und all jenem, was mein Vater Cenarius predigt. All das entsprang aus mir! Und ich kann ihnen das nicht nehmen... nicht einmal ob ihrer Verbrechen gegen mich.\n\nEines jedoch möchte ich von Euch erbitten, damit mein Bruder Ruhe findet. Nehmt dies... es ist das erste Samenkorn, das aus dem Leben entstand, das meine Überreste nährten. Sagt ihm, dass mein Geist hier bleibt und dass ich weiterlebe. Er wird es sicherlich verstehen." },
    [7067] = { title = "Die Anweisungen des Pariahs", summary = "Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace.", desc = "Obwohl ich als Ketzer verbannt wurde, bleibe ich meinem Glauben treu - das allein treibt mich voran. Aber damit mein Schicksal sich erfüllt, benötige ich die Hilfe eines Außenstehenden... jemanden, der keinem Zentaurenstamm angehört.\n\nFür diese Aufgabe muss jemand die heiligen Hallen von Maraudon betreten - das ist ein Tempel, den mein Volk schützt, und nur die Gläubigsten dürfen ihn betreten.\n\nWenn Ihr einwilligt, mir zu helfen, dann müsst Ihr nur nicken. Ich werde Euch ein Pergament mit meinen Anweisungen geben. Lest es durch und denkt über meine Worte nach.", objectives = { "Amulett der Vereinigung", "Amulett der Geister" } },
    [7068] = { title = "Schattensplitter", summary = "Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar.", desc = "Man findet starke Magie am heiligen Ort der Zentauren... dem heiligen Ort von Maraudon. Die Desolace-Stämme der Zentauren schützen diesen Ort mit ihrem Leben, aber sie können uns nicht davon abhalten, das zu nehmen, was wir brauchen.\n\nBegebt Euch zu diesem Maraudon-Ort und sucht nach den Felskreaturen, die aus Schattenstein bestehen. Bringt mir die lila Kristalle und Uthel'nay wird Euch Eure Mühe vergelten.\n\nDer Ort ist gefährlich, daher solltet Ihr einige Freunde mitnehmen.", objectives = { "Schattensplitter x 10" } },
    [7070] = { title = "Schattensplitter", summary = "Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow.", desc = "Ich habe kürzlich begonnen, verschiedene Kristalle und ihre arkanen Eigenschaften zu testen. Lady Proudmoore hat mir die Erlaubnis erteilt, Reisende, die nach Desolace ziehen, zu bitten, einen Ort zu suchen, der Maraudon genannt wird. In dem zerfallenen Tempel dort gibt es große Elementare, die aus lila Steinen bestehen. Ich habe sie Schattensplitter getauft.\n\nFalls Ihr beschließt, diese Richtung einzuschlagen, und dort einige dieser Kristalle findet, wäre ich sehr dankbar. Ich würde Euch sogar ein Schmückstück daraus herstellen, wenn Ihr dies wünscht.", objectives = { "Schattensplitter x 10" } },
    [7201] = { title = "Das letzte Element", summary = "Begebt Euch in die Blackrocktiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat.", desc = "Es gibt Arbeit für diejenigen, die sich in die Tiefen wagen, <Name>.\n\nDen Dunkeleisenzwergen ist es gelungen, extrem mächtige Golems zu erschaffen.\n\nErsten Berichten unserer Spione zufolge verwenden die Zwerge eine einzigartige Kraftquelle, die ihren Schöpfungen eine unvergleichliche Kraft zum Töten gibt.\n\nStellt Euch nur einmal vor, was wir mit unseren Monstrositäten tun könnten, wenn wir diese Essenz der Elemente in die Hände bekommen könnten! Stellt die ganze Stadt auf den Kopf, wenn es sein muss, aber kommt nicht wieder, ehe Ihr nicht die Essenz gefunden habt! Die Bezahlung ist es wert, das Risiko einzugehen.", objectives = { "Essenz der Elemente x 10" } },
    [7441] = { title = "Pusillin und der Älteste Azj'Tordin", summary = "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben. Kehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück.", desc = "Ich habe nur einen Moment nicht aufgepasst, Fremder. In meiner Eile, dem Griff des gefallenen Prinzen zu entkommen, wurde ich ausgeraubt. Ein besonders widerlicher Dämon, namens Pusillin, stahl mir mein Buch der Zauberformeln und den Schlüssel zu den einstmals großen Hallen von Eldre'Thalas.\n\nMein Interesse am Schlüssel ist verloschen als ich meine Unsterblichkeit gegen die Freiheit eingetauscht habe. Doch ich benötige unbedingt mein Buch der Zauberformeln.\n\nFindet den Dämon Pusillin und bringt mir mein Buch.\n\nSucht Pusillin im Wucherborkenviertel von Düsterbruch.", objectives = { "Buch der Zauberformeln" } },
    [7461] = { title = "Der innere Wahnsinn", summary = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen. Betretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten. Kehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", desc = "Habt Ihr genug gehört? Seid Ihr <ein Mann/eine Frau> der Tat?\n\nDieser Wahnsinn muss ein Ende haben. Das Zeitalter der Unsterblichen ist lange vergangen. Vernichtet die Wächter rings um die Pylonen herum, um das Kraftfeld zu senken. Habt Ihr das erst einmal geschafft, könnt Ihr Immol'thar vernichten. Die Macht des Prinzen wird stark geschwächt sein, greift ihn an und beendet seine Existenz. Gewährt den Geistern dieser Stadt ihre letzte Ruhe, Abenteurer.", objectives = { "Immol'thar", "Prinz Tortheldrin" } },
    [7463] = { title = "Arcane Erfrischung", summary = "Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück.", desc = "Ein <Volk> Magiekundiger! Wie wunderbar. Ich habe jemanden wie Euch schon seit... wie lange ist es nun schon her?... 500 Jahren nicht mehr gesehen!\n\nIch habe da etwas, dass Euren Durst zu löschen vermag, doch zuerst müsst Ihr etwas für mich erledigen.\n\n<Lydros kichert.>\n\nEs gibt eine Anomalie in Eldre'Thalas. Ein Wasserelementar hat sich im östlichen Flügel niedergelassen. Seine Anwesenheit muss unbedingt katalogisiert werden!\n\nReist nach Düsterbruch in das Wucherborkenviertel und sammelt etwas von der elementaren Essenz der Hydrobrut. Bringt Sie anschließend zu mir zurück und ich werde Euch einen äußerst nützlichen Zauberspruch beibringen.", objectives = { "Hydrobrutessenz" } },
    [7481] = { title = "Elfische Legenden", summary = "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei Sage Korolusk in Camp Mojache.", desc = "Vor vielen Jahren entkam ein einzelner Elfenmeister namens Kariel Winthalus der Vernichtung seines Heimatlandes. Bei sich trug er einige uralte Artefakte der Elfen.\n\nUnsere Suche nach dem verschwundenen Meister führte uns von den Ruinen Quel'Thalas, durch die brennende Steppe, über die großen Weiten der See, hinüber nach Feralas.\n\nWir nehmen an, dass der Elf in den Hallen von Eldre'Thalas, die nun als Düsterbruch bekannt sind, Schutz suchte.\n\nIhr müsst ihn finden, Abenteurer. Ob er nun lebt oder schon lange tot ist, das Wissen, welches er bei sich trug, muss gerettet werden!", objectives = { "Meister Kariel Winthalus gefunden" } },
    [7482] = { title = "Elfische Legenden", summary = "Sucht in Düsterbruch nach Kariel Winthalus. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon.", desc = "Vor vielen Jahren entkam ein einzelner Elfenmeister namens Kariel Winthalus der Vernichtung seines Heimatlandes. Bei sich trug er einige uralte Artefakte der Elfen.\n\nUnsere Suche nach dem verschwundenen Meister führte uns von den Ruinen Quel'Thalas, durch die brennende Steppe, über die großen Weiten der See, hinüber nach Feralas.\n\nWir nehmen an, dass der Elf in den Hallen von Eldre'Thalas, die nun als Düsterbruch bekannt sind, Schutz suchte.\n\nIhr müsst ihn finden, Abenteurer. Ob er nun lebt oder schon lange tot ist, das Wissen, welches er bei sich trug, muss gerettet werden!", objectives = { "Meister Kariel Winthalus gefunden" } },
    [7488] = { title = "Lethtendris' Netz", summary = "Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas.", desc = "Die Magierin Lethtendris, eine bösartige Blutelfe, deren Brutalität nur durch ihre pervertiere Hingabe zur Magie in den Schatten gestellt wird, ist nach Düsterbruch geflüchtet. Sie hat eine Apparatur entwickelt, ein Netz, um die magischen Energien dieses Ortes einzufangen und wir fürchten, dass wenn Sie niemand aufhält, sie der Welt einen unwiderruflichen Schaden zufügen wird!\n\nStoppt Sie, <Name>. Findet Sie und nehmt das Netz an Euch. Am ehesten werdet Ihr sie nahe den Satyrn, im Wucherborkenviertel von Düsterbruch, finden. Bringt das Netz anschließend zu mir und ich werde versuchen, dessen Kräfte wieder der Wildnis zurückzugeben...", objectives = { "Lethtendris' Netz" } },
    [7489] = { title = "Lethtendris' Netz", summary = "Bringt Lethtendris' Netz zu Talo Thornhoof im Camp Mojache in Feralas.", desc = "Die Blutelfe Lethtendris hat ihre Grenzen überschritten. So versessen war sie darauf magische Macht zu erlangen, das sie ihre Brüder verraten und eine teuflische Apparatur gebaut hat, ein Netz welches in der Lage ist, die verdorbenen magischen Energien von Düsterbruch einzufangen. Selbst jetzt sammelt sie diese Energien und plant, sie gegen ihre Feinde einzusetzen.\n\nLethtendris muss aufgehalten werden. Sucht sie im Wucherborkenviertel von Düsterbruch, besiegt sie und bringt anschließend ihr Netz zu mir. So kann es vielleicht wieder in die Hände einiger Blutelfen übergeben werden, die dieses Artefakt mit klarem Verstand untersuchen können.", objectives = { "Lethtendris' Netz" } },
    [7492] = { title = "Camp Mojache", summary = "Sprecht mit Talo Thornhoof in Camp Mojache, in Feralas.", desc = "Talo Thornhoof, ein Taurenältester in Feralas, hat uns um Hilfe gebeten. Er hat nur wenige Einzelheiten verraten, doch wie es scheint sucht er nach Agenten für eine Angelegenheit, die sowohl heikel als auch dringend ist.\n\nDient der Horde, <Name>. Begebt Euch ins Camp Mojache in Feralas und sprecht mit Talo." },
    [7494] = { title = "Die Festung Feathermoon", summary = "Sprecht mit Latronicus Moonspear in der Festung Feathermoon, in Feralas.", desc = "<Name>! Man braucht Euch in Feralas!\n\nEine abtrünniger Magierin, Lethtendris, ist in die uralten Elfenruinen von Eldre'thalas, vielen bekannt als Düsterbruch, geflohen. Es wird angenommen, dass Sie einen gefährlichen Gegenstand voller magischer Energien bei sich trägt, der dringend wiederbeschafft werden muss.\n\nLatronicus Moonspear hat Agenten angefordert, die in Düsterbruch eindringen und den Gegenstand von Lethtendris zurückholen sollen.\n\nDient der Allianz! Sucht Latronicus in der Festung Feathermoon, in Feralas auf." },
    [7507] = { title = "Forors Kompendium", summary = "Bringt Forors Kompendium des Drachentötens zurück in das Athenaeum.", desc = "Ihr habt etwas von größter Wichtigkeit entdeckt. Dieses Buch ist anders, als alle anderen die Ihr bisher gesehen habt.\n\nEs scheint, als hätte jemand oder etwas es geschafft, das Siegel des Athenaeums aufzubrechen. Der Text in seinem Inneren ist beschädigt und schwer lesbar." },
    [7668] = { title = "Die Bedrohung durch Schattensichel", summary = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn. Bringt Schattensichels Kopf zu Sagorne Creststrider im Tal der Weisheit in Orgrimmar.", desc = "Der Todesritter Schattensichel herrscht über das große Ossuarium in Scholomance. Er droht die spirituelle Ebene zu seinen eigenen Zwecken zu missbrauchen... Er muss gestoppt werden! Dabei kommt das Orakel der Anrufung, bei dessen Herstellung Ihr behilflich wart, zum Einsatz.\n\nSetzt das Orakel inmitten des Kellergewölbes des großen Ossuariums ein, um Schattensichels Geistergefolge herbeizurufen. Besiegt die Geister und der Todesritter selbst wird erscheinen. <Name>, bringt mir seinen Kopf! Lediglich seine Niederlage wird den Schaden, den er der spirituellen Ebene zugefügt hat, wieder umkehren können!", objectives = { "Schattensichels Kopf" } },
    [7703] = { title = "Die offene Rechnung der Gordok", summary = "Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch. Kromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.", desc = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von gruseligen Elfen, der sich selbst nennen Prinz! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur de' wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, de' gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", objectives = { "Stulpen der Gordokmacht" } },
    [7761] = { title = "Blackhands Befehl", summary = "Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen. Dem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen.", desc = "Schwachkopf,\n\nich habe Euch immer für unfähig gehalten, Fremde daran zu hindern, den Hort unseres Herrn zu betreten. Für den sehr wahrscheinlichen Fall Eures Todes hat diese Kugel einen eingebauten Sicherheitsmechanismus der verhindert, dass sich Außenstehende direkt in den Pechschwingenhort teleportieren können.\n\nNur diejenigen, denen das Mal von Drakkisath in die Handfläche eingebrannt wurde, können die Kugel überhaupt benutzen. Glücklicherweise ist Drakkisath nicht einmal ansatzweise so inkompetent wie Ihr, Rüstmeister. Er selbst bewacht das Brandzeichen!\n\nKriegshäuptling Rend Blackhand\n\nP.S. Verbrennt diesen Brief, Idiot!" },
    [7848] = { title = "Abstimmung mit dem Kern", summary = "Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück.", desc = "Risse und Abgründe bilden sich um uns herum und kollabieren wieder, <Volk>. Keine zwei Schritte von mir entfernt, ist ein Riss, der hinab in die tiefsten Tiefen des Blackrock führt, bis in die Ruhestätte des Feuerfürsten.\n\nÜberrascht? Wie bedauerlich... Ihr sterblichen Völker versteht einfach nichts, was Ihr nicht sehen, anfassen oder fühlen könnt.\n\nIch versichere Euch, das Portal ist da und es ist passierbar.\n\nHabe ich Euer Interesse geweckt? Eine Anpassung ist simpel. Begebt Euch in die Blackrocktiefen und findet ein Kernfragment. Bringt es zu mir zurück und ich werde Eure Essenz mit dem Portal abstimmen.", objectives = { "Kernfragment" } },
    [8905] = { title = "Ein aufrichtiges Angebot", summary = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Ironforge.", desc = "Seid gegrüßt, <Klasse>. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", objectives = { "Blutprobe aus Winterspring x 15", "Armschienen des Wildherzens" } },
    [8921] = { title = "Der Ektoplasmadestillierer", summary = "Kehrt mit einem empfindlichen Arkanitwandler, 4 großen ewigen Essenzen, 10 Flaschen Steinschuppenöl, 25 Einheiten Vulkanasche und 40 Gold im Gepäck zu Mux Manascrambler in Gadgetzan zurück.", desc = "Ah, Ihr seid an meinem letzten Projekt interessiert... Dem extradimensionalen Geisterdetektor! Dummerweise sind mir die Geldmittel und Hilfskräfte ausgegangen\n\nIhr sagt, dass Ihr mir aushelfen wollt? Sehr gut! Zunächst müssen wir einen Apparat bauen, der die Essenz des Todes absaugen kann! Einen Ektoplasmadestillierer zu konstruieren wird allerdings nicht ganz einfach sein, <Name>.\n\nIhr müsst mir einen Arkanitwandler, einige große ewige Essenzen und Steinschuppenöl bringen. Außerdem brauche ich noch Vulkanasche aus den Lavatümpeln in der brennenden Steppe, um einen Filter zu konstruieren.", objectives = { "Empfindlicher Arkanitwandler", "Große ewige Essenz x 4", "Steinschuppenöl x 10", "Vulkanasche x 25" } },
    [8922] = { title = "Ein übernatürlicher Apparat", summary = "Bringt den versiegelten Blutbehälter zu Mux Manascrambler in Gadgetzan.", desc = "Ich muss einen Weg finden, mit Anthion Harmon zu sprechen... Oder genauer gesagt mit seinem Geist!\n\nIch kenne da einen Ingenieur, der eine gewisse Faszination für das Übernatürliche hegt. Er behauptet eine Maschine konstruieren zu können, die es ihm erlaubt mit den Toten zu kommunizieren!\n\nDas Blut, dass Ihr gesammelt habt, war für ihn bestimmt. Reist nach Gadgetzan und bringt es ihm als Bezahlung für seine Dienste!" },
    [8924] = { title = "Ektoplasmajagd", summary = "Benutzt den Ektoplasmadestillierer in der Nähe von schemenhaften Untoten, um 12 Einheiten versengtes Ektoplasma in Silithus, 12 Einheiten gefrorenes Ektoplasma in Winterspring und 12 Einheiten stabiles Ektoplasma in den östlichen Pestländern zu erhalten. Bringt das Ektoplasma dann mitsamt des Ektoplasmadestillierers zu Mux Manascrambler in Gadgetzan zurück.", desc = "Ein hervorragendes Stück Ingenieurarbeit, wenn ich das mal selbst so sagen darf! Ich fürchte allerdings, dass Ihr weit umherreisen werden müsst, um die Art schemenhafter Untoten zu finden, die wir benötigen.\n\nIhr müsst verstehen, dass verschiedenen Klimabedingungen Einfluss auf die spektrale Struktur der Toten haben. Die gequälten Nachtelfen in Silithus, die Geister der Hochgeborenen in Winterspring und die Geister und Banshees in den östlichen Pestländern sollten uns mit den verschiedenen Sorten von Ektoplasma versorgen, die wir benötigen. Stellt auf jeden Fall den Destillierer in der Nähe auf, bevor Ihr sie bekämpft.", objectives = { "Versengtes Ektoplasma x 12", "Gefrorenes Ektoplasma x 12", "Stabiles Ektoplasma x 12" } },
    [8925] = { title = "Eine portable Energiequelle", summary = "Findet Magmafürst Bokk in der brennenden Steppe, nehmt seinen Magmakern an Euch und bringt ihn zu Mux Manascrambler in Gadgetzan.", desc = "Jetzt brauchen wir nur noch eine stabile und portable Energiequelle, um das Ektoplasma aktiv zu halten. Ich habe Gerüchte über einen machtvollen Elementar namens Magmafürst Bokk gehört, dessen Herz ein mächtiger Magmakern ist - eine schier unerschöpfliche Hitzequelle!\n\nMan sagt, dass er sich irgendwo in der brennenden Steppe südlich des Blackrock herumtreibt. Bringt mir den Magmakern und wir werden genug Saft haben, um den extradimensionalen Geisterdetektor zu betreiben!", objectives = { "Magmakern" } },
    [8926] = { title = "Die angemessene Entlohnung", summary = "Bringt Deliana in Ironforge einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", desc = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.", objectives = { "Gürtel des Wildherzens", "Handschuhe des Wildherzens" } },
    [8928] = { title = "Ein verschlagener Händler", summary = "Sucht den Wichtel in der Höhle in der Nähe der flüsternden Schlucht im Süden von Winterspring. Kauft ihm einen teufelselementaren Brennstab ab und kehrt zu Mux Manascrambler in Gadgetzan zurück.", desc = "Der Kern sollte uns mit genügend Energie zum Betreiben des Apparates versorgen, jetzt brauchen wir nur noch einen Brennstab, der diese Energie auch weiterleiten kann, ohne dabei zu schmelzen.\n\nIch habe in Winterspring mal einen Wichtel getroffen, der allerlei exotische Waren im Angebot hatte. Er hatte einen elementaren Brennstab, der einfach perfekt gewesen wäre. Ich könnte mich schwarzärgern, dass ich den nicht gekauft habe.\n\nEr lebt in einer Höhle nahe dem Zugang zur flüsternden Schlucht. Schleicht Euch hinein und seht zu, dass Ihr ihn findet.\n\nLasst Euch aber nicht von ihm übers Ohr hauen, zahlt ihm nicht mehr als 40 Goldstücke. Den Preis hat er mir damals angeboten!", objectives = { "Teufelselementarer Brennstab" } },
    [8929] = { title = "Suche nach Anthion", summary = "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.", desc = "Tja, wir haben wohl keine andere Wahl, als die Erfindung des Goblins auszuprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemetzelt wurde, als er versuchte, durch dessen Tore zu schreiten.\n\nVersucht den Apparat dort zu benutzen und herauszufinden, was auch immer Anthion wusste." },
    [8945] = { title = "Die letzte Bitte eines toten Mannes", summary = "Geht nach Stratholme und befreit Ysida Harmon aus den Fängen von Baron Rivendare.", desc = "Ich werde Euch mit den Informationen, nach denen Ihr verlangt, versorgen, <Name>. Aber jetzt gibt es Wichtigeres zu tun.\n\nMeine geliebte Frau wird von Rivendares Abschaum gefangen gehalten.\n\nIch war immer dagegen, dass sie sich dem närrischen Kreuzzug der Argentumdämmerung anschließt, aber jetzt ist es zu spät für Schuldgefühle. Ihr müsst das vollbringen, wozu ich nicht fähig war. Ihr müsst Ysida aus den Fängen des Barons befreien!", objectives = { "Ysida befreit" } },
    [8977] = { title = "Rückkehr zu Deliana", summary = "Bringt Deliana in Ironforge den extradimensionalen Geisterdetektor.", desc = "War mir eine Freude, mit Euch zusammenzuarbeiten, <Name>. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden." },
    [92401] = { title = "Eine verängstigte Bitte", summary = "Untersucht das Verschwinden von Edward Heartweaver in den Ruinen von Lordaeron.", desc = "Es geht um meinen Mann, Edward...\n\nEr ist nicht von seiner wöchentlichen Reise zum Friedhof in den Ruinen von Lordaeron zurückgekehrt. Unser Sohn ging verloren, als Arthas die Stadt zerstörte, und mein geliebter Edward hat noch immer Schuldgefühle und leidet darunter, dass wir seine Leiche nie gefunden haben. Ich habe ihn davor gewarnt, diese überrannten Ruinen zu durchsuchen, aber er weigert sich aufzugeben. Ich versuche, mir keine Sorgen zu machen, aber er ist schon seit Tagen fort.\n\nEs gibt dort Dinge, mit denen ich es nicht aufnehmen kann. Aber wärt Ihr vielleicht so gut? Ich muss Gewissheit über das Schicksal meines Ehemanns haben.", objectives = { "Untersucht das Verschwinden von Edward Heartweaver in den Ruinen von Lordaeron." } },
    [92415] = { title = "Denk daran, ich liebe dich", summary = "Bringt den blutbefleckten Brief zu Waisenmatrone Nightingale in Stormwind.", desc = "<Ein zerrissenes und schmutziges Pergamentbündel hat gerade so die von Untoten zertrampelte Friedhofserde überstanden. Darin wird ein vermisstes Kind der Familie Heartweaver erwähnt. Vielleicht weiß die Waisenmatrone in Stormwind mehr darüber.>" },
    [92421] = { title = "Die Gerechtigkeit des Lichts", summary = "Sammelt 25 intakte Gliedmaßen in den Ruinen von Lordaeron für Morbin Lightbane in Undercity.", desc = "Als Paladin der Verlassenen ist es meine Pflicht, den Willen der Dunklen Fürstin auszuführen und gleichzeitig die Bedürfnisse unseres Volkes zu erfüllen. Zum Glück bietet sich uns eine Gelegenheit, beides zu tun.\n\nÜber Undercity streifen immer noch Anhänger der Geißel in großen Zahlen herum. Unsere Truppen schwinden beim Versuch, unser Land zurückzuerobern, und verwesendes Fleisch kann nicht geflickt werden. Nicht ohne Ersatzteile.\n\nIch weiß, was unser glorreicher Hauptmann Garek Bandarion sich wünschen würde, wäre er noch unter uns. Zu beenden, was er begonnen hat, und unser Volk zu heilen. Für Lordaeron!", objectives = { "Intakte Gliedmaßen x 25" } },
    [92422] = { title = "Der Zorn von Rath'mael", summary = "Tötet Rath'mael in den Ruinen von Lordaeron für Todeswache Kristof in Brill.", desc = "Es sind Berichte aus der Warte Lordamere tief in den Ruinen von Lordaeron eingetroffen. Ein unheiliger Nebel hat sich über die Straßen und den Friedhof gelegt, der es der Geißel dort oben teilweise erlaubt, im Verborgenen zu agieren.\n\nUnsere Späher berichten, dass er von einer neuen Macht in ihren Rängen herbeigerufen wird, einem Totenbeschwörer namens Rath'mael. Wir können es uns nicht leisten, dem einfach zuzusehen, <Name>.\n\nWenn Ihr Verbündete habt, versammelt sie, und eilt den Verlassenen zur Hilfe. Vertreibt diese Kreatur aus unseren Landen.", objectives = { "Rath'mael" } },
    [92742] = { title = "Test der Brunnen", summary = "Nutzt das Set für Brunnenwasserproben, um Proben aus den Brunnen auf Jansens Hof und Molsens Hof zu sammeln.", desc = "Wir müssen die Quelle und Natur des Gifts, das dieses Land verdirbt, bestimmen. Lasst uns mit dem Grundwasser unter den Höfen in diesem Gebiet beginnen.\nGeht zu Jansens Hof und Molsens Hof, und sammelt Proben von den Brunnen dort.", objectives = { "Wasserprobe von Jansens Hof", "Wasserprobe von Molsens Hof" } },
    [92744] = { title = "Murlochkiemen", summary = "Alba Fairmoon möchtet, dass Ihr 7 Murlockiemen von Longshore an der Küste von Westfall sammelt.", desc = "Die Verderbnis, die die Pflanzen von Westfall befallen hat, ist möglicherweise auch ins Meer gesickert. Wenn auch die örtlichen Fische betroffen sind, könnte es Stormwind zu einer Hungersnot verdammen.\nSammelt Kiemen von den Murlocs an der Küste und bringt sie zu mir. Murlocs sind ziemlich zäh, aber ihre Physiologie ist extrem empfindlich gegenüber Schadstoffen. Jegliche Giftstoffe im Meerwasser werden in den Kiemen, die Ihr findet, offensichtlich zu finden sein.", objectives = { "Murlockiemen von Longshore x 7" } },
    [92745] = { title = "Der Status der Minen", summary = "Tötet 4 Koboldbuddler im Jangoschacht und 6 Minenarbeiter der Flusspfoten im Goldküstensteinbruch.", desc = "Die Brunnenproben, die Ihr gesammelt habt, enthalten giftige Metalle! Wenn wir dieser Verderbnis nicht schnell ein Ende bereiten, wird es Jahrzehnte dauern, bis wir etwas in diesem Boden anpflanzen können.\nDie Defias haben die Minen von Westfall beschlagnahmt und nutzen Kreaturen als Arbeitskräfte, um Ressourcen abzubauen. Stört sie, indem Ihre ihre Minenarbeiter im Jangoschacht im Norden und im Goldküstensteinbruch im Westen tötet.", objectives = { "Koboldbuddler x 4", "Minenarbeiter der Flusspfoten x 6" } },
    [92747] = { title = "Moonbrookspionage", summary = "Sammelt 8 verdächtige Industriebedarfsvorräte von Moonbrook.", desc = "Seltsam... Das Gift scheint nicht aus den Minen zu stammen, die Ihr untersucht habt.\n\nEs heißt, die Todesminen unter der Stadt Moonbrook wären die größten und tiefsten Minen von Westfall, wurden aber mit dem Ersten Krieg aufgegeben. Könnten die Todesminen wieder aktiv sein?\n\nBitte reist nach Moonbrook, <Name>, und sucht nach Hinweisen auf Bergbau- oder Industrieaktivitäten. Das ist die letzte Spur, die wir haben!", objectives = { "Verdächtige Industriebedarfsvorräte x 8" } },
    [92748] = { title = "Explosive Beratung", summary = "Reist zum Zwergendistrikt in Stormwind und findet einen Ingenieur, der Euch helfen kann.", desc = "Die Vorräte, die Ihr gefunden habt, deuten auf eine groß angelegte industrielle Operation irgendwo in den Todesminen hin. Es besteht kein Zweifel, dass sie die Ursache für die Toxine ist, die das Ackerland von Westfall kontaminieren Wir müssen dem so schnell wie möglich ein Ende machen.\n\nWas auch immer dort unten ist, wird nur schwer zu zerstören sein. Begebt Euch zum Zwergendistrikt von Stormwind und treibt einen Ingenieur auf, der uns mit Sprengstoff versorgen kann." },
    [92749] = { title = "Ein explosiver Plan", summary = "Erhaltet 10 grobes Dynamit durch Herstellung, Handel oder im Auktionshaus, und kehrt anschließend zu Sprite Jumpsprocket im Zwergendistrikt von Stormwind zurück.", desc = "Industriesabotage? Ihr habt meine Aufmerksamkeit!\nBeginnen wir mit etwas Dynamit...", objectives = { "Grobes Dynamit x 10" } },
    [92750] = { title = "Detonation aus der Ferne", summary = "Sprecht mit jemanden beim Geheimdienst von Stormwind über die Beschaffung eines Fernzünders.", desc = "Ich nehme an, Ihr wollt eine \"kontrollierte\" Explosion? Macht nicht so viel Spaß, aber eine gute Wahl, wenn Ihr all Eure Gliedmaßen behalten möchtet.\nIch fürchte, ich habe keinen Fernzünder. Ihr solltet Euch mit den raffinierten Leuten beim Geheimdienst von Stormwind unterhalten. Sie sollten in der Lage sein, etwas für uns zu finden." },
    [92751] = { title = "Detonation aus der Ferne", summary = "Bringt das Fernzünderset zu Sprite Jumpsprocket im Zwergendistrikt von Stormwind.", desc = "Ihr müsst etwas zerstören? Das hat nicht zufällig etwas mit Euren Aktivitäten in Moonbrook zu tun? Schaut nicht so überrascht. SI:7 ist immer auf dem Laufenden über alles, was in Stormwind vor sich geht.\nWenn Ihr vorhabt, eine Explosion in den Höhlen unter Westfall auszulösen, müsst Ihr Euch lange aus dem Staub gemacht haben, bevor alles in die Luft geht. Nehmt diesen Fernzünder - er ist ein neuer Prototyp von unseren Ingenieuren.\nOh, und es wäre wohl am besten, wenn Ihr meine Beteiligung gegenüber Eurem Elfenfreund nicht erwähnt." },
    [92752] = { title = "Explosive Beratung", summary = "Kehrt zu Alba Fairmoon in Westfall zurück.", desc = "Fertig, die Bombe ist bereit! Seid vorsichtig mit dem Zünder." },
    [92753] = { title = "Zerstörung in den Todesminen", summary = "Findet die versteckte Schmiede in den Todesminen und platziert die besonders zerstörerischen Sprengladungen in der Nähe. Trefft dann Alba Fairmoon am Ausgang der Todesminen.", desc = "Die Quelle dieses Gifts ist wahrscheinlich eine Art große metallurgische Schmiede. Sucht einen Weg in die Todesminen und findet die Schmiede. Platziert dann den Sprengstoff.\nIch warte auf den Hügeln hinter Moonbrook auf Euch. Sobald Ihr zurückkehrt, sprengen wir die Schmiede in die Luft. Hoffentlich kann das Land heilen, sobald sie fort ist.", objectives = { "Sprengsätze platziert" } },
    [92819] = { title = "Zerstörung in den Todesminen", summary = "Verwendet den Zünder.", desc = "Wir sind fast fertig. Verwendet den Zünder und macht dem ein Ende.", objectives = { "Zünder benutzt" } },
    [95189] = { title = "Wappen von Lordaeron", summary = "Bringt das Wappen von Lordaeron zu Lady Dena Kennedy in Stormwind.", desc = "<Ein verwittertes Wappen zeigt das Emblem von Lordaeron. Bei den wenigen Relikten, die nach dem Fall des Reiches noch übrig sind, gibt es sicherlich jemanden in Stormwind, der daran Interesse hat.>" },
    [95195] = { title = "Blutverschmiertes Insigne", summary = "Sammelt 10 blutverschmierte Insignien und bringt sie zu General Marcus Jonathan in Stormwind.", desc = "<Die alte Allianzinsignie scheint einem Soldaten von Lordaeron gehört zu haben. Diese Ruinen sind vermutlich voll mit ähnlichen Medaillen, die deren Hinterbliebene bestimmt gern zurück haben würden.>" },
    [95204] = { title = "Wappen von Lordaeron", summary = "Bringt das Wappen von Lordaeron zu Oran Snakewrithe in Undercity.", desc = "<Ein verwittertes Wappen zeigt das Emblem von Lordaeron. Bei den wenigen Relikten, die nach dem Fall des Reiches noch übrig sind, gibt es sicherlich jemanden in Undercity, der daran Interesse hat.>" },
    [95216] = { title = "Die neue Seuche", summary = "Bergt den hochgiftigen Erreger von Welkzahn in den Ruinen von Lordaeron für Theodore Griffs in Undercity.", desc = "Herzlich willkommen im lebenswichtigsten Organ von Undercity, dem Apothekarium! Hier führen wir Experimente an den aggressivsten exotischen Exemplaren von Azeroth durch.\n\nIch bin gut gelaunt, deswegen will ich Euch von meiner neuesten Untersuchung berichten. Anscheinend lauert ein besonders giftiger Gliederfüßler in den Ruinen über unserer schönen Stadt. Sein Gift soll sogar untotes Fleisch zersetzen. Wie aufregend!\n\nIch möchte der Sache gerne nachgehen. Und solltet Ihr aufgrund seines Bisses verkümmern, hätte ich gerne eine Probe.", objectives = { "Hochgiftiger Erreger" } },
    [95250] = { title = "Scheußliche Kreaturen", summary = "Holt den Kopf des Barons in den Ruinen von Lordaeron und bringt ihn zu Hauptmann Truman.", desc = "Was wollt Ihr, <Volk>? Seht Ihr nicht, dass es hier einen Krieg zu gewinnen gilt?\n\nMein Meister ist schon in den Kampf gestürmt und hat mir befohlen, auf meinem Posten zu bleiben. Das ist allerdings schon einige Zeit her.\n\nIch bezweifle, dass Ihr zehn Minuten im Kampf überleben würdet, aber wenn es Euren beschränkten Geist beschäftigt, dann sucht doch den Großmarschall auf. Er ist der größte Held, den Ihr je erblickt habt, mit einer Gestalt wie eine Statue. Ihr erkennt ihn, wenn Ihr ihn seht.", objectives = { "Kopf des Barons" } },
    [96391] = { title = "Karte des Untergrunds", summary = "Bringt die Dunkeleisenkarte zu Erdseher Farsen in Dun Morogh.", desc = "<Die Karte in Eurer Hand zeigt offenbar eine komplexe Reihe von unterirdischen Tunneln und Gängen, die alle an einem Punkt unter Ironforge selbst zusammenzuführen scheinen.\n\nIhr könnt die Runen nicht entziffern, da sie in der hässlichen gezackten Runensprache der Dunkeleisenzwerge geschrieben sind, aber Ihr könnt den Zweck dieser Tunnel erraten. Während Ihr die Karte studiert, erfasst Euch ein Windhauch und Ihr könnt schwach eine Zwergenstimme darin hören. Erdseher Farsen muss hiervon erfahren.>" },
    [96393] = { title = "Eindringlinge in der Altstadt von Ironforge", summary = "Betretet die Halle der Thanen unter der Altstadt von Ironforge und besorgt den Kopf von Durgen Dirgehammer.", desc = "Versammelt einige Verbündete und steigt in die Höhlen unter der Altstadt von Ironforge hinab. Betretet dort die Halle der Thanen und dringt bis zu den unteren Gewölben vor.\n\nMein Dunkeleisenzwergisch ist etwas eingerostet, aber ich kann einen Namen entziffern – Durgen Dirgehammer. Wahrscheinlich ist er der Kommandant. Schlagt seinen Kopf ab und bringt ihn zu König Magni Bronzebeard.\n\nOh, und richtet ihm aus, dass sein alter Freund Farsen ihn grüßen lässt!", objectives = { "Durgen Dirgehammers Kopf" } },
    [96394] = { title = "Die rastlosen Toten", summary = "Tötet 15 wütende Erscheinungen und 10 gepeinigte Seelen, und bettet den Geist von Anvilmar zur Ruhe.", desc = "Etwas hat die Gräber unten in der Halle der Thanen gestört, und seltsame Geräusche waren zu hören, die tief aus den Gewölben kamen. Die Geister der Toten haben einen leichten Schlaf, und was auch immer dort unten vor sich geht, scheint sie aufgeschreckt zu haben.\n\nGeht dort hinunter und seht, was Ihr für uns tun könnt. Wenn einer der Toten erwacht ist – nun, dann schickt ihn wieder zurück ins Grab!", objectives = { "Wütende Erscheinung x 15", "Gepeinigte Seele x 10" } },
    [96395] = { title = "Ein uralter Groll", summary = "Bettet den Geist von Faldrim Anvilmar in der Halle der Thanen zu Ruhe.", desc = "Der... Than... Mein mächtiger... Than... Er... muss... ruhen.\n\nBitte... helft ihm... Helft ihm... zu ruhen...\n\nVerzehrt... von... altem... Groll... Keine... Ruhe...", objectives = { "Faldrim Anvilmar" } },
    [96403] = { title = "Wichtige Erbstücke", summary = "Sammelt 8 zwergische Erbstücke in der Halle der Thanen.", desc = "Ihr da, <Abenteurer/Abenteurerin>... ich brauche Eure Hilfe.\n\nIch bin im Gewölbe herumgeschlichen – äh, ich meine \"patrouilliert\", als ein Trupp Dunkeleisenzwerge mit Maulwurfmaschinen aus der Tiefe kam! ich weiß nicht, was sie hier wollen, aber es gibt wertvolle Beute – äh, ich meine natürlich \"wichtige kulturelle Erbstücke\" da unten! Bitte, bergt alle Relikte dieser Art, die Ihr findet, und bringt sie hierher.\n\nIch versichere Euch, dass jeder Eurer Funde katalogisiert und an seinen rechtmäßigen Ehrenplatz zurückgebracht wird.", objectives = { "Zwergisches Erbstück x 8" } },
    [97288] = { title = "Endlose Qual", summary = "Bringt den monströsen Kopf jemanden in Undercity.", desc = "<Als die Kreatur umfällt, kullert ihr Kopf zu Boden. Es wirkt, als wäre er schon des Öfteren wieder angebracht worden. Die Verbindung scheint mit jedem neuerlichen Anbringen schwächer zu werden.\n\nIrgendjemand in Undercity weiß bestimmt mehr über diese einzigartige Monstrosität.>", objectives = { "Bringt den monströsen Kopf jemanden in Undercity." } },
    [98423] = { title = "Das Abkommen des Einvernehmens", summary = "Bringt das Abkommen des Einvernehmens zu Magni Bronzebeard in Ironforge.", desc = "Im Inneren der Kammer findet Ihr eine Tafel, auf der die Bedingungen des Friedensvertrages zwischen den Klans der Bronzebeard- und Wildhammerzwerge festgehalten sind. Sie scheint aus der Zeit kurz nach dem Krieg der Drei Hämmer zu stammen und ist zweifelsohne ein wertvolles Stück Zwergengeschichte. Der König von Ironforge hätte bestimmt Interesse an diesem Artefakt." },
  },
  enUS = {
    [17] = { title = "Uldaman Reagent Run", summary = "Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.", desc = "I've heard about a newly discovered plant called the magenta fungus caps. They grow in clusters, deep in the Uldaman dig site; they may be elsewhere, but for now that's the only place I know they're at. I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps. Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", objectives = { "Magenta Fungus Cap x 12" } },
    [65] = { title = "The Defias Brotherhood", summary = "Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.", desc = "The band of wretches responsible for driving the good people of Westfall from the land call themselves The Defias Brotherhood. I need you to infiltrate this clan of thugs. We need to know who heads up the cartel and where they are hiding out. In Lakeshire, in the inn, there is a rogue by the name of Wiley who owes me a favor.\n\nTravel to Lakeshire in the Redridge Mountains, east of Elwynn, and find out what you can." },
    [132] = { title = "The Defias Brotherhood", summary = "Take Wiley's Note to Gryan Stoutmantle in Westfall.", desc = "What I am about to tell you could cost me my life. The Defias gang is up to something big. Last I heard they were working in conjunction with various gnolls, kobolds and even goblins.\n\nTake this note to Stoutmantle. It explains as much as I know on the subject." },
    [135] = { title = "The Defias Brotherhood", summary = "Take Wiley's Note to Mathias Shaw in Stormwind.", desc = "I wonder what Wiley meant when he mentioned the Stonemasons. Perhaps that was a slip of tongue. Could the Defias gang be related to the Stonemasons? Only one man would know for sure: Mathias Shaw, head of SI:7. Show him Wiley's Note and see if he has anything to add to this growing mystery. If you have trouble finding Shaw, check the Barracks in Old Town." },
    [141] = { title = "The Defias Brotherhood", summary = "Take Shaw's report to Gryan Stoutmantle in Westfall.", desc = "The Stonemasons' Guild was run by a man named Edwin VanCleef. VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War. Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete. That just might explain a thing or two.\n\nI have written a more detailed account for your Master in Westfall. Take this to him at once!" },
    [142] = { title = "The Defias Brotherhood", summary = "Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.", desc = "We need to discover the location of the Defias hideout. <name>, my scout reports that a Defias Messenger has been seen on the roads between Moonbrook, the Gold Coast Quarry and the Jangolode Mine. I want you to capture him. If he resists, kill him and bring me whatever he is carrying.", objectives = { "A Mysterious Message" } },
    [155] = { title = "The Defias Brotherhood", summary = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.", desc = "So Stoutmantle sends a scrawny <race> like you to protect me? Guess you'll have to do. Better bring some friends too.\n\nYou know the deal, right? You watch my back and I'll take you to the Defias hideout. But you better be close by my side. The Defias gang wants my head now. If they see me with you, they'll try to kill me.\n\nLet me know when you and any friends you can round up are ready to go.", objectives = { "Escort The Defias Traitor to discover where VanCleef is hiding" } },
    [166] = { title = "The Defias Brotherhood", summary = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.", desc = "There is but one task left for you to complete. Edwin VanCleef must be assassinated. While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all. Bring me the villain's head once the deed is done.", objectives = { "Head of VanCleef" } },
    [167] = { title = "Oh Brother...", summary = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.", desc = "We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us. I got out but the others... well... the others haven't been heard from.\n\nYou look like you might have better luck in there. If you could look for my brother, I'd be thankful. He always carried his Explorers' League Badge. If you can't find him, that badge would at least give me some peace of mind.", objectives = { "Thistlenettle's Badge" } },
    [168] = { title = "Collecting Memories", summary = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.", desc = "Many of my friends perished that horrible day when the mine tunnel caved in. If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them. If you come across any of their Miners' Union Cards, bring them back to me and I'll make sure their families get some resolution from this horrible accident.", objectives = { "Miners' Union Card x 4" } },
    [214] = { title = "Red Silk Bandanas", summary = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.", desc = "It's no secret that the trademark of the Defias Gang is their Red Bandanas. But we've learned that the material from which these bandanas are made signifies the member's rank.\n\nThat being said, I want you to eliminate as many high ranking Defias members as you can. The highest ranking members will undoubtedly be found in VanCleef's secret hideout. When you're done bring me 10 Red Silk Bandanas as proof of their deaths and I will reward you. Good luck, <name>.", objectives = { "Red Silk Bandana x 10" } },
    [261] = { title = "Down the Scarlet Path", summary = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.", desc = "I will be frank. We are at war with the Scourge. It is an evil that corrupts our people and infects our land. It must be stopped before it overwhelms us and drags our world into shadow. We of the Scarlet Crusade have sworn to fight the Scourge with body and soul.\n\nIf you are with us, then gather your courage and prove your allegiance--destroy the undead ravagers of Desolace, in the Valley of Bones to the south.\n\nDo this, and the Crusade will embrace you.", objectives = { "Undead Ravager x 30" } },
    [303] = { title = "The Dark Iron War", summary = "Motley Garmason at Dun Modr wants you to kill 15 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.", desc = "War rages both home and abroad. While mighty Dwarven soldiers give their lives in far off territories in the name of the Alliance, our own lands fall prey to the evil deeds of the Dark Iron Dwarves. They laid waste to the Thandol Span. Dun Modr fell soon after.\n\nWe need you to gather force and push the front back. If you can kill 15 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs and 5 Demolitionists, the reserve might arrive in time to finish the drive.\n\nNow make haste!", objectives = { "Dark Iron Dwarf x 15", "Dark Iron Tunneler x 5", "Dark Iron Saboteur x 5", "Dark Iron Demolitionist x 5" } },
    [373] = { title = "The Unsent Letter", summary = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.", desc = "Searching Edwin VanCleef's person, you discover, among other things, an unsent letter. It is addressed to Baros Alexston, the City Architect of Stormwind, City Hall, Cathedral Square.\n\nIt appears to be recently written and sealed." },
    [377] = { title = "Crime and Punishment", summary = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.", desc = "As if the neglect for the residents of Duskwood was not bad enough, now the House of Nobles spits in the eye of the Darkshire Council with their decision to imprison Dextren Ward in Stormwind rather than behead the villain as per Lord Ebonlocke's sentence.\n\nWard was caught selling bodies from the cemetery to Morbent Fel, a crime punishable by death. Yet Stormwind claims Ward as their prisoner.\n\nAssassinate Ward in The Stormwind Stockade - bring me his hand - and I shall reward you.", objectives = { "Hand of Dextren Ward" } },
    [378] = { title = "The Fury Runs Deep", summary = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.", desc = "You have proven your loyalty to King Magni, <class>. And your hatred for the Dark Iron scum is as great as my own.\n\nThere is a task I wish to complete myself but I am bound by honor to stay with Longbraid. But Roggo has gathered intelligence that proves Kam Deepfury was a conspirator in the attack on the Thandol Span. It was by Deepfury's planning that Longbraid lost his kin.\n\nDeepfury is being held for political reasons in the Stormwind Stockade. I want him dead, <name>. For Longbraid! Bring me his head!", objectives = { "Head of Deepfury" } },
    [386] = { title = "What Comes Around...", summary = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.", desc = "Targorr the Dread served under Gath'Ilzogg as supreme Executioner. His methods were ruthless, even by filthy orc standards. Men who fought bravely to defend the Kingdom were tortured on his whim. Now he is being held in the Stormwind Stockade, sentenced to die. Yet something is amiss. One of the bureaucratic nobles put a hold on his execution. I am sure foul play is in the works.\n\nPut an end to Targorr the Dread, <name>. Travel to The Stockade and behead him before trickery is upon us.", objectives = { "Head of Targorr" } },
    [387] = { title = "Quell the Uprising", summary = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.", desc = "The uprising must be quelled! I need your assistance. If word gets out that the prison is overrun I will lose my job! This is a case of foul play if I've ever seen one. But what's important now is forcing these prisoners into submission for the safety of Stormwind.\n\nThe punishment for insurgency is death. Kill some of these deviants! That ought to get things under control.", objectives = { "Defias Prisoner x 10", "Defias Convict x 8", "Defias Insurgent x 8" } },
    [388] = { title = "The Color of Blood", summary = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.", desc = "Bitterness flows through my veins like a cold river. My grandson, Mac, was such a good boy. A mere 14 years old. When the army was sent off to the front, Mac took up arms to defend the city. He was a guard in The Stockade, where the Defias gang is locked up. Mac reprimanded some of the prisoners for tearing their wool blankets to make scarves, a symbol of their gang. For that Mac was stabbed in the back.\n\nI want revenge. Bring me 10 of their precious Wool Bandanas. They are the color of blood.", objectives = { "Red Wool Bandana x 10" } },
    [389] = { title = "Bazil Thredd", summary = "Speak with Warden Thelwater in the Stockade.", desc = "VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War.\n\nWhen we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge.\n\nHis lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Stockade." },
    [391] = { title = "The Stockade Riots", summary = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.", desc = "Let's get one thing straight, <name>: I don't trust you. But, with the situation as it is, you probably won't make a difference.\n\nSo here's how it's going to be: go down there and have your talk with Thredd. If you're really on our side, then kill him and bring me his head when the job's done. And if it turns out you're on his side, and don't come out... when we find you, you'll die along with the rest of the maggots.", objectives = { "Head of Bazil Thredd" } },
    [704] = { title = "Agmond's Fate", summary = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.", desc = "The last report I received from Agmond is troubling, more so now that he's dead! He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman. I fear that the urns he found at that site incited the troggs, just as did the idols I found here.\n\nI need you to get those urns for our studies. Go to the Uldaman site, gather the urns, then return to me.", objectives = { "Carved Stone Urn x 4" } },
    [707] = { title = "Ironband Wants You!", summary = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.", desc = "<name>. I received reports from Prospector Ironband at his excavation site in Loch Modan--he needs some legwork done concerning another of our excavations.\n\nI don't have more details than that, but if you want to stretch your legs then go speak with Ironband." },
    [709] = { title = "Solution to Doom", summary = "Bring the Tablet of Ryun'eh to Theldurin the Lost.", desc = "Oh my! Oh my! There is a doom approaching. Mark me! A doom!\n\nNo, I cannot speak of it...cannot utter their names or they may hear me! But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!\n\nMaybe.\n\nGo into Uldaman. No! I said it! You must find...find the tablet of...Ryun'eh. Yes, find it! And don't make me speak that name again!\n\nIt is deep in that place, in an ancient chest. That's where it hides...in a chest crafted before the works of any dwarf.", objectives = { "Tablet of Ryun'eh" } },
    [720] = { title = "A Sign of Hope", summary = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.", desc = "<There is text roughly scribbled in chalk on the map.>\n\n\"Ryedol,\nThey're taking me to Uldaman. Send help.\n-Hammertoe\"" },
    [721] = { title = "A Sign of Hope", summary = "Find Hammertoe Grez in Uldaman.", desc = "<name>, can ye find him? Can you find Hammertoe in Uldaman?\n\nIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.\n\nFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.\n\nThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!" },
    [722] = { title = "Amulet of Secrets", summary = "Find Hammertoe's Amulet and return it to him in Uldaman.", desc = "Ye're brave... <cough>... to come into Uldaman fer me, <class>.\n\nIf ye're really here to help... ol' Hammertoe, then... <cough>... you'll need to find... me amulet.\n\nDeepshadow's got it... Magregan Deepshadow. He's 'round here... in the ruins fer sure. That amulet'll lead 'em... <cough>... right to the scrolls if he ain't stopped. It's up to you, <name>. Please... get that amulet.\n\nThe scrolls will surely help the Dark Irons create even more powerful golems. I just know it. I can feel it in me bones.", objectives = { "Hammertoe's Amulet" } },
    [723] = { title = "Prospect of Faith", summary = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.", desc = "<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.>\n\nFind Ryedol, <name>. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>" },
    [724] = { title = "Prospect of Faith", summary = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.", desc = "Okay, okay... who would know what to do?\n\nHistorian Karnik! That's it!\n\nHe's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman.\n\nGuess the Shadowforge found out the two of them knew more than they were lettin' on.\n\nTell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next." },
    [725] = { title = "Passing Word of a Threat", summary = "Find Advisor Belgrum and give him his note.", desc = "<name>, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him.\n\nIn the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray." },
    [726] = { title = "Passing Word of a Threat", summary = "Speak to Historian Karnik.", desc = "<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>\n\nOch, these are evil tidings.\n\n<name>, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands." },
    [738] = { title = "Find Agmond", summary = "Find Agmond.", desc = "Prospector Agmond was in charge of our excavation sites in the Badlands, to the southwest. I say \"was\" because...well, I haven't heard from him in weeks. I need you to find Agmond so I can get his report.\n\nLast I heard Agmond was at the southernmost dig site in the Badlands--a tiny operation past the Angor Fortress. I'd start your search for him there." },
    [739] = { title = "Murdaloc", summary = "Slay Agmond's killer, Murdaloc. Slay 12 Stonevault Bonesnappers. Report to Prospector Ironband in Loch Modan.", desc = "Agmond's tracks lead from the west. It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance.\n\nAnd here he died.\n\nUpon close inspection, the word \"Murdaloc\" is roughly scrawled in a patch of Badlands sandstone.\n\nScrawled next to Agmond's dead hand.", objectives = { "Murdaloc", "Stonevault Bonesnapper x 12" } },
    [762] = { title = "An Ambassador of Evil", summary = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.", desc = "Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman.\n\nIt has already meant tremendous casualties for our people, but it has obviously grown worse. I hesitate to guess how many artifacts they would be able to find and use against Ironforge.\n\nOur goal is simple, <class>. Return to the Badlands and destroy Ambassador Infernus. Once the threat is eliminated, return to Advisor Belgrum with proof of your victory.\n\nIt is in your hands now.", objectives = { "Ambassador Infernus' Bracer" } },
    [865] = { title = "Raptor Horns", summary = "Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.", desc = "The raptors of the Barrens are smarter than raptors in other lands. And I think all that smarts is hiding in their horns! If so, then I could grind their horns into powder and use it to make \"smart drinks.\" I could sell them for a fortune!!!\n\nAnd you can help me. Find me intact raptor horns from sunscale scytheclaws. They roam in the southern Barrens, and in the northern Barrens near the border of Ashenvale Forest.", objectives = { "Intact Raptor Horn x 5" } },
    [870] = { title = "The Forgotten Pools", summary = "Report back to Tonga Runetotem with your findings. -", desc = "Long ago, the Barrens was a lush place, teeming with life. But war and cataclysm raged across the land, scorching it and leaving a dry husk. Such is the way of things, and it saddens my heart.\n\nBut within the past few years, new oases have formed in the Barrens, and life stirs. And deep down, we druids sense a power leaking its way to the surface.\n\nWe must find its source. Travel to the Forgotten Pools, northwest of the Crossroads. Search its waters for a source of power, then return here.", objectives = { "Explore the waters of the Forgotten Pools" } },
    [877] = { title = "The Stagnant Oasis", summary = "Return to Tonga at The Crossroads, after investigating the Stagnant Oasis.", desc = "Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens. If so, then perhaps the fissures are the oases' source of life.\n\nWe must test this.\n\nHere, take these seeds. They are dead and infertile, but take them to the Stagnant Oasis to the southeast. If there is a fissure there, then place the seeds within it...and observe.", objectives = { "Test the Dried Seeds", "Recipe: Soothing Turtle Bisque" } },
    [880] = { title = "Altered Beings", summary = "Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.", desc = "Your findings are incredible, <name>. These oases hold properties that must come from an outside source. Or perhaps an inside one.\n\nI want to know how these fissures are affecting the beasts who drink from the oases' water.\n\nHunt oasis snapjaws at the Lushwater and Stagnant Oases. Bring me their shells so I may examine them.", objectives = { "Altered Snapjaw Shell x 8" } },
    [914] = { title = "Leaders of the Fang", summary = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.", desc = "The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.\n\nThe Druids of the Fang have four leaders, and each possesses a dream gem. Even now their faces haunt me! Defeat the leaders and bring me their gems, and the Barrens may again know peace.\n\nGo, <name>. You will find them lurking deep within the Wailing Caverns.", objectives = { "Gem of Cobrahn", "Gem of Anacondra", "Gem of Pythas", "Gem of Serpentis" } },
    [959] = { title = "Trouble at the Docks", summary = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.", desc = "Oops!\n\nHad a little mishap, as you can see! The morning cargo shipment from Booty Bay was huge. Huge I say! Never seen so many crates. Well, I was trying to expedite things so I started unloading a bit more than I could handle. That's when everything came tumbling down.\n\nBefore I knew what was going on, I saw that menace, Mad Magglish, go running off with a bottle of 99-year-old port. Chased him all the way to Wailing Caverns. No way I was going in there.\n\nMaybe you're brave enough to find him?", objectives = { "99-Year-Old Port" } },
    [962] = { title = "Serpentbloom", summary = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.", desc = "The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, <name>. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken.\n\nRecently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential.\n\nUnfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.", objectives = { "Serpentbloom x 10" } },
    [971] = { title = "Knowledge in the Deeps", summary = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.", desc = "As you might know, I collect lore. Old lore. Powerful lore. Lore that opens doorways, and lore that can awaken Those Who Sleep.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in Ashenvale. That place is the old dwelling of long-dead elves. Elves who held great knowledge before their city fell to ruin.\n\nSearch Blackfathom Deeps for the manuscript. Do this, and I will not forget it. Not even after ... the end days.", objectives = { "Lorgalis Manuscript" } },
    [1013] = { title = "The Book of Ur", summary = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.", desc = "<name>, Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection. Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to ... certain parties among the Forsaken.\n\nEnter Shadowfang Keep and find the book. Bring it to me, and I will report your service to our Dark Lady...", objectives = { "The Book of Ur" } },
    [1014] = { title = "Arugal Must Die", summary = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.", desc = "Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain.\n\nI shall see to it that his magic is eradicated, <name>. But I leave it in your hands to see that Arugal meets the death he so deserves.\n\nTravel to Shadowfang Keep and put an end to Arugal's foul spells once and for all. Bring to me the vile wizard's head!", objectives = { "Head of Arugal" } },
    [1048] = { title = "Into The Scarlet Monastery", summary = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.", desc = "Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly.\n\nNo doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants.\n\nTravel to the Monastery, <class>, and lay waste to High Inquisitor Whitemane and her top lieutenants.", objectives = { "High Inquisitor Whitemane", "Scarlet Commander Mograine", "Herod", "Houndmaster Loksey" } },
    [1049] = { title = "Compendium of the Fallen", summary = "Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.", desc = "The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?\n\nThe Forsaken whom we have allied with have a history wrought with deceit. Too hasty was our pact. Perhaps Cairne would have been wise to heed the warnings from Orgrimmar.\n\nDeep within the Scarlet Monastery lies the Compendium of the Fallen, guarded by crazed human zealots. Their method is forged from insanity but their research might prove useful.", objectives = { "Compendium of the Fallen" } },
    [1050] = { title = "Mythology of the Titans", summary = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.", desc = "The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea.\n\nBut perhaps, by studying the past, we can know what to expect and be better prepared for the unknown.\n\nBefore dire troubles fell upon Lordaeron, there was a bastion of knowledge tucked away in the Tirisfal Glades. It is rumored that a book called Mythology of the Titans was housed in the library of the old Monastery.\n\nBring it to me and perhaps together we can unlock the secrets of the past!", objectives = { "Mythology of the Titans" } },
    [1051] = { title = "Vorrel's Revenge", summary = "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.", desc = "Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered.\n\nInterrogator Vishas did this to me! Tortured me for weeks! Took my wedding ring and gave it to his wife. The bastard!\n\nRevenge... I want revenge!\n\nThe pompous fool bragged about his precious wife, Nancy, who lived along Lake Lordamere. Track the wench down, slay her and return my wedding ring to my wife, Monika in Tarren Mill.\n\nHeed my last wishes....", objectives = { "Vorrel's Wedding Ring" } },
    [1052] = { title = "Down the Scarlet Path", summary = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.", desc = "We of the Scarlet Crusade lay claim to strongholds from Hearthglen to Tirisfal Glades. We are quite proud of our bastions of cleansing throughout Lordaeron.\n\nYou have proven yourself against the undead in Desolace. But the true threat of the plague lies in Lordaeron.\n\nTravel to the town of Southshore, in the Eastern Kingdoms. Seek out a crusader named Raleigh the Devout. Give him this letter of commendation bearing my seal and he will escort you to a place of honor in our Scarlet Monastery." },
    [1053] = { title = "In the Name of the Light", summary = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.", desc = "I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead.\n\nBut as I spent time at the Monastery in Tirisfal Glades I realized that their grasp on reality was slipping. They now think everyone is plagued who doesn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued.\n\nThe Scarlet Crusade must be crushed in the name of the Light. You, <name>, must destroy the deranged regime.", objectives = { "High Inquisitor Whitemane", "Scarlet Commander Mograine", "Herod", "Houndmaster Loksey" } },
    [1098] = { title = "Deathstalkers in Shadowfang", summary = "Find the Deathstalker Adamant and Deathstalker Vincent.", desc = "In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence. It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!\n\nSo here is your task, <name>. Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent. Find them, and if they require aid then give it.\n\nThis mission is as dangerous as is it critical, <name>. Do not fail." },
    [1100] = { title = "Lonebrow's Journal", summary = "Read Henrig Lonebrow's Journal.", desc = "You slowly open the weathered journal of Henrig Lonebrow...." },
    [1101] = { title = "The Crone of the Kraul", summary = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.", desc = "Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was.\n\nWe must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped.\n\nSurely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. <name>, assemble a party to slay the crone.\n\nBring me Razorflank's Medallion as proof of demise.", objectives = { "Razorflank's Medallion" } },
    [1102] = { title = "A Vengeful Fate", summary = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.", desc = "Cairne is a noble leader for uniting our people here on Thunder Bluff.\n\nBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.\n\nA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.\n\nBring me Razorflank's heart and I can die in peace, <name>.", objectives = { "Razorflank's Heart" } },
    [1109] = { title = "Going, Going, Guano!", summary = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", desc = "As you can see, <name>, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a <class>. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...", objectives = { "Kraul Guano" } },
    [1113] = { title = "Hearts of Zeal", summary = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.", desc = "Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.\n\nIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate. Slay them and bring me their zealous hearts.\n\nOur concoction will be most wicked!", objectives = { "Heart of Zeal x 20" } },
    [1139] = { title = "The Lost Tablets of Will", summary = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.", desc = "We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say.\n\nWe must still recover the Tablet before the Shadowforge clan finds it.\n\nReturn to Uldaman, find the tablet, and return here immediately.", objectives = { "Tablet of Will" } },
    [1142] = { title = "Mortality Wanes", summary = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.", desc = "I have not long to live... so... so... weak.\n\n...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel...\n\nBut before I... d-d-die...\n\n...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors...\n\nFind it p-p-please... and return it to Treshala in Darnassus...\n\n...along with w-w-word of my lonely... death.", objectives = { "Treshala's Pendant" } },
    [1144] = { title = "Willix the Importer", summary = "Escort Willix the Importer out of Razorfen Kraul.", desc = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Redleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", objectives = { "Help Willix the Importer escape from Razorfen Kraul" } },
    [1149] = { title = "Test of Faith", summary = "If you have faith, leap from the planks overlooking Thousand Needles.", desc = "So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.\n\nMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.\n\nIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.\n\nThe first is a Test of Faith.", objectives = { "The Cauldron" } },
    [1150] = { title = "Test of Endurance", summary = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.", desc = "I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body.\n\nFirst is a test of endurance. Go with friends to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test.", objectives = { "Grenka's Claw", "Flank of Meat" } },
    [1151] = { title = "Test of Strength", summary = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.", desc = "During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.\n\nThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.\n\nTo test your strength, find Rok'Alim in Thousand Needles and slay him.", objectives = { "Fragments of Rok'Alim" } },
    [1152] = { title = "Test of Lore", summary = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", desc = "Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.\n\nIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, <name>.\n\nWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, <name>, the night elves may wish to impede your test." },
    [1154] = { title = "Test of Lore", summary = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", desc = "You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.\n\nI shall explain it simply: find the book I name, study it, and answer my question about its contents.\n\nWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.", objectives = { "Legacy of the Aspects" } },
    [1159] = { title = "Test of Lore", summary = "Find Parqual Fintallas in Undercity.", desc = "Well done, <name>. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.\n\nSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.\n\nHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle." },
    [1160] = { title = "Test of Lore", summary = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.", desc = "I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.\n\nGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.\n\nBring it to me.", objectives = { "Beginnings of the Undead Threat" } },
    [1198] = { title = "In Search of Thaelrid", summary = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.", desc = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale.\n\nMy role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out and aid Thaelrid for me, <name>." },
    [1199] = { title = "Twilight Falls", summary = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.", desc = "Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps on the coast of Ashenvale.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", objectives = { "Twilight Pendant x 10" } },
    [1200] = { title = "Blackfathom Villainy", summary = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.", desc = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Selgorm in Darnassus, <name>, please.", objectives = { "Head of Kelris" } },
    [1221] = { title = "Blueleaf Tubers", summary = "Grab a Crate with Holes. Grab a Snufflenose Command Stick. Grab and read the Snufflenose Owner's Manual. In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers. Bring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.", desc = "Blueleaf tubers are a delicacy around the world! But they're rare, very rare. The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look! That's why I've trained these snufflenose gophers to find them for me. They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.", objectives = { "Blueleaf Tuber x 6", "Crate With Holes", "Snufflenose Owner's Manual", "Snufflenose Command Stick" } },
    [1275] = { title = "Researching the Corruption", summary = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.", desc = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the elves are headed toward. In Blackfathom Deeps, on the coast of Ashenvale, you will find both satyr and naga.\n\n'Tis a long journey, <name>.", objectives = { "Corrupted Brain Stem x 8" } },
    [1360] = { title = "Reclaimed Treasures", summary = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.", desc = "I had myself a fine job as a digger at the Uldaman excavation site in the Badlands... that is until those blasted troggs showed up. I escaped with my hide barely intact, and nothing else. In the chaos, I left my most treasured possession. It's safe from the troggs in my chest, sure, but it's right in the thick of 'em.\n\nI'd be in your debt, both in honor and coin, if you could fetch it for me! A chest with my name on it is at the end of the North Common Hall. That's the one you need to get in.", objectives = { "Krom Stoutarm's Treasure" } },
    [1424] = { title = "Pool of Tears", summary = "Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts.", desc = "The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.\n\nThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.\n\nThe green dragons now guard the site, claiming to be protectors of Azeroth.\n\nWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.", objectives = { "Atal'ai Artifact x 10" } },
    [1429] = { title = "The Atal'ai Exile", summary = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.", desc = "While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.\n\nThis priest was sentenced to a fate worse than death amongst the Atal'ai.\n\nHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.\n\nI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete." },
    [1444] = { title = "Return to Fel'Zerul", summary = "Return to Fel'Zerul in Stonard.", desc = "Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.\n\nHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.\n\nWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.\n\nThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril...." },
    [1445] = { title = "The Temple of Atal'Hakkar", summary = "Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.", desc = "So he spoke of Jammal'an's prophecy?\n\nThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.\n\nFoolish trickery to bring about a premature doomsday if you ask me.\n\nBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.\n\nVenture into the Temple, and seize the fetishes!", objectives = { "Fetish of Hakkar x 20" } },
    [1446] = { title = "Jammal'an the Prophet", summary = "The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.", desc = "My Witherbark companions don't take kindly to strangers around their home.\n\nMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.\n\nOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.\n\nBut I urged caution. What if the prophecy was nothing more than manipulation?\n\nI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free.", objectives = { "Head of Jammal'an" } },
    [1448] = { title = "In Search of The Temple", summary = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.", desc = "There was a time when I was young and full of vigor like you, <class>.\n\nBut now I'm old and unable to explore the world like I once did. Ah, the things I saw!\n\nBut there was one mystery that eluded me. For my final quest, the Explorers' League sent me in search of The Temple of Atal'Hakkar. It was rumored to be located in the Swamp of Sorrows.\n\nBecause of my frail state, I traveled the skies by gryphon in search of it but never found it.\n\nHelp an old dwarf out? Perhaps you will have better luck on foot.", objectives = { "Razor Hill", "Search for the Temple of Atal'Hakkar" } },
    [1449] = { title = "To The Hinterlands", summary = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.", desc = "As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.\n\nI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...\n\nIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.\n\nJourney there and seek out Falstad Wildhammer.\n\nWe need to find out what happened to that pilot." },
    [1450] = { title = "Gryphon Master Talonaxe", summary = "Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary.", desc = "So you're a glorified errand <boy/girl> for some old Explorers' League geezer, eh?\n\nWell you listen to me, <class>. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?\n\nIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.\n\nNow get a move on." },
    [1451] = { title = "Rhapsody Shindigger", summary = "Seek out Rhapsody Shindigger in The Hinterlands.", desc = "Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.\n\nBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.\n\nFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.\n\nLast I heard, he's set up a brew camp to the east of here..." },
    [1452] = { title = "Rhapsody's Kalimdor Kocktail", summary = "Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers.", desc = "Hiccup!\n\nSo that crazy fool Brohann sent ya? My we had quite an adventure...Hiccup!\n\nIf ya want me to tell ya what happened down in the swamp, I'm gonna need me something stiff to drink. It wasn't a pretty scene, ya see. Hiccup!\n\nTell ya what... bring me what I need to whip up a Kalimdor Kocktail and I'll tell ya all about it.\n\nGonna need some Roc gizzards from Tanaris... and let's see... some Groddoc and Ironfur livers from Feralas...\n\nA nice stiff Kalimdor Kocktail... that'll get me talking!", objectives = { "Roc Gizzard x 3", "Ironfur Liver x 3", "Groddoc Liver x 3" } },
    [1469] = { title = "Rhapsody's Tale", summary = "Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.", desc = "Before the flight, I drank me a whole keg of stout. Hiccup!\n\nAnd what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup!\n\nWell, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hiccup!" },
    [1475] = { title = "Into The Temple of Atal'Hakkar", summary = "Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.", desc = "According to legend, The Temple of Atal'Hakkar is a holy shrine dedicated to the ancient god, Hakkar the Soulflayer. Maintained by a vicious tribe of trolls named the Atal'ai, the temple is rumored to be impenetrable.\n\nNow sunk beneath the Pool of Tears, retrieving artifacts from the temple is even more difficult. But that's what I need you to do, <name>.\n\nAid me by gathering the intact Atal'ai Tablets. Bring them to me and I will return to the Explorers' Guild a hero. Together we will share the glory.", objectives = { "Atal'ai Tablet x 10" } },
    [1486] = { title = "Deviate Hides", summary = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.", desc = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking.\n\nIf you feel up to the task, venture into the caves below and retrieve some deviate hides.", objectives = { "Deviate Hide x 20" } },
    [1487] = { title = "Deviate Eradication", summary = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.", desc = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong.\n\nNaralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns.\n\nWhile some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts.\n\nBrave the caverns, <name>, and eradicate the deviate spawn.", objectives = { "Deviate Ravager x 7", "Deviate Viper x 7", "Deviate Shambler x 7", "Deviate Dreadfang x 7" } },
    [1489] = { title = "Hamuul Runetotem", summary = "Speak with Hamuul Runetotem", desc = "The shells you brought me have a taint, one I have never before seen. I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land. It is as if the land dreams and cannot awake.\n\nThe Wailing Caverns must be the source of the taint. But before you go there, speak with Hamuul Runetotem, the elder druid. I sent word to him of the happenings in the Barrens. He is wise, and can offer you counsel.\n\nYou will find him in Thunder Bluff, on the Elder Rise." },
    [1490] = { title = "Nara Wildmane", summary = "Speak with Nara Wildmane.", desc = "I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns. I saw that their goals were once noble, but they have lost their way. They are now servants of the taint seeping through the Barrens.\n\nI am old and my strength fails. I could not long dwell in that dreaming place and know little more of the tainted druids. But Nara is young and her spirit is fierce. She remained in the dreaming when I fled.\n\nSpeak with Nara. She is in the tent, over yonder." },
    [1491] = { title = "Smart Drinks", summary = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.", desc = "Ok, so the raptor horns didn't work so well. But that's all right -- no one got rich on their first try! And besides, I think I found something that'll work even better in my smart drinks!\n\nThere is a substance called Wailing Essence, and I think it is the cause of the strange plants and animals in the Barrens. Get me some and I'll try it in my drink!\n\nI heard the essence gathers in ectoplasmic creatures in the Wailing Caverns to the west. Hunt those creatures and gather the essence.", objectives = { "Wailing Essence x 6" } },
    [1649] = { title = "The Tome of Valor", summary = "Speak to Duthorian Rall in Stormwind.", desc = "Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows.\n\nThis strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot." },
    [1650] = { title = "The Tome of Valor", summary = "Find Daphne Stilwell in Westfall.", desc = "Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.\n\nAt the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.\n\nReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there." },
    [1651] = { title = "The Tome of Valor", summary = "Defend Daphne Stilwell from the Defias attack. Neither of your spirits must be released from their mortal coils if you wish to succeed. After you are successful, speak to Daphne Stilwell again.", desc = "Now, they'll be coming again soon, I'd wager, so get yourself ready.\n\nI've got myself a gun in the house. I'll grab it and be ready to help you out, but for the most part, you're on your own.\n\nI've no idea how many they'll send, but I'm sure it'll be more than the few they sent earlier.\n\nAsk the Light for whatever blessings you can because... did you hear that? I think they're coming.\n\nWe make our stand near the house!", objectives = { "Protect Daphne Stilwell" } },
    [1652] = { title = "The Tome of Valor", summary = "Speak to Duthorian Rall in Stormwind.", desc = "Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that.\n\nHe'll send word to Ironforge to let my Jordan know that he has nothing to fear.\n\nOh, how I miss my husband. I can't wait till he returns." },
    [1653] = { title = "The Test of Righteousness", summary = "Speak to Jordan Stilwell in Ironforge", desc = "Actually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice.\n\nJordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful.\n\nHe should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air." },
    [1654] = { title = "The Test of Righteousness", summary = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.", desc = "I'd like to reward you if you'd be willing to accept such a thing? Don't misunderstand me, my generosity is dependent on how much help you can be, but I see us both benefiting greatly from such an alliance.\n\nI will craft for you a weapon worthy of what you've accomplished, a symbol of paladinhood and the Light, but you must gather the items I need to craft it. I've already started taking notes on the items, it just requires someone brave and skilled enough to recover them. What do you say, <class>?", objectives = { "Whitestone Oak Lumber", "Jordan's Refined Ore Shipment", "Jordan's Smithing Hammer", "Purified Kor Gem" } },
    [1740] = { title = "The Orb of Soran'ruk", summary = "Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.", desc = "When demons of the Legion fall out of favor, their spirits are imprisoned within orbs and distributed to their mages and warlocks.\n\nMany were carried by their servants in Azeroth. Even fragmented, they still possess the powers of the demons trapped inside.\n\nThe orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps. The other, larger piece, was possessed by a wizard in Shadowfang Keep. Find them and I can reform it.", objectives = { "Soran'ruk Fragment x 3", "Large Soran'ruk Fragment" } },
    [1947] = { title = "Journey to the Marsh", summary = "Speak with Tabetha.", desc = "Now it is time for you to earn your mage's wand. To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh. You will find her shack deep in the marsh, west of Theramore.\n\nSpeak with her, for her knowledge is vast. You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins." },
    [1949] = { title = "Hidden Secrets", summary = "Speak with Magus Tirth in the Shimmering Flats.", desc = "To make your wand, there are key passages in a certain book that I must read. The book is called Rituals of Power, written by the Magus Tirth.\n\nI do not have a copy of his book, and none of the world's great libraries possess it. So you must speak with Tirth and gain it from him.\n\nGood luck. Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling." },
    [1950] = { title = "Get the Scoop", summary = "Find the phrase to Tirth's strongbox, then return to Tirth.", desc = "I can help you with the book, but first you have to help me!\n\nThe tome you seek is in my magically locked strongbox. To open it a special phrase must be uttered, and I can't remember the phrase! Normally my assistant helps me remember these things but he's nowhere to be found.\n\nIf you want my book, then find my apprentice! Ask around the race track--if you're lucky then someone has seen him. Either drag him back here, or at least get my magic phrase from him so we can open my box!", objectives = { "Secret phrase found" } },
    [1951] = { title = "Rituals of Power", summary = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.", desc = "Hm... now that I think about it, I don't have my book! You see, I had some gambling debts and to pay them off I sold the last copy of Rituals of Power to a member of the clergy....\n\nA member of the Scarlet Brotherhood. He must have taken it to their library in the Scarlet Monastery in Tirisfal Glades!\n\nIf you want that book, then you'll have to go to the monastery to find it. And sorry about all the trouble. I'm not myself these days...", objectives = { "Rituals of Power" } },
    [1953] = { title = "Return to the Marsh", summary = "Speak with Tabetha.", desc = "It is time, <name>, for you to speak with Tabetha... the hermit of Dustwallow Marsh. She will instruct you on the creation of a powerful mage's implement.\n\nTabetha's shack lies deep in Dustwallow Marsh, west of Theramore." },
    [1954] = { title = "The Infernal Orb", summary = "Bring an Infernal Orb to Tabetha in Dustwallow Marsh.", desc = "The first step is to acquire an orb with power. The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them! But we can fix that, yes we can.\n\nGo to Desolace and snatch an infernal orb from a Burning Blade summoner. You'll find summoners at the Mannoroc Coven.\n\nWhen you have the orb, return to me.", objectives = { "Infernal Orb" } },
    [1955] = { title = "The Exorcism", summary = "Kill the Demon of the Orb, then speak with Tabetha.", desc = "Now that we have a summoner's orb, we must exorcise the demon within it. I can do that. That's the easy part.\n\nYou're the one who has the hard job. You're the one who has to kill the demon once it's out.\n\nAnd you'll have to be quick. If you take too long then he'll jump back in the orb and we'll have to start over!\n\nSo get yourself ready. Prepare your strongest spells and keep your potions handy, and go get a friend if you have one. Because this isn't going to be pretty.", objectives = { "Demon of the Orb", "Kill the Demon of the Orb" } },
    [1956] = { title = "Power in Uldaman", summary = "Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", desc = "Now that the demon has been removed, we must gain a power source. Unfortunately, the best power sources are usually the oldest and the hardest to get. It's neat how fate likes to take a bite out of you sometimes, isn't it?\n\nSo you're going to need to go to Uldaman and defeat the obsidian sentinel there. He's big, he's tough, and his power source packs a punch!\n\nI wish you the best of luck, <name>. And if you don't get lucky then, well... it was nice knowing you.", objectives = { "Obsidian Power Source" } },
    [2040] = { title = "Underground Assault", summary = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.", desc = "Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help, <name>.\n\nDeep in the Deadmines is a functional goblin shredder. Find that shredder and bring back the intact power supply. With the shredder's power supply, we can give our gyrodrillmatic excavationators the power they need to break through the rocky underground borders of Gnomeregan, opening the way for a gnomish assault!", objectives = { "Gnoam Sprecklesprocket" } },
    [2198] = { title = "The Shattered Necklace", summary = "Search for the original creator of the shattered necklace to learn of its potential value.", desc = "You have found a tarnished necklace, though the tarnish belies intricate and magical craftsmanship. The necklace has been shattered, as its setting appears to be missing three gems. On the underside of the necklace is the faint imprint of the city seal for Ironforge. Below the seal are three tiny, engraved letters: \"TdK\".\n\nIf there is anything to be gleaned from the necklace, you will need to learn about its origins. Perhaps the seal and the initials are a start..." },
    [2202] = { title = "Uldaman Reagent Run", summary = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.", desc = "I've heard about a newly discovered plant called the magenta fungus caps. They grow in clusters, deep in the Uldaman dig site; they may be elsewhere, but for now that's the only place I know they're at. I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps. Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", objectives = { "Magenta Fungus Cap x 12" } },
    [2240] = { title = "The Hidden Chamber", summary = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike. -", desc = "Now for the task at hand.\n\nThere is a secret chamber, the Chamber of Khaz'mul, that must be explored. The problem is that the chamber's behind a huge, locked door! It's a lucky thing I know how to open it.\n\nI've described everything in my journal, here on the table. My band and I are stuck here for now... so you, <name>, must find the chamber of Khaz'mul for us!\n\nRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge.", objectives = { "Explore the Hidden Chamber" } },
    [2258] = { title = "Badlands Reagent Run", summary = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and 5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.", desc = "<name>, I could use your aid if you're up for it. I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards. Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal. Watcha wanna do?", objectives = { "Buzzard Gizzard x 5", "Crag Coyote Fang x 10", "Rock Elemental Shard x 5" } },
    [2278] = { title = "The Platinum Discs", summary = "Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon.", desc = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin. Touching them makes your hand tingle. Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations. I am a keeper of knowledge. The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!", objectives = { "Learn what lore that the stone watcher has to offer" } },
    [2283] = { title = "Necklace Recovery", summary = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged.", desc = "We've got work for you, that is if you've got the guts to do it!\n\nDeep in the Badlands is the Uldaman dig site. We've heard a tale about some idiot paladin who died there recently. Why we even care is that he had a very valuable necklace on him. It's supposedly got three large gems: a ruby, a sapphire, and a topaz.\n\nThe shot: we want it, and we're payin' TOP SILVER to get it. It may be damaged, but that's neither here nor there; we'll fix whatever scratches are on it.", objectives = { "Shattered Necklace" } },
    [2342] = { title = "Reclaimed Treasures", summary = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.", desc = "Sweeping the bat pens with this broom is not befitting a Garrett! I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.\n\nThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers. Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.\n\nReclaim my family's treasure and bring it to me! Help me restore my birthright!", objectives = { "Garrett Family Treasure" } },
    [2398] = { title = "The Lost Dwarves", summary = "Find Baelog in Uldaman.", desc = "The dig site at Uldaman wasn't always overrun. We Ironforge dwarves used to control the area, but... that was before the troggs came. They came so fast and in such numbers that not even dwarven might could stop them!\n\nIn fact, their attack was so sudden that I fear some of our people may be trapped behind enemy lines.\n\nMy friend Baelog led a small band of dwarves deep within the site just before the troggs showed up. If he and his company live, then I want you to find them." },
    [2418] = { title = "Power Stones", summary = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.", desc = "A while ago, I had an incident with the Shadowforge Dwarves. They brought me to Angor Fortress to study two types of strange stones from Uldaman. I discovered that the stones were sustained, stable power sources if treated correctly. It's amazing the things one can find in that old dig site!\n\nAnyway, after I told them the secret of the stones they kicked me out of Angor Fortress and began digging for more in Uldaman.\n\nI want those stones for myself! Bring me both types and I'll pay you plenty!", objectives = { "Dentrium Power Stone x 8", "An'Alleum Power Stone x 8" } },
    [2500] = { title = "Badlands Reagent Run", summary = "Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.", desc = "<class>, I would make use of your services. I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards. Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.\n\nWell, what say ye?", objectives = { "Buzzard Gizzard x 5", "Crag Coyote Fang x 10", "Rock Elemental Shard x 5" } },
    [2768] = { title = "Divino-matic Rod", summary = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", desc = "Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??\n\nFind Bly and bring me my rod! I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul'Farrak to the west. I bet you'll find him there.\n\nLet's hope the trolls took care of him, because if you have to fight him for the rod then you're in for a serious fight.", objectives = { "Divino-matic Rod" } },
    [2770] = { title = "Gahz'rilla", summary = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.", desc = "Deep in Zul'Farrak, the sand troll city in Tanaris, there is a sacred pool. From that pool the trolls summon a huge beast! Gahz'rilla! He's so fierce that even his scales crackle with energy. It's that energy I want to harness for my car!\n\nBring me the electrified scale of Gahz'rilla!\n\nBut the summoning of Gahz'rilla is a well-kept secret of the trolls. To face him, you must first wrest the secret from them.", objectives = { "Gahz'rilla's Electrified Scale" } },
    [2841] = { title = "Rig Wars", summary = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.", desc = "Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, <name>!\n\nUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.\n\nDo whatever you have to do to get that combination, <name>. Then crack open that safe and bring back those blueprints!", objectives = { "Rig Blueprints", "Thermaplugg's Safe Combination" } },
    [2842] = { title = "Chief Engineer Scooty", summary = "Speak with Scooty in Booty Bay.", desc = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, <name>. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!" },
    [2843] = { title = "Gnomer-gooooone!", summary = "Wait for Scooty to calibrate the Goblin Transponder.", desc = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.\n\nYou may experience some unusual side effects, but none of those should be permanent... anymore.\n\nI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!\n\nNow to calibrate the transponder to your size and weight.", objectives = { "Goblin Transponder" } },
    [2846] = { title = "Tiara of the Deep", summary = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", desc = "Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep. And not only was it pretty--it held great power for those with the knowledge to use it.\n\nSo when word of the tiara reached the Hydromancer Velratha, she had to have it. She sent agents to my home and they stole it while I was away. The thieves!\n\nI want my tiara back! Go to Zul'Farrak, the troll city in Tanaris, find Velratha and wrench the tiara from her. Return it to me and you'll earn my favor.", objectives = { "Tiara of the Deep" } },
    [2864] = { title = "Tran'rek", summary = "Speak with Tran'rek in Gadgetzan.", desc = "My cousin Tran'rek is in a tight spot. He promised me a load of scarab shells weeks ago and he hasn't delivered. He's my cousin, so I'd hate to have to send someone to Gadgetzan to break something on him.\n\nCan you speak to Tran'rek for me? Let him know he needs to get that delivery together before I do something rash?\n\nGadgetzan is in northern Tanaris, in Kalimdor." },
    [2865] = { title = "Scarab Shells", summary = "Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.", desc = "The scarabs of Tanaris have very hard shells! Hard enough to use as a building material for lots of things. So many things!\n\nIn fact, those shells are so useful... the scarabs were hunted all to near extinction!\n\nI know where there are more scarabs, and if you promise to bring me their shells then I'll tell you where they are. Promise?\n\nOk, the scarabs have a colony in Zul'Farrak. I guess the trolls don't hunt them for their shells.\n\nBut you can! Go to Zul'Farrak and get me uncracked shells!", objectives = { "Uncracked Scarab Shell x 5" } },
    [2904] = { title = "A Fine Mess", summary = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.", desc = "<Kernobee groans.> Wha.. What happened?\n\nThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.\n\nGet me out of here, <name>!\n\nHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.\n\nLet's get going!", objectives = { "Kernobee Rescue" } },
    [2922] = { title = "Save Techbot's Brain!", summary = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.", desc = "When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot. It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized. Now it's negatronic... and Techbot's behaviors are reversed. It roams Gnomeregan in a frenzy!\n\nBut perhaps it can be salvaged. Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Techbot.", objectives = { "Techbot's Memory Core" } },
    [2923] = { title = "Tinkmaster Overspark", summary = "Speak with Tinkmaster Overspark in Ironforge.", desc = "Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot. I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad. But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge. He would welcome your help." },
    [2924] = { title = "Essential Artificials", summary = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.", desc = "A nigh-universal mechanical component--the essential artificial--was of great use to the tinkers and smiths of Gnomeregan. But during the frantic exodus from our city, no one remembered to take any of these devices with them! And I need a large supply of them for work I will soon undertake.\n\nPlease, go into Gnomeregan and get me some essential artificials. You'll find them in the deeper areas of our city, held in containers called artificial extrapolators.\n\nThank you, <name>, and please hurry!", objectives = { "Essential Artificial x 12" } },
    [2926] = { title = "Gnogaine", summary = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.", desc = "Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, <name>.\n\nLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!", objectives = { "Full Leaden Collection Phial" } },
    [2927] = { title = "The Day After", summary = "Speak with Ozzie Togglevolt in Kharanos.", desc = "You don't think I was always bald, do you? No <sir/ma'am>! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.\n\n<Gnoarn shakes his fist in the air.>\n\nDamn those damned dirty troggs - damn them all!!\n\nPerhaps it's not too late, <name>. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution." },
    [2928] = { title = "Gyrodrillmatic Excavationators", summary = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.", desc = "It's terrible, <name>. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh.\n\nWhat we need are spare parts, <name>. What better place to get the spare parts for our vehicles than Gnomeregan? I hear that bots and mechs roam around that place like cattle on an open range.\n\nWhat I need you to do is go to Gnomeregan and tear apart those robots. Bring me back their robot guts. Two dozen should be sufficient.", objectives = { "Robo-mechanical Guts x 24" } },
    [2929] = { title = "The Grand Betrayal", summary = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.", desc = "I trusted Thermaplugg, <race>. Never did I expect that he would betray me and the entire gnomish people. And for what? Power? Wealth? All things that he would have had in time. Now we have been displaced from our home and that madman is in charge. The king of nothing....\n\nWe will retake Gnomeregan, <name>. We will not stop until the city is back in our control. If you wish to join in our fight, a simple task I ask of you: Kill the betrayer. Destroy Mekgineer Thermaplugg.", objectives = { "Mekgineer Thermaplugg" } },
    [2930] = { title = "Data Rescue", summary = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.", desc = "When we fled Gnomeregan, we left so much data behind! Vitally important data!\n\nI need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan. You must access the terminal, but to do that you first need clearance... and to get that you must access lower security terminals-- models -A, -B and -C. And to do THAT you need security punch cards, starting with white... and we left all the punch cards in the city.\n\nIt's a catastrophe! Can you help?", objectives = { "Prismatic Punch Card" } },
    [2933] = { title = "Venom Bottles", summary = "Bring a Venom Bottle to an apothecary in Tarren Mill.", desc = "These bottles hold a vile, green venom.\n\nConsidering the number of bottles in this village, the Witherbarks must deem it very important. Perhaps an apothecary in nearby Tarren Mill would like a sample." },
    [2934] = { title = "Undamaged Venom Sac", summary = "Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill.", desc = "I must have a fresh sample of the venom you brought me. The spiders from which it was gathered must dwell in the Hinterlands -- hunt them until you find an undamaged venom sac and bring it to me. You will find many spiders near the troll city of Shadra'Alor.\n\nDo not tarry, <name>, for the venom sac must be fresh when you deliver it.", objectives = { "Undamaged Venom Sac" } },
    [2935] = { title = "Consult Master Gadrin", summary = "Speak with Master Gadrin in Sen'jin Village.", desc = "The venom from the broodguards wasn't as potent as the venom you brought originally. It must have come from a different spider.\n\nI want a fresh sample of that venom. To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village. Travel to Durotar and speak with Gadrin. With luck, he'll know where the Witherbarks get their venom." },
    [2936] = { title = "The Spider God", summary = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.", desc = "The Witherbarks worship a spider god, and from her they collect their most potent venom. So if you want the venom, then you must summon their god!\n\nTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.\n\nDefeat Theka and find and read his tablet to discover the spider god's name. When you know it, return to me.", objectives = { "Find the Spider God's Name" } },
    [2945] = { title = "Grime-Encrusted Ring", summary = "Figure out a way to remove the grime from the Grime-Encrusted Ring.", desc = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves. It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible. You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it." },
    [2951] = { title = "The Sparklematic 5200!", summary = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", desc = "This contraption stands out amongst the gnomes holding out against the madness outside the room. A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies? The Sparklematic 5200 puts the shine back in shine-tastic! Insert the item you wish to clean and deposit three silver coins in the coin slot. Give The Sparklematic 5200 a moment for operation, and voila! Your valuables will emerge clean and shiny!\"", objectives = { "Grime-Encrusted Object" } },
    [2962] = { title = "The Only Cure is More Green Glow", summary = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly. Ozzie will also require your Heavy Leaden Collection Phial when the task is complete.", desc = "Not only was your sample insufficient in quantity, it was also impure.\n\nWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered.", objectives = { "High Potency Radioactive Fallout" } },
    [2988] = { title = "Witherbark Cages", summary = "Check the cages at the two Witherbark villages, then return to Gryphon Master Talonaxe.", desc = "The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.\n\nYou must aid us! Search the cages in the two Witherbark troll villages to see if Sharpbeak is there.", objectives = { "Check First Cage", "Check Second Cage", "Check Third Cage" } },
    [2989] = { title = "The Altar of Zul", summary = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe. -", desc = "Sharpbeak was not with the Witherbark trolls. Perhaps the Vilebranch trolls took him. Go to the Altar of Zul on the western edge of Vilebranch territory and search for the gryphon child.", objectives = { "Search the Altar of Zul" } },
    [2990] = { title = "Thadius Grimshade", summary = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands.", desc = "Take this feather to Thadius Grimshade, the diviner. He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!\n\nAnd perhaps his talents can help us find Sharpbeak.\n\nThis feather was taken from the nest where the gryphon child sleeps. If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.\n\nGood luck, <name>. You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep." },
    [2991] = { title = "Nekrum's Medallion", summary = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.", desc = "I'll find out where your gryphon is, but first you have to do something for me. There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study. Bring me that Medallion and I'll use my powers to find Sharpbeak.\n\nZul'Farrak is across the ocean to the west, in the desert of Tanaris.", objectives = { "Nekrum's Medallion" } },
    [3042] = { title = "Troll Temper", summary = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.", desc = "The Sandfury trolls of Zul'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft, yes I can! It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I'll reward you well.\n\nZul'Farrak is northwest of Gadgetzan. Good luck.", objectives = { "Troll Temper x 20" } },
    [3341] = { title = "Bring the End", summary = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.", desc = "In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...\n\nThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.\n\nAmnennar has a direct telepathic link to Ner'zhul; we must sever this bond, <name>. An end must come to the Coldbringer.", objectives = { "Skull of the Coldbringer" } },
    [3373] = { title = "The Essence of Eranikus", summary = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", desc = "As you touch the gem, a deep voice resonates in your mind.\n\n\"Mortal, heed this plea. I am Eranikus of the Green Dragonflight, keeper of this accursed temple. My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure. As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos. Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"" },
    [3380] = { title = "The Sunken Temple", summary = "Find Marvon Rivetseeker in Tanaris.", desc = "There are restless spirits in this world, <name>. There are spirits that have been tainted by their isolation, bound to an ancient evil...\n\nI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris." },
    [3441] = { title = "Divine Retribution", summary = "Listen as Kalaran Windblade tells his story.", desc = "Hear my tale, adventurer.", objectives = { "Kalaran Story" } },
    [3442] = { title = "The Flawless Flame", summary = "Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.", desc = "You have made the right decision, <name>.\n\nWe must strike where we will do the most damage: the four sentry towers.\n\nWith the four towers in flames, we can initiate an offensive before they have time to react.\n\nYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.\n\nBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.\n\nThe golems and elementals in these lands should be your first target.", objectives = { "Heart of Flame x 4", "Golem Oil x 4" } },
    [3443] = { title = "Forging the Shaft", summary = "Bring 8 Thorium Plated Daggers to Kalaran Windblade.", desc = "To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.\n\nThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft.", objectives = { "Thorium Plated Dagger x 8" } },
    [3444] = { title = "The Stone Circle", summary = "Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.", desc = "I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...\n\nRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you more.", objectives = { "Stone Circle" } },
    [3446] = { title = "Into the Depths", summary = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", desc = "Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.\n\nI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple." },
    [3447] = { title = "Secret of the Circle", summary = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues.", desc = "My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.\n\nFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.\n\nI warn you though, <name>. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded..." },
    [3452] = { title = "The Flame's Casing", summary = "Find and return a Symbol of Ragnaros to Kalaran Windblade.", desc = "We need one final piece to form the torch.\n\nIn the mountains to the northwest you will find a large encampment of Twilight's Hammer. It is rumored that they carry symbols and idols that pay homage to their god. These symbols and idols could carry sufficient enchantment to form a magical casing. Bring me a single symbol of Ragnaros and I will try to extract the magic from the item to create the casing.", objectives = { "Symbol of Ragnaros" } },
    [3453] = { title = "The Torch of Retribution", summary = "Wait for Kalaran Windblade to complete the Torch of Retribution.", desc = "Give me a moment to combine the pieces and apply the necessary enchantments.", objectives = { "Torch Creation" } },
    [3454] = { title = "The Torch of Retribution", summary = "Take the Torch of Retribution.", desc = "The torch must now be bound to its owner. Pick up the torch, <name>." },
    [3462] = { title = "Squire Maltrake", summary = "Speak with Squire Maltrake.", desc = "Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution." },
    [3463] = { title = "Set Them Ablaze!", summary = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings.", desc = "Listen well, <name>. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.\n\nWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.\n\nYou must enter each tower and use the torch of retribution within their fortifications. Beware the elite sentry units of the Dark Irons, <name>.", objectives = { "Western Tower Ablaze", "Southern Tower Ablaze", "Eastern Tower Ablaze", "Northern Tower Ablaze" } },
    [3481] = { title = "Trinkets...", summary = "Open the chest.", desc = "The chest appears locked." },
    [3520] = { title = "Screecher Spirits", summary = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", desc = "I seek the spirits of the vale screechers of Feralas. They are the cousins of an old, old god, and their spirits are linked to him.\n\nTake this bramble wand and go to Feralas. Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies. This will coax their spirit to reveal itself. Touch the spirit and collect its essence.\n\nReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke.", objectives = { "Screecher Spirits Collected x 3" } },
    [3523] = { title = "Scourge of the Downs", summary = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", desc = "Outstanding! My name is Belnistrasz, and I thank you for rescuing me. I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin. Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.\n\nListen... rather than just flee, I want to make a difference for all of our sakes. Would you be up to helping me out to that end? It's probably dangerous, but you seem to be the type not to worry about that too much." },
    [3525] = { title = "Extinguishing the Idol", summary = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs. Protect Belnistrasz while he performs the ritual to shut down the idol.", desc = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens. I can shut down the idol and bind them from using it again, but I need your aid in doing so. My plan: escort me to the idol. Once we arrive, I'll commence the ritual. I'll barely be able to communicate with you, let alone defend myself. Protect me while I shut down the idol. If they take me down, then it's all over for us.\n\nAre you with me?!", objectives = { "Protect Belnistrasz while he performs the ritual to shut down the idol" } },
    [3527] = { title = "The Prophecy of Mosh'aru", summary = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", desc = "The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence. It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.\n\nBring me the Mosh'aru tablets!\n\nThe first tablet is held by the long-dead troll Theka the Martyr. It is said his persecutors were cursed into scarabs and now scuttle about his shrine.\n\nThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.\n\nWhen you have the tablets, bring them to me.", objectives = { "First Mosh'aru Tablet", "Second Mosh'aru Tablet" } },
    [3528] = { title = "The God Hakkar", summary = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", desc = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth. Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you. Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit. When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the Egg of Hakkar.", objectives = { "Filled Egg of Hakkar", "Essence of Hakkar" } },
    [3636] = { title = "Bring the Light", summary = "Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.", desc = "The Scourge is a persistent threat to the Alliance, a fact I am sure you know quite well. Recently, we have come across some very peculiar findings, <name>.\n\nIn the Barrens lies a horrid tangle of briars called Razorfen Downs. While once it was the home of simple quilboar, now it has become apparent that a pact was made with the Scourge, creating creatures far worse... They are now ruled by the lich, Amnennar the Coldbringer.\n\nAlign yourself with the Light, <name>; put an end to this evil union.", objectives = { "Amnennar the Coldbringer" } },
    [3701] = { title = "The Smoldering Ruins of Thaurissan", summary = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.", desc = "Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.\n\nIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, <name>. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.", objectives = { "Information Recovered x 12" } },
    [3702] = { title = "The Smoldering Ruins of Thaurissan", summary = "Listen to Royal Historian Archesonus recant the history of Thaurissan.", desc = "Would you like to hear a brief history of the Dark Iron dwarves?", objectives = { "Story of Thaurissan" } },
    [3765] = { title = "The Corruption Abroad", summary = "Travel to Gershala Nightwhisper in Auberdine.", desc = "Stormwind -- such a bustling hub of activity.\n\nI have traveled from afar to seek help. Often it is heard that brave adventurers roam these city streets.\n\nMy brother, Gershala, requires assistance in Darkshore. He resides in the seaside town of Auberdine.\n\nThe journey is a long and epic one. It is for this reason that I ask the help of a seasoned <class> such as yourself." },
    [3801] = { title = "Dark Iron Legacy", summary = "Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major.", desc = "Greetings, <name>. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.\n\nYou are probably wondering why I am here and what it is that I want from you - both valid questions.\n\nI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city." },
    [3802] = { title = "Dark Iron Legacy", summary = "Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.", desc = "You will find Fineous Darkvire beyond the Ring of Law, in the Hall of Crafting. Kill the miserable cur and recover Ironfel.\n\nTake Ironfel to the Shrine of Thaurissan and place the hammer in its rightful place: In the hands of the statue erected in my honor.\n\nWhen this is done, the compartment in which I stored the master key will open. More importantly, Ironfel will remain forever in my grasp. Should they make an attempt to remove the hammer; both the statue and hammer will shatter, lost forever.", objectives = { "Ironfel" } },
    [3906] = { title = "Disharmony of Flame", summary = "Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.", desc = "The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated.\n\nTravel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron.\n\nEnd the disruption and return to me.", objectives = { "Overmaster Pyron" } },
    [3907] = { title = "Disharmony of Fire", summary = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.", desc = "I can taste the foulness in the air that surrounds you, <name>. There is another, hidden in the depths of Blackrock, who does control this foulness.\n\nThe wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary.\n\nFind him and discover where his master hides. Return to me when you have collected this information.", objectives = { "Lord Incendius", "Tablet of Kurniya" } },
    [3981] = { title = "Commander Gor'shak", summary = "Find Commander Gor'shak in Blackrock Depths. You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.", desc = "Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now...\n\n<Galamav grimaces.>\n\nWhen we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached.\n\nIf he's still alive in the Depths, you'll have to find him.\n\nA trap you say? Well no kidding, numb hooves! That's why you're going!" },
    [3982] = { title = "What Is Going On?", summary = "Defend Gor'shak.", desc = "I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence.\n\n<Gor'shak whispers.>\n\nThe Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news.\n\n<Gor'shak laughs.>\n\nShhh! Do you hear that? Guards coming! DEFEND YOURSELF!", objectives = { "Survive the Onslaught" } },
    [4001] = { title = "What Is Going On?", summary = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar. You recall Gor'shak mentioning that Kharan is being held in a cell nearby.", desc = "So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm.\n\nGo speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief.\n\nThrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go!", objectives = { "Information Gathered from Kharan" } },
    [4002] = { title = "The Eastern Kingdoms", summary = "Speak with Thrall if you are prepared to take on the mission he has planned.", desc = "You bring excellent information, <name>.\n\nAs Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence.\n\nThe opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail!\n\nAre you prepared?" },
    [4003] = { title = "The Royal Rescue", summary = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.", desc = "This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.\n\nPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.\n\nDO NOT HARM HER!", objectives = { "Emperor Dagran Thaurissan" } },
    [4022] = { title = "A Taste of Flame", summary = "Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade.", desc = "The flight is aware of your work in the Searing Gorge.\n\nShow it to me, <race>. The molt, imbecile.", objectives = { "Black Dragonflight Molt", "Proof Presented" } },
    [4024] = { title = "A Taste of Flame", summary = "Travel to Blackrock Depths and slay Bael'Gar. You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence. Return the Encased Fiery Essence to Cyrus Therepentous.", desc = "I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave.\n\nBael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire.\n\nUse the molt on his remains to safely extract the inner flame.\n\nSucceed and be rewarded.", objectives = { "Encased Fiery Essence" } },
    [4061] = { title = "The Rise of the Machines", summary = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania. You recall Theodora mentioning the golems and elementals of that region as being a source for these shards.", desc = "The machines made themselves known to us during our initial forays into the Searing Gorge. Upon further investigation we discovered that they were being imported from Burning Steppes, possibly Blackrock Depths. That is what we need you for, <name>.\n\nYour first task is to venture to the Burning Steppes and recover elemental shards from the rock automatons and lesser rock creations of the region. Once you have collected a sufficient amount, return to me and I shall determine their source of origin.", objectives = { "Fractured Elemental Shard x 10" } },
    [4062] = { title = "The Rise of the Machines", summary = "Take the Elemental Shard Sample to Lotwil Veriatus. You recall Theodora saying that Lotwil was stationed in a camp to the east.", desc = "G.L.A.\n\nThose are the 'initials' imprinted on the elemental shards. Below the initials are a rank marking of some sort. The machinations you destroyed in the Burning Steppes were of 'Rank IV.' I assume that this is a lowly rank.\n\nTake this shard sample to Lotwil Veriatus in the camp to the east. He is a scholar of some renown in the field of elemental sciences. He may be able to assist us in our search." },
    [4063] = { title = "The Rise of the Machines", summary = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", desc = "This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him.\n\nHe was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs. It seems that the wicked always find a way to escape justice.\n\nIf this is Argelmach's handiwork then he must be destroyed. I will need samplings of his latest creations. With the proper samples, I may be able to stop this uprising. The creations guard Argelmach in Blackrock Depths.", objectives = { "Head of Argelmach", "Intact Elemental Core x 10" } },
    [4081] = { title = "KILL ON SIGHT: Dark Iron Dwarves", summary = "Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.", desc = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nAny and all of General Angerforge's forces within Blackrock Depths must be annihilated.\n\nAngerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes.\n\nAny person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute.", objectives = { "Anvilrage Guardsman x 15", "Anvilrage Warden x 10", "Anvilrage Footman x 5" } },
    [4082] = { title = "KILL ON SIGHT: High Ranking Dark Iron Officials", summary = "Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", desc = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nHead of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them!\n\nCompletion of this mission will result in a tribute.", objectives = { "Anvilrage Medic x 10", "Anvilrage Soldier x 10", "Anvilrage Officer x 10" } },
    [4121] = { title = "Precarious Predicament", summary = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge. You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody. You will also be required to hand over your Thorium Shackles to Lexlort.", desc = "Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?\n\nYou will be destroyed!", objectives = { "Thorium Shackles", "Prisoner Transport" } },
    [4122] = { title = "Grark Lorkrub", summary = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress. When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.", desc = "I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.\n\nHe now sits in the Burning Steppes, safely under their protection - or so he thinks.\n\nTake these shackles, <name>. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours." },
    [4123] = { title = "The Heart of the Mountain", summary = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", desc = "For years I have sought a certain gem. It is called the Heart of the Mountain and it's the size of your fist! The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to the Lower Vault of Blackrock Depths, breach its secret safe and gain the Heart. To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", objectives = { "The Heart of the Mountain" } },
    [4126] = { title = "Hurley Blackbreath", summary = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.", desc = "The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!\n\n<name>, I have a tough task for you. Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager!\n\nPlease, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!", objectives = { "Lost Thunderbrew Recipe" } },
    [4128] = { title = "Ragnar Thunderbrew", summary = "Speak with Ragnar Thunderbrew.", desc = "Ho, <name>. I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale. He's looking for stalwart adventurers, and willing to pay plenty.\n\nTalk to Ragnar if you're interested. He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh." },
    [4132] = { title = "Operation: Death to Angerforge", summary = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", desc = "You have done an exemplary job, <name>. It is now time to send you on your last mission.\n\nGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.\n\nThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded.", objectives = { "General Angerforge" } },
    [4133] = { title = "Vivian Lagrave", summary = "Speak with Shadowmaster Vivian Lagrave in Kargath.", desc = "Shadowmaster Vivian Lagrave is in need of your services. She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.\n\nSpeak with Vivian. She awaits you." },
    [4134] = { title = "Lost Thunderbrew Recipe", summary = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.", desc = "It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale. This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage. We wish to study the drink. Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.\n\nDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.\n\nAnd to find him, you may have to entice him by threatening his precious ale.", objectives = { "Lost Thunderbrew Recipe" } },
    [4136] = { title = "Ribbly Screwspigot", summary = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.", desc = "My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another.\n\nWell, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head. I can't tell you how happy this makes the Screwspigots! Our little Ribbly's finally worth something!\n\nBut now he's hiding out, deep in Blackrock Depths. Please, find him and bring him to me!\n\nOr, if he won't come, then that's ok... just bring me his head.", objectives = { "Ribbly's Head" } },
    [4141] = { title = "Muigin and Larion", summary = "Collect 15 Bloodpetals and return to Muigin.", desc = "See Larion over there? It's HIS fault we're here!\n\nI told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him.\n\nHave you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands.\n\nFirst thing though, I'll need some samples to study. Do you think you could collect some?", objectives = { "Bloodpetal x 15" } },
    [4142] = { title = "A Visit to Gregan", summary = "Take a Bloodpetal to Gregan Brewspewer in Feralas.", desc = "I'm not quite sure what to make of this, <name>. The plants... they seem to have some minimal intelligence.\n\nI'm no expert, though. But, I do know someone that is!\n\nHead to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing.\n\nI'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city." },
    [4143] = { title = "Haze of Evil", summary = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.", desc = "To tell you the truth, <name>, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater...\n\nAt any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters.\n\nYou'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, <name>!", objectives = { "Atal'ai Haze x 5" } },
    [4145] = { title = "Larion and Muigin", summary = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.", desc = "See Muigin over there? It's HIS fault we're lost!\n\nI'm the one that knew the way, but he insisted he knew a shortcut, and we ended up here!\n\nTo make matters worse, now he keeps sending his crazy plant pests to annoy me. I'm so angry that I'm not planning on talking to him any time soon, but these pests are too much to handle.\n\nWhy don't we try to limit his supply, first thing. Go out and hunt some Bloodpetals, then return to me.", objectives = { "Bloodpetal Lasher x 5", "Bloodpetal Trapper x 5", "Bloodpetal Flayer x 5", "Bloodpetal Thresher x 5" } },
    [4146] = { title = "Zapper Fuel", summary = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.", desc = "You're in luck, <name>! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests.\n\nI can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.", objectives = { "Atal'ai Haze x 5" } },
    [4147] = { title = "Marvon's Workshop", summary = "Travel to Marvon Rivetseeker's workshop in Ratchet.", desc = "I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!\n\nI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!\n\nWe'll need the help of my friend, Marvon, who has a workshop in Ratchet. I'm sure he'll be able to create some sort of gadget that will help us." },
    [4182] = { title = "Dragonkin Menace", summary = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.", desc = "Life in the Burning Steppes is rife with conflict.\n\nJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.\n\nEnough lamenting! We have a problem, <name>. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.", objectives = { "Black Broodling x 15", "Black Dragonspawn x 10", "Black Drake", "Black Wyrmkin x 4" } },
    [4183] = { title = "The True Masters", summary = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon.", desc = "We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.\n\nIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.\n\nTake this letter to Magistrate Solomon. He will know what must be done.\n\n<Helendis hands you a sealed letter.>" },
    [4184] = { title = "The True Masters", summary = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon. Bolvar resides in Stormwind Keep.", desc = "This is grim news, <name>. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?\n\nYou must take this information to Highlord Bolvar Fordragon in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost." },
    [4185] = { title = "The True Masters", summary = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.", desc = "Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.\n\nSpeak with Lady Prestor, <name>. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation.", objectives = { "Advice from Lady Prestor" } },
    [4186] = { title = "The True Masters", summary = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire.", desc = "I am going to empower you as an acting deputy of Stormwind, <name>.\n\nReturn to Magistrate Solomon in Lakeshire and deliver this decree." },
    [4201] = { title = "The Love Potion", summary = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.", desc = "Oh, the pains of love! My dear Private Rocknot is immune to my charms. I am spurned! It's maddening!\n\nYou must help me! We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart. To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un'Goro. You can place the water in this vial.\n\nPlease, <name>, help a poor soul in her quest for happiness!", objectives = { "Gromsblood x 4", "Giant Silver Vein x 10", "Nagmara's Filled Vial" } },
    [4223] = { title = "The True Masters", summary = "Speak with Marshal Maxwell in the Burning Steppes.", desc = "<Magistrate Solomon sighs.>\n\nYou must return to the Burning Steppes, <name>. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck." },
    [4224] = { title = "The True Masters", summary = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task. You recall Marshal Maxwell telling you to search for him in a cave to the north.", desc = "What? You thought you were the first? How many soldiers must we lose before Stormwind acts?\n\nWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.\n\nWhat we need is that documentation. Speak with Ragged John, <name>. He was with Windsor when they were attacked by a Blackrock raiding party. He was last seen in a cave to the north.", objectives = { "Ragged John's Story" } },
    [4241] = { title = "Marshal Windsor", summary = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor. You recall Ragged John talking about Windsor being dragged off to a prison.", desc = "So that good for nothing coward says that Windsor is alive, eh?\n\nSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.\n\n<Maxwell laughs.>\n\nI bet you are getting tired of hearing that, aren't you?" },
    [4242] = { title = "Abandoned Hope", summary = "Give Marshal Maxwell the bad news.", desc = "Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.\n\nHe is a blind buffoon. Proof stands two feet away from him and he does not see.\n\nAs for my data, it's lost. Gone. Unrecoverable.\n\nShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.\n\nLeave me, <name>." },
    [4262] = { title = "Overmaster Pyron", summary = "Slay Overmaster Pyron and return to Jalinda Sprig. You recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?", desc = "The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse.\n\n<Jalinda picks up some ashes from the ground and releases them into the air.>\n\nOne nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths!\n\nHe guards the entrance at the Blackrock Quarry.", objectives = { "Overmaster Pyron" } },
    [4263] = { title = "Incendius!", summary = "Find Lord Incendius in Blackrock Depths and destroy him!", desc = "Are you sure Pyron said 'Incendius' when he died?\n\n<Jalinda swallows hard.>\n\nLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?\n\nDo you think you can handle another mission? I don't have anybody else to send, <name>!\n\nWe will never get a team in if Incendius continues to raise Pyron from the ashes.\n\nYou'll have to find and destroy Lord Incendius!", objectives = { "Lord Incendius" } },
    [4264] = { title = "A Crumpled Up Note", summary = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.", desc = "The note has stains covering its surface. The text is barely legible, but you make out the following:\n\n...sweet irony...\n\n...the fall of the broken Alliance...\n\n...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...\n\n...Argelmach is almost done with the decryption of Windsor's notes.\n\nOur lord will rise from the depths and crush any that remain...\n\n-Emperor Dagran Thaurissan." },
    [4282] = { title = "A Shred of Hope", summary = "Return Marshal Windsor's Lost Information. Marshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.", desc = "<Marshal Windsor shakes the note excitedly.>\n\nDo you realize what this means, <name>?\n\nPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.\n\nI hope you are ready to battle.\n\nVenture forth and find these two villains! Destroy them and return my lost information.", objectives = { "Marshal Windsor's Lost Information", "Marshal Windsor's Lost Information" } },
    [4286] = { title = "The Good Stuff", summary = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions.", desc = "Captain Winky tells me that the Dark Irons in the Depths got all the good stuff. Ain't that right, Winky?\n\n<Oralius does his best impersonation of a pirate.>\n\nARRR MATEY! IT BE RIGHT!\n\nSee what I'm saying? You need to get in there and bring me back some samples of the good stuff.\n\nGet in there and shake your moneymaker!", objectives = { "Dark Iron Fanny Pack x 20" } },
    [4322] = { title = "Jail Break!", summary = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.", desc = "We need to get out of here, <name>. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.", objectives = { "Jail Break!" } },
    [4324] = { title = "Yuka Screwspigot", summary = "Speak with Yuka Screwspigot in the Burning Steppes.", desc = "Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value! But... we might need your help to capitalize on Ribbly's newfound worth.\n\nMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes. She sent word to me, asking for some hired hands.\n\nSo, what do you say? Want to help? If so, then speak with my sister. You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock." },
    [4341] = { title = "Kharan Mighthammer", summary = "Travel to Blackrock Depths and find Kharan Mighthammer. The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.", desc = "You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!\n\n<The King sobs.>\n\nAnd now she's gone, <name>!\n\nI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!\n\nKharan is supposedly being held prisoner there... find him! I want answers!" },
    [4361] = { title = "The Bearer of Bad News", summary = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.", desc = "You must take this information back to King Magni, <name>. He will know what to do!" },
    [4362] = { title = "The Fate of the Kingdom", summary = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", desc = "It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.\n\nYou may be my last hope, <name>. You must rescue my dear daughter, Moira!\n\nThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.\n\nAnd <name>, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!", objectives = { "Emperor Dagran Thaurissan" } },
    [4701] = { title = "Put Her Down", summary = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.", desc = "You have no doubt seen the worgs which the Blackrock orcs command.\n\nIt is curious - no matter how many we destroy, their numbers never dwindle. My scouts have reported that the worgs are bred, trained, and ultimately exported from Blackrock Spire: capital city of the Blackrock orcs. You must travel to Blackrock Spire and discover the source of this menace. Discover... and destroy.\n\nGood luck, <name>. May Cenarius protect you...", objectives = { "Halycon" } },
    [4724] = { title = "The Pack Mistress", summary = "Slay Halycon, pack mistress of the Bloodaxe worg.", desc = "Some say the worg controlled by the Blackrock orcs are the creation of a supernatural force. Others say they are not true worg but instead a breed of demon dog, granted to the orcs by a fallen pit lord.\n\nThe truth is far less contrived but every bit as frightening. The worg of Blackrock come from Halycon and her mate. Halycon is the gigantic den mother of the worg. Her mate? Nobody has ever lived to tell the tale of that one.\n\nStrike at the heart of the worg. Destroy Halycon... and <name>, watch your back.", objectives = { "Halycon" } },
    [4726] = { title = "Broodling Essence", summary = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", desc = "I have been studying the dragonkin of the Burning Steppes for weeks, and I think I've finally had a breakthrough! I created a device--I call it the Draco Incarcinatrix 900. It can capture the essence of dragon whelp broodlings!\n\nOr, at least I think it can.\n\nHere, take the device and zap a broodling in the Burning Steppes with it. While it's under the device's effects, defeat the broodling and its essence should be released.\n\nIf it is, then splendid! Bring me back samples so I can study them!", objectives = { "Broodling Essence x 8" } },
    [4729] = { title = "Kibler's Exotic Pets", summary = "Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.", desc = "You're probably wondering what I'm doing out here. Look at the cages! Ain't it obvious?\n\nI'm an animal lover, first and foremost, but a salesman by trade. I track down exotic animals for the rich and famous and domesticate the beasts so they behave as proper pets.\n\nNow you're probably wondering, \"What can I do for you, Kibler.\" The answer is simple: Take this here beast cage and find me some worg pups. For that, I'll domesticate a worg for you!", objectives = { "Caged Worg Pup" } },
    [4734] = { title = "Egg Freezing", summary = "Use the Eggscilloscope Prototype on an egg in the Rookery.", desc = "<name>, I've been working hard on a new device, the eggscilloscope! It's designed to project a burst of cold energy at the egg of a black dragon... and freeze it solid! Can you test it for me?\n\nI heard that high up in Blackrock Spire, the dragons have a rookery where they hatch their eggs. That's where you'll have to go to test the eggscilloscope, and then let me know how it worked!\n\nAnd don't worry. Frozen dragon eggs should be harmless. It's the unfrozen ones you have to worry about!", objectives = { "Test the Eggscilliscope Prototype" } },
    [4735] = { title = "Egg Collection", summary = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", desc = "<name>, I'm finally ready for real samples of dragon eggs! Here, take this collectronic module. It's designed to extract a dragon egg and prepare it for transport. Go back to the Rookery and use the module to collect eggs.\n\nAnd don't forget to freeze them first, or they might hatch before you can collect them!\n\nWhen you have enough eggs, bring them to me!", objectives = { "Collected Dragon Egg x 8" } },
    [4742] = { title = "Seal of Ascension", summary = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan. The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe.", desc = "As you can see, the unadorned seal has three empty sockets. Each of those sockets must be filled with a gemstone representing the leadership's command. Finally, Overlord Wyrmthalak, master of the lower citadel, must forge the seal in the flames of the Black Dragonflight.\n\nUnderstand this, mortal: the chance that one of the three generals of the lower citadel would carry a gemstone at any given time is rare. You must be vigilant in your quest. Remain determined!", objectives = { "Gemstone of Spirestone", "Gemstone of Smolderthorn", "Gemstone of Bloodaxe", "Unadorned Seal of Ascension" } },
    [4764] = { title = "Doomrigger's Clasp", summary = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", desc = "There is a chamber, high in Blackrock Spire, that was once called the Hall of Fortune. It was where the Dark Iron dwarves kept their relics, trophies and objects of art.\n\nThat was long ago. It is said the hall has collapsed and is now used for... less savory tasks. But I believe some old dwarven relics may still be found there.\n\nOne such relic is Doomrigger's clasp, with a surface so encrusted with rare gems that it was said to make weep any dwarf who gazes upon it.\n\nThat clasp, <name>, is your goal.", objectives = { "Doomrigger's Clasp" } },
    [4766] = { title = "Mayara Brightwing", summary = "Speak with Mayara Brightwing in the Burning Steppes.", desc = "An agent of mine, Mayara Brightwing, was sent to the Burning Steppes to scout the ruined city of Thaurissan. That destroyed city of the Dark Iron dwarves may hide objects of great value... objects that would fit nicely into our family museum.\n\nMayara says she found something and will need aid in retrieving it, but it is not in Thaurissan. Instead, a foray into Blackrock Spire will be required.\n\nI do not know the details, but if interested then speak with Mayara in the Burning Steppes." },
    [4768] = { title = "The Darkstone Tablet", summary = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.", desc = "The Darkstone Tablet holds the writings of the long-dead dwarf Urheld Darkstone. An alchemist of great skill, he was thought insane by his contemporaries and, hence, did not share his research.\n\nBut he did etch it onto tablets, and I believe one such tablet lies in Blackrock Spire, in a chamber once named the Hall of Fortune. I know not what it is now called, for few enter Blackrock and return.\n\nBut if you are willing to brave its dangers and return to me with the tablet, your reward will be great.", objectives = { "Darkstone Tablet" } },
    [4769] = { title = "Vivian Lagrave and the Darkstone Tablet", summary = "Speak with Shadowmage Vivian Lagrave.", desc = "Vivian Lagrave sent me word from Kargath, in the Badlands. Through her studies, she believes there is an ancient text within Blackrock Spire that would benefit our research. To confirm this, she will need someone to extract the text from the spire. No easy task.\n\nIf interested, then speak with Vivian in Kargath." },
    [4771] = { title = "Dawn's Gambit", summary = "Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink.", desc = "I've placed Dawn's Gambit in the container you brought to us, the one that held the dragon eggs. Your job is to bring it deep within the Scholomance.\n\nThe undead mage Vectus leads a team of scourge scholars... place Dawn's Gambit in their chamber, called the \"viewing room.\" It will then react with the undead found there and, with a little luck, destroy them!\n\nAfter that, defeating Vectus shouldn't be a problem. Right?", objectives = { "Vectus", "Place Dawn's Gambit" } },
    [4787] = { title = "The Ancient Egg", summary = "Bring the Ancient Egg to Yeh'kinya in Tanaris.", desc = "The Prophecy of Mosh'aru speaks of an ancient egg. It is a relic of a time when trolls ruled vast empires, and it has the power to hold the essence of Hakkar. It may be the only way to keep our world safe from his evil.\n\nBring me the ancient egg, <name>. It is said to lay hidden deep within Jintha'Alor in the Hinterlands, in a cave behind the amphitheater at the top of the city.", objectives = { "Ancient Egg" } },
    [4788] = { title = "The Final Tablets", summary = "Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", desc = "While I look over the third and fourth tablets of Mosh'aru, you must find the fifth and sixth! It will not be easy, for they are held by the Smolderthorn trolls within Blackrock Spire. The spire is a dark mountain of fire between the Burning Steppes and the Searing Gorge.\n\nGood luck, <name>. Blackrock Spire is no place for decent folk...", objectives = { "Fifth Mosh'aru Tablet", "Sixth Mosh'aru Tablet" } },
    [4808] = { title = "Felnok Steelspring", summary = "Give Tinkee's Letter to Felnok Steelspring.", desc = "I have another favor to ask of you.\n\nMy initial study of the essence you collected shows that it might be possible to freeze dragon whelp eggs and preserve them! I want to test this theory, but first I need specially made engineering components. My colleague, Felnok Steelspring, can make them.\n\nHere, take this letter to Felnok. It tells him what I need. You'll find Felnok in Winterspring, in the town of Everlook." },
    [4809] = { title = "Chillwind Horns", summary = "Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.", desc = "I have most of what Tinkee needs, but I'm missing one important component, and that's chillwind horns. The horns of the chillwind chimaera in Winterspring are a concentrated source of cold, but only pristine, uncracked horns will do! I'll need a supply of those to complete Tinkee's order.\n\nBring me the uncracked chillwind horns, and I'll prepare a package for Tinkee.", objectives = { "Uncracked Chillwind Horn x 8" } },
    [4810] = { title = "Return to Tinkee", summary = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes.", desc = "Ok, everything is prepared and packed and ready for transport! Good luck in your journey, and make sure you tell Tinkee that she owes me!" },
    [4862] = { title = "En-Ay-Es-Tee-Why", summary = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler. By the sound of it, these eggs could be found near spiders.", desc = "Believe it or not, there are people out there willing to pay for the most vile of domesticated beast!\n\nI'd sent Bijou into the Spire to try and collect some of those spire spider eggs but I haven't heard from her in weeks. Maybe you can help me out?\n\nI'll tell you what, <name>. Go to Blackrock Spire and collect some spire spider eggs for me. Bring them back here and not only will I give you a little cash, but I'll even domesticate one for you!", objectives = { "Spire Spider Egg x 15" } },
    [4866] = { title = "Mother's Milk", summary = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.", desc = "It's probably one of the most potent poisons in the world, <race>!\n\nI've overheard the Blackrock speaking about its lethality in my jaunts into the Spire. They call it 'Mother's Milk', named after Mother Smolderweb, the big nasty spider in the Skitterweb cave.\n\nNow here's what I need from you: A live sample of the Milk, flowing through YOUR veins. Just bringing me the gland won't be enough! Get her to poison you and come back to me!\n\nThen... I get to milk ya!\n\n<Rubs his hands together in anticipation.>", objectives = { "Milked" } },
    [4867] = { title = "Urok Doomhowl", summary = "Read Warosh's Scroll. Bring Warosh's Mojo to Warosh.", desc = "Argh! So hard to speak!\n\nTake this note! Get me my mojo!", objectives = { "Warosh's Mojo" } },
    [4903] = { title = "Warlord's Command", summary = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", desc = "By order of Warlord Goretooth, the following inhabitants of Blackrock Spire must be destroyed:\n\nThe rotund menace, Highlord Omokk.\n\nThe cruel and ruthless troll, War Master Voone.\n\nOverlord Wyrmthalak, taskmaster of the lesser city.\n\nYou will also be required to return any important documents that you may find.\n\nSucceed and be honored.\n\nFail and be forgotten.", objectives = { "Overlord Wyrmthalak", "Highlord Omokk", "War Master Voone", "Important Blackrock Documents" } },
    [4941] = { title = "Eitrigg's Wisdom", summary = "Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall. You recall having seen Eitrigg in Thrall's chamber.", desc = "Rend lives?\n\nImpossible!\n\nIt had been thought that Rend was slain decades ago.\n\nSeek out the wisdom of Eitrigg, <name>. None know the workings of the Blackrock better than he and if what is written here bares truth, Eitrigg should be informed. No person should be denied the right of vengeance.\n\nYou will find him in Orgrimmar.\n\nOnce you have spoken with Eitrigg, confer with the Warchief to find out what he wishes to do about this problem.", objectives = { "Council with Eitrigg." } },
    [4974] = { title = "For The Horde!", summary = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.", desc = "Rend dares make such grand claims because of the protection he is afforded by the black flight.\n\nYou, <name>, will find a way to pass through the Halls of Ascension. You will then find 'Warchief' Rend Blackhand and you will destroy him - FOR THE HORDE!\n\n<Thrall slams a fist down upon his throne.>\n\nThe next time you return to my chambers, you will hold his head high in triumph and then you shall present it to your Warchief. Do this and be honored as a hero of the Horde.", objectives = { "Head of Rend Blackhand" } },
    [4981] = { title = "Operative Bijou", summary = "Travel to Blackrock Spire and find out what happened to Bijou.", desc = "Never trust a goblin. That's what it comes down to, <name>.\n\nBijou is her name - one of our slipperiest operatives. I found out she was working for some shady exotic pet dealer out of the Burning Steppes named Kibler, in essence, two timing us. Worse yet, she was using Horde funds to finance her operations.\n\nI want her brought back here alive.\n\nShe was last seen entering Blackrock Spire. Find her and bring her back.\n\nAnd <name>, do not let her sweet talk you." },
    [5001] = { title = "Bijou's Belongings", summary = "Find Bijou's Belongings and return them to her. Good luck!", desc = "Ordinarily I don't deal with <race>s but it seems that I'm stuck between a troll and a hard place. You see, my mission here is one of utmost importance to the Horde. The information I've discovered, however, applies to the well being of the Alliance as well. Now believe me, I'm no Alliance sympathizer, but the Blackrock threat is bigger than just a bunch of orcs.\n\nYou help me out by finding my belongings and I'll help you out with some information that could prove useful to your kind.\n\nDeal?", objectives = { "Bijou's Belongings" } },
    [5047] = { title = "Finkle Einhorn, At Your Service!", summary = "Talk to Malyfous Darkhammer in Everlook.", desc = "You'll find Malyfous Darkhammer in Everlook, <class>. Tell him that 'Finkle is A-OK' and that the suit works perfectly.\n\nThen hand him this:\n\n<Finkle hands you a glowing piece of flesh.>\n\nI snatched it from the beast's innards during my 'vacation.'\n\nI bet Malyfous could give you a fairly accurate assessment of what he can do with parts from a monster like this!\n\nOh, I suppose you don't know where Everlook is, do you? To Winterspring, <fella/lady>!" },
    [5065] = { title = "The Lost Tablets of Mosh'aru", summary = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", desc = "The troll with whom you spoke did not tell the truth. The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend. I have studied long, and found that there are six Tablets of Mosh'aru, not two! Six!\n\nAnd I fear that we will not like what secrets the others hold..\n\nFind the third and fourth tablets of Mosh'aru. They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me.", objectives = { "Third Mosh'aru Tablet", "Fourth Mosh'aru Tablet" } },
    [5089] = { title = "General Drakkisath's Command", summary = "Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes.", desc = "From the corpse of the defeated serpent you uncover what appears to be a note of some importance: A letter from his superior, General Drakkisath, concerning protocol.\n\nYour instinct tells you that you should take it to Marshal Maxwell." },
    [5102] = { title = "General Drakkisath's Demise", summary = "Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done.", desc = "We battle against these beasts on two fronts: From our capital of Stormwind we fight them from the inside out and here, in the Burning Steppes, we take the battle to their doorstep. We must be vigilant, <name>. None should be spared our wrath as none of our own were spared when they struck at our homes and families.\n\nFind this General Drakkisath and destroy him!\n\nThe task certainly will not be a simple one, but the rewards shall be extravagant.", objectives = { "General Drakkisath" } },
    [5122] = { title = "The Medallion of Faith", summary = "The power of this chapel gives me the strength to resist the corruption in my heart. If I leave it, I will become a death knight. But there is a medallion, the medallion of faith, that will give me the strength I need to leave. Please, <name>, retrieve the medallion. It is guarded by Malor the Zealous, a crazed member of the Scarlet Brotherhood who resides deep in the Scarlet Bastion in western Stratholme.", objectives = { "Medallion of Faith" } },
    [5125] = { title = "Aurius' Reckoning", summary = "<name>, I am dying... but my soul is saved. For that, I owe you more than words can say. Please, take this... and fight on, brave <class>!" },
    [5126] = { title = "Lorax's Tale", summary = "Speak with Lorax. Listen to what he has to say.", desc = "The Satyr paces about and talks to himself. Do you wish to question him?", objectives = { "Listen to Lorax's Tale" } },
    [5127] = { title = "The Demon Forge", summary = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained. You must also find the Unforged Rune Covered Breastplate. Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.", desc = "Lorax makes deals, he does not accept them from insignificant mortals.\n\nA deal I shall make with you, however... take this pike, it is imbued with powerful Fel energies. When you find Goraluk Anvilcrack, slay him and drive this pike through his dying heart. His soul he bartered, his soul I shall have. Return the pike and return the breastplate that the thief stole and I shall teach you what it is that he was to learn.", objectives = { "Soul Stained Pike", "Unforged Rune Covered Breastplate" } },
    [5160] = { title = "The Matron Protectorate", summary = "Travel to Winterspring and find Haleh. Give her Awbee's scale.", desc = "Travel to Kalimdor, <race>. Our flight makes its home in the frigid landscape of Winterspring. Once you reach Winterspring, find the caves of Mazthoril.\n\nUpon the icy floors of Mazthoril you will find cobalt runes. Hold one of my scales and stand upon a rune and you shall be transported to Haleh, our matron protectorate.\n\nGive her the scale so that she may scry what it is I have seen and felt, here in this doomed place." },
    [5212] = { title = "The Flesh Does Not Lie", summary = "Recover 20 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", desc = "The Forsaken apothecaries are not the only beings in this world schooled in the sciences.\n\nI have been studying the plague for years, <race>. We had previously thought that the potency of the plague was dwindling, but what I have discovered here in the Plaguelands is startling. The plague seems to be growing in strength!\n\nI need to run more tests! The most potent source of the plague is from the tainted flesh of the most recently infected. Travel to Stratholme and bring me samples, <name>.", objectives = { "Plagued Flesh Sample x 20" } },
    [5213] = { title = "The Active Agent", summary = "Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.", desc = "You will have to delve deeper into Stratholme, <name>.\n\nBeyond the first gates you will find the ziggurats. We know that the Scourge draws great power from these structures. Search the Ziggurats and return with any information that you may discover.", objectives = { "Scourge Data" } },
    [5214] = { title = "The Great Fras Siabi", summary = "Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done.", desc = "Terrible thing... what happened to Fras. You see, the town was sacked and Fras didn't want to leave his precious goods behind. The last thing I remember him saying was, 'I'll burn every last leaf before they get their damned, dirty hands on them!'\n\nI may love a good stogie but I'm no fool. I left Fras and his delightful store that day. I assume he went down in flames but if there's a chance that even one box of his famous tobacco is still intact...\n\nWhat do you say, <name>? Find a box for ol' Smokey?", objectives = { "Grimm's Premium Tobacco" } },
    [5243] = { title = "Houses of the Holy", summary = "Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", desc = "I look at my undeath as a malady, <race>. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead?\n\nI am revered by my colleagues because of the sacrifices I have made, but the accolades mean nothing to me.\n\nIf you are interested in assisting the Argent Dawn, then a job I can offer.\n\nVenture to Stratholme and recover our surplus of holy water. Search the supply crates.", objectives = { "Stratholme Holy Water x 5" } },
    [5251] = { title = "The Archivist", summary = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", desc = "Anything taken to an extreme is hazardous to our world, <name>. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light?\n\nBlasphemers, one and all!\n\nOne in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade's most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded.", objectives = { "Archivist Galford", "Archive Burned" } },
    [5262] = { title = "The Truth Comes Crashing Down", summary = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.", desc = "You try and gather your thoughts as the dust settles across the chamber. You go over the events that just transpired and still cannot comprehend the gravity of the situation.\n\nThe Grand Crusader of the Scarlet Crusade a demon? And not just any demon but brother to Varimathras, arch lord of the Undercity?\n\nYou carefully stow the severed head of the dreadlord into your pack. Surely, none would believe the tale you would tell without proof.\n\nDuke Nicholas Zverenhoff must be told at once!" },
    [5263] = { title = "Above and Beyond", summary = "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", desc = "You display a natural aptitude for destruction and you follow orders. It is rare to see the two coexist. I am beginning to think that you may make an excellent vehicle of divine justice.\n\n<Zverenhoff clasps his hands together in front of his face.>\n\nKel'Thuzad's errand boy rules over Stratholme. Prove to me that you are a champion - my champion. Destroy Baron Rivendare and return to me with his head.", objectives = { "Head of Baron Rivendare" } },
    [5281] = { title = "The Restless Souls", summary = "Find Egan. You only know that he was last seen around Stratholme.", desc = "There are those that died tragically in the fall of Stratholme. Many took their own lives, opting to hurl themselves into the myriad flames of the smoldering city rather than become one of the Scourge.\n\nThey now walk the streets of Stratholme as restless spirits.\n\nWe must aid them, <name>!\n\nI have an associate named Egan who has been doing miraculous work with ghosts and souls. Seek him out. He walks the eastern Plaguelands, near Stratholme, testing his innovations." },
    [5282] = { title = "The Restless Souls", summary = "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan.", desc = "I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done. I am, however, no zealot. There are those, like the Scarlet Crusade, who would sooner destroy the innocent undead than lend them even an ounce of compassion.\n\nWhich brings me to this: My blaster. It will unchain the tortured souls from Stratholme.\n\nUse it on the ghosts that haunt the ransacked streets. Free their souls.", objectives = { "Souls Freed x 15" } },
    [5341] = { title = "Barov Family Fortune", summary = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.", desc = "Within the Scholomance lays the Barov family fortune. I, Alexi Barov, am one of the last two remaining heirs of the house Barov. My brother, Weldon, is the other.\n\nWeldon, the miserable coward, fled during the war and thus retained his worthless existence as a human.\n\nHe now searches for the deeds so that he may claim the fortune for his own. Recover the deeds before my brother does and I shall make you wealthy beyond your wildest dreams!", objectives = { "The Deed to Brill", "The Deed to Caer Darrow", "The Deed to Southshore", "The Deed to Tarren Mill" } },
    [5343] = { title = "Barov Family Fortune", summary = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.", desc = "My dear brother Alexi. What a fool I was to spare his life. I looked into the face of the enemy, one of the undead, and let him live.\n\n<Weldon spits.>\n\nHe now searches for MY inheritance. This simply cannot happen.\n\nFind my family's deeds before that vile retch gets his boney hands upon them and I shall reward you with vast riches. They lay in the ruins of the Scholomance. Make haste!", objectives = { "The Deed to Brill", "The Deed to Caer Darrow", "The Deed to Southshore", "The Deed to Tarren Mill" } },
    [5382] = { title = "Doctor Theolen Krastinov, the Butcher", summary = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", desc = "Krastinov is responsible for the deaths of thousands. He must be punished, justice must be meted out.\n\nFind him and exact upon him the agony he has inflicted upon countless innocents. Once he is destroyed, burn our remains. Turn them to ashes, <name>.", objectives = { "Doctor Theolen Krastinov", "Remains of Eva Sarkhoff Burned", "Remains of Lucien Sarkhoff Burned" } },
    [5384] = { title = "Kirtonos the Herald", summary = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul. Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.", desc = "This is it, <name>.\n\n<Eva points to the vial inside the bag.>\n\nThe blood of innocents. The purest blood, used to appease Krastinov's master.\n\nIt is with this blood that Kirtonos may be summoned. It is with this blood, then, that Kirtonos must be destroyed.\n\nTake the blood to the porch. Place it upon the brazier. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.\n\nShould you succeed, you will earn more than just our gratitude.", objectives = { "Kirtonos the Herald" } },
    [5461] = { title = "The Human, Ras Frostwhisper", summary = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.", desc = "The undead fear life just as the living fear death. It is not unusual for a sentient undead being to completely destroy all remnants of his or her previous life after having turned.\n\nUnfortunately, in order to create an artifact capable of reverting Ras Frostwhisper to a mortal, we must have a keepsake from his years among the living.\n\nYou must venture to the ruined city of Stromgarde, Frostwhisper's home, and search for such an item. May luck be with you, <name>.", objectives = { "Keepsake of Remembrance" } },
    [5462] = { title = "The Dying, Ras Frostwhisper", summary = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.", desc = "Upon tainted soil, the keepsake must be attuned.\n\nIt is rumored that Stratholme is where Frostwhisper succumbed to the Lich King. Upon those bloodied grounds he gave his life - freely and with motive - to become one of the undying.\n\nIt is those grounds that must be found.\n\nThere is one, an undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the cause of the Argent Dawn. Find him: Leonid Barthalomew the Revered. He may know more. Seek out Light's Hope, <name>." },
    [5463] = { title = "Menethil's Gift", summary = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.", desc = "I watched as the human, Ras Frostwhisper, pledged his undying soul to the Lich King. He drew the dagger to his own throat and with a smile, cut from ear to ear. His body collapsed inside the borders of the pentagram. The Lich King stood over the fallen mage and with a single motion, Ras Frostwhisper the lich, was born.\n\n<Leonid gazes at the ground and then looks up at you.>\n\nYes, <race>, I remember. What you seek has a name - Menethil's Gift: The ground blessed by the Lich King - holy ground to Scourge." },
    [5464] = { title = "Menethil's Gift", summary = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.", desc = "The soul of the fallen clings to that which represents its former life and transforms the item into a soulbound keepsake. You pick the item up and place it in your pack." },
    [5465] = { title = "Soulbound Keepsake", summary = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.", desc = "Return to Marduke with the keepsake, <name>. He will instruct you in its use." },
    [5466] = { title = "The Lich, Ras Frostwhisper", summary = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", desc = "There is but one task remaining, <name>. Confront the lich, Ras Frostwhisper, in his lair.\n\nUse the power of the keepsake against the beast - be unrelenting in your actions! Weather the blows that the flailing beast will surely bring down upon you. Do not give in to the pain!\n\nWhen the ritual is complete, Ras will be mortal once more. It is at that point that he must be slain. Strike him down and take his human head.", objectives = { "Human Head of Ras Frostwhisper" } },
    [5515] = { title = "Krastinov's Bag of Horrors", summary = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", desc = "A great weight has been lifted from our hearts, <name>, but your task is not yet complete. Krastinov's master, Kirtonos, still lives.\n\nBefore you may face Kirtonos, however, you must first secure a method in which to summon him.\n\nIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.\n\nFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find.", objectives = { "Krastinov's Bag of Horrors" } },
    [5518] = { title = "The Gordok Ogre Suit", summary = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.", desc = "If you're going to fight the king of this dump - and I think that's what you're bound to do - then you're going to need to get by Captain Kromcrush. Now, you can get by him by killing him, sure. You might actually want to leave him alive.\n\nHow, you ask? Since I've been here, I think I know how to make an ogre suit that will last just long enough to fool these bozos. The only problem is stability - ten minutes tops. Bring me what I need, and I'll make you one. I'm not going anywhere...", objectives = { "Bolt of Runecloth x 4", "Rugged Leather x 8", "Rune Thread x 2", "Ogre Tannin" } },
    [5522] = { title = "Leonid Barthalomew", summary = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.", desc = "I received a message from my master, Vectus. Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew. I don't know Leonid, but he knew my master, and no one knows my master unless he allows it.\n\nLeonid says Vectus wants the dragon eggs. He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands.\n\nThat hurts! Why you? Doesn't Vectus trust me? Oh, never mind... just take the eggs and tell Leonid that I did what our master commanded." },
    [5525] = { title = "Free Knot!", summary = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it. I think any of the ogres might have it, but I'm not sure if any specific ones do. Maybe the guards have a better chance of having one... What am I talking about - you have it already, don't you?! Is that it there??!", objectives = { "Gordok Shackle Key" } },
    [5526] = { title = "Shards of the Felvine", summary = "Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.", desc = "Your knowledge of Eldre'Thalas - Dire Maul - in Feralas will now come into play, <name>. In the eastern part of the ruined city is where Alzzin the Wildshaper has exerted his corrupt dominion. Go there with all due haste and brave whatever challenges await you.\n\nThe Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin. When he falls, capture whatever essence of the Felvine you can. Seal it in the Reliquary, and bring it to me.\n\nGood luck, and Cenarion's speed.", objectives = { "Sealed Reliquary of Purity", "Felvine Shard" } },
    [5527] = { title = "A Reliquary of Purity", summary = "Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.", desc = "The first step is to find a container capable of holding an extremely corruptible substance without the handler suffering ill effects. There is only one sort device I am aware of that could possibly contain something as vile as the Felvine: a Reliquary of Purity.\n\nDeep in the wasteland of Silithus is the remnants of the night elf village known as Southwind. I know one was there many, many years ago. If we are to succeed, I need you to scour those ruins in the hopes of reclaiming it.", objectives = { "Reliquary of Purity" } },
    [5528] = { title = "The Gordok Taste Test", summary = "You da big boss now, so you get free sample of my better brews! These drinks boost you up AND give you good buzz! These are da good ones, chief... you try and tell Kreeg yourself!" },
    [5529] = { title = "Plagued Hatchlings", summary = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.", desc = "The Argent Dawn recently learned that the Scourge are creating their own plagued dragonflight! We must stop them -- if the Scourge gain a force of dragons they'll sweep across Azeroth unchecked!\n\nTheir necromancers are breeding plagued dragons at the Scholomance, in the middle of Darrowmere Lake.\n\nGo to the Scholomance and kill as many hatchlings as you can... before they get any bigger!", objectives = { "Plagued Hatchling x 20" } },
    [5531] = { title = "Betina Bigglezink", summary = "Bring the Frozen Eggs to Betina Bigglezink.", desc = "The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight. These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable.\n\nNow, it is time we ended their research.\n\nTake the frozen eggs to Betina Bigglezink outside. She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge. With your help, we will deal them a heavy blow." },
    [5542] = { title = "Demon Dogs", summary = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", desc = "If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.'\n\nYou can start with the Plaguehounds and their runts.\n\nI cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed.", objectives = { "Plaguehound Runt x 20", "Plaguehound x 5", "Frenzied Plaguehound x 5" } },
    [5543] = { title = "Blood Tinged Skies", summary = "Slay 30 Plaguebats and return to Tirion Fordring.", desc = "Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks.\n\nEven the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats.", objectives = { "Plaguebat x 30" } },
    [5544] = { title = "Carrion Grubbage", summary = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", desc = "My food supplies are running low, <race>. I am ashamed to admit that I might not have enough food to share with you.\n\nCould you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!", objectives = { "Slab of Carrion Worm Meat x 15" } },
    [5582] = { title = "Healthy Dragon Scale", summary = "Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands.", desc = "This is a scale shed from a plagued dragon hatchling. But unlike the other pocked, oozing scales on the infant beast, this rare scale is healthy and unmarred.\n\nBetina Bigglezink will want a sample of this to study." },
    [5722] = { title = "Searching for the Lost Satchel", summary = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.", desc = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar." },
    [5723] = { title = "Testing an Enemy's Strength", summary = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.", desc = "Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde.\n\nShe asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy them all.", objectives = { "Ragefire Trogg x 8", "Ragefire Shaman x 8" } },
    [5724] = { title = "Returning the Lost Satchel", summary = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.", desc = "You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs.\n\nRemoving the satchel from his vice-like grip, you stow it with your own equipment and prepare to make your way out of the tunnels and back to Rahauro in Thunder Bluff." },
    [5725] = { title = "The Power to Destroy...", summary = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.", desc = "Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision.\n\nA sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to \"borrow\" these books from them. You will get them for her.", objectives = { "Spells of Shadow", "Incantations from the Nether" } },
    [5726] = { title = "Hidden Enemies", summary = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.", desc = "One thing I will not tolerate are traitors in our midst, <name>. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.\n\nBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.\n\nIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.", objectives = { "Lieutenant's Insignia" } },
    [5727] = { title = "Hidden Enemies", summary = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.", desc = "Now let us see if this insignia you found is worth the effort.\n\nThere is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies.\n\nTake this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here.", objectives = { "Gauge Neeru Fireblade's reaction to you being a member of the Burning Blade" } },
    [5728] = { title = "Hidden Enemies", summary = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.", desc = "Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.\n\nReturn to the Cleft of Shadow and enter Ragefire Chasm, <name>. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his <brothers/sisters> in arms.", objectives = { "Bazzalan", "Jergosh the Invoker" } },
    [5742] = { title = "Redemption", summary = "Listen to what Tirion Fordring has to say.", desc = "You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself.", objectives = { "Tirion's Tale" } },
    [5761] = { title = "Slaying the Beast", summary = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.", desc = "The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.\n\nIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.\n\nKill him, and his heart will appease Thrall, of this I'm sure.", objectives = { "Taragaman the Hungerer's Heart" } },
    [5781] = { title = "Of Forgotten Memories", summary = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", desc = "To help Taelan regain what he has lost, you must gather items from his past.\n\nThe first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own.\n\nAfter I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever.\n\nYou must venture to the Undercroft and recover Taelan's hammer.", objectives = { "Taelan's Hammer" } },
    [5845] = { title = "Of Lost Honor", summary = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", desc = "The Order of the Silver Hand was utterly decimated when Uther was slain.\n\nThe boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand.\n\nWere any of the Order left alive, he thought - and did it matter?\n\nIt was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale.\n\nYou must travel to Northdale and recover that symbol of lost honor.", objectives = { "Symbol of Lost Honor" } },
    [5846] = { title = "Of Love and Family", summary = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.", desc = "When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again.\n\nIf this painting still exists, you must find it.\n\nTravel to the ruined island of Caer Darrow and see if the painting or the artist remain." },
    [5848] = { title = "Of Love and Family", summary = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world. Return the painting to Tirion Fordring.", desc = "The painting... It hung on the wall of my workshop - inside the Order's barracks - for years.\n\nAfter Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look.\n\nTravel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.'\n\nMay the Light guide your actions.", objectives = { "Of Love and Family" } },
    [6133] = { title = "The Ranger Lord's Behest", summary = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge. You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.", desc = "The high elves of the Quel'Lithien lodge possesses something that belongs to me, <class>: A document detailing my life as a mortal.\n\nBefore you ask; no, you most certainly are not privy to such information. Just do as I tell you, worm: Recover the registry.\n\nAnd imbecile, be sure to leave as much strife and grief as possible in your wake. Leave them suffering...", objectives = { "Pathstrider x 8", "Ranger x 8", "Woodsman x 8", "Quel'Thalas Registry" } },
    [6135] = { title = "Duskwing, Oh How I Hate Thee...", summary = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller. It is said that Duskwing roams the countryside to the north of Marris Stead.", desc = "Up until now, you have completed the missions I have assigned; even if not in the most timely manner.\n\nI suppose you think that you are ready for a challenge. Yes... Yes, imbecile, perhaps you are ready for a more involved set of missions.\n\nThe albino demon bat, Duskwing, roams the countryside just north of here. Track him down and destroy him. Return to me with a patch of his white fur and you shall be rewarded.", objectives = { "Patch of Duskwing's Fur" } },
    [6163] = { title = "Ramstein", summary = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.", desc = "I was overwhelmed. On this very stead, I stood... held my ground in defense of Lordaeron. The farm and all on it were waylaid by a gigantic wave of Scourge.\n\nThe wretch. The filth. It hovered above me, entrails hanging from its gaping chest cavity.\n\nI woke as Scourge. For so long I was helpless. My mind had coalesced with the Lich King's.\n\nShe came for me... somewhere, somehow, I knew she would. Free.\n\nAnd now, I must have my vengeance - my vengeance on that which took from me my life. Destroy it.", objectives = { "Head of Ramstein the Gorger" } },
    [6402] = { title = "Stormwind Rendezvous", summary = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived.", desc = "You are to meet with Windsor at the gates of Stormwind.\n\nWhat Windsor is about to unveil will shake the very foundation of the kingdom!\n\nDo not attempt to venture there alone, <name>. You must amass an army! Gather your compatriots. To arms!" },
    [6403] = { title = "The Great Masquerade", summary = "Follow Reginald Windsor through Stormwind. Protect him from harm!", desc = "It has been quite the adventure, friend. I owe you a great debt of gratitude. Perhaps, when all is said and done...\n\nAs you have no doubt ascertained by now, Lady Prestor is Onyxia: Brood of Deathwing, twin to the tyrant of the Spire, Nefarian.\n\nFor too long she has held our kingdom in her captivating gaze. Even the Highlord is controlled by her trickery - a puppet. It all ends today... The spell will be broken.\n\nWorry not, for together, we shall be victorious!\n\nAre you ready?", objectives = { "Reginald's March" } },
    [6501] = { title = "The Dragon's Eye", summary = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist.", desc = "A fragment of the shattered medallion is all that I can offer.\n\nYou must find another of dragon blood willing to assist you in forging a new key. Once you secure this key, you must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find her lair, <name>.\n\nWhere to find other flights willing to help? Sadly, I do not know... They are said to exist. Some may even work and live among us, disguised as one of the humanoid races. I wish you luck." },
    [6502] = { title = "Drakefire Amulet", summary = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", desc = "It is a piece of the dragon; a scale - enchanted and transformed. Whole, it could have granted access to the beast's lair. Shattered, it is useless.\n\nIt is possible to repair the item, but to do so would require the blood of a black dragon champion. There is one... He is known as General Drakkisath, ruler of the dragonspawn armies of Nefarian. Perhaps you have heard of him?\n\nReturn with his blood, <race>, and I shall enchant the fragment into something that will grant you access to Onyxia's lair.", objectives = { "Blood of the Black Dragon Champion" } },
    [6521] = { title = "An Unholy Alliance", summary = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.", desc = "Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.\n\nHis presence there does explain much of what we've discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they've struck.\n\nFind Malcin and slay him, <name>. Return to me after the deed is done.", objectives = { "Ambassador Malcin's Head" } },
    [6522] = { title = "An Unholy Alliance", summary = "Take the Small Scroll to Varimathras in the Undercity.", desc = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin" },
    [6561] = { title = "Blackfathom Villainy", summary = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", desc = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Bashana in Thunder Bluff, <name>, please.", objectives = { "Head of Kelris" } },
    [6562] = { title = "Trouble in the Deeps", summary = "Speak to Je'neu Sancrea in Ashenvale.", desc = "Je'neu Sancrea is in need of aid. He is at the Zoram'gar Outpost in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, <name>. There are forces there that will not take to your presence kindly." },
    [6563] = { title = "The Essence of Aku'Mai", summary = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.", desc = "Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.\n\nWill you help me, <name>? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", objectives = { "Sapphire of Aku'Mai x 20" } },
    [6564] = { title = "Allegiance to the Old Gods", summary = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.", desc = "Some poor handwriting is scrawled on the crumpled up note:\n\n\"Yes, tell all the priestesses to bring the crystals to me. The water elemental spirits are strong within them and they will aid our aquamancers greatly in their own summonings.\n\nBy controlling the power within the crystals, we will appease Aku'Mai. One day we will have enough power to bring Aku'Mai back to us and the world will return to its greatest era! An era of rule by the Old Gods!\"" },
    [6565] = { title = "Allegiance to the Old Gods", summary = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.", desc = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, <name>. I cannot do it myself--I am too weak.\n\nGo into Blackfathom Deeps, find him, and kill him. Return to me here at Zoram'gar when it's done.", objectives = { "Lorgus Jett" } },
    [6566] = { title = "What the Wind Carries", summary = "Listen to Thrall.", desc = "It is good to see you again, <name>. The wind carries with it news from the Eastern Kingdom.\n\nSit, listen.", objectives = { "Thrall's Tale" } },
    [6567] = { title = "The Champion of the Horde", summary = "Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas.", desc = "I have received word from one of my champions that a way into the lair of the dragon may exist. You are to seek him out.\n\nRexxar wanders the desert wasteland of Desolace, traveling between Stonetalon and Feralas. He awaits your arrival." },
    [6568] = { title = "The Testament of Rexxar", summary = "Deliver Rexxar's Testament to Myranda the Hag in the Western Plaguelands.", desc = "What do you know of illusions, <name>? For you see, it is an illusion that you must create in order to circumvent the Black Flight's defenses.\n\nI know of one that may be willing to assist you in your quest of deception. She has assisted our kind in the past when she has deemed the cause worthy.\n\nIn the Western Plaguelands you will find Myranda the Hag, master illusionist - an exile of the Lordaeron alliance. Travel there and take with you this message." },
    [6569] = { title = "Oculus Illusions", summary = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.", desc = "So the <race> wishes to become one of the Black Flight, eh?\n\nThe creation of the illusion you require is trivial, but the components required for the divination are quite difficult to obtain. Rexxar and the Warchief have entrusted you with this mission, so Myranda must assume you as capable.\n\nTravel to the upper citadel of Blackrock Spire and slay enough of the black dragonspawn to fill up one of your packs with their eyes.\n\nReturn to Myranda when you have gathered enough of the reagent.", objectives = { "Black Dragonspawn Eye x 20" } },
    [6570] = { title = "Emberstrife", summary = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife.", desc = "I have attuned this medallion with the magic necessary to create and maintain an illusion within the bounds of the den of Emberstrife.\n\nEmberstrife is an ancient drake; an old gatekeeper of Nefarian, burdened with the duty to test those dragonspawn that would ascend to the rank of elite guard to Onyxia.\n\nTravel to the Wyrmbog of Dustwallow Marsh and enter the lair of Emberstrife. Once there, put on the amulet and follow where your destiny may lead!" },
    [6582] = { title = "The Test of Skulls, Scryer", summary = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife. You know that Scryer can be found in Winterspring.", desc = "We are Deathwing's children, whelp. Our dominance over the lesser Aspects must be enforced.\n\nIf you are truly worthy of ascension, the lesser dragonflight will wilt in your presence.\n\nFind their champions and lay waste to them in the name of our Father!\n\nTravel to Winterspring and track down the mighty blue drake, Scryer. Crush him and any of the Blue Flight that stand in your path. Tear out his skull and return it to me.", objectives = { "The Skull of Scryer" } },
    [6583] = { title = "The Test of Skulls, Somnus", summary = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.", desc = "Just as our Father crushes the Aspects themselves, so too must we strive to bring chaos and destruction to their children.\n\nYou must test your battle prowess against the sleepless dreamers: The children of the Green Flight.\n\nTravel to the Swamp of Sorrows and track down Somnus, drake champion of the Green Flight. Let flow your hatred; dominate the insect... Return to me with his skull...", objectives = { "The Skull of Somnus" } },
    [6584] = { title = "The Test of Skulls, Chronalis", summary = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.", desc = "The time watchers, children of Nozdormu - Lord of the Centuriesss...\n\nIt is three that guard the Caverns of Time, but only one that holds the interests of the Black Flight: The Time Shifter, Chronalis, favored drakeling of Nozdormu.\n\nSsstrike at this champion, a blow to make even the stoic sands of time weep. Return to me with his skull.", objectives = { "The Skull of Chronalis" } },
    [6585] = { title = "The Test of Skulls, Axtroz", summary = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.", desc = "It was over the mountains of Grim Batol that our Father raged against the combined might of the Aspects. The cowardly act of the betrayer, Alexstrasza, bought the other Aspects enough time to escape from Father's wrath.\n\nSssuch a shameful act...\n\nThe Red Flight now guards Grim Batol, their lieutenant, Axtroz, must be destroyed. Return the skull of Axtroz to me. For Father, whelp!", objectives = { "The Skull of Axtroz" } },
    [6601] = { title = "Ascension...", summary = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.", desc = "From the skulls of our enemies is shaped a medallion. You know this medallion, yesss? You have no doubt seen it worn by your elders.\n\nTake it, whelp. Return to the Spire and present it to General Drakkisath. The General will place the final enchantment upon the medallion, attuning the trinket to your spirit.\n\nYou will wear the finished medallion as a badge of honor, symbolizing your ascension to one of our most guarded ranks: Guardian to the brood mother.\n\nGo!" },
    [6602] = { title = "Blood of the Black Dragon Champion", summary = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.", desc = "You will pay the General a visit, yes, but not as one of the Black Dragonflight.\n\nYou see, a ceremony is merely another term for blood letting to the Black Flight.\n\nThe latent amulet merely needs the blood of the General in order to become active. One of their crude failsafe mechanisms.\n\nReturn to Blackrock Spire and destroy Drakkisath. Bring his blood back here and I shall activate the key to Onyxia's lair.", objectives = { "Blood of the Black Dragon Champion" } },
    [6626] = { title = "A Host of Evil", summary = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.", desc = "The Forsaken do not pass on their... illness... from what I have seen. This diplomat seems to be granting undeath to would-be followers. I am beginning to think he is one of the Scourge.\n\nFor now, my concern is not with him though, it's with the growing ranks around him. They creep from the shadows daily, almost begging him for more power.\n\nI'm not powerful enough to fight them on my own, <name>. What do you say? Are you up for some hunting?", objectives = { "Razorfen Battleguard x 8", "Razorfen Thornweaver x 8", "Death's Head Cultist x 8" } },
    [6627] = { title = "Test of Lore", summary = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.", desc = "You have brought me the book, and now it is time for your question. Are you ready?\n\nTime is not an issue, <class>, so do not feel pressured. You may take as long as you like to answer.", objectives = { "Answer Braug Dimspirit's question correctly" } },
    [6804] = { title = "Poisoned Water", summary = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands. Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.", desc = "A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them. The Waterlords cannot allow this affront to our purity!\n\nTake this vial. In it is a quantity of one aspect of Neptulon. If used on the plagued elementals it will fight the poison within their bodies and cure them! But their inner conflict will drive them into a surging madness.\n\nDefeat the discordant surges and bring me their bracers of binding.", objectives = { "Discordant Bracers x 12" } },
    [6805] = { title = "Stormers and Rumblers", summary = "Kill 15 Dust Stormers and 15 Desert Rumbers and then return to Duke Hydraxis in Azshara.", desc = "We, the elementals of water, wage war with those beings of the lesser elements. If you are truly our ally in this conflict, then show me your conviction!\n\nFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale. They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.\n\nGo to the Crystal Vale in Silithus and defeat our enemies, then return to me.", objectives = { "Dust Stormer x 15", "Desert Rumbler x 15" } },
    [6821] = { title = "Eye of the Emberseer", summary = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.", desc = "You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords. But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?\n\nThat is your new task.\n\nHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer. Find his place of imprisonment, slay his captors, and then slay the emberseer. Bring me his eye and it will show me your worth.", objectives = { "Eye of the Emberseer" } },
    [6921] = { title = "Amongst the Ruins", summary = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", desc = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps. Their presence can only serve to coerce the elements into working against us. If left unchecked, this region will be theirs for good.\n\n<name>, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water. In it is a fathom core - a device that when properly read it will relate a history of all elemental activity. If I have it, I and the Earthen Ring can maybe do something to stop them!", objectives = { "Fathom Core" } },
    [6922] = { title = "Baron Aquanis", summary = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", desc = "The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about. The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring. He is located at the Horde's Zoram'gar Outpost in Ashenvale." },
    [6981] = { title = "The Glowing Shard", summary = "Travel to Ratchet to find someone that can tell you more about the glowing shard. Then, deliver the shard as you are directed.", desc = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.", objectives = { "Speak with someone in Ratchet about the Glowing Shard" } },
    [7028] = { title = "Twisted Evils", summary = "Collect 25 Theradric Crystal Carvings for Willow in Desolace.", desc = "The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it, <class>. Relics of the old gods lie hidden behind the giant doors.\n\nIf you are willing to brave the twisted evils found in Maraudon, I believe I can make it worth your time. Collect the theradric crystal carvings you find, and return them to me.\n\nOnce I get the carvings, I will be able to... study them. These powers have been too long at rest...", objectives = { "Theradric Crystal Carving x 25" } },
    [7029] = { title = "Vyletongue Corruption", summary = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.", desc = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, <name>. Fill it at the orange crystal pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...", objectives = { "Vylestem Vines healed x 8", "Filled Cerulean Vial" } },
    [7041] = { title = "Vyletongue Corruption", summary = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.", desc = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, <name>. Fill it at the corrupted orange pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...", objectives = { "Vylestem Vines healed x 8", "Filled Cerulean Vial" } },
    [7044] = { title = "Legends of Maraudon", summary = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond. Find a way to speak with Celebras.", desc = "A dark satyr called Lord Vyletongue spread his evil through these twisting caves, poisoning the minds of all inside. He still resides beyond the purple crystals.\n\nVyletongue also created a living symbol of his corruption called Noxxion that dwells beyond the orange crystals. Together, they have stolen the two parts of my brother's scepter. Celebras, my brother... he wanders blindly inside, cursed by corruption.\n\nYou must help him! Find the pieces, and speak to my brother... somehow.", objectives = { "Celebrian Diamond", "Celebrian Rod" } },
    [7046] = { title = "The Scepter of Celebras", summary = "Assist Celebras the Redeemed while he creates the Scepter of Celebras. Speak with him when the ritual is complete.", desc = "My scepter was once a source of hope for me. Its power allowed me the freedom to travel quickly through these caverns. I had hoped to bring peace to the spirit of my uncle... It is a task that I now pass to you.\n\nFor the two parts to once again become one, I will need your assistance in performing the ritual. Please follow me, and listen to my instructions while I channel the energy required to reunite the rod with the diamond.\n\nTogether, we shall create the Scepter of Celebras once again!", objectives = { "Create the Scepter of Celebras" } },
    [7064] = { title = "Corruption of Earth and Seed", summary = "Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.", desc = "Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship. The offspring of their time together became known to the people of Kalimdor as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now hold Zaetar's remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.", objectives = { "Princess Theradras" } },
    [7065] = { title = "Corruption of Earth and Seed", summary = "Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.", desc = "In the depths of Maraudon lives a creature of chaos and evil, <name>. Princess Theradras is an elemental force of earth related somehow to the Old Gods. Ages ago, she was sought out by Zaetar, first son of Cenarius. The offspring of their... relationship are the creatures known as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now Theradras keeps his remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.", objectives = { "Princess Theradras" } },
    [7066] = { title = "Seed of Life", summary = "Seek out Remulos in Moonglade and give him the Seed of Life.", desc = "The misbegotten centaur--my sons and daughters--have need of their father.\n\nLook around you--this place rings of hope and all that my father Cenarius preaches. It sprung from me! And I cannot take that away from them... not even for their crimes against me.\n\nBut there is one thing I would ask of you to ease my brother's mind. Take this... it is the first seed that fell from the life my remains nourished. Tell him my spirit remains here, and that I live on. I am sure he will understand." },
    [7067] = { title = "The Pariah's Instructions", summary = "Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.", desc = "Though exiled as a heretic, my beliefs still ring true--that alone drives me onward. But for my destiny to be complete, I need the aid of an outsider... one not of any centaur tribe.\n\nThe task requires someone to enter the holy halls of Maraudon--a tomb my people protect, and only the most devout are ever allowed to enter.\n\nIf you agree to aid me, then you need only nod. I will pass you a parchment with my instructions on it. Read it over and consider my words.", objectives = { "Amulet of Union", "Amulet of Spirits" } },
    [7068] = { title = "Shadowshard Fragments", summary = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.", desc = "Strong magics be found in the centaur holy place... the holy place of Maraudon. The Desolace tribes of centaur protect that place wit' their lives, but they canna stop us from takin' what we need.\n\nYou, you head to this Maraudon place and find the rock creatures made of shadowshard. You bring me the purple crystals, and Uthel'nay make you somethin' for your time.\n\nThe place be dangerous, so maybe you be bringing some friends.", objectives = { "Shadowshard Fragment x 10" } },
    [7070] = { title = "Shadowshard Fragments", summary = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.", desc = "I've recently begun testing various crystals and their arcane properties. Lady Proudmoore has given me leave to ask travelers heading into Desolace to seek out a place called Maraudon. Within the ruined temple are great elementals composed of purplish stones I've named shadowshards.\n\nIf you decide to head that direction and find some of the crystals, I would be very thankful. I could even fashion you a trinket from them if you so desired.", objectives = { "Shadowshard Fragment x 10" } },
    [7201] = { title = "The Last Element", summary = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", desc = "There is work to be had for those venturing into the depths, <name>.\n\nThe Dark Irons have mastered creation of extremely powerful golems.\n\nInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.\n\nJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.", objectives = { "Essence of the Elements x 10" } },
    [7441] = { title = "Pusillin and the Elder Azj'Tordin", summary = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", desc = "I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas.\n\nI no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations.\n\nFind the imp, Pusillin, and recover my book.\n\nSearch the Warpwood Quarter of Dire Maul for Pusillin.", objectives = { "Book of Incantations" } },
    [7461] = { title = "The Madness Within", summary = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated. Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum. Return to the Shen'dralar Ancient in the courtyard should you complete this quest.", desc = "Have you heard enough? Are you a <man/woman> of action?\n\nThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.", objectives = { "Immol'thar", "Prince Tortheldrin" } },
    [7463] = { title = "Arcane Refreshment", summary = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", desc = "A <race> mage! How wonderous. I have not seen one of your kind for... oh what is it going on now? 500 years!\n\nI have something that will quench your thirst, but first you must do a task for me.\n\n<Lydros snickers.>\n\nThere is an anomaly in Eldre'Thalas. A water elemental has taken residence in the east wing. His presence must be catalogued!\n\nVenture to the Warpwood Quarter and extract a portion of the elemental essence of the Hydrospawn. Return it to me and I shall teach you a useful cantrip.", objectives = { "Hydrospawn Essence" } },
    [7481] = { title = "Elven Legends", summary = "Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", desc = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", objectives = { "Master Kariel Winthalus Found" } },
    [7482] = { title = "Elven Legends", summary = "Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.", desc = "Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", objectives = { "Master Kariel Winthalus Found" } },
    [7488] = { title = "Lethtendris's Web", summary = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", desc = "The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul. She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!\n\nStop her, <name>. Find her and retrieve her web. She is likely near the satyrs in Warpwood Quarter of Dire Maul. Bring the web to me so that its power may be released safely back into the wilds...", objectives = { "Lethtendris's Web" } },
    [7489] = { title = "Lethtendris's Web", summary = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.", desc = "The blood elf Lethtendris has overstepped her bounds. So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul. Even now she gathers those energies and plans to release them against her enemies.\n\nLethtendris must be stopped. Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for study.", objectives = { "Lethtendris's Web" } },
    [7492] = { title = "Camp Mojache", summary = "Speak with Talo Thornhoof at Camp Mojache in Feralas.", desc = "Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid. He offered few details, but he did say that he needs agents for a matter both delicate... and dire.\n\nServe the Horde, <name>. Go to Camp Mojache in Feralas and speak with Talo." },
    [7494] = { title = "Feathermoon Stronghold", summary = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", desc = "<name>! Your aid is needed in Feralas!\n\nAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul. It is believed she has an item of dangerous magical energy which must be recovered.\n\nLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.\n\nServe the Alliance! Seek out Latronicus at the Feathermoon Stronghold in Feralas." },
    [7507] = { title = "Foror's Compendium", summary = "Return Foror's Compendium of Dragon Slaying to the Athenaeum.", desc = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible." },
    [7668] = { title = "The Darkreaver Menace", summary = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him. Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.", desc = "Death Knight Darkreaver lords over the Great Ossuary in the Scholomance. He threatens to twist the spirit realm to do his own bidding, and he must be stopped! This is where the scryer you helped make comes into play.\n\nUse the divination scryer in the heart of the Great Ossuary's basement to call forth Darkreaver's spirit minions. Defeat the spirits and the death knight himself will appear. <name>, bring me his head! Only his demise will reverse the damage dome to the spirit realm!", objectives = { "Darkreaver's Head" } },
    [7703] = { title = "Unfinished Gordok Business", summary = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul. According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.", desc = "Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince! Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might. Old timey stories say only da one true king da Gordok can get it back. Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever! Yar, I show you!", objectives = { "Gauntlet of Gordok Might" } },
    [7761] = { title = "Blackhand's Command", summary = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command. The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.", desc = "Imbecile,\n\nI hold very little faith in your ability to prevent outsiders from accessing the master's lair. In the very likely event of your death, this orb has its own failsafe built in to prevent outsiders from teleporting directly into Blackwing.\n\nOnly those with the Mark of Drakkisath branded upon their hand may make use of this orb. Thankfully, Drakkisath is not nearly as incompetent as you, Quartermaster. He guards the brand himself!\n\n-Warchief Rend Blackhand\n\nP.S. Destroy this letter, idiot." },
    [7848] = { title = "Attunement to the Core", summary = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", desc = "Rifts stir, tear, and collapse all around us, <race>. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.", objectives = { "Core Fragment" } },
    [8905] = { title = "An Earnest Proposition", summary = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge.", desc = "Well met, <class>. I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality. I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment. Bring me a sizeable sample of it along with the bracers and a small amount of gold. You shall find the effort worth your while.", objectives = { "Winterspring Blood Sample x 15", "Wildheart Bracers" } },
    [8921] = { title = "The Ectoplasmic Distiller", summary = "Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold.", desc = "Ah, you're in need of my latest project... the extra-dimensional ghost revealer! Unfortunately I've run out of funds and manpower.\n\nYou're willing to help? Excellent! Our first task is to build a device to harvest the very fabric of death! Building an ectoplasmic distiller won't be an easy task, <name>.\n\nI'll need you to bring me an arcanite converter, some greater eternal essences and stonescale oil. I'll also need some volcanic ash from the lava pools in the Burning Steppes to build a filter.", objectives = { "Delicate Arcanite Converter", "Greater Eternal Essence x 4", "Stonescale Oil x 10", "Volcanic Ash x 25" } },
    [8922] = { title = "A Supernatural Device", summary = "Bring the Sealed Blood Container to Mux Manascrambler inside Gadgetzan in Tanaris.", desc = "I must find a way to speak with Anthion Harmon... or more specifically, his ghost!\n\nI know of an engineer with a queer interest in the supernatural. He claims he can build a machine that allows him to speak with the dead!\n\nThe blood you collected was intended for him; travel to Gadgetzan and bring it to him as payment for his services!" },
    [8924] = { title = "Hunting for Ectoplasm", summary = "Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands. Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan.", desc = "A fine piece of engineering, if I do say so myself! You will need to travel a bit, I'm afraid, in order to find the incorporeal undead we require.\n\nYou see, different climates lend different consistencies to the spectral fabric of the dead. The tortured night elves of Silithus, the spirits of the highborne from Winterspring and the ghosts and banshees of the Eastern Plaguelands should give us the different types of ectoplasm we need. Be sure to place the distiller nearby before you harvest them!", objectives = { "Scorched Ectoplasm x 12", "Frozen Ectoplasm x 12", "Stable Ectoplasm x 12" } },
    [8925] = { title = "A Portable Power Source", summary = "Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan.", desc = "Next we shall need to find a stable and portable source of energy to keep the ectoplasm active. I've heard rumors of a mighty elemental called Magma Lord Bokk, whose heart is a powerful magma core - an endless supply of heat!\n\nIt's said he can be found in the Burning Steppes, south of Blackrock Mountain. Bring the magma core to me and we shall have enough juice to power the extra-dimensional ghost revealer!", objectives = { "Magma Core" } },
    [8926] = { title = "Just Compensation", summary = "Bring a Wildheart Belt and a set of Wildheart Gloves Deliana in Ironforge.", desc = "You kept your word and brought the device built by Mux. I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gloves that you wish to upgrade. I promise the ones I give you in return will be far superior.", objectives = { "Wildheart Belt", "Wildheart Gloves" } },
    [8928] = { title = "A Shifty Merchant", summary = "Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan.", desc = "The core will provide us with enough juice to power our device; now we just have to build a rod that can channel that energy without melting.\n\nI met an imp in Winterspring that sold all manner of exotic goods. He had an elemental rod that would do perfectly. I'm kicking myself in the head right now for not having bought it.\n\nHe lives inside a cave in the entrance to Darkwhisper Gorge. Sneak in there and try to find him.\n\nMake sure he only charges you forty gold; that's the price he quoted me!", objectives = { "Fel Elemental Rod" } },
    [8929] = { title = "In Search of Anthion", summary = "Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.", desc = "Well, nothing left for us to do but try out the goblin's invention. Word has it that Anthion was mowed down by the undead legions of Stratholme as he tried to enter its gates.\n\nTry using the device there and find out whatever Anthion knew." },
    [8945] = { title = "Dead Man's Plea", summary = "Go into Stratholme and rescue Ysida Harmon from Baron Rivendare.", desc = "I'll provide you the information you ask for, <name>. But more pressing matters are at hand.\n\nMy beloved wife has been taken prisoner by Rivendare's undead scum.\n\nI strongly objected to her joining the Argent Dawn's foolish crusade, yet that's not of importance anymore. You must finish what I attempted to do, you must rescue Ysida from the clutches of the Baron!", objectives = { "Ysida Freed" } },
    [8977] = { title = "Return to Deliana", summary = "Bring the Extra-Dimensional Ghost Revealer to Deliana in Ironforge.", desc = "It's been great working with you, <name>. Here is the finished product.\n\nI hope it helps you in your current endeavors. And hey, if you don't mind, help spread the word. I wouldn't mind having more customers!" },
    [92401] = { title = "A Frightened Request", summary = "Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron.", desc = "It's my husband Edward...\n\nHe has not returned from his weekly journey to the graveyard in the Lordaeron ruins. Our son was lost when Arthas razed the city, and my dear Edward is still filled with guilt and sorrow that we never found his body. I've tried to warn him against searching those overrun ruins, but he refuses to give up. I try not worry, but it's been days.\n\nThere are things there I cannot contend with but if you are willing, I need to know the fate of my husband.", objectives = { "Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron." } },
    [92415] = { title = "Remember That I Love You", summary = "Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City.", desc = "<A torn and stained bundle of parchment has barely survived the undead trodden grounds of the graveyard. It mentions a missing child of the Heartweaver family. Perhaps the orphan matron in Stormwind City will know more.>" },
    [92421] = { title = "Light's Justice", summary = "Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity.", desc = "As a paladin of the Forsaken, it is my duty to exact the will of our Dark Lady while tending to our people's needs. We are fortunate with an opportunity to accomplish both.\n\nAbove the Undercity, the scourge still roam unchecked in great numbers. Our forces dwindle trying to reclaim our land, and decaying flesh cannot be reknit. Not without replacements.\n\nWould that our glorious captain Garek Bandarion still be with us, I know what he would wish. To finish what he started and heal our kin. For Lordaeron!", objectives = { "Intact Limbs x 25" } },
    [92422] = { title = "The Wrath of Rath'mael", summary = "Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill.", desc = "Reports have come in from the Lordamere Overlook deep within the Ruins of Lordaeron. An unholy fog has taken over the streets and graveyard, affording the scourge up there some measure of stealth.\n\nOur scouts indicate they're being conjured by a new power within their ranks, a necromancer known as Rath'mael. We do not have the luxury of waiting this one out, <name>.\n\nIf you have allies, summon them and their aid to the Forsaken. Drive this creature out of our lands.", objectives = { "Rath'mael" } },
    [92742] = { title = "Testing the Wells", summary = "Use the Well Water Sample Kit to collect samples from the wells at the Jansen Stead and the Molsen Farm.", desc = "We must determine the source and nature of the poison corrupting this land. Let us begin with the groundwater under the farms in the area.\nGo to the Jansen Stead and the Molsen Farm, and collect samples from the wells there.", objectives = { "Jansen Stead Water Sample", "Molsen Farm Water Sample" } },
    [92744] = { title = "Murloc Gills", summary = "Alba Fairmoon wants you to collect 7 Longshore Murloc Gills along the shoreline of Westfall.", desc = "The corruption affecting Westfall's crops may have seeped into the ocean as well. If the local fish are affected too, it could doom Stormwind to famine.\nCollect gills from the murlocs along the shoreline and bring them to me. Murlocs are quite hardy, but their physiology is extremely sensitive to contaminants. Any toxins in the seawater will be readily apparent in the gills you find.", objectives = { "Longshore Murloc Gill x 7" } },
    [92745] = { title = "The State of the Mines", summary = "Slay 4 Kobold Diggers in the Jangolode Mine and 6 Riverpaw Miners in the Gold Coast Quarry.", desc = "The well samples you collected contain toxic metals! If we do not put an end to this corruption quickly, it will be decades before crops can grow in this soil again.\nThe Defias have seized the mines of Westfall and use creatures as labor to strip their resources. Disrupt them by slaying their miners in the Jangolode Mine to the north, and the Gold Coast Quarry to the west.", objectives = { "Kobold Digger x 4", "Riverpaw Miner x 6" } },
    [92747] = { title = "Moonbrook Espionage", summary = "Collect 8 Suspicious Industrial Supplies from Moonbrook.", desc = "Strange - the poison does not seem to originate from the mines you investigated.\n\nI am told the Deadmines under the town of Moonbrook are the largest, deepest mines of Westfall, but they have been abandoned since the First War. Could the Deadmines be active again?\n\nPlease travel to Moonbrook, <name>, and look for evidence of mining or industrial activity. This is the last lead we have!", objectives = { "Suspicious Industrial Supplies x 8" } },
    [92748] = { title = "Explosive Consultation", summary = "Travel to the Dwarven District in Stormwind and find an engineer who can help.", desc = "The supplies you found point to a massive industrial operation somewhere in the Deadmines. There's no question that this is the source of the toxins plaguing the farmland of Westfall. We need to stop it, quickly.\n\nWhatever's down there will be difficult to destroy. Go to the Dwarven District of Stormwind, and find an engineer who can supply us with some explosives." },
    [92749] = { title = "A Dynamite Plan", summary = "Obtain 10 Coarse Dynamite from crafting, trading, or the auction house, then return to Sprite Jumpsprocket in the Dwarven District of Stormwind.", desc = "Industrial sabotage? You've got my attention!\nWe'll start with some dynamite...", objectives = { "Coarse Dynamite x 10" } },
    [92750] = { title = "Detonation at a Distance", summary = "Talk to someone in Stormwind Intelligence about acquiring a remote detonator.", desc = "I assume you want a \"controlled\" explosion? Not as much fun, but a good choice if you want to keep all your limbs.\nI'm afraid I don't have a remote detonator - why don't you go check with the sneaky folks down at Stormwind Intelligence? They should be able to find us something." },
    [92751] = { title = "Detonation at a Distance", summary = "Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind.", desc = "You need something destroyed? Would this have anything to do with your activities in Moonbrook? Don't look surprised. SI:7 stays apprised of all that goes on in Stormwind's lands.\nIf you're planning to set off an explosion in the caves below Westfall, you'll want to be well outside beforehand. Take this remote detonator - it's a recent prototype from our own engineers.\nOh - and it would be best if you didn't mention my involvement to your elf friend." },
    [92752] = { title = "Explosive Consultation", summary = "Return to Alba Fairmoon in Westfall.", desc = "That's it - the bomb's ready to go! Careful with that detonator, now." },
    [92753] = { title = "Destruction in Deadmines", summary = "Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit.", desc = "The source of the poison is likely a large metallurgical forge of some kind. Find a way into the Deadmines and locate the forge, then place the explosives.\nI will wait for you in the hills behind Moonbrook. Once you return, we can detonate the explosives. Hopefully with the forge gone, the land can begin to heal.", objectives = { "Explosives placed" } },
    [92819] = { title = "Destruction in Deadmines", summary = "Use the detonator.", desc = "We are almost finished. Use the detonator, and end this.", objectives = { "Detonator used" } },
    [95189] = { title = "Crest of Lordaeron", summary = "Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City.", desc = "<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in Stormwind would be very keen to get their hands on this.>" },
    [95195] = { title = "Bloodied Insignia", summary = "Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City.", desc = "<The old Alliance insignia appears to have belonged to a soldier of Lordaeron. These ruins are likely filled with similar medals that living relatives would be grateful to have returned to them.>" },
    [95204] = { title = "Crest of Lordaeron", summary = "Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity.", desc = "<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in the Undercity would be very keen to get their hands on this.>" },
    [95216] = { title = "The New Plague", summary = "Collect the Highly Toxic Strain from Witherfang in Ruins of Lordaeron for Theodore Griffs in Undercity.", desc = "Welcome to the most vital organ of the Undercity: The Apothecarium! Here we experiment on the most virulent of Azeroth's exotic specimens.\n\nYou've caught me in a good mood, so I will let you in on my latest investigation. It appears there is a particularly venomous arthropod stalking the ruins above our fair city. Its toxins are said to eat through even undead flesh. How exhilarating!\n\nI wish to validate these claims. Should you find yourself withering away from its bite, I should love a sample.", objectives = { "Highly Toxic Strain" } },
    [95250] = { title = "Abominable Creatures", summary = "Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman.", desc = "What do you want, <race>? Can't you see there is a war to be won?\n\nMy master has already charged into the fray and has ordered me to maintain my post. It has been quite some time, however.\n\nI doubt you'll survive ten minutes in combat, but if it keeps your simple mind busy, why don't you seek out the Grand Marshal. He is the tallest, most statuesque hero you've ever laid eyes on. You'll know him when you see him.", objectives = { "Head of the Baron" } },
    [96391] = { title = "Underground Map", summary = "Deliver the Dark Iron Map to Earthseer Farsen in Dun Morogh.", desc = "<The map you are holding seems to show a complex series of underground tunnels and highways that all seem to converge on a point underneath Ironforge itself.\n\nYou can't be sure what the runes say as they are written in the ugly jagged rune language of the Dark Iron dwarves, but you can guess at the purpose of these tunnels. As you are reading the map, a gust of wind washes over you and you can faintly hear a dwarven voice carried on it. Earthseer Farsen needs to see this.>" },
    [96393] = { title = "Old Ironforge Incursion", summary = "Enter the Hall of Thanes beneath Old Ironforge and claim the Head of Durgen Dirgehammer.", desc = "Gather some allies and head down into the caverns beneath Old Ironforge. Enter the Hall of Thanes there and push to the lower vaults.\n\nMy Dark Iron is a bit rusty, but I can make out a name--one Durgen Dirgehammer. It's likely that he's the commander. Take his head and deliver it to King Magni Bronzebeard.\n\nOh, and when you do, tell him his old friend Farsen sends his regards!", objectives = { "Durgen Dirgehammer's Head" } },
    [96394] = { title = "The Restless Dead", summary = "Kill 15 Enraged Apparitions, 10 Tormented Souls and put the spirit of Anvilmar to rest.", desc = "Something has disturbed the tombs down in the Hall of Thanes, and strange noises have been heard coming from deep within the vaults. The spirits of the dead are light sleepers, and whatever is going on down there seems to have startled them.\n\nHead down there and see what you can do about that for us. If any of the dead are awake--well, put them back down!", objectives = { "Enraged Apparition x 15", "Tormented Soul x 10" } },
    [96395] = { title = "An Ancient Grudge", summary = "Put the spirit of Faldrim Anvilmar to rest in the Hall of Thanes.", desc = "The... Thane... my mighty... Thane... he... needs to... rest.\n\nPlease... help him... help him... rest...\n\nConsumed... by... ancient... grudge... No... rest...", objectives = { "Faldrim Anvilmar" } },
    [96403] = { title = "Important Heirlooms", summary = "Collect 8 Dwarven Heirlooms from the Hall of Thanes.", desc = "You there, adventurer... I could really use your aid.\n\nI was sneaking--uh... 'patrolling' in the vaults when a force of Dark Iron dwarves emerged from the depths in mole machines! I don't know what they are here for, but there is priceless loot--uh or, rather... I mean, 'important cultural heirlooms' down there! Please, recover any such relics you see and return them here.\n\nI assure you that anything you recover will be catalogued and returned to its proper place of honor.", objectives = { "Dwarven Heirloom x 8" } },
    [97288] = { title = "Unending Torment", summary = "Deliver the Abominable Head to someone within the Undercity.", desc = "<As the creature falls, its head comes toppling off. It seems as if it has been reattached several times, and the connection gets weaker with each reconnection.\n\nSomeone in the Undercity would know more about this unique abomination.>", objectives = { "Deliver the Abominable Head to someone within the Undercity." } },
    [98423] = { title = "The Treaty of Understanding", summary = "Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge.", desc = "Inside of the vault you find a tablet detailing the terms of a peace treaty between the Bronzebeard and Wildhammer dwarf clans. It appears to date back to time period just after of the War of the Three Hammers, and is very likely a notable piece of dwarven history. The king of Ironforge would no doubt be interested in this artifact." },
  },
  esES = {
    [17] = { title = "Componentes de Uldaman", summary = "Lleva 12 setas moradas a Ghak Sanadón a Thelsamar.", desc = "Hace poco me hablaron de un organismo recién descubierto, las setas moradas. Crecen arracimadas en lo más profundo de la excavación de Uldaman; es el único sitio del que tengo noticia. Quiero ver qué usos potenciales pueden tener en la alquimia, por eso necesito tu ayuda.\n\nTráeme una docena de setas moradas. Es posible que se defiendan con esporas venenosas; ten cuidado.\n\n¡A cambio, te daré uno de mis famosos elixires vigorizantes!", objectives = { "Seta magenta x 12" } },
    [65] = { title = "La hermandad de los Defias", summary = "Gryan Mantorrecio quiere que hables con Wiley en Villa del Lago.", desc = "La banda de desgraciados responsable de que las gentes de los Páramos de Poniente abandonaran sus tierras se llama a sí misma la Hermandad Defias. Necesito que te infiltres en este clan de matones. Debemos averiguar quién lidera el grupo y dónde se esconden. En Villa del Lago, en la posada, encontrarás a un pícaro que responde al nombre de Wiley; me debe un favor.\n\nViaja a Villa del Lago, en las Montañas Crestagrana, al este de Elwynn, y averigua todo lo que puedas." },
    [132] = { title = "La hermandad de los Defias", summary = "Lleva la Nota de Wiley a Gryan Mantorrecio en los Páramos de Poniente.", desc = "Lo que voy a contarte puede costarme la vida. La banda Defias está preparando algo grande. Lo último que oí fue que estaban colaborando con varios gnolls, kobolds e incluso goblins.\n\nLlévale esta nota a Mantorrecio. Explica todo lo que sé sobre este asunto." },
    [135] = { title = "La hermandad de los Defias", summary = "Lleva la Nota de Wiley a Mathias Shaw de Ventormenta.", desc = "Me pregunto qué querría decir Wiley cuando habló de los Albañiles. Quizás fue un lapsus. ¿Podría estar relacionada la banda Defias con los Albañiles? El único que podría saberlo es Mathias Shaw, líder del IS:7. Enséñale la nota de Wiley, tal vez tenga algo que añadir a este misterio. Si tienes problemas para encontrarlo, busca en el Cuartel, en el Casco Antiguo." },
    [141] = { title = "La hermandad de los Defias", summary = "Lleva el informe de Shaw a Gryan Mantorrecio de los Páramos de Poniente.", desc = "La Hermandad de los Albañiles estaba dirigida por un tal Edwin VanCleef. VanCleef fue responsable de la reconstrucción de Ventormenta cuando la ciudad fue arrasada por los orcos en la Primera Guerra. Al parecer, VanCleef y sus hombres no estaban satisfechos con el tratamiento que les brindó el rey cuando terminó la reconstrucción. Pero eso solo explicaría algunas cosas.\n\nHe redactado un informe más detallado para tu maestro en los Páramos de Poniente. ¡Llévaselo de una vez!" },
    [142] = { title = "La hermandad de los Defias", summary = "Localiza al mensajero Defias de los Páramos de Poniente y lleva su mensaje a Mantorrecio.", desc = "Tenemos que descubrir la localización de la Ladronera Defias. <nombre>, según los informes de mi rastreador, se ha visto a un mensajero Defias en los caminos entre el Arroyo de la Luna, la Mina de la Costa de Oro y la Mina de Jango. Quiero que le captures. Si ofrece resistencia, mátalo y tráeme lo que esté llevando.", objectives = { "Un mensaje misterioso" } },
    [155] = { title = "La hermandad de los Defias", summary = "Escolta al Traidor de los Defias a la ladronera secreta de la Hermandad Defias. Cuando el Traidor de los Defias te enseñe dónde se esconden VanCleef y sus hombres, regresa con Gryan Mantorrecio con toda la información.", desc = "¿Así que Mantorrecio envía a un <raza> enclenque para protegerme? Supongo que tendrás que hacerlo. Pero será mejor que traigas algunos amigos.\n\n¿Ya conoces el trato, verdad? Tú me guardas las espaldas y yo te llevo hasta la Ladronera Defias. La banda Defias busca mi cabeza, así que si me ven contigo, intentarán matarme.\n\nAvísame cuando tú y los amigos que puedas reunir estéis listos para emprender la marcha.", objectives = { "Escolta al Traidor de los Defias para descubrir dónde se oculta VanCleef" } },
    [166] = { title = "La hermandad de los Defias", summary = "Mata a Edwin VanCleef y lleva su cabeza a Gryan Mantorrecio.", desc = "Todavía hay una tarea que debes cumplir. Edwin VanCleef debe ser asesinado. Aunque me entristece condenar a alguien a la pena de muerte, el bien común de las gentes de los Páramos de Poniente exige que VanCleef descanse de una vez por todas. Tráeme la cabeza de ese villano cuando hayas terminado tu hazaña.", objectives = { "Cabeza de VanCleef" } },
    [167] = { title = "Oh, hermano...", summary = "Lleva la insignia de la Liga de Exploradores del supervisor Cardortiga a Wilder Cardortiga, en Ventormenta.", desc = "Estábamos en las profundidades de una gran mina en Páramos de Poniente, oculta tras un granero en el Arroyo de la Luna. No tenemos ni idea de dónde salieron esos ladrones. En fin, el túnel se derrumbó sobre nosotros. Conseguí salir, pero los otros... bueno... de los otros no sé nada.\n\nCreo que tú podrías tener más suerte ahí abajo. Si pudieras buscar a mi hermano, te lo agradecería mucho. Siempre llevaba su insignia de la Liga de Exploradores. Si no puedes encontrarle, al menos la insignia me daría algo de paz mental.", objectives = { "Tarjeta de Ortigacardo" } },
    [168] = { title = "La recolección de Tarjetas del Sindicato Minero", summary = "Recupera 4 Tarjetas del Sindicato Minero y llévaselas a Wilder Cardortiga, en Ventormenta.", desc = "Muchos de mis amigos murieron ese horrible día cuando se derrumbó el túnel de la mina. Si tus aventuras te llevan de casualidad a esa parte de la mina en el Arroyo de la Luna, por favor, busca alguna señal que pueda identificarles. Si te encuentras con alguna de sus Tarjetas del Sindicato Minero, tráemelas y me aseguraré de que sus familias reciban la resolución de este horrible accidente.", objectives = { "Tarjeta de sindicato de minero x 4" } },
    [214] = { title = "Pañuelos rojos de seda", summary = "La exploradora Riell de la Colina del Centinela quiere que le lleves 10 pañuelos de seda roja.", desc = "No es ningún secreto que la marca distintiva de la banda Defias son los pañuelos rojos. Pero hemos averiguado que el material del que están hechos los pañuelos sirve para identificar el rango del miembro.\n\nDicho esto, quiero que elimines tantos miembros Defias de alto rango como puedas. Podrás encontrarlos en la ladronera secreta de VanCleef. Cuando hayas terminado tráeme 10 pañuelos de seda roja y sabré recompensarte. Buena suerte, <nombre>.", objectives = { "Pañuelo de seda rojo x 10" } },
    [261] = { title = "El sendero Escarlata", summary = "Destruye 30 devastadores no-muertos y luego ve a buscar al hermano Antón a Punta de Nijel.", desc = "Te hablaré con franqueza. Estamos en guerra con la Plaga. Es un mal que corrompe a nuestra gente e infesta nuestra tierra. Hay que detenerlo antes de que nos arrolle y arrastre a nuestro mundo a las sombras. Los miembros de la Cruzada Escarlata hemos jurado combatir a la Plaga en cuerpo y alma.\n\nSi estás con nosotros, reúne valor y prueba tu lealtad: destruye a los devastadores no-muertos de Desolace. Búscalos en el Valle de los Huesos, al sur.\n\nHazlo y la Cruzada te acogerá con los brazos abiertos.", objectives = { "Devastador no-muerto x 30" } },
    [303] = { title = "La guerra contra los Hierro Negro", summary = "Motley Garmason de Dun Modr quiere que mates 15 enanos Hierro Negro, 5 tuneladores Hierro Negro, 5 saboteadores Hierro Negro y 5 demoledores Hierro Negro.", desc = "La guerra arde aquí en casa y en el extranjero. Mientras los grandes soldados enanos dan sus vidas en tierras lejanas en nombre de la Alianza, nuestras propias tierras caen víctimas de la depravación de los enanos Hierro Negro. Arrasaron el Puente Thandol y Dun Modr pronto caerá.\n\nTe necesitamos para reunir fuerzas y hacer retroceder el frente. Si puedes matar a 15 enanos Hierro Negro, 5 tuneladores, 5 saboteadores y 5 demoledores, tal vez la reserva consiga llegar a tiempo para terminar la ofensiva.\n\n¡Date prisa!", objectives = { "Enano Hierro Negro x 15", "Tunelador Hierro Negro x 5", "Saboteador Hierro Negro x 5", "Demoledor Hierro Negro x 5" } },
    [373] = { title = "La carta sin enviar", summary = "Entrega la carta destinada al arquitecto jefe a Baros Alexston en Ventormenta.", desc = "Registrando a Edwin VanCleef descubres, entre otras cosas, una carta sin enviar. Va dirigida a Baros Alexston, el arquitecto jefe de Ventormenta, Ayuntamiento, Plaza de la Catedral.\n\nParece ser que ha sido escrita y sellada recientemente." },
    [377] = { title = "Crimen y castigo", summary = "El consejero Tallolino de Villa Oscura quiere que le lleves la mano de Dextren Tutor.", desc = "Como si no tuviéramos suficiente con la negligencia de los residentes del Bosque del Ocaso, ahora la Casa de Nobles escupe en el ojo al Consejo de Villa Oscura con su decisión de encarcelar a Dextren Tutor en Ventormenta en lugar de decapitarlo como establecía la sentencia de Lord Ebonlocke.\n\nTutor fue descubierto vendiendo cadáveres del cementerio a Morbent Vil, y ese es un delito que se castiga con la muerte. Y sin embargo, Ventormenta lo reclama como prisionero.\n\nAsesina a Tutor en las Mazmorras de Ventormenta. Tráeme su mano y yo te recompensaré.", objectives = { "Mano de Dextren Tutor" } },
    [378] = { title = "La furia mora en las profundidades", summary = "Motley Garmason quiere que le lleves la cabeza de Kam Furiahonda a Dun Modr.", desc = "Has demostrado tu lealtad al rey Magni, <clase>. Y tu odio por la escoria Hierro Negro es tan grande como el mío.\n\nHay una tarea que me gustaría hacer por mí mismo, pero el honor me obliga a permanecer junto a Largatrenza. Roggo ha conseguido reunir datos que demuestran que Kam Furiahonda fue miembro de la conspiración para el ataque del Puente Thandol. Fueron los planes de Furiahonda los que hicieron perder a Largatrenza a toda su familia.\n\nFuriahonda está retenido, por razones políticas, en las Mazmorras de Ventormenta. Le quiero muerto, <nombre>. ¡Por Largatrenza! ¡Tráeme su cabeza!", objectives = { "Cabeza de Furiahonda" } },
    [386] = { title = "Lo que sucece alrededor…", summary = "Lleva la cabeza de Targor el Horror al guardia Berton a Villa del Lago.", desc = "Targorr el Pavoroso sirvió bajo las órdenes de Gath'llzogg como Ejecutor supremo. Sus métodos eran los más despiadados, incluso para los orcos. No dudó en torturar a hombres que habían servido lealmente en la defensa del Reino. Ahora se encuentra recluso en las Mazmorras de Ventormenta, a la espera de que se cumpla su sentencia de muerte. Aún así, hay algo que no encaja. Uno de los nobles burócratas ha detenido su ejecución. Estoy seguro de que se trata de una maniobra oscura.\n\nTienes que acabar con Targorr el Pavoroso, <nombre>. Viaja a las Mazmorras y decapítalo antes de que logre escapar a su destino.", objectives = { "Cabeza de Targorr" } },
    [387] = { title = "Detener el motín", summary = "El alcaide Thelagua de Ventormenta quiere que mates 10 prisioneros Defias, 8 presidiarios Defias y 8 insurgentes Defias en las Mazmorras.", desc = "¡Hay que detener el motín! Necesito tu ayuda. ¡Si alguien se entera de que la prisión es un caos perderé mi trabajo! Esto es juego sucio. Pero lo importante es obligar a los prisioneros a rendirse, por la seguridad de Ventormenta.\n\nEl castigo por sublevación es la muerte. Mata a alguno de esos desviados. Y verás cómo vuelven al buen camino...", objectives = { "Prisionero Defias x 10", "Presidiario Defias x 8", "Insurgente Defias x 8" } },
    [388] = { title = "El color de la sangre", summary = "Nikova Raskol, de Ventormenta, quiere que consigas 10 pañuelos de lana roja.", desc = "El resentimiento corre por mis venas como una corriente fría. Mi nieto, Mac, era un chico muy bueno. 14 años recién cumplidos. Cuando el ejército fue mandado al frente, Mac cogió las armas para defender la ciudad. Fue un guardia de las Mazmorras, donde está encerrada la banda Defias. Mac reprendió a algunos de los prisioneros por romper sus mantas de lana para hacer bufandas, un símbolo de la banda. Por hacerlo, recibió una puñalada en la espalda.\n\nQuiero venganza. Tráeme 10 de sus valiosos pañuelos de lana. Son del color de la sangre.", objectives = { "Pañuelo de lana roja x 10" } },
    [389] = { title = "Bazil Thredd", summary = "Habla con el alcaide Thelagua en las Mazmorras.", desc = "VanCleef y yo fuimos miembros de la Hermandad de los Albañiles. Nuestro primer proyecto después de la Guerra era reconstruir Ventormenta.\n\nCuando terminamos, nos estafaron. Los nobles se negaron a pagarnos. A algunos de los Albañiles mayores les ofrecieron trabajos gubernamentales, pero VanCleef y yo los rechazamos debido a nuestra lealtad con los Albañiles. Él lideró un motín y abandonó la ciudad, jurando venganza.\n\nEs posible que su teniente, Bazil Thredd, sepa más sobre los planes de VanCleef. Está prisionero en las Mazmorras." },
    [391] = { title = "El motín de las Mazmorras", summary = "Mata a Bazil Thredd y lleva su cabeza al alcaide Thelagua en las Mazmorras.", desc = "Dejemos esto claro, <nombre>. No confío en ti. Pero en estas circunstancias, tendré que pasarlo por alto.\n\nEsto es lo que vamos a hacer: baja ahí y habla con Thredd. Si realmente estás de nuestra parte, mátale y tráeme su cabeza como prueba. Si descubrimos que estás de su parte, cuando te encontremos... morirás junto con el resto de esos gusanos.", objectives = { "Cabeza de Bazil Thredd" } },
    [704] = { title = "El sino de Agmond", summary = "Llévale 4 urnas de piedra labrada al prospector Vetaferro en Loch Modan.", desc = "El último informe de Agmond es preocupante, ¡sobre todo ahora que ha muerto! Mencionaba que en sus excavaciones había desenterrado unas \"urnas antiguas\" en la explotación situada en las afueras de Uldaman. Me temo que las urnas que encontró instigaron a los troggs, igual que lo hicieron los ídolos que encontré aquí.\n\nNecesito que recuperes esas urnas para nuestros estudios. Ve a la excavación de Uldaman, encuentra las urnas y tráemelas aquí.", objectives = { "Urna de piedra grabada x 4" } },
    [707] = { title = "¡Vetaferro te necesita!", summary = "Habla con el prospector Vetaferro en su excavación de Loch Modan.", desc = "<nombre>, he recibido unos informes del prospector Vetaferro sobre la excavación de Loch Modan; dice que necesita a alguien que estudie otra excavación.\n<nombre>o dice nada más, pero si te apetece estirar las piernas, ve a hablar con Vetaferro." },
    [709] = { title = "La solución a la maldición", summary = "Llévale la tablilla de Ryun'eh a Theldurin el Perdido.", desc = "¡Ay, ay! ¡Ay, ay! Se acerca una catástrofe. ¡Recuerda mis palabras! ¡Una catástrofe!\n\nBNo, no puedo hablar de ello… no puedo pronunciar sus nombres, ¡podrían oírme! Pero si aprendemos de ellos... Sí, si aprendemos más... ¡quizás logremos frustrar sus planes!\n\nBQuizás.\n\nVe a Uldaman. ¡No! ¡Ya te lo dije! Tienes que encontrar... encontrar la tablilla de... Ryun’eh. ¡Sí, encuéntrala! ¡Y no me hagas pronunciar ese nombre otra vez!\n\nBSe encuentra en las profundidades de ese lugar, en un antiguo cofre. Ahí es donde se esconde... en un cofre creado antes del tiempo de los enanos.", objectives = { "Tablilla de Ryun'eh" } },
    [720] = { title = "Un signo de esperanza", summary = "Localiza al prospector Ryedol y dile que Grez Dedomaza está vivo.", desc = "<Hay texto garabateado de forma tosca con tiza en el mapa.>\n\n\"Ryedol,\nMe llevan a Uldaman. Envía ayuda.\n-Piemartillo\"" },
    [721] = { title = "Un signo de esperanza", summary = "Encuentra a Grez Dedomaza en Uldaman.", desc = "<nombre>, ¿puedes encontrarlo? ¿Puedes encontrar a Piemartillo en Uldaman?\n\nSi esos asquerosos Forjatiniebla l’han raptao pa’ sonsacarle lo que sabe de las excavaciones de los titanes, entonces todo Forjaz podría ‘star en gran peligro.\n\nDurante mucho tiempo esos Hierro Negro han buscao magia pa’ hacer golems más poderosos. Piemartillo ‘staba haciendo lo mismo, claro, pero pa’ detenerlos.\n\nProbablemente lo mantengan vivo hasta que s’enteren de lo que sabe. ¡‘spabila si quieres salvarlo!" },
    [722] = { title = "El amuleto de los secretos", summary = "Encuentra el amuleto de Piemartillo y llévaselo a Uldaman.", desc = "Eres valiente... <tose>... por venir a Uldaman pa’ mí, <clase>.\n\nSi realmente ‘stás aquí pa’ ayudar... al viejo Piemartillo, entonces... <tose>... tendrás qu’encontrar... mi amuleto.\n\nSombraprofunda lo tiene... Magregan Sombraprofunda. ‘stá por aquí... en las ruinas, seguro. Ese amuleto los conducirá... <tose>... derechito a los pergaminos si no lo paran. Depende de ti, <nombre>. Favor... recupera el amuleto.\n\nCon los pergaminos los Hierro Negro conseguirán crear golems aún más poderosos. Lo sé. Me lo dicen los huesos.", objectives = { "Amuleto de Piemartillo" } },
    [723] = { title = "Tener fe en el porvenir", summary = "Llévale el amuleto de Piemartillo al prospector Ryedol en las Tierras Inhóspitas.", desc = "<Piemartillo se sujeta las heridas y se toma un momento para recuperarse antes de seguir hablando.>\n\nEncuentra a Ryedol, <nombre>. Llévale mi amuleto. <Tose> Él… <tose> saber qué hacer. Sabe qu’estaba buscando los orígenes de nuestro pueblo, y él <tose> sabe que mi misión era detener al clan Forjatiniebla. Hay qu’impedir qu’encuentren esos pergaminos... <tose>" },
    [724] = { title = "Tener fe en el porvenir", summary = "Llévale el amuleto de Piemartillo a Karnik el Historiador en Forjaz.", desc = "Vale, vale... ¿quién sabrá qué hacer?\n\n¡El historiador Karnik! ¡Eso es!\n\nSe encuentra en Forjaz. Podrá ayudarnos. Él y Piemartillo estaban trabajando juntos para encontrar los artefactos en Uldaman.\n\nSupongo que los Forjatiniebla se enteraron de que los dos sabían más de lo dejaban ver.\n\nDile a Karnik lo que le ha ocurrido a Piemartillo y dale el amuleto, él te dirá qué hacer después." },
    [725] = { title = "Avertir de la amenaza", summary = "Encuentra al consejero Belgrum y dale su nota.", desc = "<nombre>, corre y encuentra al consejero Belgrum en cuanto puedas. Cuéntale lo que has presenciado y pregúntale qué quiere que hagamos a continuación. En esta nota encontrará más detalles.\n\nMientras tanto, dedicaré un tiempo a hablar con el espíritu de Piemartillo. A lo mejor sabe algo que nos ayudará a detener las actividades de esos cretinos Forjatiniebla en Tierras Inhóspitas. Solo nos queda rezar." },
    [726] = { title = "Avertir de la amenaza", summary = "Habla con Karnik el Historiador.", desc = "<El consejero Belgrum acaba de leer la nota, los ojos se le abren aún más por un momento.>\n\nVaya unas malas noticias.\n\n<nombre>, regresa con el historiador Karnik y dile que por la autoridad del rey actúe pronto y de forma contundente en base a esta información. Tiene que detener las actividades de los Forjatiniebla en Tierras Inhóspitas." },
    [738] = { title = "Encontrar a Agmond", summary = "Encuentra a Agmond.", desc = "El prospector Agmond estaba a cargo de nuestra excavación en las Tierras Inhóspitas, hacia el suroeste. Y digo \"estaba\" porque... bueno, hace semanas que no sé nada de él. Necesito que encuentres a Agmond para poder conseguir su informe.\n\nLa última vez que oímos algo de Agmond se encontraba en la más meridional de nuestras excavaciones en las Tierras Inhóspitas, una pequeña explotación más allá de la Fortaleza de Angor. Yo empezaría a buscarlo allí." },
    [739] = { title = "Murdaloc", summary = "Mata al asesino de Agmond, Murdaloc. Mata a 12 partehuesos Petracripta. Preséntate ante el prospector Vetaferro en Loch Modan.", desc = "La pista de Agmond arranca en el oeste. Es fácil saber por las manchas de sangre en las rocas y en la arena que el enano se arrastró cierta distancia.\n\nY murió aquí.\n\nTras una inspección más detenida, se descubre la palabra \"Murdaloc\" toscamente garabateada en un pedazo de arenisca de las Tierras Inhóspitas.\n\nGarabateada junto a la inerte mano de Agmond.", objectives = { "Murdaloc", "Partehuesos Grutacanto x 12" } },
    [762] = { title = "Un embajador de mal", summary = "Mata al embajador Infernus en la Fortaleza de Angor llévale la prueba de su muerte al consejero Belgrum en Forjaz.", desc = "El propio Ragnaros envió al embajador Infernus a la Fortaleza de Angor para controlar a los Forjatiniebla en su búsqueda de artefactos perdidos en Uldaman.\n\nHa supuesto ya gran número de bajas entre nuestra gente pero, a todas luces, ha empeorado. Dudo en adelantar una cifra respecto a cuántos artefactos habrán encontrado y usarán contra Forjaz.\n\nNuestro objetivo es sencillo, <clase>. Vuelve a Tierras Inhóspitas y destruye al embajador Infernus. Una vez eliminada la amenaza, vuelve con el consejero Belgrum con una prueba de tu victoria.\n\nAhora todo depende de ti.", objectives = { "Brazal del Embajador Infernus" } },
    [865] = { title = "Los cuernos de raptor", summary = "Recolecta 5 cuernos de raptor intactos de los segadores solescama y llévaselos a Mebok Mizzyrix en Trinquete.", desc = "Los raptores de Los Baldíos son más inteligentes que los de cualquier otro sitio, y creo que se debe precisamente a sus cuernos. Si es así, quizás podría moler algunos para fabricar \"bebidas de inteligencia\". ¡Podría amasar fortunas!\n\nAhí entras tú: busca cuernos intactos de raptores segadores solescama. Se encuentran por Los Baldíos del Sur y en la parte norte, cerca de la frontera con Vallefresno.", objectives = { "Cuerno de raptor intacto x 5" } },
    [870] = { title = "Las Charcas del Olvido", summary = "Informa a Tonga Runatótem con tus hallazgos. -", desc = "Antaño, Los Baldíos era un lugar exuberante, rebosante de vida. Pero la guerra y los cataclismos asolaron esa tierra, abrasándola y dejándola como una cáscara seca. Así son las cosas y siento gran pesadumbre en el corazón.\n\nPero en los últimos años, se han formado nuevos oasis en Los Baldíos y la vida vuelve a despertar. En lo más hondo, nosotros, los druidas, sentimos que se está filtrando una energía hacia la superficie.\n\nDebemos encontrar la fuente. Dirígete a Las Charcas del Olvido, al noroeste de El Cruce. Busca en sus aguas una fuente de energía y entonces vuelve aquí.", objectives = { "Busca en las aguas de Las Charcas del Olvido" } },
    [877] = { title = "El Oasis Estancado", summary = "Vuelve junto a Tonga en El Cruce después de investigar El Oasis Estancado.", desc = "Como la que encontraste en Las Charcas del Olvido, puede que haya más grietas en los otros oasis de Los Baldíos. En tal caso, a lo mejor tales grietas son la fuente de vida de los oasis.\n\nDebemos hacer una prueba.\n\nAquí tienes unas semillas. Están muertas y no son fértiles pero llévalas a El Oasis Estancado hacia el sureste. Si allí también hay una grieta, coloca las semillas en su interior… y observa..", objectives = { "Prueba las semillas secas", "Receta: sopa de tortuga reconfortante" } },
    [880] = { title = "Fuentes de vida", summary = "Llévale 8 caparazones de quijafortes alterados a Tonga Runatótem en El Cruce.", desc = "Tu descubrimiento es increíble, <nombre>. Estos oasis tienen unas propiedades que deben de proceder de una fuente exterior. O acaso de una interior.\n\nNecesito saber cómo afectan estas grietas a los animales que beben del agua de los oasis.\n\nCaza a unas tortugas quijafortes en el Oasis Aguaverde y en El Oasis Estancado. Tráeme sus caparazones para que pueda examinarlos.", objectives = { "Caparazón de quijaforte alterado x 8" } },
    [914] = { title = "Líderes del Colmillo", summary = "Lleva las gemas de Cobrahn, Anacondra, Pythas y Serpentis a Nara Bravacrín en Cima del Trueno.", desc = "Los druidas de las Cuevas de los Lamentos, los Druidas del colmillo, son una aberración. Fueron parte de una orden de nobles druidas que pretendían sanar Los Baldíos, pero ahora tan solo pretender cambiar esta tierra para amoldarla a sus propios y retorcidos sueños.\n\nLos Druidas del comillo tienen cuatro líderes, y cada uno de ellos posee una gema de sueño. ¡Sus rostros aún me siguen atormentando! Derrota a los líderes y tráeme sus gemas. Así Los Baldíos recuperarán la paz.\n\nVete, <nombre>. Los encontrarás escondidos en las profundidades de las Cuevas de los Lamentos.", objectives = { "Gema de Cobrah", "Gema de Anacondra", "Gema de Pythas", "Gema de Serpentis" } },
    [959] = { title = "¡A por la botella!", summary = "El operador de grúa Pelardo de Trinquete quiere que le consigas una botella de porto de 99 años de Magglish el Loco que se esconde en las Cuevas de los Lamentos.", desc = "¡Vaya!\n\n¡He tenido un pequeño percance, como puedes ver! El envío del carguero de la mañana de Bahía del Botín era enorme. ¡Lo que se dice enorme de verdad! Nunca había visto tantas cajas. Bueno, estaba intentando acelerar las cosas, así que empecé a descargar un poco más de lo que podía manejar. Y ahí es cuando todo se vino abajo.\n\nAntes de que me pudiera dar cuenta, vi que esa amenaza de Loco Magglish salía corriendo con una botella de porto de 99 años. Lo perseguí hasta las Cuevas de los Lamentos. Pero ni hablar de meterme en ellas.\n\n¿Eres suficientemente valiente para encontrarlo?", objectives = { "Puerto con 99 años de antigüedad" } },
    [962] = { title = "Repitilia", summary = "La boticaria Zamah de Cima del Trueno quiere que recojas 10 reptilias.", desc = "La Sociedad Real de Boticarios, establecida en la gran Entrañas de Lordaeron, me ha enviado aquí con un propósito muy concreto, <nombre>. Quizás quieras ayudarme a mí y, de paso, también a la Dama Oscura en nuestro intento de mejorar la forma física de los Renegados.\n\nÚltimamente he estado estudiando una extraña planta llamada reptilia y creo que en grandes cantidades tiene un gran potencial.\n\nLamentablemente, la reptilia solo se encuentra en los recesos más oscuros de las Cuevas de los Lamentos, un sistema de cuevas muy peligroso situado en Los Baldíos.", objectives = { "Reptilia x 10" } },
    [971] = { title = "El conocimiento de las profundidades", summary = "Lleva el manuscrito de Lorgalis a Gerrig Agarrahueso, que está en la Caverna Abandonada en Forjaz.", desc = "Como puede que ya sepas, recopilo conocimiento. Conocimiento antiguo. Conocimiento con poder. Conocimiento que abre puertas y puede despertar a los Durmientes.\n\nSe dice que un antiguo documento, el manuscrito de Lorgalis, se halla en las Cavernas Anegadas de Vallefresno. Allí vivieron unos elfos que murieron hace mucho. Acumularon mucha sabiduría antes de que su ciudad se arruinara.\n\nBusca el manuscrito en las Cavernas Anegadas. Nunca olvidaré este favor. Ni siquiera después del fin de los días.", objectives = { "Manuscrito de Lorgalis" } },
    [1013] = { title = "El Libro de Ur", summary = "Lleva el Libro de Ur al guardián Bel'dugur al Apothecarium de Entrañas.", desc = "<nombre>, en el Castillo de Colmillo Oscuro hay un libro que deseo para mi colección: el Libro de Ur. Ur era un gran mago de Dalaran antes de que llegara la Plaga; sus estudios sobre otros mundos son muy valiosos para... ciertas facciones entre los Renegados.\n\nVe al castillo y tráeme el libro. Informaré a la Dama Oscura de tus servicios...", objectives = { "El libro de Ur" } },
    [1014] = { title = "Arugal debe morir", summary = "Mata a Arugal y lleva su cabeza a Dalar Tejalba en El Sepulcro.", desc = "Arugal sigue viviendo en el Castillo de Colmillo Oscuro. No podemos reclamar Argénteos como bastión estratégico para la Dama Oscura hasta que no hayamos matado a Arugal.\n\nMe encargaré de erradicar su magia, <nombre>. Pero dejo en tus manos que Arugal se encuentre con la muerte que tanto merece.\n\nVe al Castillo de Colmillo Oscuro y pon fin de una vez por todas a los terribles hechizos de Arugal. ¡Tráeme la cabeza del malvado mago!", objectives = { "Cabeza de Arugal" } },
    [1048] = { title = "En el Monasterio Escarlata", summary = "Mata a la alta inquisidora Melenablanca, al comandante Escarlata Mograine, a Herod el campeón Escarlata y al domador de jaurías Loksey, y después ve a ver de nuevo a Varimathras a Entrañas.", desc = "Mientras la Dama Oscura se encarga de retener el avance del rey Exánime por el norte, yo me ocupo de los problemas que tienen lugar cerca de nuestro hogar.\n\nSin duda, los humanos que se hacen llamar la Cruzada Escarlata representan la mayor amenaza en nuestra zona. Los Claros de Tirisfal están atestados de estas pequeñas hormigas rojas.\n\nVe al Monasterio, <clase>, y acaba con la alta inquisidora Melenablanca y sus principales tenientes.", objectives = { "Alta Inquisidora Melenablanca", "Comandante Escarlata Mograine", "Herod", "Domador de jaurías Loksey" } },
    [1049] = { title = "El Compendio de los Caídos", summary = "Recupera el Compendio de los Caídos del Monasterio que se encuentra en los Claros de Tirisfal y regresa ante Sabio Buscaverdad, que está en Cima del Trueno.", desc = "Las intenciones del Anillo de la Tierra para con nuestros hermanos eran puras. ¿Pero quién sabe las motivaciones de los que confabulaban con el Consejo de los Ancianos?\n\nLa historia de los Renegados con los que nos aliamos está plagada de grandes engaños, de ahí que nuestro pacto con ellos haya sido breve. Quizás Cairne fue lo suficientemente inteligente para atender a las advertencias de Orgrimmar...\n\nEn lo más profundo del Monasterio Escarlata se encuentra el Compendio de los Caídos, custodiado por agresivos y fanáticos humanos. Su método proviene de la locura pero su trabajo de investigación puede resultar de utilidad.", objectives = { "Compendio de los Caídos" } },
    [1050] = { title = "Mitología de los Titanes", summary = "Coge Mitología de los Titanes en el monasterio y llévaselo a la bibliotecaria Mae Palipolvo a Forjaz.", desc = "¡El futuro es ineludible! Nos estrellamos contra él como las gotas de lluvia contra el Mare Magnum.\n\nPero quizás el estudio del pasado nos ayude a prepararnos mejor para lo desconocido.\n\nAntes de que la tragedia se abatiera sobre Lordaeron, existía un templo del saber oculto en los Claros de Tirisfal. Se dice que la biblioteca del antiguo Monasterio albergaba un libro llamado Mitología de los Titanes.\n\nSi me lo traes, puede que consigamos desvelar los secretos del pasado.", objectives = { "Mitología de los titanes" } },
    [1051] = { title = "La venganza de Vorrel", summary = "Lleva la alianza de Vorrel Sengutz a Monika Sengutz de Molino Tarren.", desc = "Aunque tengo libre albedrío, no puedo seguir sirviendo a la Dama Oscura. Siento que se acaba mi tiempo en Azeroth. Mi fuerza vital está mermada.\n\n¡Es culpa del interrogador Vishas! ¡Me torturó durante semanas! Me quitó la alianza y se la dio a su mujer. ¡Maldito!\n\nMe vengaré... ¡Juro que me vengaré!\n\nEse cretino pomposo anda presumiento de su mujer, Nancy, que vive junto al Lago Lordamere. Liquida a esa bruja y llévale la alianza a mi mujer, Monika, a Molino Tarren.\n\nCumple mi último deseo...", objectives = { "Alianza de Vorrel" } },
    [1052] = { title = "El sendero Escarlata", summary = "Lleva la carta de mención honorífica del hermano Antón a Raleigh el Devoto, en Costasur.", desc = "Nosotros, los de la Cruzada Escarlata, hemos reclamado las fortalezas desde la Vega del Amparo hasta los Claros de Tirisfal. Nos sentimos bastante orgullosos de haber conseguido nuestros bastiones en Lordaeron.\n\nHas demostrado estar en contra de los no-muertos en Desolace. Pero el corazón de la Plaga está en Lordaeron.\n\nVe a la ciudad de Costasur, en los Reinos del Este. Busca a un cruzado llamado Raleigh el Devoto. Dale esta carta de recomendación que lleva mi sello y te escoltará a un lugar de honor en nuestro Monasterio Escarlata." },
    [1053] = { title = "En el nombre de la Luz", summary = "Mata a la alta inquisidora Melenablanca, al Comandante Escarlata Mograine, a Herod, el Campeón Escarlata y al domador de jaurías Loksey. A continuación, preséntate ante Raleigh el Devoto, en Costasur.", desc = "Una vez serví a la Cruzada Escarlata con honor, lealtad y orgullo. Creí que su causa era noble: Librar Azeroth de los no-muertos.\n\nPero según pasé más y más tiempo en el Monasterio, en los Claros de Tirisfal, me di cuenta de que habían perdido la noción de la realidad. Ahora creen que todo aquel que no lleva el tabardo de la Cruzada, está infestado. Hombres y mujeres inocentes torturados porque, supuestamente, estaban infestados.\n\nHay que poner fin a la Cruzada Escarlata, en el nombre de la Luz. Tú, <nombre>, debes destruir al enloquecido régimen.", objectives = { "Alta Inquisidora Melenablanca", "Comandante Escarlata Mograine", "Herod", "Domador de jaurías Loksey" } },
    [1098] = { title = "Mortacechadores en Colmillo Oscuro", summary = "Encuentra a los mortacechadores Adamant y Vincent.", desc = "Estamos preparando un ataque a Colmillo Oscuro y enviamos a dos mortacechadores a investigar. De eso hace ya muchos días ¡y necesitamos su informe para preparar el ataque!\n\n<nombre>, tienes que ir al Castillo de Colmillo Oscuro, hacia el sur, y localizar a los mortacechadores Adamant y Vincent. Ayúdalos si lo necesitan.\n\nEsta misión es tan peligrosa como crítica, <nombre>. No falles." },
    [1100] = { title = "El diario de Henrig Soliceja", summary = "Lee el diario de Henrig Soliceja.", desc = "Abres lentamente el desgastado diario de Henrig Soliceja..." },
    [1101] = { title = "La bruja del Horado", summary = "Llévale el medallón de Filonavaja a Díscolo Falfildel de Thalanaar.", desc = "¡Pobre Heralath! Y el enano Soliceja, ¡qué valiente era!\n\nNo debemos permitir que su valentía caiga en el olvido. Hay que detener a esa malvada... Charlga Filonavaja.\n\nSin duda, infiltrarse en el Horado es arriesgado pero no hay tiempo para enviar noticias a Darnassus. <nombre>, reúne un equipo para matar a Charlga.\n\nTráeme el medallón de Filonavaja como prueba de su muerte.", objectives = { "Medallón de Filonavaja" } },
    [1102] = { title = "Un destino vengador", summary = "Llévale el corazón de Filonavaja a Auld Picopiedra, que está en Cima del Trueno.", desc = "Cairne es un líder noble que ha unido a nuestro pueblo aquí en Cima del Trueno.\n\nPero no puedo perdonar a aquellos que nos han echado de nuestras tierras ancestrales. Mi pueblo habitó en los Baldíos del Sur durante décadas, una tierra que era sagrada para nosotros, hasta que numerosos enemigos nos expulsaron de ellas.\n\nEl destino le depara venganza a Charlga Filonavaja, que tiene a un ejército congregado en Horado Rajacieno.\n\nTráeme el corazón de Filonavaja y podré morir en paz, <nombre>.", objectives = { "Corazón de Filonavaja" } },
    [1109] = { title = "Guano del Horado", summary = "Llévale una pila de guano del Horado al maestro boticario Faranell de Entrañas.", desc = "Como puedes comprobar, <nombre>, tenemos unos interesantes experimentos entre manos aquí en la Sociedad Real de Boticarios.\n\nDado que yo soy el maestro aquí, mi trabajo consiste en supervisar nuestros proyectos de alquimia más ambiciosos. ¡Hay tanto trabajo y tan poco tiempo!\n\nParece que tienes muchos kilómetros a tus espaldas, <clase>, así que quizás puedas ayudarnos.\n\nNecesito una sustancia no muy común y un tanto nauseabunda que proviene de una extraña especie de murciélagos que solo se encuentran en ese agujero apestoso conocido como Horado Rajacieno. Tráeme el guano de los murciélagos del Horado para que podamos ponernos manos a la obra.", objectives = { "Kraul Guano" } },
    [1113] = { title = "Corazones de fervor", summary = "El maestro boticario Faranell de Entrañas quiere 20 corazones de fervor.", desc = "Por qué necesito un tipo de guano tan poco común, te preguntarás. Bueno, para este experimento quiero ver el efecto que dos sustancias químicas diametralmente opuestas tienen entre sí, sobre todo cuando se combinan con un agente incluso más tóxico para obtener... los resultados más horripilantes.\n\nEn las cumbres más nororientales de los Claros de Tirisfal se encuentra el Monasterio Escarlata, lugar en el que se reúnen los fervientes discípulos de la Cruzada Escarlata. Mátalos a todos y tráeme sus corazones.\n\n¡Nuestro brebaje será de lo más vil!", objectives = { "Corazón de Zeal x 20" } },
    [1139] = { title = "Las tablillas perdidas de Voluntad", summary = "Encuentra la tablilla de Voluntad y llévasela al consejero Belgrum en Forjaz.", desc = "Hemos conseguido frenar al clan Forjatiniebla al aislarlos de la Cumbre de Roca Negra pero aún no hemos completado la misión de Piemartillo. Su muerte no debe ser en vano. Soñaba con encontrar la tablilla de Voluntad: un fragmento de piedra grabado con magia de los mismísimos titanes para ayudar a imbuir de vida a sus creaciones dándoles voluntad propia, o al menos eso cuenta la leyenda.\n\nDebemos recuperar la tablilla antes de que lo haga el clan Forjatiniebla.\n\nRegresa a Uldaman, encuentra la tablilla y vuelve aquí inmediatamente.", objectives = { "Tablilla de Voluntad" } },
    [1142] = { title = "Decaída mortal", summary = "Encuentra el colgante de Treshala Arroyobarbecho y llévaselo a Darnassus.", desc = "No voy a durar mucho... Estoy débil.\n\nEl valiente enano Cimahuraña ha ido a advertir a Falfindel...\n\nAntes de morir, quisiera...\n\nSe han llevado el colgante de vínculo de mi esposa, Treshala...\n\nEncuéntralo, por favor... Llévaselo a Treshala a Darnassus...\n\nY dile que he... muerto.", objectives = { "Colgante de Treshala" } },
    [1144] = { title = "Willix el Importador", summary = "Ayuda a Willix el Importador a salir de Horado Rajacieno.", desc = "¡Por fin llega ayuda!\n\nNo sabes cuánto hace que me tienen aquí. Ya ni recuerdo la última vez que estuve fuera.\n\nVerás, es que soy empresario, siempre ando olfateando negocios. Oí decir que Mebok Mizzyrix pagaba bien el tubérculo hojarroja para su porqueriza, y me pareció un negocio redondo y fácil. Como puedes ver, ¡calculé mal!\n\nPero si me ayudas a salir de aquí, te recompensaré.", objectives = { "Ayuda a Willix el Importador a salir de Horado Rajacieno." } },
    [1149] = { title = "Prueba de fe", summary = "Si tienes fe, salta desde las tablas que dominan Las Mil Agujas.", desc = "¿Me has estado buscando o quizás ha sido el destino el que te ha traído a mí? No tiene importancia... Ahora estás aquí y tu viaje encontrará un nuevo punto de partida.\n\nSon muchas las facetas que conforman un ser, tanto su espíritu como su cuerpo y su mente. Algunas de ellas son mensurables por las tradiciones de una cultura. Otras, sin embargo, solo podemos esperar que encuentren un lugar dentro de nosotros. Si no te opones, pondré a prueba algunas de tus facetas.\n\nSi superas las pruebas, te harás más fuerte. De lo contrario, descubrirás la inmensidad del Vacío Abisal.\n\nLa primera es una prueba de fe.", objectives = { "La Caldera" } },
    [1150] = { title = "Prueba de resistencia", summary = "Llévale la garra de Grenka a Dorn Acechaprados, que está en Las Mil Agujas.", desc = "Me complace comprobar que tu valor permanece inquebrantable después de lo que acabas de hacer. Dado que tu fe está intacta, ha llegado el momento de poner a prueba tu cuerpo.\n\nEn primer lugar, harás una prueba de resistencia. Ve con algunos amigos a Guarida Malapluma al oeste del Poblado Viento Libre. Consigue llegar hasta las profundidades de su guarida y destruye sus alimentos. Con eso provocarás su ira. Si eres capaz de aguantar con vida el tiempo suficiente, la propia Grenka Aullasangre irá a por ti. Acaba con ella y tráeme su garra para superar tu prueba.", objectives = { "Garra de Grenka", "Costillar de carne" } },
    [1151] = { title = "Prueba de fuerza", summary = "Llévale fragmentos de Rok'Alim a Dorn Acechaprados, que está en Las Mil Agujas.", desc = "En los tiempos de los dioses antiguos, los elementales ocupaban la mayor parte de este mundo. Ellos veneraban a los dioses antiguos y estos, haciendo uso de su poder, relegaron a los elementales a este mundo. Cuando los dioses antiguos desaparecieron, los elementales se desvanecieron de nuestro mundo y ahora solamente regresan cuando los poderosos magos requieren su presencia.\n\nAun así, hay algunas excepciones. Algunos elementales eran más poderosos y consiguieron permanecer aquí por su cuenta. Uno de ellos es Rok'Alim.\n\nPara poner a prueba tu fuerza, encuentra a Rok'Alim en Las Mil Agujas y acaba con él.", objectives = { "Fragmentos de Rok'Alim" } },
    [1152] = { title = "Prueba de conocimiento", summary = "Encuentra a Braug Espiritoscuro cerca de la entrada de El Paso del Espolón en Sierra Espolón.", desc = "Tu tiempo conmigo está llegando a su fin. Tengo una amplia cultura mas la prueba de conocimiento no seré yo quien te la haga. Hay lecciones que aprender y lugares que visitar que corresponden a otros.\n\nSi estás <preparado/preparada>, busca a Braug Espiritoscuro, un chamán muy sabio. Él continuará poniéndote a prueba, así que sigue sus indicaciones.\n\nCuando lo desees, busca el túnel que comunica Sierra Espolón con Vallefresno pues Braug anda por esa zona. Y ten cuidado, <nombre>, a los elfos de la noche les encantaría impedir que acabaras tus pruebas." },
    [1154] = { title = "Prueba de conocimiento", summary = "Encuentra el Legado de los Aspectos y devuélveselo a Braug Espiritoscuro que se encuentra cerca de la entrada de El Paso del Espolón en Sierra Espolón.", desc = "Has superado con éxito las pruebas de Dorn y sé que quieres hacer lo mismo con la siguiente. Muy bien, pero ten en cuenta que hasta el momento las pruebas han sido demasiado sencillas. Es fácil poner a prueba el cuerpo... pero la mente es un tema aparte.\n\nTe lo explicaré bien para que lo entiendas: encuentra el libro que yo te diga, estúdiatelo bien y responde la pregunta que te haga acerca de su contenido.\n\nQué libro, te estarás preguntando... El Legado de los Aspectos. Lo encontrarás en la parte baja de Dor'danil, en el sur de Vallefresno, bajo la protección de los druidas muertos y sus asesinos.", objectives = { "Legado de los Aspectos" } },
    [1159] = { title = "Prueba de conocimiento", summary = "Encuentra a Parqual Fintallas en Entrañas.", desc = "Bien hecho, <nombre>. Has superado la primera parte de la prueba de conocimiento pero aún hay otra pregunta que debes responder. Sin embargo, no seré yo quien te la haga.\n\nBusca a Parqual Fintallas en la ciudad de Lordaeron. Él era un gran historiador al servicio de los humanos antes de que la Plaga lo sorprendiera. Ahora sigue persiguiendo el conocimiento, pero de un modo distinto.\n\nAntes de formularte ninguna pregunta, te asignará otro encargo. Lo has hecho tan bien hasta el momento que no tengo ninguna duda de que superarás este obstáculo sin problemas." },
    [1160] = { title = "Prueba de conocimiento", summary = "Encuentra la Guía básica para no-muertos y devuélvesela a Parqual Fintallas, que está en Entrañas.", desc = "Te diré lo que tienes que buscar, e incluso te formularé mi pregunta, pero no porque desees ponerte a prueba. El conocimiento va más allá de la fuerza física. Aunque otros puedan superarte en habilidad, el conocimiento del mundo te dará ventaja.\n\nDirígete al monasterio que está al norte de los Claros de Tirisfal. En la biblioteca que encontrarás allí, verás un libro titulado Guía básica para no-muertos. Lo utilizaban los ahora corruptos paladines de allí para instruir a los no-muertos para luchar contra los de mi especie.\n\nTráemelo.", objectives = { "Comienzos de la amenaza de los no-muertos" } },
    [1198] = { title = "Buscando a Thaelrid", summary = "Busca al guardia Argenta Thaelrid en las Cavernas de Brazanegra.", desc = "Estos últimos días circulan muchos rumores sobre la reunión del Azote del Ocaso y los nagas en las Cavernas Anegadas de las costas de Vallefresno.\n\nEstoy aquí para reunir toda la información que pueda para el Alba Argenta, para que sepamos dónde y cuándo necesitaremos ayuda.\n\nHace unas semanas envié a un explorador para observar la actividad de las Cavernas Anegadas... Pero Thaelrid, mi guardia Argenta, aún no ha regresado.\n\nMis otros exploradores están ocupados con asuntos más urgentes.\n\nBusca a Thaelrid por mí, <nombre>." },
    [1199] = { title = "Cascada del Crepúsculo", summary = "Lleva 10 colgantes del Azote al guardia Argenta Manados a Darnassus.", desc = "Con el poder que les confieren los ritos de los caóticos dioses antiguos, los miembros del Azote del Ocaso trabajan para devolver a sus oscuros Señores a este mundo y así extender la muerte y el terror por él.\n\nCreemos que el Azote del Ocaso se ha aliado con los nagas . Se están concentrando en las Cavernas Anegadas de la costa de Vallefresno.\n\nDebemos frustrar los planes que se forjan en las profundidades del viejo santuario, sean cuales sean.\n\nEnfréntate al Azote y tráenos pruebas de tus hazañas. Tus esfuerzos serán ampliamente recompensados.", objectives = { "Colgante del Crepúsculo x 10" } },
    [1200] = { title = "La vileza de Brazanegra", summary = "Llévale la cabeza del Señor Crepuscular Kelris a Selgorm Guardalbas en Darnassus.", desc = "Las fuerzas me han abandonado. ¡Necesito tu ayuda!\n\nOtrora este lugar era un gran templo de Elune. Pero la desgracia lo ha llevado a la ruina cuando la corrupción de un dios antiguo empezó a calar desde el subsuelo y contaminó la sagrada Poza de la Luna.\n\nAku'Mai, sirviente del dios antiguo, surgió de las aguas.\n\nLos adeptos del Azote del Ocaso se han unido a los nagas para ocupar esas tierras. Esos adeptos, cuyo jefe es Kelris, sacrifican a inocentes a Aku'Mai a cambio de poder.\n\nMata a Kelris y llévale su cabeza a Selgorm en Darnassus, <nombre>, te lo ruego.", objectives = { "Cabeza de Kelris" } },
    [1221] = { title = "Los tubérculos hojazul", summary = "Coge un cajón agujereado. Coge una vara de mando de Husmeador. Lee el manual del propietario del Husmeador. Cuando llegues a Horado Rajacieno, usa el cajón agujereado para invocar un husmeador taltuza; usa la vara para que busque tubérculos. Lleva 6 tubérculos hojazul, la vara de mando de Husmeador y el cajón agujereado a Mebok Mizzyrix a Trinquete.", desc = "Los tubérculos hojazul son muy apreciados en todo el mundo. Pero son muy raros. Solo se encuentran aquí, en Los Baldíos, enterrados profundamente en Horado Rajacieno.\n\n¡Y es imposible encontrarlos a no ser que sepas dónde mirar! Por eso he amaestrado husmeadores taltuza para que los busquen. Tienen un olfato extraordinario, huelen los tubérculos a una distancia de 50 pasos.\n\nNo será fácil, pero si me traes tubérculos te pagaré muy bien.", objectives = { "Tubérculo hojazul x 6", "Cajón con agujeros", "Manual de propietario del Husmeador", "Vara de mando de Husmeador" } },
    [1275] = { title = "Investigaciones acerca de la corrupción", summary = "Gershala Susurro Nocturno en Auberdine quiere 8 bulbos raquídeos corruptos.", desc = "Los tontos elfos de sangre intentan dominar la magia demoníaca. ¿Acaso no fueron testigos de lo que les sucedió a los nagas y a los sátiros de Kalimdor?\n\nTemo que los elfos de sangre sufran una deformación similar. Azeroth no está lista para soportar el nacimiento de otra raza de monstruos malignos.\n\nQuiero estudiar los bulbos raquídeos de los sátiros y los nagas para intentar deducir qué destino les espera a los elfos. En las Cavernas de Brazanegra, en la costa de Vallefresno, encontrarás tanto sátiros como nagas.\n\nEs un largo viaje, <nombre>.", objectives = { "Bulbo raquídeo corrupto x 8" } },
    [1360] = { title = "Los tesoros reclamados", summary = "Recoge la posesión más preciada de Krom Brazorrecio de su cofre, que está en la Sala Comunal Norte de Uldaman, y llévasela a Forjaz.", desc = "Tenía un trabajo estupendo en la excavación de Uldaman en las Tierras Inhóspitas; todo iba bien hasta que aparecieron los malditos trogg. Escapé por los pelos y con lo puesto. Me dejé mi posesión más preciada. Está en mi cofre, a salvo de los trogg, pero claro, está allí.\n\n¡Te agradecería mucho que me lo trajeras! Está al fondo de la Sala Comunal Norte; tiene mi nombre. Anda, ve.", objectives = { "Tesoro de Krom Brazorrecio" } },
    [1424] = { title = "Charca de Lágrimas", summary = "Fel'zerul, en Rocal, quiere que consigas 10 artefactos Atal'ai.", desc = "El Jefe de Guerra nos envió a investigar los extraños sucesos que están ocurriendo en El Templo de Atal'Hakkar.\n\nLos trols Atal'ai son una tribu de magos oscuros, famosos por practicar la magia prohibida. Te puedes imaginar lo sorprendidos que nos quedamos cuando llegamos y descubrimos que el templo estaba sumergido.\n\nAhora, los dragones verdes protegen el lugar, erigiéndose como protectores de Azeroth.\n\nNecesitamos descubrir qué ha pasado. Explora la Charca de Lágrimas y consigue artefactos Atal'ai. Con eso, podré empezar a unir las piezas del puzzle.", objectives = { "Artefacto Atal'ai x 10" } },
    [1429] = { title = "El exiliado Atal'ai", summary = "Lleva los artefactos Atal'ai al exiliado Atal'ai en las Tierras del Interior.", desc = "Mientras te enfrentabas a los peligros de la Charca de Lágrimas, uno de mis exploradores encontró un pergamino hecho de carne seca y escrito con sangre. Parece ser una sentencia judicial contra un sacerdote de la tribu Atal'ai.\n\nEste sacerdote fue condenado a un destino considerado como mucho peor que la muerte entre los Atal'ai.\n\nFue exiliado al norte de las Tierras del Interior, con los trols Secacorteza.\n\nGuardaré estos artefactos. Tienes que encontrar al exiliado y descubrir para qué se usan. Regresa cuando hayas completado tu viaje." },
    [1444] = { title = "Vuelve con Fel'Zerul", summary = "Vuelve a ver a Fel'Zerul en Rocal.", desc = "Jammal'an el Profeta me condenó al exilio del Templo de Atal'Hakkar. Antiguamente creía que el sumo sacerdote era un buen líder.\n\nSu implacable fe en su profecía llevará a la destrucción de los Atal'ai. Si es que todavía no lo ha hecho.\n\nCuando hablé sobre mis preocupaciones, fui considerado un infiel y me expulsaron del Templo.\n\nEsos artefactos que me has traído son inofensivos. Pero si Jammal'an ha descubierto el encantamiento fetiche correcto para el ritual de invocación, el mundo corre un grave peligro..." },
    [1445] = { title = "El Templo de Atal'Hakkar", summary = "Reúne 20 fetiches de Hakkar y llévaselos a Fel'Zerul en Rocal.", desc = "¿Así que habló de la profecía de Jammal'an?\n\nEl líder espiritual de los Atal'ai cree que cuando Hakkar vuelva a Azeroth desde el Vacío Abismal, el dios concederá la inmortalidad a la tribu Atal'ai.\n\nArtimañas estúpidas para conseguir una muerte temprana, si me lo preguntas.\n\n¿Pero dices que el exiliado habló sobre unos fetiches encantados? Eso me preocupa. Si esos fetiches son, realmente, la llave del ritual Atal'ai que ha causado todo este caos, debemos comprender los poderes intrínsecos.\n\nVete al Templo y consigue los fetiches.", objectives = { "Fetiche de Hakkar x 20" } },
    [1446] = { title = "El profeta Jammal'an", summary = "El exiliado de Atal'ai, en las Tierras del Interior, quiere la cabeza de Jammal'an.", desc = "A mis compañeros Secacorteza no les gustan los extraños errantes.\n\n¿Yo? Yo ya no tengo hogar. Vivo en el exilio, lejos de mi gente, los Atal'ai del Pantano de las Penas.\n\nNuestro líder espiritual, Jammal'an, tuvo lo que él llama una visión. Cree que invocar al dios Hakkar traerá la inmortalidad a los Atal'ai.\n\nPero yo pedí prudencia. ¿Y si la visión no es más que manipulación?\n\nQuiero vengarme por estar en el exilio. Tráeme la cabeza de Jammal'an. A lo mejor así mi gente podrá ser libre.", objectives = { "Cabeza de Jammal'an" } },
    [1448] = { title = "En búsqueda del templo", summary = "Brohann Barriliga, en Ventormenta, quiere que busques el Templo de Atal'Hakkar.", desc = "Hace tiempo, yo era joven y rebosaba vigor como tú, <clase>.\n\nPero ahora soy mayor e incapaz de explorar el mundo como hice antaño. ¡Ah, las cosas que vi!\n\nPero un misterio me eludió siempre. En mi última misión, la Liga de Exploradores me envió a buscar El Templo de Atal'Hakkar. Se decía que estaba situado en el Pantano de las Penas.\n\nDebido a mi delicado estado, viajé surcando los cielos sobre un grifo buscándolo, pero no conseguí encontrarlo.\n\n¿Ayudarías a un viejo enano? Quizás tengas más suerte que yo si vas a pie.", objectives = { "Cerrotajo", "Busca El Templo de Atal'Hakkar" } },
    [1449] = { title = "A las Tierras del Interior", summary = "Habla con el Gran señor feudal Falstad Martillo Salvaje en el Pico Nidal, en las Tierras del Interior.", desc = "Como mencioné antes, intenté buscar el templo desde el aire. Aunque no estaba exactamente solo.\n\nFui a la famosa pajarera de grifos en Pico Nidal, en las Tierras del Interior. Allí recluté a uno de sus mejores pilotos. El piloto se cayó de la montura, al pantano...\n\nA mis años, no soy capaz de recordar el nombre del pobre piloto. Pero, sin duda, el maestro de la pajarera se acordará.\n\nVe allí y busca a Falstad Martillo Salvaje.\n\nTenemos que saber lo que le ocurrió a ese piloto." },
    [1450] = { title = "Maestro de grifos Garracha", summary = "Habla con el maestro de grifos Garracha dentro de la pajarera del Pico Nidal.", desc = "¿Así que eres $gel chico:la chica de los recados de algún vejete de la Liga de Exploradores, eh?\n\nBueno, pues escúchame bien. No sé con quién volaba por Azeroth tu viejo amigo. ¿Acaso te parezco el maestro de grifos Garracha? ¿Eh?\n\nSi tanto te interesan las asignaciones de vuelo, ¿por qué no le preguntas al maestro de grifos? Si te pillo haciendo el vago por aquí mucho más tiempo, voy a ponerte a trabajar.\n\nY ahora, lárgate." },
    [1451] = { title = "Rapsodio Machacacanillas", summary = "Busca a Rapsodio Machacacanillas en las Tierras del Interior.", desc = "Rapsodio empezó a darle bastante al alcohol. No me malinterpretes, a nosotros, los enanos que estamos en la pajarera, nos encanta una buena cerveza de vez en cuando.\n\nPero al viejo Machacacanillas empezó a gustarle tanto la bebida como a un grifo le gusta el cielo. Y fue una pena. Nadie podía volar como Rapsodio.\n\nEl primer signo de problemas, fue cuando volvió dando tumbos de esa misión con tu amigo, Brohann. Y, después de eso, todo fue cuesta abajo. Tuve que dejarle marchar.\n\nLa última vez que supe de él, había establecido una fábrica de cerveza al este de aquí..." },
    [1452] = { title = "El cubata de Kalimdor de Rapsodio", summary = "Rapsodio Machacacanillas, en las Tierras del Interior, quiere que le lleves 3 mollejas de Roc, 3 hígados de Groddoc y 3 hígados de piel pétrea.", desc = "¡Hip!\n\n¿Así que te ha mandao ese loco de Brohann? Pedazo de aventura que tuvimos... ¡Hip!\n\nSi quieres que te cuente lo que pasó allí en el pantano, voy a necesitar beber algo fuerte. No fue nada bonito, ¿sabes? ¡Hip!\n\nMira... Tráeme lo que necesito pa hacer un cubata de Kalimdor y te lo contaré.\n\nVoy a necesitar mollejas de Roc de Tanaris y... veamos... algunos Groddocs e hígados de piel pétrea de Feralas...\n\nUn buen cubata de Kalimdor... ¡Con eso hablaré!", objectives = { "Mollejas de Roc x 3", "Hígado de Cueracero x 3", "Hígado Groddoc x 3" } },
    [1469] = { title = "El relato de Rapsodio", summary = "Lleva el fragmento de la tablilla Atal'ai a Brohann Barriliga, en Ventormenta.", desc = "Antes del vuelo, me bebí un barril entero de cerveza negra. ¡Hip!\n\n¡Y menudo pedazo de vuelo! De un lao pa otro con Brohann siguiéndome. Aunque no vimos ni un templo. ¡Hip!\n\nBueno, yo no vi ni un templo hasta que me puse un poco achispao y me caí de la montura. Caí justo en el agua y me arrastró pa’bajo. Me encontré rodeao de un montón de trols muy feos. ¡Salí de allí pitando! Incluso conseguí escapar con este souvenir trol. Toma, llévaselo a Brohann y dile que su templo tá ahí abajo. ¡Hip!" },
    [1475] = { title = "En El Templo de Atal'Hakkar", summary = "Consigue 10 tablillas de Atal'ai para Brohann Barriliga, en Ventormenta.", desc = "Según la leyenda, El Templo de Atal'Hakkar es un santuario sagrado dedicado al dios ancestral, Hakkar el Cazador de Almas. Está protegido por una tribu viciosa de trols, los Atal'ai, y se rumorea que el templo es impenetrable.\n\nAhora está hundido en la Charca de Lágrimas, con lo que sacar artefactos del templo es mucho más difícil. Pero eso es lo que necesito que hagas, <nombre>.\n\nAyúdame, tráeme las tablillas de Atal'ai intactas. Tráemelas y podré volver con los Exploradores convertido en un héroe. Juntos compartiremos la gloria.", objectives = { "Tablilla Atal'ai x 10" } },
    [1486] = { title = "Pellejo de los descarriados", summary = "Nalpak de las Cuevas de los Lamentos quiere 20 cueros descarriados.", desc = "Cuando Naralex se hundió en su pesadilla, una extraña raza de bestias salió de debajo de Los Baldíos y se adentró en las Cuevas de los Lamentos.\n\nEstas criaturas descarriadas tienen propiedades extrañas y como de otro mundo. Aunque su naturaleza es malvada, creo que puede venir algo bueno de su presencia aquí en Kalimdor. Creo que sus pieles serán especialmente útiles para la peletería.\n\nSi crees que estás <preparado/preparada> para emprender esta tarea, aventúrate en las cuevas y hazte con algunos cueros descarriados.", objectives = { "Pellejo descarriado x 20" } },
    [1487] = { title = "Erradicación de descarriados", summary = "Ebru de las Cuevas de los Lamentos quiere que mates 7 devastadores descarriados, 7 víboras descarriadas, 7 arrastrados descarriados y 7 colminfernos descarriados.", desc = "Naralex tiene un fin muy noble.\n\nNuestro gran líder aspiraba a entrar en el Sueño Esmeralda y a ayudar a que estas duras tierras volvieran a convertirse en el exuberante bosque que fueron un día. Pero algo fue terriblemente mal.\n\nEl sueño de Naralex se convirtió en pesadilla y criaturas corruptas comenzaron a habitar las cavernas.\n\nMientras algunos discípulos de Naralex se esfuerzan por despertar a nuestro maestro, yo me ocupo de librar a las cuevas de esas malvadas bestias.\n\nAventúrate a las cavernas, <nombre>, y erradica esa prole descarriada.", objectives = { "Devastador descarriado x 7", "Víbora descarriada x 7", "Arrastrado descarriado x 7", "Colminferno descarriado x 7" } },
    [1489] = { title = "Hamuul Runatótem", summary = "Habla con Hamuul Runatótem.", desc = "Los caparazones que me has traído están contaminados, nunca había visto algo así. Estoy seguro de que el agua de los oasis es la causa, y puedo sentir la confusión que causan en esta tierra. Es como si la tierra soñara y no pudiera despertar.\n\nLas Cuevas de los Lamentos deben de ser la fuente de la contaminación. Pero antes de ir allí habla con Hamuul Runatótem, el druida anciano. Ya le hice saber lo que está ocurriendo en Los Baldíos. Es sabio y podrá ofrecerte consejo.\n\nLo encontrarás en Cima del Trueno, en el Alto de los Ancestros." },
    [1490] = { title = "Nara Bravacrín", summary = "Habla con Nara Bravacrín.", desc = "Entré en el país de los sueños, y soñé con un culto de druidas que habitaba en las Cuevas de los Lamentos. Vi que sus fines fueron nobles, pero se echaron a perder. Ahora sirven a la corrupción que se está filtrando por Los Baldíos.\n\nSoy viejo y mi fuerza se desvanece. No puedo morar mucho tiempo en el país de los sueños y sé muy poco sobre los druidas corruptos. Pero Nara es joven y su espíritu implacable. Ella permaneció sumergida en la ensoñación cuando yo tuve que huir.\n\nHabla con Nara. La encontrarás en la tienda, ahí mismo." },
    [1491] = { title = "Las bebidas astutas", summary = "Llévale 6 unidades de esencia de lamentos a Mebok Mizzyrix en Trinquete", desc = "Bueno, sí, los cuernos de raptor no funcionaron muy bien. Pero no importa, ¡nadie se hace rico a la primera! Y además, creo que he encontrado algo ¡que funcionará aún mejor que mis bebidas astutas!\n\nHay una sustancia llamada esencia de lamentos y creo que es la causa de la extraña fauna y flora de Los Baldíos. ¡Consígueme algo de esa esencia y la probaré en mi nueva bebida!\n\nHe oído que se concentra en las criaturas ectoplásmicas de las Cuevas de los Lamentos hacia el oeste. Caza a esas criaturas y recolecta la esencia.", objectives = { "Esencia de lamentos x 6" } },
    [1649] = { title = "Libro del valor", summary = "Habla con Duthorian Rall en Ventormenta.", desc = "El valor y todas las virtudes que lo acompañan, son como minerales preciosos y poco comunes: debes apreciarlos cuando los encuentras porque son valiosos, pero también debes invertir tiempo en cuidarlos... refinarlos. Cuando se mezclan correctamente, se forma una fuerte aleación que, algunas veces, resulta imposible de romper, incluso con los golpes más poderosos.\n\nTodo esto debe ser puesto a prueba: la fuerza, tu fe, tu valentía. Debes aprender al no perder la fe y darte cuenta de que con el poder de la Luz, puedes conseguir cosas que otros no pueden." },
    [1650] = { title = "Libro del valor", summary = "Encuentra a Daphne Fontana en Páramos del Poniente.", desc = "¡Bien! Que no vaciles es una señal inequívoca de que estás <preparado/preparada> y <dispuesto/dispuesta> a ponerte a prueba. Que así sea.\n\nJusto al final de Longavera, en Páramos de Poniente, hay una pequeña casa con vistas al océano. Allí vive una pareja, los Fontana. Jordan es un herrero fabuloso y ha ido a Forjaz a pasar una temporada con los enanos. Pero esto ha dejado a Daphne, su mujer, sola y desprotegida.\n\nLos informes sugieren que los Defias han tomado casi toda la zona, es posible que Daphne necesite protección. Ve allí." },
    [1651] = { title = "Libro del valor", summary = "Defiende a Daphne Fontana del ataque de los Defias. Si quieres tener éxito, vuestros espíritus no pueden salir de sus espirales mortales. Cuando lo hayas conseguido, vuelve a hablar con Daphne Fontana.", desc = "Apuesto a que volverán pronto, así que debes prepararte.\n\nTengo una pistola en la casa. La cogeré y me prepararé para ayudarte pero, en general, estarás <solo/sola>.\n\nNo tengo ni idea de cuántos mandarán, pero seguro que serán más de los que mandaron antes.\n\nRuega a la Luz que nos bendiga porque... ¿Has oído eso? Creo que vienen ya.\n\n¡Nos colocaremos cerca de la casa!", objectives = { "Protege a Daphne Fontana" } },
    [1652] = { title = "Libro del valor", summary = "Habla con Duthorian Rall en Ventormenta.", desc = "Por favor, vuelve a ver a Duthorian y dile que, por ahora, estoy a salvo. Y todo gracias a ti y a la iglesia.\n\nÉl enviará el mensaje a Forjaz para que mi querido Jordan sepa que no tiene nada que temer.\n\n¡Oh, cómo echo de menos a mi marido! Qué ganas tengo de que vuelva." },
    [1653] = { title = "La prueba de rectitud", summary = "Habla con Jordan Fontana en Forjaz.", desc = "No dudo que Jordan desea darte las gracias personalmente, y puesto que debo enviarle mensaje de que su esposa está bien, creo que eres la mejor elección.\n\nJordan iba a ser paladín de la Luz hasta que su dedicación al arte de su padre lo llevó por otros derroteros; conoce bien nuestro modo de vida y lo consideramos uno de nuestros más devotos.\n\nEstará en Forjaz; le gusta trabajar en el exterior por algo relacionado con el aire fresco." },
    [1654] = { title = "La prueba de rectitud", summary = "Consulta la lista y llévale a Jordan Fontana de Forjaz lo siquiente: madera de roble de Piedrablanca, envío de oro refinado de Bailor, el martillo de herrero de Jordan y una gema Kor.", desc = "Si aceptas, te recompensaré. Entiéndeme bien, mi generosidad depende de hasta qué punto me ayudes, pero creo que una alianza nos sería beneficiosa.\n\nTe haré un arma digna de tus logros, un símbolo de los paladines y de la Luz, pero tienes que traerme los objetos que necesito para crearla. Tengo aquí la lista; solo necesito a alguien valiente que vaya a buscar los objetos. ¿Qué me dices, <clase>?", objectives = { "Madera de roble de Piedrablanca", "Envío de mineral refinado de Jordan", "Martillo de herrería de Jordan", "Gema kor purificada" } },
    [1740] = { title = "El orbe de Soran'ruk", summary = "Encuentra 3 fragmentos de Soran'ruk y 1 fragmento grande de Soran'ruk y llévaselos a Doan Karhan en Los Baldíos.", desc = "Cuando los demonios de la Legión caen en desgracia, sus espíritus quedan presos en unos orbes que se distribuyen entre sus magos y brujos.\n\nMuchos fueron llevados por sus sirvientes en Azeroth. Incluso rotos en fragmentos, poseen poderes de los demonios en ellos presos.\n\nEl orbe de Soran'ruk se partió en dos piezas, una de las cuales se rompió en pedazos aún más pequeños para los acólitos del Azote del Ocaso de las Cavernas Anegadas. La otra, la de mayor tamaño, acabó en manos de un mago del Castillo de Colmillo Oscuro. Encuéntralas y podré reconstituirlo.", objectives = { "Fragmento Soran'ruk x 3", "Fragmento de Soran'ruk grande" } },
    [1947] = { title = "Viaje al pantano", summary = "Habla con Tabetha.", desc = "Ha llegado el momento de que obtengas tu varita de mago. Para comenzar esta búsqueda habla con Tabetha, una ermitaña humana que habita en el Marjal Revolcafango. Encontrarás su choza en las profundidades del marjal, al oeste de Theramore.\n\nHabla con ella, su saber es enorme. Encontrarás su casucha al oeste de Theramore y al norte de las Ruinas Quebrantarrocas." },
    [1949] = { title = "Secretos escondidos", summary = "Habla con Magus Tirth en El Desierto de Sal.", desc = "Para hacer tu varita, necesito leer unos pasajes clave de un libro determinado. El libro se llama Rituales de poder, y fue escrito por Magus Tirth.\n\nNo tengo ninguna copia del libro y ninguna de las grandes bibliotecas del mundo lo tiene. Debes hablar con Tirth y conseguir que te lo dé.\n\nBuena suerte. Tirth era un gran mago y erudito, pero ahora se pasa el día en las carreras de los goblins y de los gnomos en El Desierto de Sal, bebiendo y haciendo apuestas." },
    [1950] = { title = "Santo y seña", summary = "Averigua la frase para la caja fuerte de Tirth y regresa con Tirth.", desc = "¡Puedo ayudarte con el libro, pero antes tienes que ayudarme!\n\nEl tomo que buscas está en mi caja fuerte cerrada mágicamente. Para abrirla hay que pronunciar una determinada frase, ¡y no puedo recordarla! Normalmente mi asistente me ayuda a recordar esas cosas, pero no hay forma de encontrarlo.\n\nSi quieres mi libro debes encontrar a mi aprendiz. Pregunta por la pista de carreras, si tienes suerte lo habrá visto alguien. ¡Tráelo de vuelta aquí o consigue que te diga mi frase mágica para poder abrir la caja!", objectives = { "Frase secreta encontrada" } },
    [1951] = { title = "Rituales de poder", summary = "Lleva el libro Rituales de poder a Tabetha en el Marjal Revolcafango.", desc = "Umm... ahora que lo pienso... ¡no tengo el libro! Verás, tenía algunas deudas de juego y para pagarlas vendí la última copia de Rituales de poder a un miembro del clero...\n\nUn miembro de la Hermandad Escarlata. ¡Debe haberlo llevado a su biblioteca en el Monasterio Escarlata de los Claros de Tirisfal!\n\nSi quieres el libro, tendrás que ir al monasterio a buscarlo. Y perdona por todo este lío... últimamente no soy yo mismo.", objectives = { "Rituales de Poder" } },
    [1953] = { title = "Regreso al pantano", summary = "Habla con Tabetha.", desc = "<nombre>, es hora de que vayas a hablar con Tabetha... la ermitaña del Marjal Revolcafango. Te instruirá sobre la creación de un instrumento muy poderoso para un mago.\n\nLa choza de Tabetha está en las profundidades del Marjal Revolcafango, al oeste de Theramore." },
    [1954] = { title = "El orbe infernal", summary = "Lleva un orbe infernal a Tabetha en el Marjal Revolcafango.", desc = "El primer paso es adquirir un orbe con poder. Los brujos del Filo Ardiente tienen orbes fantásticos, de gran calidad... ¡lo malo es que tienen atados demonios en su interior! Pero podemos arreglarlo, sí, podemos.\n\nVe a Desolace y hazte con un orbe infernal de un invocador del Filo Ardiente. Encontrarás invocadores en el Aquelarre Mannoroc.\n\nCuando tengas el orbe, vuelve a verme.", objectives = { "Orbe infernal" } },
    [1955] = { title = "El exorcismo", summary = "Mata al demonio del orbe y habla con Tabetha.", desc = "Ahora que tenemos un orbe de invocador, debemos exorcizar al demonio que hay en su interior. Podemos hacerlo. Es la parte más fácil.\n\nPero tú tienes que hacer el trabajo duro. Tendrás que matar al demonio cuando esté fuera.\n\nY tendrás que hacerlo rápido. Si te lleva demasiado tiempo volverá a meterse en el orbe y tendremos que empezar de nuevo.\n\nTendrás que estar <preparado/preparada>. Ten listos tus hechizos más poderosos y ten tus pociones a mano. Trae también a un amigo, si lo tienes, esto no va a ser nada fácil.", objectives = { "Demonio del orbe", "Kill the Demon of the Orb" } },
    [1956] = { title = "Poder en Uldaman", summary = "Hazte con una fuente de poder obsidiano y llévasela a Tabetha en el Marjal Revolcafango.", desc = "Ahora que hemos eliminado al demonio, debemos hacernos con una fuente de poder. Por desgracia, las mejores fuentes de poder suelen ser las más antiguas y las más difíciles de obtener. Los juegos y tretas del destino son fascinantes, ¿verdad?\n\nAsí que vas a tener que ir a Uldaman y vencer al centinela obsidiano. Es grande, duro ¡y su fuente de poder da buenos golpes!\n\nTe deseo todo lo mejor, <nombre>. Y si no tienes suerte... ha sido un placer conocerte.", objectives = { "Fuente de poder obsidiano" } },
    [2040] = { title = "Asalto subterráneo", summary = "Recupera la Trituradora Piñonera de Las Minas de la Muerte y devuélveselo a Shoni el Shilenshioso, en Ventormenta.", desc = "¡Esos malditos troggs han tomado Gnomeregan! La situación es grave, pero quizás puedas ayudar, <nombre>.\n\nEn las profundidades de Las Minas de la Muerte hay una trituradora goblin operativa. Encuentra la trituradora y trae su batería intacta. Con la batería de la trituradora, podemos dar a nuestras excavadoras gyroagujereamáticas la energía necesaria para atravesar los rocosos límites subterráneos de Gnomeregan, ¡y nos abrirán el camino para el asalto gnomo!", objectives = { "Dentrituradora goblin" } },
    [2198] = { title = "El collar hecho añicos", summary = "Busca al creador del collar hecho añicos y descubre para qué sirve.", desc = "Has encontrado un collar deslustroso, que todavía deja ver el minucioso y mágico trabajo de artesanía del que ha sido fruto. El collar está dañado y parece que faltan tres gemas. En la parte de atrás del collar hay una inscripción apenas visible con el sello de la ciudad de Forjaz. Debajo hay tres pequeñas iniciales grabadas. \"TdK\".\n\nSi este collar significa algo, tendrás que descubrir de qué se trata. El sello y las iniciales serán un buen punto de partida..." },
    [2202] = { title = "Componentes de Uldaman", summary = "Llévale 12 setas moradas a Musgofusión en Kargath.", desc = "He oído hablar de unas plantas recién descubiertas llamadas setas moradas. Crecen en macizos en lo más remoto de la excavación de Uldaman; puede que también se encuentren en otra parte pero ese es el único sitio donde sé que hay. Deseo estudiar su uso potencial en alquimia y ahí es donde entras tú.\n\nEncuentra los macizos de setas moradas y tráeme una docena de setas. Ándate con ojo, los macizos pueden arrojar veneno si se les sacude.\n\nHaz esto por mí ¡y te prepararé un lote de mis famosos elixires vigorizantes!", objectives = { "Seta magenta x 12" } },
    [2240] = { title = "La cámara oculta", summary = "Lee el diario de Baelog, inspecciona la cámara oculta y ve a informar al prospector Pico Tormenta. -", desc = "Pasemos a la siguiente tarea.\n\nExiste una cámara secreta, la cámara de Khaz'mul, que hay que examinar. ¡El problema es que esta cámara se encuentra tras una enorme puerta cerrada con llave! Es una suerte que sepa cómo abrirla.\n\nLo explico todo en mi diario, que está sobre la mesa. Mi equipo y yo no podemos salir de aquí... así que tú, <nombre>, debes encontrar la cámara de Khaz'mul por nosotros.\n\nLee mi diario, examina la cámara y ve a informar al prospector Pico Tormenta de la Liga de Expedicionarios en Forjaz.", objectives = { "Inspecciona la cámara oculta." } },
    [2258] = { title = "Componentes de Tierras Inhóspitas", summary = "Llévale 5 mollejas de águila ratonera, 10 colmillos de coyote del risco y 5 fragmentos de elemental de piedra a Jarkal Musgofusión en Kargath, en las Tierras Inhóspitas.", desc = "<nombre>, no me vendría mal tu ayuda si te apetece echar una mano. Soy un alquimista de cierto renombre y necesitaría tu ayuda para conseguir unos componentes que se hallan en las Tierras Inhóspitas.\n\nMe hacen falta los siguientes objetos para reponer mis existencias: 5 mollejas de águila ratonera, 10 colmillos de coyote montés y 5 fragmentos de elemental de piedra. Como es lógico, puedes conseguirlos de los propios animalitos; si no eres del tipo luchador, llévate a unos amigos que lo sean.\n\nConsígueme esos objetos y acabarás con unas monedas más en el bolsillo. ¿Qué me dices? ¿Te hace?", objectives = { "Molleja de águila ratonera x 5", "Colmillo de coyote de risco x 10", "Fragmento de roca elemental x 5" } },
    [2278] = { title = "Los discos de platino", summary = "Habla con el guardapiedras y descubre qué conocimiento antiguo alberga. Cuando hayas adquirido el conocimiento que te ofrece, activa los Discos de Norgannon.", desc = "En el centro de esta cámara del tesoro se encuentran cuatro discos de platino gigantes, cada uno de ellos adornado con sigilos de origen desconocido. Al tocarlos sientes un cosquilleo en la mano. Tras haber tocado los discos, se muestra ante ti un enorme guardapiedras.\n\n\"Saludos. Soy un guardián del conocimiento. La síntesis de los Creadores de los terráneos se describe y almacena para este mundo en los Discos de Norgannon.\"\n\n¡Acabas de encontrar una fuente de conocimiento nunca antes descubierta por nadie!", objectives = { "Adquiere el conocimiento que te ofrece el guardapiedras." } },
    [2283] = { title = "La recuperación del collar", summary = "Busca el collar en la excavación de Uldaman y llévaselo a Dran Droffers a Orgrimmar. Puede que el collar esté estropeado.", desc = "Tenemos un trabajillo para ti. ¿Te atreves?\n\nAl parecer, hace poco que un idiota de paladín murió en la excavación Uldaman, en medio de las Tierras Inhóspitas. Lo que nos interesa de esto es que llevaba un collar muy valioso con tres gemas: un rubí, un zafiro y un topacio.\n\nEn resumen: queremos el collar y cubriremos de plata a quien lo traiga. Aunque esté deteriorado, no importa; ya lo arreglaremos.", objectives = { "Collar destrozado" } },
    [2342] = { title = "Los tesoros reclamados", summary = "Coge el tesoro de la familia de Patrick Garrett del cofre de su familia que se encuentra en la Sala Comunal Sur de Uldaman y llévasela a él a Entrañas.", desc = "¡Espantar murciélagos con una escoba no es apropiado para un Garrett! He ahorrado algo con este sórdido trabajo, y quiero entregártelo a ti para que me ayudes.\n\nEl arma elegida por la familia Garrett está guardada en nuestro cofre de la Sala Comunal Sur de Uldaman desde que nosotros, los Garrett, trabajábamos allí como excavadores. Sin ella, estaré atrapado aquí para siempre, literalmente, limpiando este lugar de estos murciélagos infernales.\n\n¡Reclama el tesoro de mi familia y tráemelo! ¡Ayúdame a recuperar mis derechos!", objectives = { "Tesoro de la familia Garrett" } },
    [2398] = { title = "Los enanos desaparecidos", summary = "Encuentra a Baelog en Uldaman.", desc = "La excavación de Uldaman no siempre estuvo ocupada por extraños. Nosotros los enanos solíamos controlar la zona... pero eso era antes de que los troggs hicieran su aparición. ¡Llegaron tan rápido y eran tan numerosos que ni los enanos fuimos capaces de hacerles frente!\n\nDe hecho, su ataque fue tan repentino que yo mismo temí que algunos de los nuestros hubieran podido quedar atrapados tras las líneas enemigas.\n\nMi amigo Baelog estaba al frente de un pequeño grupo de enanos en las profundidades de la excavación en el momento en el que aparecieron los troggs. Si él y quienes lo acompañaban siguen con vida, quiero que los encuentres." },
    [2418] = { title = "Las piedras de energía", summary = "Llévale 8 piedras de energía de dentrio y 8 piedras de energía de An'Alleum a Aparejez en las Tierras Inhóspitas.", desc = "Hace algún tiempo, me ocurrió un incidente con los enanos de Forjatiniebla. Me trajeron a la Fortaleza de Angor para estudiar dos tipos de extrañas piedras de Uldaman. Descubrí que las piedras eran fuentes de energía estable y continua si se manipulaban correctamente. ¡Es asombroso las cosas que te puedes encontrar en esa vieja excavación!\n\nEn fin, después de compartir con ellos el secreto de las piedras, me echaron de la Fortaleza de Angor y siguieron excavando para conseguir más en Uldaman.\n\n¡Quiero esas piedras para mí! Tráeme de los dos tipos ¡y te pagaré con creces!", objectives = { "Piedra de energía de dentrio x 8", "Piedra de energía An'Alleum x 8" } },
    [2500] = { title = "Componentes de Tierras Inhóspitas", summary = "Ve a las Tierras Inhóspitas a buscar los ingredientes que te ha pedido Ghak Sanadón y llévaselos a Thelsamar.", desc = "<clase>, necesito asistencia. Soy un alquimista de cierto renombre y necesito que me ayudes a conseguir ingredientes que se encuentran en las Tierras Inhóspitas.\n\nEsto es lo que necesito: 5 mollejas de águila ratonera, 10 colmillos de coyote montés y 5 fragmentos de elemental de piedra. Evidentemente, estos ingredientes están en las propias bestias; si la lucha no es lo tuyo, lleva a un par de amigos duros.\n\nSi me traes todo esto, te ganarás unas monedas.\n\nDime, ¿aceptas?", objectives = { "Molleja de águila ratonera x 5", "Colmillo de coyote de risco x 10", "Fragmento de roca elemental x 5" } },
    [2768] = { title = "Cetro Divinomático", summary = "Lleva el Cetro Divinomático al ingeniero jefe Silvaina en Gadgetzan.", desc = "¡El sargento me ha robado! Dijo que solo lo cogía prestado, ¡pero me robó mi querido Cetro Divinomático! Sin el Cetro, ¿cómo puedo saber dónde hacer nuevos pozos?\n\n¡Encuentra a Bly y tráeme mi cetro! He oído que condujo a su panda de aventureros a buscar tesoros en Zul'Farrak, al Oeste. Seguro que lo encontrarás allí.\n\nEsperemos que los trols se hayan ocupado de él porque si tuvieras que combatir con él por el cetro será un combate realmente duro.", objectives = { "Vara Divinomática" } },
    [2770] = { title = "Gahz'rilla", summary = "Llévale la escama electrificada de Gahz'rilla a Wizzle Pernolatón, que está en El Desierto de Sal.", desc = "En las profundidades de Zul'Farrak, la ciudad de arena de los trols de Tanaris, se encuentra una poza sagrada en la que los trols invocan a una bestia gigante... ¡Gahz'rilla! Es tan violento que hasta sus escamas crepitan con energía. ¡Esa es la energía que busco para mi coche!\n\n¡Tráeme la escama electrificada de Gahz'rilla!\n\nPara ello tendrás que invocar a Gahz'rilla y ese ritual es un secreto bien guardado por los trols. Para enfrentarte a él, primero tienes que arrebatarles el secreto.", objectives = { "Escama electrificada de Gahz'rilla" } },
    [2841] = { title = "Las guerras de la plataforma", summary = "Consigue la combinación de la caja fuerte de Termochufe en Gnomeregan y lleva los planos de la plataforma a Nogg a Orgrimmar.", desc = "Hasta hace dos años, la tecnología gnómica solo servía para echarse unas risas. Las cosas han cambiado mucho; han construido una plataforma mejor que todas las nuestras juntas. ¡Quiero los planos!\n\nEstán en una caja fuerte cerca del mekigeniero Termochufe. Para empeorar las cosas, él es el único que sabe la combinación.\n\nHaz lo que sea por conseguirla, <nombre>. ¡Tienes que abrir la caja y traerme los planos!", objectives = { "Planos de torre", "Combinación de la caja fuerte de Termochufe" } },
    [2842] = { title = "Scooty, ingeniero jefe", summary = "Habla con Scooty en Bahía del Botín.", desc = "En cuanto Kernobee nos avisó de lo de la plataforma gnómica, Scooty y yo empezamos a trabajar en el Transpoliportador 6000. Es el medio más seguro y rápido para ir a Gnomeregan.\n\nYa está a punto para despegar. Si quieres probarlo, ve a Bahía del Botín y habla con Scooty en la alcándara de jinete de Viento. Para ir a Bahía del Botín tienes que coger el barco en Trinquete.\n\nPor supuesto, puedes ir a Gnomeregan cruzando las montañas de Dun Morogh, que están infestadas de enanos." },
    [2843] = { title = "¡Gnomer-yaaaaa!", summary = "Espera a que Scooty calibre el transpondedor goblin.", desc = "Mientras tengas el transpondedor, todo lo que necesitas hacer es colocarte sobre la plataforma y serás <teletransportado/teletransportada> a Gnomeregan.\n\nQuizás experimentes algunos extraños efectos secundarios, pero ninguno será permanente... al menos ahora.\n\nCasi me olvido de lo más importante, la vuelta. Cuando quieras volver, colócate en la plataforma del Transpoliportador en Gnomeregan.\n\nTienes que calibrar el transpondedor según tu talla y peso.", objectives = { "El transpondedor goblin" } },
    [2846] = { title = "Tiara de la Profundidad", summary = "Lleva la Tiara de la Profundidad a Tabetha en el Marjal Revolcafango.", desc = "Hace mucho tiempo tenía una bonita joya, la Tiara de la Profundidad. No solo era hermosa... tenía un gran poder para quien sabía usarlo.\n\nPor eso, cuando la hidromántica Velratha oyó hablar de ella quiso tenerla. Envío a sus agentes a mi hogar y me la robaron cuando estaba fuera. ¡Ladrones!\n\n¡Quiero recuperar mi tiara! Ve a Zul'Farrak, la ciudad trol de Tanaris, encuentra a Velratha y quítale la tiara. Cuando la tengas vuelve a verme y te ganarás mi favor.", objectives = { "Tiara de las profundidades" } },
    [2864] = { title = "Tran'rek", summary = "Habla con Tran'rek en Gadgetzan.", desc = "Mi primo Tran'rek está en un aprieto. Me prometió un cargamento de caparazones de escarabajo hace semanas y todavía no lo ha traído. Es mi primo, así que odio tener que enviar a alguien a Gatgetzan para que le eche la bronca.\n\n¿Puedes hablar con Tran'rek por mí? Hazle saber que tiene que conseguir ese cargamento antes de que haga algo malo.\n\nGadgetzan está en el norte de Tanaris, en Kalimdor." },
    [2865] = { title = "Caparazones de escarabajo", summary = "Lleva 5 caparazones de escarabajos sin grietas a Tran'rek en Gadgetzan.", desc = "¡Los escarabajos de Tanaris tienen unos caparazones muy duros! Tan duros que se pueden utilizar para construir muchas cosas. ¡Muchísimas!\n\nDe hecho, esos caparazones son tan útiles y cazamos tantos escarabajos... ¡que casi se han extinguido!\n\nSé dónde hay más escarabajos, y si me prometes traerme sus caparazones te diré dónde están. ¿Prometido?\n\nMuy bien, hay una colonia de escarabajos en Zul'Farrak. Supongo que los trols no los cazan en busca de caparazones.\n\n¡Pero tú sí! ¡Ve a Zul'Farrak y consígueme caparazones sin grietas!", objectives = { "Caparazón de escarabajo sin rajar x 5" } },
    [2904] = { title = "Un buen lío", summary = "Acompaña a Kernobee a La rampa del engranaje y luego ve a ver a Scooty a Bahía del Botín.", desc = "<Gruñe.> ¿Qué..? ¿Qué ha pasado?\n\nSolo recuerdo que me capturó un grupo de enanos Hierro Negro, me dieron una paliza de muerte y me echaron aquí, con estos asquerosos trogg.\n\n¡Sácame de aquí, <nombre>!\n\nEste es el plan: llévame a la salida; si salimos con vida, tú te vas a la Bahía del Botín y le dices a Scooty que he ido a Trinquete para avisar a Manitas de Oro que los Hierro Negro están metidos en lo de la superplataforma.\n\n¡Andando!", objectives = { "El rescate de Kernobee" } },
    [2922] = { title = "¡Salva el cerebro de Techrobot!", summary = "Lleva el procesador central de memoria del techrobot al maestro manitas Sobrechispa a Forjaz.", desc = "Supongo que mi pobre techrobot recibió algún chispazo perdido cuando cayó nuestra amada Gnomeregan. Antes nos era muy útil gracias a sus incontables funciones y su capacidad ilimitada de almacenaje de información, pero su cerebro positrónico se ha polarizado. Ahora es negatrónico y la conducta del techrobot se ha invertido. ¡Anda descontrolado por Gnomeregan!\n\nPero quizás podamos recuperarlo. Si me trajeras el procesador central de memoria del techrobot, podría descubrir la causa de la polarización y repararlo.", objectives = { "Memoria de Tecnobot" } },
    [2923] = { title = "Maestro manitas Sobrechispa", summary = "Habla con el maestro manitas Sobrechispa en Forjaz.", desc = "El maestro manitas Sobrechispa está muy disgustado con lo ocurrido a su obra mecánica, el techrobot. Por lo que sé, el techrobot era una herramienta muy útil para los gnomos, pero dice que se ha averiado.\n\nLástima. ¡Aunque con suerte se podrá arreglar!\n\nVe a hablar con Sobrechispa a Ciudad Manitas, en Forjaz. Se alegrará de que vayas a ayudarlo." },
    [2924] = { title = "Esencias artificiales", summary = "Lleva 12 esencias artificiales a Klockmort Palmalicate a Forjaz.", desc = "Los herreros y manitas de Gnomeregan usaban un componente mecánico casi universal, la esencia artificial, en su trabajo. Pero durante la huída de la ciudad, ¡nadie pensó en coger esencia! Necesitaré mucha para un trabajo que estoy a punto de empezar.\n\nTe ruego que vayas a Gnomeregan a conseguirme esencia artificial. Está en las zonas más profundas de la ciudad, en unos contenedores que se llaman extrapoladores artificiales.\n\n¡Date prisa y muchas gracias, <nombre>!", objectives = { "Esencia artificial x 12" } },
    [2926] = { title = "Gnogaine", summary = "Usa la ampolla de plomo con invasores o saqueadores radiactivos para recoger restos radiactivos. Cuando esté llena, llévasela a Ozzie Voltiflop a Kharanos.", desc = "Desde el accidente, Gnoarn no piensa en otra cosa que en expulsar a los trogg de Gnomeregan y encontrar una cura para la plaga. <nombre>.\n\nPor suerte, Razzle y yo estamos a punto de conseguirlo; o eso, o hemos destilado un ron muy potente. ¡No lo sabremos hasta que lo probemos! Claro que para poner a prueba nuestra teoría, necesitamos algunas cosas, como restos de los trogg radiactivos en Gnomeregan. ¡Llena este frasco de material verdoso radiactivo y tráelo!", objectives = { "Ampolla de plomo llena" } },
    [2927] = { title = "Al día siguiente", summary = "Ve a hablar con Ozzie Voltiflop en Kharanos.", desc = "¿Crees que siempre he sido calvo? ¡Pues no <señor/señorita>! Perdí todo el pelo por culpa de la fuga radiactiva de Gnomeregan. Hasta entonces, tenía una mata de pelognomo única en todo Azeroth.\n\n<Sacude los puños.>\n\n¡Así se pudran esos malditos trogg en las simas del averno!\n\nA lo mejor no es tarde, <nombre>. Aún podemos salvarla. ¡A la ciudad, me refiero! Ve a hablar con Ozzie Voltiflop en Kharanos. Está buscando una solución con su colega Razzle." },
    [2928] = { title = "Gyrodrillmatic Excavationators", summary = "Lleva veinticuatro entrañas robomecánicas a Shoni en Ventormenta.", desc = "Es terrible, <nombre>. No vamos a tener suficientes repuestos para llevar nuestra flota de excavadoras gyroagujereamáticas a Dun Morogh.\n\nLo que necesitamos son repuestos, <nombre>. ¿Y qué mejor lugar que Gnomeregan para conseguir repuestos para nuestros vehículos? He oído que robots y mecazancudos vagan libremente por ese lugar.\n\nNecesito que vayas a Gnomeregan y destruyas a esos robots. Tráeme sus entrañas robot. Con dos docenas tendré suficiente.", objectives = { "Entrañas robomecánicas x 24" } },
    [2929] = { title = "La gran traición", summary = "Ve a Gnomeregan y mata al mekigeniero Termochufe. Ve a ver al Manitas Mayor Mekkatorque cuando hayas terminado.", desc = "Yo confiaba en Termachufe, <raza>. Nunca pensé que me traicionaría a mí y a todos los gnomos. ¿Y por qué? ¿Por el poder? ¿Por el dinero? Habría conseguido todo eso por sí mismo. Ahora nos han echado de nuestro hogar y ese chiflado es el que manda. Rey de pacotilla...\n\nVamos a recuperar Gnomeregan, <nombre>. No cejaremos hasta que la ciudad vuelva a nuestras manos. Si quieres ayudarnos, tengo un trabajito para ti. Mata al traidor. Acaba con el mekigeniero Termochufe.", objectives = { "Mekigeniero Termochufe" } },
    [2930] = { title = "Rescatar los datos", summary = "Lleva una tarjeta perforada prismática al maestro mecánico Funditubo a Forjaz.", desc = "¡Cuando tuvimos que huir de Gnomeregan, dejamos atrás información muy valiosa! ¡Qué digo, valiosa! ¡Vital!\n\nNecesito los datos de la tarjeta perforada prismática de un Perforágrafo Matriz 3005-D de alta seguridad oculto en Gnomeregan. Tienes que acceder a la terminal, pero para eso necesitas un permiso... Y para eso tienes que acceder a una terminal de baja seguridad de los modelos -A, -B y -C. Y para eso, necesitas tarjetas perforadas de seguridad en blanco... y todas se quedaron en la ciudad.\n\n¡Qué desastre! ¿Puedes ayudarme?", objectives = { "Tarjeta perforada prismática" } },
    [2933] = { title = "Botellas de veneno", summary = "Lleva una botella de veneno a algún boticario de Molino Tarren.", desc = "En estas botellas hay un veneno verde e infame.\n\nVista la cantidad de botellas que hay en el poblado, los Cortezaseca deben de considerarlo muy importante. A lo mejor algún boticario de Molino Tarren estaría interesado en esto." },
    [2934] = { title = "Glándula de veneno intacta", summary = "Lleva una glándula de veneno intacta al boticario Lydon de Molino Tarren.", desc = "Necesito más veneno como el que trajiste. Creo que las arañas de las que se extrae viven en las Tierras del Interior; encuentra una con la glándula de veneno intacta y tráemela. Habrá muchas cerca de la ciudad trol de Shadra'Alor.\n\nNo te entretengas, <nombre>. La glándula tiene que ser fresca.", objectives = { "Glándula de veneno no dañada" } },
    [2935] = { title = "Consulta al maestro Gadrin", summary = "Habla con el maestro Gadrin en el Poblado Sen'jin.", desc = "El veneno de las guardias del nido no era tan potente como el que me trajiste primero. Debía de ser de otra araña.\n\nQuiero que me traigas más de ese veneno. Para averiguar de dónde viene, ve al Poblado Sen'jin y habla con el maestro Gadrin. Es un trol que conoce bien a los Cortezaseca. Ve a Durotar y habla con Gadrin. Con un poco de suerte, sabrá de dónde sacan el veneno los Cortezaseca." },
    [2936] = { title = "Diosa araña", summary = "Lee el nombre de la diosa araña de los Secacorteza en la tablilla de Theka y vuelve a ver al maestro Gadrin.", desc = "Los Cortezaseca adoran a una diosa araña, de la cual extraen su veneno más potente. Así que, si quieres el veneno, ¡tienes que invocar a la diosa!\n\nPara ello debes conocer su verdadero nombre, inscrito en una tablilla enterrada en Tanaris, en la ciudad trol de Zul'Farrak, en una tumba custodiada por el Mártir Theka.\n\nDerrótalo y lee el nombre en la tablilla. Después, vuelve.", objectives = { "Averigua el nombre de la diosa araña" } },
    [2945] = { title = "Un anillo sucio", summary = "Encuentra la manera de limpiar el anillo sucio.", desc = "Has encontrado algo que parece un anillo en el cadáver de un enano Hierro Negro. Está cubierto de barro y restos secos y endurecidos, por lo que no se puede llevar ni se puede ver qué tipo de anillo es. Entre el barro, te parece entrever el brillo de metal precioso y quizás una gema.\n\nSi quieres ponértelo, tendrás que encontrar la manera de limpiarlo." },
    [2951] = { title = "¡El Destellamatic 5200!", summary = "Inserta un objeto sucio en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano.", desc = "Este aparato destaca entre los gnomos que se mantienen firmes frente a la locura que acecha fuera de la sala. Tiene una plaquita que dice: \"Destellamatic 5200\" y:\n\n\"¿La suciedad arruina sus destellos? ¡Destellamatic 5200 devuelve el brillo de forma brillante! Inserte el objeto que desea limpiar e introduzca tres monedas de plata en la ranura. Espere unos momentos, ¡y ya está! ¡Sus objetos de valor aparecerán limpios y resplandecientes!\"", objectives = { "Objeto con mugre incrustada" } },
    [2962] = { title = "Necesitamos más material verdoso", summary = "Viaja hasta Gnomeregan y recupera los restos radiactivos de gran potencia. Pero ten cuidado, ya que es inestable y podría explotar en cualquier momento. Ozzie también quiere que traigas la ampolla pesada de plomo una vez que hayas terminado el trabajo.", desc = "Tu muestra no solo era insuficiente en cuanto a cantidad, además era impura.\n\nNecesitamos más material verdoso radiactivo. Es evidente que los troggs no han sido suficientemente irradiados. Tendrás que ir a Gnomeregan y traer restos radiactivos, directamente de la fuente. Estoy hablando de babosas, rondadores y horrores irradiados. Y ten cuidado: contener este tipo de restos es difícil. Es posible que tengas que hacer varios intentos hasta que hayas reunido una muestra adecuada.", objectives = { "Restos radiactivos de gran potencia" } },
    [2988] = { title = "Las jaulas de Secacorteza", summary = "Mira en las jaulas de los poblados Secacorteza y vuelve a ver al maestro de grifos Garracha.", desc = "¡El hijo de nuestro mejor grifo ha desaparecido! El hijo de Alarrápida, Picoafilado, se perdió hace unos días cuando cazaba. Creemos que lo tienen los trols.\n\n¡Ayúdanos! Busca entre las jaulas de los dos poblados Secacorteza, a ver si lo encuentras.", objectives = { "Mira en la primera jaula", "Mira en la segunda jaula", "Mira en la tercera jaula" } },
    [2989] = { title = "El Altar de Zul", summary = "Mira en el Altar de Zul y vuelve a ver al maestro de grifos Garracha. -", desc = "Los Secacorteza no tienen a Picoafilado. A lo mejor fueron los trols Vilrama. Busca al grifito en el Altar de Zul, en el extremo occidental del territorio Vilrama.", objectives = { "Busca el Altar de Zul" } },
    [2990] = { title = "Thadius Sombramacabra", summary = "Lleva la pluma de Picoafilado a Thadius Sombramacabra a Las Tierras Devastadas.", desc = "Llévale esta pluma al adivino Thadius Sombramacabra. Se fue de Pico Nidal hace años para estudiar ciencias oscuras, pero sigue siendo un Martillo Salvaje.\n\nA lo mejor puede ayudarnos a encontrar a Picoafilado.\n\nEsta pluma estaba en su nido. Con ella y un poco de suerte, Thadius usará sus poderes de adivinación para localizar al grifo.\n\nSuerte, <nombre>. Thadius vive en las Tierras Devastadas, en la torre de los magos del Castillo de Nethergarde." },
    [2991] = { title = "Medallón de Nekrum", summary = "Lleva el medallón de Nekrum a Thadius Sombramacabra a Las Tierras Devastadas.", desc = "Voy a averiguar en dónde está tu grifo, pero primero haz algo por mí. Hay un trol en Zul'Farrak, Nekrum Cometripas, que tiene un medallón que me gustaría estudiar. Tráeme ese medallón y usaré mis poderes para encontrar a Picoafilado.\n\nZul'Farrak está al otro lado del océano, al oeste, en el desierto de Tanaris.", objectives = { "Medallón de Nekrum" } },
    [3042] = { title = "Temple trol", summary = "Lleva 20 viales de temple trol a Trenton Mazaligera en Gadgetzan.", desc = "Los trols Furiarena de Zul'Farrak utilizan arenisca para crear sus materiales de temple y yo también puedo utilizarlo para templar mis creaciones, ¡sí! Es muy valorado entre los expertos, así que si me traes un buen suministro de temple, te recompensaré muy bien.\n\nZul'Farrak está al noroeste de Gadgetzan. Buena suerte.", objectives = { "Temple trol x 20" } },
    [3341] = { title = "Acaba con la amenaza", summary = "Andrew Brownell quiere que mates a Amnennar el Gélido y que le lleves su calavera.", desc = "En Los Baldíos se encuentra una horrible maraña de vides llamadas Zahúrda Rajacieno. Aunque los primeros estudios de este lugar indicaban que no representaba una seria amenaza, nuestros últimos descubrimientos son un poco más desconcertantes...\n\nLos jabaespines de Zahúrda Rajacieno se han aliado con la Plaga. Un exánime llamado Amnennar el Gélido los gobierna, usando el poder de su vasto conocimiento para controlar cada uno de sus movimientos.\n\n<nombre>, Amnennar tiene un vínculo telepático directo con Ner'zhul que debemos eliminar y, para ello, hay que acabar con el Gélido cuanto antes.", objectives = { "Cráneo del Gélido" } },
    [3373] = { title = "Esencia de Eranikus", summary = "Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido.", desc = "Cuando tocas la gema, una voz profunda resuena en tu cabeza.\n\n\"Mortal, escucha esta súplica. Soy Eranikus del Vuelo Verde, guardián de este templo maldito. Mi deber de asegurarme de que los trols nunca jamás vuelvan a traer su abominación de dios, ha fracasado. Mientras esta gema queda imbuida de parte de mi esencia, puedo sentir que mi vínculo con el Sueño se dirige hacia el caos. Por favor, coloca esta gema en la fuente de esencia de mi guarida, y deja que nuestra magia purgue la corrupción de mi psique, para que pueda descansar.\"" },
    [3380] = { title = "El Templo Sumergido", summary = "Encuentra a Marvon Buscarroblones en Tanaris.", desc = "En este mundo, hay espíritus inquietos, <nombre>. Espíritus marcados por su aislamiento, atados a un mal ancestral...\n\nHe oído hablar de un lugar en el fondo de las profundidades de la tierra. Ha sido desterrado allí por poderes muy superiores a los que jamás he visto.\n\nSi quieres saber más cosas sobre este lugar, el Templo Sumergido, busca a un goblin llamado Marvon Buscarroblones. Ha estudiado muchas zonas antiguas del mundo. Se sabe que dejó su hogar en Trinquete para estudiar las ruinas trols en Tanaris.D" },
    [3441] = { title = "Castigo divino", summary = "Escucha a Kalaran Espada del Viento.", desc = "Escúchame bien.", objectives = { "La historia de Kalaran" } },
    [3442] = { title = "La llama pura", summary = "Lleva 4 corazones de llama y 4 globos de aceite gólem a Kalaran Espada del Viento.", desc = "Has tomado la decisión correcta, <nombre>.\n\nDebemos atacar donde más daño hagamos: en las 4 torres del centinela.\n\nSi las incendiamos, podremos atacar sin darles tiempo a reaccionar.\n\nPara incendiar las torres necesitarás una herramienta. Necesito algunas cosas para fabricarla.\n\nTráeme 4 corazones de llama y 4 aceites de gólem; con eso te haré la antorcha de llama pura.\n\nBusca primero a los golems y elementales de estas tierras.", objectives = { "Corazón de llama x 4", "Aceite gólem x 4" } },
    [3443] = { title = "Forjar el mango", summary = "Lleva 8 dagas chapadas en torio a Kalaran Espada del Viento.", desc = "Necesitamos un soporte y un mango para transportar la llama pura. Busca primero el mango.\n\nLos capataces y esclavistas Hierro Negro de La Caldera usan armas de torio encantado, una aleación muy resistente. Si me traes 8 dagas chapadas en torio, fundiré la aleación para fabricar el mango.", objectives = { "Daga bañada en torio x 8" } },
    [3444] = { title = "El Círculo de Piedras", summary = "Recupera el Círculo de Piedras del taller de Marvon Buscarroblones, en Trinquete.", desc = "Una vez entré en las cámaras prohibidas del Templo Sumergido. El mal que yace en ese lugar penetra en todo lo que entra. Casi no consigo salir de allí, vadeando entre el lodo que cubre el suelo. Todo lo que puedo recordar es que pasé a trompicones por una gran sala circular llena de estatuas de la Serpiente...\n\nHace poco, descubrí una piedra redonda que parece tener el mismo símbolo de la Serpiente grabado. Hice que me la enviaran a mi taller en Trinquete. Recupérala y podré decirte más cosas.", objectives = { "Círculo de Piedras" } },
    [3446] = { title = "En las profundidades", summary = "Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas.", desc = "Dentro del templo, encontré una sala circular con seis balcones. Cada uno de ellos tenía una estatua de la Serpiente en el borde. Curioso, empujé una de ellas para ver lo que pasaba, ¡era una trampa! Casi encuentro la muerte en la explosión que surgió. Allí, en el borde, miré hacia abajo y vi otra estatua en el fondo de la sala, una especie de altar... Creo que se llamaba Hakkar.\n\nMe da la impresión de que ese altar es el secreto. Debes llevar este objeto al altar del Templo Sumergido." },
    [3447] = { title = "El secreto del círculo", summary = "Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas.", desc = "Mis recuerdos son borrosos, pero te diré lo que pueda. Aunque el círculo de estatuas del Templo Sumergido es peligroso, creo que contiene el secreto para encontrar un tesoro mucho mayor.\n\nDesde el altar principal, conseguí activar una serie de luces. Si puedes descubrir el significado de esas luces, quizás puedas revelar el secreto que se esconde en esa sala.\n\nPero te lo advierto, <nombre>. Un gran mal yace en el templo. Lo más probable es, que si hay algo de valor, estará muy protegido..." },
    [3452] = { title = "El soporte para la llama", summary = "Lleva un Símbolo de Ragnaros a Kalaran Espada del Viento.", desc = "Nos falta un elemento para acabar la antorcha.\n\nEn las montañas del noroeste encontrarás un campamento de Azote del Ocaso. Se dice que llevan símbolos e ídolos en honor a su dios; seguro que tienen suficiente magia para crear un soporte encantado. Tráeme 1 símbolo de Ragnaros; intentaré extraer su magia.", objectives = { "Símbolo de Ragnaros" } },
    [3453] = { title = "La Antorcha de Reprensión", summary = "Espera a que Kalaran Espada del Viento termine la Antorcha de Reprensión.", desc = "Déjame montar el conjunto y pronunciar los encantamientos.", objectives = { "Creación de la antorcha" } },
    [3454] = { title = "La Antorcha de Reprensión", summary = "Coge la Antorcha de Reprensión.", desc = "Ahora hay que vincular la antorcha a quien la porta. Cógela, <nombre>." },
    [3462] = { title = "Escudero Maltrake", summary = "Habla con mi enviado, el escudero Maltrake.", desc = "Habla con mi enviado, el escudero Maltrake; te dirá cómo usar la Antorcha de Reprensión." },
    [3463] = { title = "¡Préndelas fuego!", summary = "Entra en las 4 torres del centinela e incéndialas con la Antorcha de Reprensión.", desc = "Escúchame bien, <nombre>. Aunque no es posible destruir las torres, con la antorcha provocarás unos incendios muy difíciles de extinguir, un fuego que no puede apagar ninguna fuerza ni elemento.\n\nMientras ardan no podrá haber centinelas ni guardias; su primera línea de defensa quedará anulada.\n\nTienes que entrar en cada torre y usar la antorcha dentro de las fortificaciones. Ten cuidado con las unidades de élite de los Hierro Negro, <nombre>.", objectives = { "Torre Oeste en llamas", "Torre Sur en llamas", "Torre Este en llamas", "Torre Norte en llamas" } },
    [3481] = { title = "Abalarios...", summary = "Abre el cofre.", desc = "El cofre está cerrado con llave." },
    [3520] = { title = "Los espíritus de los estriadores", summary = "Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor.", desc = "Busco espíritus de los estridadores del valle de Feralas. Son primos lejanos de un viejo dios y sus espíritus están unidos al suyo.\n\nCoge esta rama de zarza y ve a Feralas. Busca estridadores del valle en la zona sur y central de Feralas y derrótalos. Después agita mi rama sobre sus cuerpos para que sus espíritus se muestren. Toca el espíritu y recoge su esencia.\n\nRegresa con mi rama y con la esencia que hayas recogido y te contaré más acerca del viejo dios del que te hablé.", objectives = { "Espíritus de los estridadores recogidos. x 3" } },
    [3523] = { title = "La plaga de la Zahúrda", summary = "Si decides ayudar a Belnistrasz, habla con él otra vez y devuélvele la piedra de juramento.", desc = "¡Fantástico! Me llamo Belnistrasz, gracias por rescatarme. Esperaba la muerte o algo peor, como servir de cena a estas alimañas infectadas de Plaga. Sí, la Plaga. Han sellado algún pacto con los jabaespines y el resultado es esta pesadilla.\n\nNo quiero limitarme a huir; quiero cambiar las cosas, por el bien de todos. ¿Quieres ayudarme? Seguro que es peligroso, pero no parece que el peligro te preocupe mucho." },
    [3525] = { title = "Extinguir el ídolo", summary = "Acompaña a Belnistrasz al ídolo jabaespín en Zahúrda Rajacieno. Protégelo mientras realiza el ritual para inutilizar el ídolo.", desc = "Cerca de la entrada hay un ídolo que sirve de horno macabro para los jabaespines. Esas bestias consumen literalmente a quienes secuestran en Los Baldíos. Puedo cerrar el ídolo e impedir que vuelvan a usarlo, pero necesito tu ayuda. Llévame hasta el ídolo y ejecutaré mi ritual. Apenas si podré comunicarme contigo, por no hablar de defenderme. Protégeme; si me matan, será el fin para todos nosotros.\n\n¿Estás conmigo?", objectives = { "Protege a Belnistrasz mientras realiza el ritual para inutilizar el ídolo" } },
    [3527] = { title = "La profecía de Mosh'aru", summary = "Llévale la primera y segunda tablillas de Mosh'aru a Yeh'kinya, que está en Tanaris.", desc = "La antigua profecía de Mosh'aru cuenta el modo de encerrar la esencia del dios Hakkar. Está escrita en dos tablillas que fueron depositadas en la ciudad trol de Zul'Farrak, al oeste de Gadgetzan.\n\n¡Tráeme las Tablillas de Mosh'aru!\n\nLa primera tablilla obra en poder de un trol difunto llamado Theka el Mártir. Se dice que sus perseguidores fueron transformados en escarabajos que ahora vagan por los alrededores de su sepulcro.\n\nLa segunda tablilla está en manos de la hidromántica Velratha, cerca de la poza sagrada de Gahz'rilla.\n\nCuando tengas las tablillas, tráemelas.", objectives = { "Primera tablilla Mosh'aru", "Segunda tablilla Mosh'aru" } },
    [3528] = { title = "El dios Hakkar", summary = "Llévale el Huevo relleno de Hakkar a Yeh'kinya, que está en Tanaris.", desc = "Ha llegado la hora de atrapar la esencia del avatar de Hakkar.\n\nLleva el Huevo de Hakkar al Sagrario del Dios Caído que se encuentra en el Templo Sumergido de Azeroth. Invoca el poder del huevo para agitar al dios muerto.\n\nÉl enviará a sus esbirros a atacarte. Derrota a sus chupasangres y extráeles su sangre Hakkari. A continuación, utiliza la sangre para apagar las llamas eternas que protegen el espíritu de Hakkar. Cuando el fuego haya sido sofocado, el avatar de Hakkar entrará en nuestro mundo.\n\nDerrótalo y coloca su esencia en el interior del Huevo de Hakkar.", objectives = { "Huevo de Hakkar relleno", "Esencia de Hakkar" } },
    [3636] = { title = "Trae la Luz", summary = "El Arzobispo Bendictus quiere que mates a Amnennar el Gélido en Zahúrda Rajacieno.", desc = "La Plaga es una amenaza constante para la Alianza, lo cual no es nada nuevo. Hace poco, nos topamos con unos hallazgos muy peculiares, <nombre>.\n\nEn los Baldíos existe un laberinto de púas llamado la Zahúrda Rajacieno. Solía ser el hogar de jabaespines, pero ahora parece ser que la Plaga ha hecho algún tipo de pacto, creando criaturas mucho peores... Las gobierna el exánime Amnennar el Gélido.\n\nÚnete a la Luz, <nombre>, y acaba con tal pacto.", objectives = { "Amnennar el Gélido" } },
    [3701] = { title = "Las ruinas humeantes de Thaurissan", summary = "Ve a las Ruinas de Thaurissan, en las Estepas Ardientes, y recopila información sobre los tesoros de Thaurissan. Informa al historiador regio Archesonus.", desc = "Intérnate en las ruinas de Thaurissan, en las Estepas Ardientes, y consigue toda la información que puedas.\n\nDicen que las ruinas están plagadas de tesoros misteriosos. Empieza tu búsqueda por ahí, <nombre>. Ten cuidado con los guardias de Thaurissan: son asesinos que protegen las ruinas y los secretos que hay en ellas.", objectives = { "Has recuperado la información x 12" } },
    [3702] = { title = "Las ruinas humeantes de Thaurissan", summary = "Escucha al historiador regio Archesonus relatar la historia de Thaurissan.", desc = "¿Te cuento la historia de los enanos Hierro Negro?", objectives = { "La historia de Thaurissan" } },
    [3765] = { title = "Lejana corrupción", summary = "Ve a ver a Gershala Noctusurro en Auberdine.", desc = "Ventormenta... un centro de mucho movimiento.\n\nVengo desde muy lejos buscando ayuda. A menudo se dice que hay valientes aventureros caminando por las calles de esta ciudad.\n\nMi hermano, Gershala, necesita ayuda en Costa Oscura. Vive en la ciudad costera de Auberdine.\n\nEl viaje es largo y épico. Por esta razón, necesito la ayuda de un <clase> experimentado como tú." },
    [3801] = { title = "El legado de los Hierro Negro", summary = "Habla con Franclorn Forjafina si te interesa obtener una llave de la ciudad.", desc = "Saludos, <nombre>. Me llamo Franclorn Forjafina. Sí, el Franclorn Forjafina responsable del revolucionario método de arquitectura. Seguro que has cruzado o has estado en alguna de mis obras a lo largo de tus aventuras en este mundo desgarrado por la guerra.\n\nDebes de estar preguntándote qué hago aquí y qué quiero de ti, dos preguntas muy válidas.\n\nNecesito tu ayuda, claro. A cambio de esa ayuda, te concederé la llave de las profundidades de mi execrable ciudad." },
    [3802] = { title = "El legado de los Hierro Negro", summary = "Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjafina.", desc = "Encontrarás a Fineous Virunegro pasado el Círculo de la Ley, en la Sala de los Oficios. Mata al miserable bellaco y recupera a Ferrovil.\n\nLleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en su legítimo lugar: entre las manos de la estatua erigida en mi honor.\n\nCuando lo hayas hecho, el compartimento en el que guardé la llave maestra estará abierto. Y lo que es más importante, Ferrovil permanecerá para siempre jamás en mis manos. Si intentaran extraer el martillo, tanto la estatua como el martillo se harán añicos y se perderán para siempre.", objectives = { "Ferrovil" } },
    [3906] = { title = "La discordia de las llamas", summary = "Ve a la cantera de la Montaña Roca Negra y ejecuta al gran maestro Pyron. Vuelve junto a Truenozón cuando hayas completado este encargo.", desc = "Los miembros del consejo han sentido una perturbación en los elementos. Los enanos Hierro Negro han conjurado a un espíritu maligno en nuestro mundo que amenaza con una catástrofe en nuestras tierras en forma de inundación permanente. Hay que investigar la discordancia de las llamas.\n\nVe hasta Montaña Roca Negra, atraviesa el Abismo de Llama y hasta la cantera. Allí encontrarás al Señor del Fuego: gran maestro Pyron.\n\nPon fin a la perturbación y vuelve aquí.", objectives = { "Gran Maestro Pyron" } },
    [3907] = { title = "La discordia de las llamas", summary = "Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Truenozón.", desc = "Puedo oler que el aire que te rodea está viciado, <nombre>. Hay otro ente, oculto en las profundidades de Roca Negra, que lo controla.\n\nEl viento y la tierra gritan su nombre: Lord Incendius... pero alguien... algo... manda en este ente ser. Es un mero emisario.\n\n¡Encuéntralo y descubre dónde se oculta su maestro! Vuelve a mí cuando hayas obtenido esta información.", objectives = { "Lord Incendius", "Tablilla de Kurniya" } },
    [3981] = { title = "Comandante Gor'shak", summary = "Encuentra al comandante Gor'shak en las Profundidades de Roca Negra. Recuerdas que en el dibujo burdo había rejas sobre el rostro del orco. Quizás deberías buscar una cárcel o algo similar.", desc = "Pobre Gargal... no le dio tiempo ni a olerla. ¡BAM! La flecha se le clavó en el mismísimo centro de la cabeza. No es que fuera una lumbrera antes pero ahora...\n\n<Galamav esboza una mueca.>\n\nCuando le extrajimos la flecha, descubrimos una nota enrollada en el asta. En la nota había un dibujo burdo de un orco entre rejas con la firma del comandante Gor'shak adjunta.\n\nSi aún está vivo en las Profundidades, tendrás que encontrarlo.\n\n¿Una trampa? No estoy de broma, ¡pezuñas entumecidas! ¡Por eso vas!" },
    [3982] = { title = "¿Qué pasa?", summary = "Defiende a Gor'shak.", desc = "Me enviaron aquí bajo los auspicios de Thrall. ¿En serio crees que estos patanes podrían capturarme? Dejé que me apresaran para poder espiarlos.\n\n<Gor'shak habla ahora susurrando.>\n\nEl Emperador Thaurissan ha secuestrado a la Princesa de Forjaz. ¡La Princesa Barbabronce se encuentra aquí mismo en esta ciudad! Apuesto a que a Magni casi le da un infarto cuando lo supo.\n\n<Gor'shak suelta una carcajada.>\n\n¡Chitón! ¿Has oído eso? ¡Se acerca la guardia! ¡DEFIÉNDETE!", objectives = { "Sobrevive a la masacre" } },
    [4001] = { title = "¿Qué pasa?", summary = "Habla con Kharan Martillazo y recaba información sobre el secuestro de la princesa Moira Barbabronce. Llévale esa información a Thrall en Orgrimmar. Recuerdas que Gor'shak mencionó que Kharan estaba preso en una celda cercana.", desc = "Hasta ahora mi comunicación con Kharan, el enano que está en la celda al otro lado del vestíbulo, ha sido escasa. Sin embargo, he logrado convencerle de que yo, bueno, nosotros, no queremos hacerle ningún daño.\n\nVe a hablar con él y sácale toda la información que puedas sobre la Princesa y sus secuestradores. Después informa de todo ello al Jefe de Guerra.\n\nThrall no quiere que se hiera a la Princesa, por lo que ha elaborado un minucioso plan según el cual podrá volver sana y salva a Forjaz. Kharan ya está al tanto... ¡Vete!", objectives = { "Información obtenida de Kharan" } },
    [4002] = { title = "Los Reinos del Este", summary = "Si aceptas la misión, habla con Thrall.", desc = "<nombre>, la información que traes es excelente.\n\nMi deber como Jefe de Guerra es hacer lo que sea mejor para la Horda. Debo asegurar la libertad de las generaciones venideras.\n\nTenemos la oportunidad de formar nuestras futuras alianzas. Si ayudamos a los enanos, se estrecharían las relaciones con los Reinos del Este. ¡Por eso no puedes fallar!\n\n¿Estarás a la altura?" },
    [4003] = { title = "El rescate real", summary = "Mata al emperador Dagran Thaurissan para liberar a la princesa Barbabronce del hechizo.", desc = "Si sale bien, este golpe a los Hierro Negro sacudirá los cimientos de su reino.\n\nLa princesa Barbabronce está bajo el control del emperador Thaurissan; para liberarla, tendrás que matarlo. Ten en cuenta que tu misión es doblemente peligrosa, porque la princesa intentará atacarte mientras esté controlada por el Emperador.\n\n¡¡Asegúrate de que no sufra daños!!", objectives = { "Emperador Dagran Thaurissan" } },
    [4022] = { title = "Un sabor a llamarada", summary = "Enséñale a Cyrus Therepentio la escama de Vuelo Negro que recibiste de Kalaran Espada del Viento.", desc = "El Vuelo tiene conocimiento de tu trabajo en La Garganta de Fuego.\n\nEnséñamela, <raza>. La escama, imbécil.", objectives = { "Muda de piel de vuelo negro", "Prueba aportada" } },
    [4024] = { title = "Un sabor a llamarada", summary = "Viaja hasta las Profundidades de Roca Negra y mata a Bael'Gar. Solo sabes que el gigante vive en las Profundidades de Roca Negra. Acuérdate de usar la escama alterada de Vuelo Negro sobre los restos de Bael'Gar para capturar la esencia fiera. Llévale la esencia fiera recubierta a Cyrus Therepentio.", desc = "Deseo probar las ardientes llamas de la montaña de fuego. Dejar que el calor del magma de Roca Negra recorra todo mi ser. Esa esencia, ese calor abrasador, es lo que ansío.\n\nBael'Gar mora en las Profundidades de Roca Negra: un ser que es llama pura, nacido de los fuegos de Ragnaros. Ejecuta a Slay Bael'Gar y tráeme un poco de su fuego interior de entre sus ardientes restos.\n\nUsa la escama de sus restos para extraer sin peligro la llama interior.\n\nConsíguelo y recibirás tu merecida recompensa.", objectives = { "Esencia ígnea encerrada" } },
    [4061] = { title = "La revuelta de las máquinas", summary = "Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos de elemental agrietado para Hierofante Theodora Mulvadania. Recuerdas que Theodora mencionó que los golems y elementales de esa región eran la fuente de estos fragmentos.", desc = "Las máquinas se hicieron notar solas en nuestras primeras incursiones en La Garganta de Fuego. Después de investigar el asunto, descubrimos que las estaban importando de Las Estepas Ardientes, posiblemente desde las Profundidades de Roca Negra. Por eso te necesitamos, <nombre>.\n\nTu tarea consistirá en aventurarte en Las Estepas Ardientes y recuperar los fragmentos de elementales de los autómatas de piedra y de otras creaciones de piedra menores de la región. Cuando hayas reunido la cantidad suficiente, vuelve aquí y determinaré la fuente de procedencia.", objectives = { "Fragmento elemental fracturado x 10" } },
    [4062] = { title = "La revuelta de las máquinas", summary = "Lleva el ejemplar de fragmento de Elemental a Lotwil Veriatus. Recuerdas que Theodora dijo que Lotwil se encontraba en un campamento hacia el este.", desc = "“G.L.A.\n\nEsas son las iniciales impresas en los fragmentos de elementales. Debajo de las iniciales hay algún tipo de rango. Las máquinas que destruiste en Las Estepas Ardientes eran del “”Rango IV””. Supongo que es un rango más bien bajo.\n\nLleva esta muestra de fragmento a Lotwil Veriatus en el campamento del este. Es un erudito de cierto renombre en ciencias elementales. Es posible que sea capaz de ayudarnos en esta investigación.\"" },
    [4063] = { title = "La revuelta de las máquinas", summary = "Encuentra al Señor Gólem Argelmach y mátalo. Llévale su cabeza a Lotwil. Asimismo tendrás que reunir 10 núcleos de elemental intactos de los golems Furiatracadores y de los constructos belisario que protegen a Argelmach. Lo sabes porque eres un adivino.", desc = "¡No puede ser Argelmach! Mataron a Argelmach hace diez años. ¿Que cómo puedo estar seguro? Yo mismo lo maté.\n\nEra un enano despreciable, empeñado en pervertir el trabajo de mi vida para satisfacer sus diabólicas necesidades. Parece que los malvados siempre consiguen escurrirse de la justicia.\n\nSi este es el trabajo de Argelmach, debe ser destruido. Necesitaré muestras de sus creaciones más recientes. Con las muestras adecuadas, puede que consiga detener esta revuelta. Las creaciones protegen a Argelmach en las Profundidades de Roca Negra.", objectives = { "Cabeza de Argelmach", "Núcleo elemental intacto x 10" } },
    [4081] = { title = "MATAR INMEDIATAMENTE: enanos Hierro Negro", summary = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores! El señor de la guerra Dientegore quiere que mates a 15 custodios de Yunque Colérico, 10 alcaides de Yunque Colérico y 5 lacayos de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.", desc = "Por orden del señor de la guerra Dientegore, comandante de la Fuerza Expedicionaria de Kargath:\n\nTodos y cada uno de los efectivos del general Forjafuria en las Profundidades de Roca Negra debe ser aniquilado.\n\nLos hombres de Forjafuria son crueles asesinos, responsables del asesinato masivo de la 109 división de la Fuerza Expedicionaria de Kargath. Se recomienda a los héroes extremar la precaución al enfrentarse a estos animales.\n\nCualquier persona que destruya la primera línea del general Forjafuria en las Profundidades de Roca Negra recibirá un tributo.", objectives = { "Custodio de Yunque Colérico x 15", "Alcaide de Yunque Colérico x 10", "Lacayo de Yunque Colérico x 5" } },
    [4082] = { title = "MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango", summary = "Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores! El señor de la guerra Dientegore quiere que mates a 10 médicos de Yunque Colérico, 10 soldados de Yunque Colérico y 10 oficiales de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.", desc = "Por orden del señor de la guerra Dientegore, comandante de la Fuerza Expedicionaria de Kargath:\n\nEl jefe de la división de reconocimiento de la F.E.K., maestro mayor Lexlort, ha vuelto con noticias sobre el paradero de oficiales Hierro Negro de alto rango. A puerta cerrada, cerca del corazón de la ciudad, entrenan a sus tropas para acabar con nuestros hombres. Ve a las Profundidades de Roca Negra ¡y destrúyelos!\n\nEl éxito en esta misión se traducirá en un tributo.", objectives = { "Médico de Yunque Colérico x 10", "Soldado de Yunque Colérico x 10", "Oficial de Yunque Colérico x 10" } },
    [4121] = { title = "¡Estás en un aprieto!", summary = "Escolta al prisionero, Grark Lorkrub, a través de Las Estepas Ardientes y la Montaña Roca Negra hasta La Garganta de Fuego. Recuerdas que Lexlort mencionó que tendría a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido. También tendrás que entregarle a Lexlort los grilletes de torio.", desc = "¿De veras crees que llegarás a tu cita teniendo que vigilarme? ¿Esperabas realmente introducirte en una fortaleza Roca Negra fuertemente vigilada y capturar un valioso trofeo sin que nadie se percatara de nada, o advirtiera tu presencia?\n\n¡Te aplastarán!", objectives = { "Grilletes de torio", "Transporte del prisionero" } },
    [4122] = { title = "Grark Lorkrub", summary = "Ve a Las Estepas Ardientes y encuentra a Grark Lorkrub. Recuerdas que Lexlort mencionó que lo habían visto por última vez en una colosal fortaleza Roca Negra. Cuando encuentres a Grark Lorkrub, usa los grilletes de torio para atarlo y condúcelo de vuelta por la Montaña Roca Negra hasta La Garganta de Fuego. Lexlort tendrá a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido.", desc = "Le seguí la pista hasta La Garganta de Fuego, a través de la montaña y por Las Estepas Ardientes. Pillaron a ese traidor con las manos en la masa revelando a los orcos Roca Negra información vital sobre nuestras operaciones cotidianas. Me refiero a Grark Lorkrub.\n\nSe encuentra ahora en Las Estepas Ardientes, a salvo y protegido, o al menos eso cree él.\n\nLlévate estos grillete, <nombre>. Encuentra a Grark, colócale los grilletes y llévalo hasta Montaña Roca Negra. Hazlo y te llevarás un tributo." },
    [4123] = { title = "El Corazón de la Montaña", summary = "Llévale el Corazón de la Montaña a Maxwort Suprandor en Las Estepas Ardientes.", desc = "Durante años he buscado cierta gema. Se llama Corazón de la Montaña ¡y es tan grande como uno de tus puños! Los enanos Hierro Negro la tienen bajo llave en su cámara acorazada y, aunque lo he intentado, no me dejan comprarla.\n\nAsí que tengo recurrir a la fuerza.\n\nÁbrete paso hasta la cámara inferior de las Profundidades de Roca Negra, descubre la caja fuerte secreta y hazte con el Corazón. Para ello, tendrás que derrotar al vigilante Presaletal ¡y solo se manifestará cuando hayas abierto todas las arcas con reliquias de la cámara!\n\nSuerte.", objectives = { "El corazón de la montaña" } },
    [4126] = { title = "Hurley Negrálito", summary = "Llévale la receta perdida de Cebatruenos a Ragnar Cebatruenos en Kharanos.", desc = "Los enanos Hierro Negro, dirigidos por el granuja de Hurley Negrálito, han robado una de las mejores recetas de cervezas de Cebatruenos, la rubia Cebatruenos. ¡Los muy pillastres! ¡Su paladar es indigno de tan fino brebaje!\n\n<nombre>, tengo una tarea para ti. Ve a las Profundidades de Roca Negra en Las Estepas Ardientes, destruye cualquier barril de cerveza Cebatruenos que encuentres ¡y devuélvenos la receta de la rubia Cebatruenos!\n\nRecupera esa receta ¡aunque para ello tengas que remover cielo y tierra en las Profundidades de Roca Negra!", objectives = { "Receta de Cebatruenos perdida" } },
    [4128] = { title = "Ragnar Cebatruenos", summary = "Habla con Ragnar Cebatruenos.", desc = "Hola, <nombre>. He oído que Ragnar Cebatruenos está que echa chispas por el robo de su cerveza. Está buscando fornidos aventureros y les pagará bien.\n\nHabla con Ragnar, si te interesa. Se encuentra en la Destilería Cebatruenos en Kharanos, en Dun Morogh." },
    [4132] = { title = "Operación: muerte a Forjafuria", summary = "Viaja hasta las Profundidades de Roca Negra ¡y mata al general Forjira! Vuelve junto al señor de la guerra Dientegore cuando hayas acabado la tarea.", desc = "Has hecho un trabajo ejemplar, <nombre>. Ha llegado la hora de enviarte a tu última misión.\n\nEl general Forjafuria, el responsable de coordinar los ataques de los Hierro Negro sobre la 109 división de la F.E.K. y del asesinato masivo de nuestras tropas ha de ser llevado ante la justicia.\n\nEsta será sin duda tu misión más dura pero si lo logras, recibirás una jugosa recompensa.", objectives = { "General Forjira" } },
    [4133] = { title = "Vivian Latumba", summary = "Habla con la nigromante Vivian Latumba en Kargath.", desc = "La nigromante Vivian Latumba necesita tus servicios. Se encuentra en las Tierras Inhóspitas, en la avanzada de los orcos de Kargath, le sigue la pista a unos rumores sobre cierto brebaje que preparan los enanos Hierro Negro de las Profundidades de Roca Negra.\n\nHabla con Vivian. Te aguarda." },
    [4134] = { title = "La receta perdida de Cebatruenos", summary = "Llévale la receta perdida de Cebatruenos a Vivian Latumba en Kargath.", desc = "Se rumorea que el Hierro Negro Hurley Negrálito ha robado una receta de cerveza. Dicen que esta cerveza, la rubia de Cebatruenos, infunde gran fuerza y valor a quien la ingiere. Queremos estudiar esa bebida. A lo mejor, encontraremos otras aplicaciones para sus virtudes... aplicaciones más acordes con los objetivos de los Renegados.\n\nAdéntrate en las Profundidades de Roca Negra, encuentra a Hurley, quítale la receta de la cerveza de Cebatruenos y tráemela.\n\nY para encontrarlo, puede que tengas que engatusarlo amenazando su preciada cerveza.", objectives = { "Receta de Cebatruenos perdida" } },
    [4136] = { title = "Ribbly Llavenrosca", summary = "Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes.", desc = "Mi hermano Ribbly siempre ha sido un pozo sin fondo para la familia, sacándonos el dinero para malgastarlo en un plan tras otro.\n\nBueno, pues su último proyecto fue el peor porque el barón Revilgaz de Bahía del Botín acaba de ponerle precio a la cabeza de Ribbly. ¡Puedes imaginarte la alegría para los Llavenrosca! ¡Nuestro pequeño Ribbly por fin vale algo!\n\nPero ahora está escondido, en lo más remoto de las Profundidades de Roca Negra. ¡Encuéntralo y tráemelo!\n\nO, si no quiere acompañarte, entonces… basta con que me traigas su cabeza.", objectives = { "Cabeza de Ribbly" } },
    [4141] = { title = "Muigin y Larion", summary = "Recoge 15 pétalos de sangre y ve a ver a Muigin.", desc = "¿Has visto a Larion por ahí? ¡Es culpa SUYA que estemos aquí!\n\nLe dije que íbamos por mal camino, pero ¿acaso escuchó? ¿Puedes creerte que encima él es el que no me habla? Bueno, hasta que cambie de opinión, vamos a divertirnos un poco a su costa.\n\n¿Has visto las extrañas criaturas con forma de planta que hay por aquí? Solo son un montón de problemas, en serio, pero creo que si las instruyo como es debido, puedo hacer que obedezcan órdenes.\n\nAunque, antes de nada, voy a necesitar unas muestras para estudiarlas. ¿Crees que podrías reunir algunas muestras?", objectives = { "Pétalo de sangre x 15" } },
    [4142] = { title = "Visita a Gregan", summary = "Llévale un pétalo de sangre a Gregan Vomitabrebaje de Feralas.", desc = "No sé que voy a hacer con esto, <nombre>. Las plantas... parecen tener una inteligencia muy reducida.\n\nAunque yo no soy ningún experto... ¡conozco a alguien que sí lo es!\n\nDirígete al norte de Feralas y busca a un colega mío llamado Gregan Vomitabrebaje. Él es un experto en este tipo de cosas.\n\nEstoy seguro de que Gregan nos podría ayudar con esto. Lo encontrarás en plena naturaleza pues no es un tipo al que le guste vivir en una gran ciudad." },
    [4143] = { title = "Bruma del mal", summary = "Reúne 5 muestras de bruma Atal'ai y después ve a ver de nuevo a Muigin al Cráter de Un'Goro.", desc = "A decir verdad, <nombre>, nunca he visto unas plantas como estas en ninguno de mis viajes. Puede que deba emprender un viaje a ese cráter...\n\nEn todo caso, sé exactamente qué es lo que está buscando Muigin: la bruma Atal'ai. Se trata de algo horrible, muy difícil de conseguir, pero es justo lo que él necesita para controlar a esos pequeños monstruos.\n\nTendrás que hacer una visita al templo de Atal'Hakkar, en el Pantano de las Penas. La bruma Atal'ai se puede obtener de los rondadores de las profundidades, los gusanos de la oscuridad y los mocos que hay allí. ¡Buena suerte, <nombre>!", objectives = { "Calima Atal'ai x 5" } },
    [4145] = { title = "Larion y Muigin", summary = "Caza 5 latigadores Pétalo de Sangre, 5 trilladores Pétalo de Sangre, 5 desolladores Pétalo de Sangre y 5 tramperos Pétalo de Sangre para Larion en el Refugio de Marshal.", desc = "¿Has visto a Muigin por allí? ¡Es culpa SUYA que estemos perdidos!\n\nYo era el que conocía el camino, pero él insistió en coger un atajo, ¡y mira dónde acabamos!\n\nY por si fuera poco no para de mandarme sus plagas vegetales para fastidiarme. Estoy tan enfadado que no pienso hablarle en un buen tiempo, pero estas plagas son demasiado.\n\nLo primero que deberíamos hacer es intentar limitar su suministro. Sal y caza algunos pétalos de sangre, cuando los tengas vuelve a verme.", objectives = { "Latigador pétalo de sangre x 5", "Trampero pétalo de sangre x 5", "Despellejador pétalo de sangre x 5", "Trillador pétalo de sangre x 5" } },
    [4146] = { title = "Combustible de irradior", summary = "Entrega el Controlador descargado y 5 muestras de bruma Atal'ai a Larion, en el Refugio de Marshal.", desc = "¡Estás de suerte, <nombre>! He estado trabajando en algunos experimentos mientras Marvon estaba fuera, y uno de ellos es un controlador vírico de corto alcance. Con algunos ajustes debería ayudarte a librarte de esas pestes de pétalo de sangre.\n\nPuedo dejarte uno de los prototipos del controlador, pero tendrás que hacerte tú con el combustible. Podrás conseguir la bruma Atal'ai necesaria para el controlador en El Templo de Atal'Hakkar. La obtendrás de los rondadores de las profundidades, de los gusanos de la oscuridad y de los mocos.", objectives = { "Calima Atal'ai x 5" } },
    [4147] = { title = "El taller de Marvon", summary = "Viaja hasta el taller de Marvon Buscarroblones en Trinquete.", desc = "He conseguido espiar a Muigin y ya sé qué está haciendo, ¡está cultivando esas malditas cosas ahí mismo!\n\nCreo que la única opción que nos queda... no, no es ir a hablar con él... ¿en qué estás pensando? ¡La solución es contraatacar!\n\nNecesitaremos la ayuda de mi amigo, Marvon, tiene un taller en Trinquete. Seguro que podrá crear algún artilugio para ayudarnos." },
    [4182] = { title = "La amenaza de los dragonantes", summary = "Mata 15 cachorrillos negros, 10 dragauros negros, 4 vermis negros y 1 draco negro. Vuelve junto a Helendis Rivacuerno cuando hayas acabado la tarea.", desc = "La vida en Las Estepas Ardientes está plagada de enfrentamientos.\n\n¡Fíjate en este lugar! No sabemos mucho de lo que ha ocurrido con estos edificios, pero sí sabemos que antaño, antes de la gran explosión, esto era parte de las Montañas Crestagrana.\n\n¡Basta de lamentos! Tenemos un problema, <nombre>. Puede que te hayas fijado en los dragonantes al pie de estas colinas. Necesitamos ayuda para ahuyentarlos. Mata a tantos como puedas y vuelve aquí. Si lo logras, a lo mejor seguimos hablando.", objectives = { "Cachorrillo negro x 15", "Dragauro negro x 10", "Draco negro", "Vermis negro x 4" } },
    [4183] = { title = "Los verdaderos maestros", summary = "Viaja a Villa del Lago y entrégale la carta de Helendis Rivacuerno al magistrado Salomón.", desc = "Siempre habíamos creído que los orcos Roca Negra eran el producto de su salvaje educación. Lo que hemos hallado aquí, en su patria, nos muestra una cara diferente.\n\nDesde luego, la sed de sangre y de enfrentamientos los mueve pero son los Vuelos negros quienes controlan a los orcos Roca Negra. Sospechamos que los Vuelos negros no hacen más que echar leña al fuego de su furia y hostilidad.\n\nLlévale esta carta al magistrado Solomon. Él sabrá qué hacer.\n\n<Helendis te entrega una carta sellada.>" },
    [4184] = { title = "Los verdaderos maestros", summary = "Ve a Ventormenta para entregar la petición de ayuda de Solomon al Gran Señor Bolvar Fordragon. Vive en el Castillo de Ventormenta.", desc = "Qué sombrías nuevas, <nombre>. Descubrir que nuestros enemigos mortales no son más que marionetas de una amenaza mayor es muy desalentador. Villa del Lago no podría hacer frente a un ataque común de los orcos Roca Negra y los Vuelos negros. Si Villa del Lago cae, Villa Oscura caerá también, ¿y qué pasará entonces? ¿Villadorada? ¿La mismísima Ventormenta?\n\n¡Debes llevar estas nuevas al Gran Señor Bolvar Fordragon en Ventormenta de inmediato! Si Ventormenta no nos ayuda, nada lo hará y todo se habrá perdido." },
    [4185] = { title = "Los verdaderos maestros", summary = "Habla con el Alto Señor Bolvar Fordragon después de hablar con Lady Katrana Prestor.", desc = "Solomon describe una imagen terrible. Sin embargo, no podemos permitirnos enviar a nuestras escasas tropas en ayuda de Villa del Lago basándonos en especulaciones. Necesitaré pruebas de esos hechos antes de poder actuar.\n\nHabla con Lady Prestor, <nombre>. Es una mujer inteligente y sabe mucho sobre dragones y dragonantes. Quizás pueda ayudarnos a comprender mejor la situación.", objectives = { "Consejo de Lady Prestor" } },
    [4186] = { title = "Los verdaderos maestros", summary = "Lleva el decreto de Bolvar al magistrado Salomón en la Villa del Lago.", desc = "Voy a nombrarte diputado representante de Ventormenta, <nombre>.\n\nVuelve a ver al magistrado Solomon en Villa del Lago y entrégale este decreto." },
    [4201] = { title = "La poción de enamoramiento", summary = "Llévale 4 gromsanguinas, 10 venas de plata gigantescas y el vial lleno de Nagmara a la maestra Nagmara en las Profundidades de Roca Negra.", desc = "¡Ah, el sufrimiento del amor! Mi querido soldado Sinroca es inmune a mis encantos. ¡Me rechaza! ¡Me lleva por la calle de la amargura!\n\n¡Tienes que ayudarme! Las sucubis sabemos mucho de amor y puedo hacer una poción para que derrita el telón de acero que rodea el corazón de Sinroca. Para hacerla, necesito estos elementos: hierba gromsanguina, venas de plata gigantescas de los gigantes de los acantilados de Azshara, y agua del Cráter Manantial de Golakka en Un'Goro. Toma este vial para el agua.\n\nTe lo ruego, <nombre>, ¡ayuda a un alma desgraciada a alcanzar su felicidad!", objectives = { "Gromsanguina x 4", "Veta gigante de plata x 10", "Vial de Nagmara lleno" } },
    [4223] = { title = "Los verdaderos maestros", summary = "Habla con el alguacil Maxwell en Las Estepas Ardientes.", desc = "<Suspira.>\n\n<nombre>, tienes que volver a Las Estepas Ardientes. Como ayudante del alguacil de Ventormenta, estarás a las órdenes del mariscal Maxwell. Suerte." },
    [4224] = { title = "Los verdaderos maestros", summary = "Habla con John Andrajoso para averiguar el destino del alguacil Windsor y vuelve junto al alguacil Maxwell cuando hayas completado la tarea. Recuerdas que el alguacil Maxwell comentó algo sobre buscarlo en una cueva hacia el norte.", desc = "¡¿Qué?! ¿Creías ser el primero? ¿Cuántos soldados debemos perder antes de que Ventormenta actúe?\n\nHabíamos reunido muchísima información sobre la amenaza de los Roca Negra antes de perder a nuestro oficial jefe, el alguacil Windsor. Con el alguacil Windsor perdimos todos esos valiosos datos.\n\nTenemos que recuperar esa documentación. Habla con John Andrajoso, <nombre>. Se encontraba con Windsor cuando un grupo de Roca Negra los asaltó. La última vez que lo vieron estaba en una caverna hacia el norte.", objectives = { "La historia de John Andrajoso" } },
    [4241] = { title = "El alguacil Windsor", summary = "Viaja a la Montaña Roca Negra al noroeste y adéntrate en las Profundidades de Roca Negra. Averigua qué le ha ocurrido al alguacil Windsor. Recuerdas que John Andrajoso había comentado que se habían llevado a una cárcel a Windsor.", desc = "Así que ese cobarde inútil dice que Windsor está vivo, ¿eh?\n\nNo me viene mal, ayudante, vas a salir en su búsqueda. Si Windsor está vivo, vas a traérmelo. Si está muerto, quiero una prueba.\n\n<Maxwell suelta una carcajada.>\n\nApuesto a que te estás cansando de oír eso, ¿a que sí?" },
    [4242] = { title = "Esperanza perdida", summary = "Dale las malas noticias a alguacil Maxwell.", desc = "“Bolvar es un idiota. Estaba recogiendo su preciosa “”prueba”” para que él pudiera engullirla.\n\nPero ese payaso ve menos que un gato de escayola. Con la prueba a medio metro de él y no la ve.\n\nPor lo que sé, se ha perdido. Adiós. Y no se puede recuperar.\n\nSi alguna vez encuentro a Ferromazo y consigo salir de este laberinto, mi primera parada será Ventormenta, para dejarle bien señalado mi martillo entre los ojos a ese reptil.\n\nMárchate, <nombre>.”" },
    [4262] = { title = "Gran maestro Pyron", summary = "Mata al gran maestro Pyron y vuelve junto a Jalinda Sprig. Recuerdas que Jalinda dijo que Pyron guardaba la cantera. Quizás deberías empezar a buscar allí.", desc = "Mis últimos cinco magos que salieron a husmear por la Montaña Roca Negra volvieron rustiditos y crujientes o algo peor.\n\n<Jalinda recoge unas cenizas del suelo y las suelta en el aire.>\n\nUn asqueroso granuja en especial, el gran maestro Pyron, parece estar causando más de un quebradero de cabeza. ¡Tenemos que aniquilar a ese elemental para que los miembros de nuestra expedición puedan llegar a las Profundidades de Roca Negra!\n\nLo encontrarás custodiando la entrada de la cantera de Roca Negra.", objectives = { "Gran Maestro Pyron" } },
    [4263] = { title = "¡Incendius!", summary = "Encuentra a Lord Incendius en las Profundidades de Roca Negra ¡y acaba con él!", desc = "“¿Estás <seguro/segura> de que Pyron dijo “”Incendius”” cuando murió?\n\n<Jalinda traga saliva con dificultad.>\n\n¡Se afirma que Lord Incendius es un esbirro de Ragnaros! ¡Qué terrible desgracia!... ¿qué podemos hacer?\n\n¿Crees que podrías encargarte de otra misión? ¡No me queda nadie a quien recurrir, <nombre>!\n\nNunca conseguiremos infiltrar a un equipo si Incendius sigue resucitando a Pyron de las cenizas.\n\n¡Tendrás que encontrar a Lord Incendius y destruirlo!\n”", objectives = { "Lord Incendius" } },
    [4264] = { title = "Una nota arrugada", summary = "Puede que acabes de toparte con algo que le interesaría ver al alguacil Windsor. Puede que haya esperanza, después de todo.", desc = "La nota está cubierta de manchas. Es apenas legible, aunque se llega a ver lo siguiente:\n\n... qué ironía tan oportuna...\n\n... la caída de la Alianza rota...\n\n... si no fuera por la diligencia del general Forjafuria, es posible que jamás hubiésemos descubierto la clave de la codificación...\n\n... Argelmach casi ha acabado de descifrar los apuntes de Windsor.\n\nNuestro señor surgirá de las profundidades y aplastará cualquier resto...\n\n-Emperador Dagran Thaurissan." },
    [4282] = { title = "Una esperanza hecha trizas", summary = "Devuélvele al alguacil Windsor la información perdida. El alguacil Windsor cree que la información está siendo retenida en manos del Señor Gólem Argelmach y del general Forjira.", desc = "<El alguacil Windsor agita la nota claramente excitado.>\n\n¿Te das cuenta de lo que esto significa, <nombre>?\n\n¡Quizás no todo esté perdido! Por lo que puedo establecer, la información está en manos de dos enanos Hierro Negro: el general Forjafuria y el gólem lord Argelmach. Me da que no nos facilitarán esta información si se lo pedimos con educación.\n\nEspero que estés <listo/lista> para el combate.\n\n¡Sal a luchar y encuéntrame a esos dos villanos! Destrúyelos y vuelve con la información perdida.", objectives = { "Información perdida del alguacil Windsor", "Información perdida del alguacil Windsor" } },
    [4286] = { title = "Buena mercancía", summary = "Viaja a las Profundidades de Roca Negra y recupera 20 riñoneras Hierro Negro. Vuelve junto a Oralius cuando hayas completado esta tarea. Se da por sentado que los enanos Hierro Negro de las Profundidades de Roca Negra llevan estos inventos de riñoneras.", desc = "El capitán Winky me dice que los Hierro Negro de las Profundidades tienen todo lo bueno. ¿No es cierto, Winky?\n\n<Oralius imita lo mejor que puede a un pirata.>\n\n¡ARRR COLEGA! ¡DAGUTEN!\n\n¿Ves a qué me refiero? Tienes que ir allí y traerme unas muestras de esa mercancía tan buena.\n\n¡Ve y al rico dinerito!", objectives = { "Talega extraña Hierro Negro x 20" } },
    [4322] = { title = "La fuga de la prisión", summary = "Ayuda al alguacil Windsor a recuperar su equipo y a liberar a sus amigos. Vuelve junto al alguacil Maxwell si lo consigues.", desc = "Tenemos que salir de aquí, <nombre>. Ayúdame a recuperar mi equipo del área de suministros y a liberar a mis amigos. Si conseguimos escapar, irás a la Vigilia de Morgan y hablarás con el alguacil Maxwell. Él te dará más instrucciones.", objectives = { "¡Fuga!" } },
    [4324] = { title = "Yuka Llavenrosca", summary = "Habla con Yuka Llavenrosca en Las Estepas Ardientes.", desc = "Aunque mi hermano pequeño Ribbly ha sido un inútil toda su vida, ¡creo que por fin tiene algún valor! Pero... podríamos necesitar tu ayuda para sacar partido a ese nuevo valor de Ribbly.\n\nMi hermana Yuka lleva semanas buscándolo y la pista lleva a Las Estepas Ardientes. Me ha pedido que contrate ayuda.\n\nBueno, ¿qué me dices? ¿Quieres ayudar? Si estás de acuerdo, habla con mi hermana. La encontrarás escondida en el Peñasco Llamarada, una cueva al noroeste de la Roca Machacamiedo." },
    [4341] = { title = "Kharan Martillazo", summary = "Ve a las Profundidades de Roca Negra y encuentra a Kharan Martillazo. El rey dijo que estaba prisionero allí; busca una cárcel.", desc = "¿Has estado en las ruinas requemadas de Thaurissan? ¿No te encontrarías con un patán que se llama Kharan Martillazo? ¡Ese enano tenía que cuidar a mi nena!\n\n<Solloza.>\n\n¡Ha desaparecido, <nombre>!\n\nMis hombres han recorrido las Estepas de punta a punta buscándola. La única pista que tienen sobre mi hija es que puede estar en las profundidades. ¡Ni siquiera sé si aún vive!\n\nParece que Kharan la tiene retenida... ¡ve y encuéntralo! ¡Quiero respuestas!" },
    [4361] = { title = "Portador de malas noticias", summary = "Regresa a Forjaz y dale las malas noticias al rey Magni Barbabronce.", desc = "Debes llevarle esta información al Rey Magni, <nombre>. ¡Él sabrá qué hacer!" },
    [4362] = { title = "El destino del reino", summary = "Vuelve a las Profundidades de Roca Negra y rescata a la princesa Moira Barbabronce de las garras del emperador Dragan Thaurissan.", desc = "Parece que tanto yo como el reino de Forjaz estamos a merced de mi antiguo enemigo, Dagran Thaurissan.\n\nEres mi última esperanza, <nombre>. ¡Rescata a mi querida Moira!\n\nSolo hay una forma de romper el hechizo que Thaurissan ha lanzado a mi hija: matarlo.\n\n¡Y tráeme a mi hija sana y salva, <nombre>! ¡Recuerda que está embrujada por Thaurissan! ¡Lo que haga o diga será por culpa de ese maléfico hechizo!", objectives = { "Emperador Dagran Thaurissan" } },
    [4701] = { title = "Acaba con el origen de la amenaza", summary = "Viajar hasta la Cumbre de Roca Negra y destruye el origen de la amenaza del lupo. Cuando dejaste a Helendis, gritó un nombre: Halycon. Es la palabra que los orcos usan para referirse al lupo.", desc = "No cabe duda de que has visto a los lupos a las órdenes de los orcos Roca Negra.\n\nEs extraño, matemos a los que matemos, no parece reducirse su número. Según los informes de mis rastreadores, los lupos se crían, se amaestran y se exportan desde la Cumbre de Roca Negra: la capital de los orcos Roca Negra. Debes viajar hasta la Cumbre de Roca Negra y descubrir el origen de esta amenaza. Descúbrelo… y destrúyelo.\n\nSuerte, <nombre>. Que Cenario te proteja...", objectives = { "Halycon" } },
    [4724] = { title = "La maestra de la manada", summary = "Mata a Halycon, empaqueta la Maestra del lupo Hacha de Sangre.", desc = "Unos dicen que los lupos controlados por los orcos Roca Negra son una creación de una fuerza sobrenatural. Otros dicen que no es un auténtico lupo sino una variedad de perro demoníaco, concedida a los orcos por un señor del infierno caído.\n\nLa verdad no es tan artificiosa aunque ciertamente igual de aterradora. Los lupos de Roca Negra proceden de Halycon y su pareja. Halycon la gigantesca Madre del Cubil del lupo. ¿Su pareja? Nadie ha vivido nunca para contarlo.\n\nDispara al corazón del lupo. Destruye a Halycon... y, <nombre>, que no te sorprendan por la espalda.", objectives = { "Halycon" } },
    [4726] = { title = "Esencia de cría", summary = "Llévale 8 esencias de cría y el Draco Incarcinatrix 900 a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes.", desc = "He estado estudiando a los dragonantes de Las Estepas Ardientes durante semanas ¡y creo que por fin tengo algo importante! He creado un dispositivo al que he llamado Draco Incarcinatrix 900. ¡Es capaz de capturar la esencia de los cachorros de dragón!\n\nO al menos eso pienso yo.\n\nToma, llévate el dispositivo a Las Estepas Ardientes y dispárale a un cachorro de dragón con él. Mientras está bajo los efectos del dispositivo, derrota al dragón y entonces se debería liberar su esencia.\n\nY si así es, ¡fantástico! ¡Tráeme muestras para que pueda examinarlas!", objectives = { "Esencia de cría x 8" } },
    [4729] = { title = "Las mascotas exótica de Kibler", summary = "Viaja hasta la Cumbre de Roca Negra y encuentra mascolupos Hacha de Sangre. Usa la jaula para transportar a esas feroces fierecillas. Llévale a Kibler 1 mascolupo enjaulado.", desc = "Debes de estar preguntándote qué hago aquí. ¡Fíjate en las jaulas! ¿Acaso no salta a la vista?\n\nSoy un amante de los animales ante todo aunque sea vendedor de profesión. Les sigo la pista a los animales exóticos para los ricos y los famosos y amaestro a esas bestias para que se comporten como mascotas normales.\n\nY ahora te preguntarás, \"¿Qué puedo hacer por ti, Kibler?\" La respuesta es sencilla: Llévate esta jaula de bestia y encuéntrame unos cachorros de lupo. Si lo haces, ¡amaestraré a un lupo para ti!", objectives = { "Joven lupo encerrado" } },
    [4734] = { title = "Un huevo congelado", summary = "Usa el prototipo de ovosciloscopio sobre un huevo de El Grajero.", desc = "<nombre>, he estado trabajando mucho en un nuevo dispositivo, ¡el ovosciloscopio! Está diseñado para proyectar energía fría sobre un huevo de dragón negro… ¡y congelarlo de una pieza! ¿Puedes probarlo para mí?\n\nHe oído que en la Cumbre de Roca Negra, los dragones tienen un grajero donde esconden sus huevos. Es el sitio ideal para probar el ovosciloscopio, ¡me muero por que me digas si ha funcionado!\n\nAh, y descuida, que los huevos de dragón congelados son inofensivos. ¡Los descongelados ya tienen más miga!", objectives = { "Prueba el prototipo de ovosciloscopio" } },
    [4735] = { title = "La colecta de huevos", summary = "Llévale 8 huevos de dragón y el módulo colectrónico a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes.", desc = "<nombre>, ¡por fin estoy lista para las muestras reales de huevos de dragón! Aquí tienes, toma este módulo colectrónico. Está diseñado para extraer un huevo de dragón y prepararlo para su transporte. Vuelve a El Grajero y utiliza el módulo para recolectar huevos.\n\n¡Y no te olvides de congelarlos primero o podrían merendarte antes!\n\nCuando tengas suficientes huevos, tráemelos!", objectives = { "Huevo de dragón recogido x 8" } },
    [4742] = { title = "El Sello de Ascensión", summary = "Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el Sello de Ascensión sin adornos a Vaelan. Los generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el Alto señor Omokk de los Cumbrerroca y el Señor Supremo Vermiothalak de los Hacha de Sangre.", desc = "Como verás, el sello sin adornos tiene tres ranuras vacías. En cada ranura hay que encajar una gema que representa el mando del liderazgo. Por último, el Señor Supremo Wyrmthalak, maestro de la ciudadela inferior, debe forjar el sello con las llamas del Vuelo negro.\n\nDebes entender esto, mortal: la probabilidad de que uno de los tres generales de la ciudadela inferior lleve una gema en cualquier momento es escasa. Debes estar muy atento en tu misión. ¡Mantén la determinación!", objectives = { "Gema de Cumbrerroca", "Gema de Espina Ahumada", "Gema de Hacha de Sangre", "Lacre de ascensión sin adornar" } },
    [4764] = { title = "El Broche de Equipasino", summary = "Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes.", desc = "En lo más alto de la Cumbre de Roca Negra, hay una cámara antaño llamada Sala de la Fortuna. Allí era donde los enanos Hierro Negro guardaban sus reliquias, trofeos y obras de arte.\n\nEso era hace mucho tiempo. Se dice que la sala se ha derrumbado y se usa hoy para... tareas menos limpias. Pero me parece que aún se encuentran allí antiguas reliquias de los enanos.\n\nUna de esas reliquias es el Broche de Equipasino, en cuya superficie hay engastadas gemas tan raras que, al parecer, cualquier enano que posa su vista en él se echa a llorar.\n\nEse broche, <nombre>, es nuestro objetivo.", objectives = { "Broche de Equipasino" } },
    [4766] = { title = "Mayara Alasol", summary = "Habla con Mayara Alasol en Las Estepas Ardientes.", desc = "Envié a una espía, Mayara Alasol, a Las Estepas Ardientes para que rastreara la ciudad en ruinas de Thaurissan. Puede que la asolada ciudad de los enanos Hierro Negro oculte objetos de gran valor... objetos que quedarían muy bien en el museo de nuestra familia.\n\nMayara dice que encontró algo y que necesitaría ayuda para recuperarlo pero no está en Thaurissan. Es en la Cumbre de Roca Negra adonde haría falta realizar una incursión.\n\nDesconozco los detalles pero si estás <interesado/interesada>, habla con Mayara en Las Estepas Ardientes." },
    [4768] = { title = "La tablilla de Rocanegra", summary = "Llévale la tablilla de Rocanegra a la maga oscura Vivian Latumba en Kargath.", desc = "La tablilla de Rocanegra contiene los escritos del enano Urheld Rocanegra fallecido mucho tiempo ha. Alquimista de gran talento, sus coetáneos lo tomaban por loco, de ahí que no compartiera sus hallazgos.\n\nPero sí lo dejó grabado en unas tablillas y creo que una de ellas se encuentra en la Cumbre de Roca Negra, en una cámara antaño llamada Sala de la Fortuna. Desconozco su nombre actual ya que pocos son los que han entrado en Roca Negra y han regresado.\n\nPero si estás <dispuesto/dispuesta> a afrontar sus peligros y traerme la tablilla, te recompensaré con creces.", objectives = { "Tablilla Rocanegra" } },
    [4769] = { title = "Vivian Latumba y la tablilla de Rocanegra", summary = "Habla con la maga oscura Vivian Latumba Vivian Latumba.", desc = "Vivian Latumba me ha enviado un mensaje desde Kargath, en las Tierras Inhóspitas. Sus estudios la llevan a creer que en la Cumbre de Roca Negra se encuentra un antiguo texto que podría ayudarnos en nuestra investigación. Para confirmarlo, necesita que alguien consiga el texto de la Cumbre. Ardua tarea sin duda.\n\nSi estás <interesado/interesada>, habla con Vivian en Kargath." },
    [4771] = { title = "Gambito del Alba", summary = "Coloca el Gambito del Alba en la Sala de la Visión de Scholomance. Derrota a Vectus y ve a ver a Betina Bigglezink.", desc = "He puesto el Gambito del Alba en el contenedor que has enviado, el que tenía los huevos de dragón. Tú tienes que llevarlo a las profundidades de Scholomance.\n\nEl mago no-muerto Vectus dirige un grupo de eruditos miembros de la Plaga. Coloca el Gambito del Alba en su cámara, llamada la Sala de la Visión. Hará reacción con los no-muertos y con un poco de suerte acabará con todos ellos.\n\nDespués no habrá problema en derrotar a Vectus, ¿no crees?", objectives = { "Vectus", "Coloca el Gambito del Alba" } },
    [4787] = { title = "El huevo antiguo", summary = "Llévale el huevo antiguo a Yeh'kinya, que está en Tanaris.", desc = "La profecía de Mosh'aru habla de un antiguo huevo. Es una reliquia de un tiempo en el que los trols gobernaban extensos imperios y tiene el poder de retener la esencia de Hakkar. Puede que sea el único modo de proteger nuestro mundo de su maldad.\n\nTráeme el antiguo huevo, <nombre>. Se dice que permanece oculto en Jintha'Alor en las Tierras del Interior, en una cueva bajo el anfiteatro en la parte alta de la ciudad.", objectives = { "Huevo antiguo" } },
    [4788] = { title = "Las últimas tablillas", summary = "Llévale la quinta y sexta tablillas de Mosh'aru al prospector Ferrobota, que está en Tanaris.", desc = "Mientras yo examino la tercera y cuarta tablillas de Mosh'aru, ¡tú tienes que encontrar la quinta y la sexta! No será fácil pues obran en poder de los trols Espina Ahumada en Cumbre de Roca Negra. Esta cumbre es una oscura montaña de fuego situada entre Las Estepas Ardientes y La Garganta de Fuego.\n\nBuena suerte, <nombre>. Cumbre de Roca Negra no es un lugar para pundonorosos...", objectives = { "Quinta tablilla Mosh'aru", "Sexta tablilla Mosh'aru" } },
    [4808] = { title = "Felnok Acerovera", summary = "Entrégale la carta de Tinkee a Felnok Acerovera.", desc = "Necesitaría otro favor de ti.\n\nMi estudio inicial de la esencia que has recolectado indica que ¡cabría la posibilidad de congelar huevos de dragón y conservarlos! Quiero probar esta teoría pero antes necesito unos componentes especialmente diseñados para este fin. Mi colega, Felnok Acerovera, puede fabricarlos.\n\nAquí tienes una carta para Felnok. En ella le cuento lo que necesito. Encontrarás a Felnok en la Cuna del Invierno, en la ciudad de Vista Eterna." },
    [4809] = { title = "Cuernos de quimera venfresco", summary = "Llévale 8 cuernos de quimera venfresco sin fisuras a Felnok Acerovera.", desc = "Ya tengo la mayoría de lo que necesita Tinkee, aunque me falta un componente importante: cuernos de quimera del Orvallo. Los podrás encontrar en Cuna del Invierno. Estos cuernos son una fuente concentrada de frío, pero solo sirven los prístinos e intactos. Para completar la orden de Tinkee voy a necesitar algunos.\n\nTráemelos y prepararé el paquete.", objectives = { "Cuerno de quimera Orvallo x 8" } },
    [4810] = { title = "Vuelve con Tinkee", summary = "Llévale el paquete de Felnok a Tinkee Vaporio en Las Estepas Ardientes.", desc = "Muy bien, ¡todo está empaquetado y listo para que lo lleves! ¡Suerte en tu viaje y no olvides de decirle a Tinkee que me debe una!" },
    [4862] = { title = "Bestia amaestrada", summary = "Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler. Yo diría que se pueden encontrar estos huevos cerca de arañas.", desc = "Lo creas o no, ¡hay gente dispuesta a pagar por la más malvada de las bestias amaestradas!\n\nHabía enviado a Bijou a la Cumbre para tratar de recolectar algunos de esos huevos de araña pero hace semanas que no sé nada de ella. ¿A lo mejor puedes ayudarme?\n\nPues, verás, <nombre>, ve a la Cumbre de Roca Negra y recoge unos huevos de araña para mí. Tráemelos aquí y no solo te daré dinero sino que además ¡amaestraré a uno para ti!", objectives = { "Huevo de araña de la cumbre x 15" } },
    [4866] = { title = "La leche de la madre", summary = "En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti.", desc = "“¡Es probablemente uno de los venenos más potentes del mundo, <raza>!\n\nSorprendí a los Roca Negra hablando sobre cuán letal era en una de mis incursiones en la Cumbre. Lo llaman “la leche de la madre” por Madre Telabrasada, la enorme y asquerosa araña de la caverna Arácnida.\n\nBien, esto es lo que necesito de ti: una muestra viva de la leche, fluyendo por TUS venas. ¡No bastará con traerme la glándula! ¡Consigue que te envenene y vuelve aquí!\n\nEntonces... ¡te ordeño!\n\n<Se frota las manos anticipando el éxito.>”", objectives = { "Ordeñada" } },
    [4867] = { title = "Urok Doomhowl", summary = "Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh.", desc = "¡Argh! ¡Cuesta tanto hablar!\n\n¡Toma esta nota! ¡Consigue mi mojo!", objectives = { "Mojo de Warosh" } },
    [4903] = { title = "La orden del Señor de la Guerra", summary = "Mata al Alto señor Omokk, al maestro de guerra Voone y al Señor Supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión.", desc = "Por orden del señor de la guerra Dientegore, los siguientes habitantes de la Cumbre de Roca Negra deben ser destruidos:\n\nLa voluminosa amenaza, Gran Señor Omokk.\n\nEl cruel y malvado trol, maestro de guerra Voone.\n\nSeñor Supremo Wyrmthalak, maestro de tareas de la ciudad menor.\n\nSe requerirá asimismo la devolución de cualquier documento importante que se encuentre.\n\nConsíguelo y tuyos serán los honores.\n\nFracasa y caerás en el olvido.", objectives = { "Señor Supremo Vermiothalak", "Alto Señor Omokk", "Maestro de guerra Voone", "Importantes documentos de Roca Negra" } },
    [4941] = { title = "La sabiduría de Eitrigg", summary = "Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall. Recuerdas haber visto a Eitrigg en la Cámara de Thrall.", desc = "¿Rend vive?\n\n¡Imposible!\n\nSe pensaba que Rend había sido ejecutado hace décadas.\n\nVe en busca de la sabiduría de Eitrigg, <nombre>. Nadie conoce a los Roca Negra mejor que él y si hay algo de verdad en este escrito, debemos informar a Eitrigg. A nadie se le debería negar el derecho a vengarse.\n\nLo encontrarás en Orgrimmar.\n\nCuando hayas hablado con Eitrigg, consulta con el Jefe de Guerra para ver qué desea hacer para resolver este problema.", objectives = { "Habla con Eitrigg." } },
    [4974] = { title = "¡Por la Horda!", summary = "Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Llévale su cabeza a Orgrimmar.", desc = "Rend osa actuar así porque cuenta con la protección de Vuelo Negro.\n\nHas de encontrar el modo de cruzar las Salas de la Ascensión. Debes localizar a Rend Puño Negro y acabar con él, ¡por la Horda!\n\n<Da un puñetazo en el trono.>\n\nLa próxima vez que vengas, llevarás su cabeza en la mano. Después irás a enseñársela a tu Jefe de Guerra. La Horda te honrará como te mereces.", objectives = { "Cabeza de Rend Puño Negro" } },
    [4981] = { title = "La espía Bijou", summary = "Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou.", desc = "Nunca te fíes de un goblin. De eso se trata, <nombre>.\n\nSe llama Bijou, una de nuestras agentes más escurridizas. Averigüé que estaba trabajando para algún sospechoso vendedor de mascotas exóticas de Las Estepas Ardientes llamado Kibler, en esencia, dos compitiendo con nosotros. Y lo que es peor, estaba usando fondos de la Horda para financiar sus operaciones.\n\nLa quiero de vuelta aquí viva.\n\nLa vieron por última vez entrando en la Cumbre de Roca Negra. Encuéntrala y tráela.\n\nY, <nombre>, que no te engatuse con sus zalamerías." },
    [5001] = { title = "Las pertenencias de Bijou", summary = "Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!", desc = "No suelo tratar con <raza>s pero parece que estoy atrapado entre un trol y un lugar hostil. Verás, mi misión aquí es de la más alta importancia para la Horda. La información que he descubierto, sin embargo, también se aplica al bienestar de la Alianza. Créeme, no simpatizo en absoluto con la Alianza, pero la amenaza de los Roca Negra es mucho mayor que la de un puñado de orcos.\n\nTú me ayudas a recuperar mis pertenencias y yo te facilitaré información que será útil para los de tu especie.\n\n¿Hay trato?", objectives = { "Pertenencias de Bijou" } },
    [5047] = { title = "¡Finkle Unicornín, a tu servicio!", summary = "Habla con Malyfous Martilloscuro en Vista Eterna.", desc = "“Encontrarás a Malyfous Martilloscuro en Vista Eterna, <clase>. Dile que “”Finkle está muy contento”” y que el traje funciona de perlas.\n\nEntonces entrégale esto:\n\n<Finkle te tiende un trozo de carne brillante.>\n\nEs un pedazo de las entrañas de la bestia en la que pasé mis \"vacaciones\".\n\n¡Apuesto a que Malyfous te dará una idea bastante precisa de lo que puede hacer con una parte de un monstruo como este!\n\nAh, supongo que no sabes donde está Vista Eterna, ¿verdad? ¡Pon rumbo a la Cuna del Invierno, <amigo/amiga>!\"" },
    [5065] = { title = "Las tablillas perdidas de Mosh'aru", summary = "Llévale la tercera y cuarta tablillas de Mosh'aru al prospector Ferrobota, que está en Tanaris.", desc = "El trol con el que has hablado no te ha dicho la verdad. Es cierto que las dos tablillas que conseguiste para él explican el modo de retener la esencia de Hakkar, pero la leyenda no acaba ahí. Llevo mucho tiempo investigando y he descubierto que existen seis tablillas de Mosh'aru y no dos. ¡Seis!\n\nY mucho me temo que los secretos que albergan no serán de nuestro agrado...\n\nLocaliza la tercera y cuarta tablillas de Mosh'aru. Se encuentran en las Tierras de la Peste del Este en posesión de los trols Fustamusgo. Encuéntralas y tráemelas aquí.", objectives = { "Tercera tablilla Mosh'aru", "Cuarta tablilla Mosh'aru" } },
    [5089] = { title = "Orden del general Drakkisath", summary = "Llévale la orden del general Drakkisath al alguacil Maxwell en Las Estepas Ardientes.", desc = "En el cadáver del reptil derrotado descubres lo que parece ser una nota de cierta importancia: una carta de su superior, el general Drakkisath, sobre protocolo.\n\nTu instinto te dice que deberías llevársela al alguacil Maxwell." },
    [5102] = { title = "Muerte al general Drakkisath", summary = "Viaja hasta la Cumbre de Roca Negra y mata al general Drakkisath. Vuelve junto al alguacil Maxwell cuando hayas acabado tu trabajo.", desc = "Luchamos contra estos animales en dos frentes: Desde nuestra capital de Ventormenta luchamos desde el interior y aquí, en Las Estepas Ardientes, libramos la batalla en su puerta. Debemos estar atentos, <nombre>. Nadie debe librarse de nuestra ira, como ellos tampoco perdonaron nada en su asalto a nuestros hogares y familias.\n\nEncuentra al general Drakkisath ¡y destrúyelo!\n\nCiertamente la tarea no será sencilla pero la recompensa será extraordinaria.", objectives = { "General Drakkisath" } },
    [5122] = { title = "El medallón de Fe", summary = "El poder de esta capilla me da la fuerza para resistir la corrupción que habita en mi corazón. Si cedo, me convertiré en un caballero de la muerte. Pero hay un medallón, el medallón de fe, que me dará la fuerza que necesito para partir. Por favor, <nombre>, recupera el medallón. Está en manos de Malor el Fanático, un miembro demente de la Hermandad Escarlata, que reside en las profundidades del Bastión Escarlata en Stratholme occidental.", objectives = { "Medallón de Fe" } },
    [5125] = { title = "La estimación de Aurius", summary = "<nombre>, me estoy muriendo... pero mi alma está salvada. Por eso, te debo más de lo que jamás podré expresar. Por favor, acepta esto, ¡y sigue luchando... valiente <clase>!" },
    [5126] = { title = "La historia de Lorax", summary = "Habla con Lorax. Escucha todo lo que tiene que decirte.", desc = "El sátiro da vueltas y habla consigo mismo. ¿Quieres preguntarle algo?", objectives = { "Escucha el relato de Lorax" } },
    [5127] = { title = "La forja demoníaca", summary = "Viaja a la Cumbre de Roca Negra y encuentra a Goraluk Yunquegrieta. Mátale y utiliza el Pico manchado de sangre sobre su cadáver. Cuando hayas absorbido su alma, el pico estará manchado de alma. También debes encontrar el peto cubierto de runas sin forjar. Lleva el pico manchado de alma y el peto cubierto de runas sin forjar a Lorax en Cuna del Invierno.", desc = "Lorax hace tratos, y no los acepta de insignificantes mortales.\n\nPero un trato haré contigo... coge este pico, está imbuido con poderosas energías malditas. Cuando encuentres a Goraluk Yunquegrieta, mátalo y atraviesa su corazón agonizante con este pico. Se hará un intercambio con su alma, su alma yo tendré. Devuelve el pico y devuelve el peto que robó el ladrón y te enseñaré lo que él iba a aprender.", objectives = { "Pica manchada de alma", "Peto cubierto de runas sin forjar" } },
    [5160] = { title = "El Protectorado de la matrona", summary = "Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee.", desc = "Viaja a Kalimdor, <raza>. Nuestro vuelo encuentra su hogar en el gélido paisaje de la Cuna del Invierno. Cuando llegues a la Cuna del Invierno, encuentra las cavernas de Mazthoril.\n\nEn los helados suelos de Mazthoril encontrarás runas de cobalto. Con una de mis escamas en la mano, ponte de pie sobre una runa y te verás transportado hasta Haleh, nuestra madre protectora.\n\nDale la escama para que pueda ver lo que he visto y sentido, aquí en este condenado lugar." },
    [5212] = { title = "La carne no miente", summary = "Recoge 20 muestras de carne infestada de Stratholme y vuelve con Betina Bigglezink. Sospechas que podrías obtener una muestra de cualquier criatura de Stratholme.", desc = "Los boticarios Renegados no son los únicos seres de este mundo versados en las ciencias.\n\nYo he estudiado la Peste de la Plaga durante años, <raza>. Pensábamos que la potencia de la plaga había mermado, pero lo que he descubierto aquí, en las Tierras de la Peste es alarmante. ¡La plaga está cobrando fuerza!\n\n¡Necesito hacer más pruebas! La fuente más potente de plaga se encuentra en la carne infestada de sus víctimas más recientes. Viaja a Stratholme y tráeme algunas muestras, <nombre>.", objectives = { "Muestra de carne con peste x 20" } },
    [5213] = { title = "El agente activo", summary = "Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink.", desc = "Tendrás que adentrarte más en Stratholme, <nombre>.\n\nDetrás de las primeras puertas encontrarás a los ziggurats. Sabemos que la Plaga extrae un gran poder de esas estructuras. Examina los ziggurats y vuelve con cualquier información que consigas.", objectives = { "Datos de la Plaga" } },
    [5214] = { title = "El gran Fras Siabi", summary = "Encuentra la Tienda de humo de Fras Siabi en Stratholme y recupera una caja del tabaco de calidad de Siabi. Cuando lo hayas hecho, vuelve con Smokey LaRue.", desc = "Es terrible... lo que le ocurrió a Fras. Verás, saquearon el pueblo y Fras no quería dejar sus preciados bienes atrás. Lo último que recuerdo es que decía que quemaría hasta la última hoja antes de permitir que ellos les pusieran sus sucias y malditas manos encima.\n\nDisfruto un buen cigarro como el primero, pero no soy tonto. Aquel día dejé atrás a Fras y a su aromático almacén. Supongo que todo fue pasto de las llamas, pero si hubiera sobrevivido aunque fuera una sola caja de su famoso tabaco...\n\n¿Qué dices, <nombre>? ¿Encontrarás una caja para el viejo Smokey?", objectives = { "Tabaco de calidad de Grimm" } },
    [5243] = { title = "Las casas de lo sagrado", summary = "Viaja al norte, a Stratholme. Registra los cajones de provisiones que hay por toda la ciudad y recupera 5 de agua bendita de Stratholme. Vuelve junto a Leonid Barthalomew el Venerado cuando hayas reunido suficiente líquido bendecido.", desc = "Yo considero mi no-muerte como una enfermedad, <raza>. Una que hay que curar, sin más. Pero también la considero una gran bendición para el Alba Argenta. ¿Qué mejor medio hay para atacar a los paganos de la Plaga que los no-muertos?\n\nMis colegas me veneran por los sacrificios que he hecho, pero los elogios para mí no significan nada.\n\nSi te interesa ayudar al Alba Argenta, puedo ofrecerte un trabajo.\n\nVe a Stratholme y recupera nuestro excedente de agua sagrada. Busca en las cajas de suministros.", objectives = { "Agua bendita de Stratholme x 5" } },
    [5251] = { title = "El archivista", summary = "Viaja a Stratholme y encuentra al archivista Galford de La Cruzada Escarlata. Acaba con él y quema el Archivo Escarlata.", desc = "Cualquier cosa llevada al extremo es dañina para nuestro mundo, <nombre>. Piensa, por ejemplo, en la Cruzada Escarlata. ¿Crees que su ciego fanatismo sirve de verdad a un buen superior? ¿A cuántos inocentes han matado en nombre de la Luz?\n\n¡Son todos unos blasfemos! ¡Todos y cada uno de ellos!\n\nPero a mí me interesa uno en concreto: el archivista Galford de Stratholme: Un hombre por cuyas manos pasan los más valiosos documentos de la Cruzada. ¡Destrúyelo y quema su archivo! Si lo consigues, vuelve a mí y serás <recompensado/recompensada>.", objectives = { "Archivista Galford", "Archivo quemado" } },
    [5262] = { title = "La verdad cae del cielo", summary = "Lleva la cabeza de Balnazzar al Duque Nicholas Zverenhoff en las Tierras de la Peste del Este.", desc = "Intentas poner tus pensamientos en orden mientras el polvo se asienta en la sala. Repasas los sucesos que han ocurrido y todavía no llegas a comprender la gravedad de la situación.\n\n¿El Gran Cruzado de la Cruzada Escarlata es un demonio? Y no cualquier demonio, ¡sino el hermano de Varimathras, archiseñor de Entrañas!\n\nGuardas con cuidado la cabeza cortada del Señor del Terror en tu talega. Seguro que nadie se creería lo que ha pasado sin ver una prueba.\n\n¡Hay que decírselo al Duque Nicholas Zverenhoff inmediatamente!" },
    [5263] = { title = "Por encima y más allá", summary = "Viaja a Stratholme y acaba con el barón Osahendido. Coge su cabeza y vuelve con el duque Nicolas Zverenhoff.", desc = "Tienes una aptitud natural para la destrucción y además obedeces las órdenes. Son dos cosas que rara vez coexisten en un mismo espíritu. Empiezo a pensar que podrías ser un excelente vehículo de la justicia divina.\n\n<Zverenhoff junta las manos delante de su cara.>\n\nEl chico de los recados de Kel'Thuzad reina en Stratholme. Pruébame que eres <todo un campeón/toda una campeona>, mi <campeón/campeona>. Destruye al Barón Osahendido y vuelve a mí con su cabeza.", objectives = { "Cabeza de Barón Osahendido" } },
    [5281] = { title = "Espíritus inquietos", summary = "Encuentra a Egan. Solo sabes que fue visto por última vez en los alrededores de Stratholme.", desc = "Ahí están aquellos que murieron trágicamente en la caída de Stratholme. Muchos se quitaron la vida. Prefirieron arrojarse a las llamas que arrasaban la ciudad a convertirse en miembros de la Plaga.\n\nAhora sus espíritus inquietos deambulan por las calles de Stratholme.\n\nDebemos ayudarles, <nombre>.\n\nTengo un socio llamado Egan que hace un trabajo maravilloso, casi milagroso, con fantasmas y almas. Ve a buscarlo. Estará por las Tierras de la Peste del Este, cerca de Stratholme, probando sus innovaciones." },
    [5282] = { title = "Espíritus inquietos", summary = "Utiliza el libertador de Egan en los ciudadanos espectrales y fantasmas de Stratholme. Cuando las almas se liberen de sus recipientes fantasmales, vuelve a usarlo y lograrás liberarlos para siempre. Libera 15 almas y regresa a Egan.", desc = "Yo extraigo mi poder –mi voluntad de seguir viviendo y respirando– del ardiente odio que siento por la Plaga y por todo lo que ha hecho. Sin embargo, no soy un fanático. Hay quienes preferirían destruir a los inocentes no-muertos antes que mostrarles siquiera una migaja de compasión, como la Cruzada Escarlata.\n\nY eso es lo que me hizo crear esto: Mi libertador. Liberará a las almas atormentadas de Stratholme.\n\nUtilízalo en los fantasmas que vagan por sus calles ruinosas. Libera sus almas.", objectives = { "Almas liberadas x 15" } },
    [5341] = { title = "La fortuna de la familia Barov", summary = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras del Molino Tarren y Las escrituras de Costasur. Regresa con Alexi Barov cuando hayas terminado esta tarea.", desc = "En el interior de Scholomance se encuentra la fortuna familiar de los Barov. Yo, Alexi Barov, soy uno de los dos últimos herederos de la casa Barov. Mi hermano, Weldon, es el otro.\n\nWeldon, ese despreciable cobarde, huyó durante la guerra y pudo conservar su miserable existencia humana.\n\nAhora está buscando las escrituras para poder reclamar para sí esa fortuna. ¡Recupera las escrituras antes que mi hermano y te haré más <rico/rica> que en tus sueños más descabellados!", objectives = { "Las escrituras de Rémol", "Las escrituras de Castel Darrow", "Las escrituras de Costasur", "Las escrituras de Molino Tarren" } },
    [5343] = { title = "La fortuna de la familia Barov", summary = "Aventúrate a Scholomance y recupera la fortuna familiar de los Barov. La fortuna se compone de cuatro escrituras: Las escrituras de Castel Darrow, Las escrituras de Rémol, Las escrituras del Molino Tarren y Las escrituras de Costasur. Regresa con Weldon Barov cuando hayas terminado esta tarea.", desc = "Mi querido hermano Alexi. Qué idiota fui perdonándole la vida. Miré a los ojos de mi enemigo, uno de los no-muertos, y le dejé vivir.\n\n<Weldon escupe.>\n\nY ahora busca MI herencia. No puede ocurrir.\n\nEncuentra las escrituras de mi familia antes de que sus manos huesudas las encuentren y te recompensaré con enormes riquezas. Podrás encontrarlas en las ruinas de Scholomance. ¡Date prisa!", objectives = { "Las escrituras de Rémol", "Las escrituras de Castel Darrow", "Las escrituras de Costasur", "Las escrituras de Molino Tarren" } },
    [5382] = { title = "Doctor Theolen Krastinov, el Carnicero", summary = "Busca al doctor Theolen Krastinov en el interior de Scholomance. Acaba con él y quema los restos de Eva Sarkhoff y los restos de Lucien Sarkhoff. Cuando hayas terminado tu tarea regresa con Eva Sarkhoff.", desc = "Krastinov es responsable de la muerte de miles. Debe ser castigado, debe hacerse justicia.\n\nBúscale y hazle rendir cuentas por la agonía que ha infligido a incontables inocentes. Cuando haya sido destruido, quema sus restos. Redúcelos a cenizas, <nombre>.", objectives = { "Doctor Theolen Krastinov", "Has quemado los restos de Eva Sarkhoff", "Has quemado los restos de Lucien Sarkhoff" } },
    [5384] = { title = "Kirtonos el Heraldo", summary = "Vuelve a Scholomance con la Sangre de los inocentes. Busca el Porche y coloca la Sangre de los inocentes en el blandón. Kirtonos acudirá a devorar tu alma. Lucha con valentía, ¡no cedas ni una pulgada! Destruye a Kirtonos y vuelve con Eva Sarkhoff.", desc = "Esta es, <nombre>.\n\n<Eva señala al vial de la bolsa.>\n\nLa Sangre de los inocentes. La sangre más pura, utilizada para aplacar al maestro de Krastinov.\n\nCon esta sangre podrás invocar a Kirtonos. Con esta sangre, por tanto, destruirás a Kirtonos.\n\nLleva la sangre hasta el Porche, y colócala sobre el blandón. Kirtonos aparecerá, no podrá resistirse. Cuando lo haga, descarga en él la furia y la rabia de un millar de muertes inocentes.\n\nSi tuvieras éxito ganarías mucho más que nuestra simple gratitud.", objectives = { "Kirtonos el Heraldo" } },
    [5461] = { title = "El humano, Ras Levescarcha", summary = "Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Recuerdo de Evocación. Si lo encuentras llévaselo al magistrado Marduke.", desc = "Los no-muertos temen tanto la vida como los vivos la muerte. No es extraño que un no-muerto sensible destruya todo resto de su vida anterior tras haberse convertido.\n\nPor desgracia, para crear un artefacto capaz de devolver a Ras Levescarcha a la mortalidad, necesitamos un recuerdo del tiempo que pasó entre los vivos.\n\nDebes adentrarte en la ciudad en ruinas de Stromgarde, el hogar de Levescarcha y buscar algo así. Que la suerte te acompañe, <nombre>.", objectives = { "Recuerdo de Evocación" } },
    [5462] = { title = "El moribundo, Ras Levescarcha", summary = "Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Recuerdo de Evocación y cuéntale todo lo que has descubierto.", desc = "El recuerdo debe armonizarse sobre tierra corrupta.\n\nHe oído rumores de que fue en Stratholme donde Levescarcha sucumbió al rey Exánime. Sobre ese suelo manchado de sangre, dio su vida (libre y voluntariamente) para convertirse en uno de los no-muertos.\n\nDebemos buscar ese suelo, esas tierras.\n\nHay alguien, un no-muerto disidente de la Plaga, puesto en libertad por la reina alma en pena, pero leal a la causa del Alba Argenta. Encuéntralo, su nombre es Leonid Barthalomew el Venerado. Seguramente él sepa más que yo. Lo encontrarás en Esperanza de la Luz, <nombre>." },
    [5463] = { title = "El Obsequio de Menethil", summary = "Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Recuerdo de Evocación en suelo no consagrado.", desc = "Yo vi cómo el humano Ras Levescarcha entregaba su alma inmortal al rey Exánime. Acercó la daga a su garganta y, con una sonrisa, se la rajó de oreja a oreja. Su cuerpo cayó dentro de las líneas del pentagrama. El rey Exánime se acercó al mago caído... con un solo movimiento suyo nació Ras Levescarcha el exánime.\n\n<Leonid mira al suelo y después, a ti.>\n\nLo recuerdo bien, <raza>. Lo que buscas tiene un nombre: el Obsequio de Menethil. La tierra bendecida por el rey Exánime, una tierra sagrada para la Plaga." },
    [5464] = { title = "El Obsequio de Menethil", summary = "Lleva las Memorias del Vínculo del Alma a Leonid Barthalomew a las Tierras de la Peste del Este.", desc = "El alma de los caídos se aferra a los objetos que representan su vida pasada y los transforma en Memorias del Vínculo del Alma. Coge el objeto y colócalo en tu talega." },
    [5465] = { title = "Memorias del Vínculo del Alma", summary = "Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale las Memorias del Vínculo del Alma.", desc = "Busca a Marduke cuando tengas las Memorias, <nombre>. Él te explicará cómo utilizarlas." },
    [5466] = { title = "El Lich, Ras Levescarcha", summary = "Busca a Ras Levescarcha en Scholomance. Cuando lo hayas encontrado utiliza las Memorias del Vínculo del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Levescarcha. Lleva la cabeza al magistrado Marduke.", desc = "Todavía tienes una tarea pendiente, <nombre>. Enfréntate al exánime, Ras Levescarcha, en su guarida.\n\nUtiliza el poder del recuerdo contra la bestia, ¡sé implacable en tus acciones! Capea todos los golpes que la bestia lance contra ti. ¡No sucumbas al pánico!\n\nCuando el ritual haya terminado, Ras volverá a ser mortal. Entonces debes terminar con él. Hazlo y coge su cabeza humana.", objectives = { "Cabeza humana de Ras Levescarcha" } },
    [5515] = { title = "Bolsa de los horrores de Krastinov", summary = "Localiza a Jandice Barov en Scholomance y destrúyela. En su cadáver encontrarás la Bolsa de los horrores de Krastinov. Devuélvele la bolsa a Eva Sarkhoff.", desc = "Has librado a nuestros corazones de una pesada carga, <nombre>, pero tu misión aún no ha terminado. El maestro de Krastinov, Kirtonos, sigue con vida.\n\nPero antes de enfrentarte a él debes hacerte con un modo de invocarle.\n\nSe dice que Jandice Barov sirve la Sangre de los inocentes de Krastinov a Kirtonos.\n\nBúscala en Las Catacumbas Sumergidas de Scholomance y termina con ella. Trae cualquier pista o indicio que puedas encontrar.", objectives = { "Bolsa de Horrores de Krastinov" } },
    [5518] = { title = "El traje de orgo Gordok", summary = "Lleva 4 madejas de paño rúnico, 8 retales de cuero basto, 2 hebras de hilo rúnico y tanino de ogro a Knot Llavededo. Actualmente está encadenado en el interior del ala Gordok de La Masacre.", desc = "Si vas a combatir con el rey de este basurero –y creo que es lo que vas a hacer– vas a tener que llegar a un acuerdo con el capitán Kromcrush. Puedes matarlo, claro, sería una forma de estar de acuerdo. Aunque puede que prefieras no quitarle la vida.\n\n¿Que cómo? Pues... durante el tiempo que he estado aquí, he aprendido a hacer un traje de ogro que durará lo suficiente como para engañar a esos tipos. El único problema es la estabilidad... máximo diez minutos. Tráeme lo que necesito y te haré uno. Yo no voy a ir a ninguna parte...", objectives = { "Descarga de paño rúnico x 4", "Cuero basto x 8", "Hilo rúnico x 2", "Tanino ogro" } },
    [5522] = { title = "Leonid Barthalomew", summary = "Lleva los huevos congelados a Leonid Barthalomew a las Tierras de la Peste del Este.", desc = "He recibido un mensaje de mi maestro, Vectus. Bueno, no de él, sino de un tal Barthalomew. No lo conozco, pero él conoce a mi maestro.\n\nDice que Vectus quiere los huevos de dragón. Dice que se los lleves a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.\n\n¡Me molesta que te envíe a ti! ¿Por qué no yo, eh? Da igual; tú llévale los huevos y dile que he hecho lo que pedía el maestro." },
    [5525] = { title = "¡Libera a Knot!", summary = "Se llama llave de los grilletes de Gordok... bueno, así es como la llaman esos graciosillos. Creo que podría tenerla cualquiera de los ogros, pero no sé cuáles en concreto. Probablemente podrían tenerla los guardias... ¿Pero qué estoy diciendo? ¡Si tú ya la tienes! ¡¿No?! ¡¿¿No es eso que tienes ahí??!", objectives = { "Llave de los grilletes de Gordok" } },
    [5526] = { title = "Fragmentos de gangrevid", summary = "Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de pureza para guardar el fragmento y llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna.", desc = "Lo que sabes de Eldre'Thalas - La Masacre - en Feralas te será muy útil, <nombre>. Alzzin el Formaferal ha instalado sus corruptos dominios al este de la ciudad en ruinas. Ve a la mayor brevedad y enfréntate al desafío que te está esperando.\n\nLa fruta de la fertilidad, ahora corrompida en forma de gangrevid, estará cerca de Alzzin. Cuando caiga, recupera tanta esencia de gangrevid como puedas. Sella el relicario y tráemelo.\n\nSuerte y que Cenarion te acompañe.", objectives = { "Relicario de Pureza sellado", "Fragmento de gangrevid" } },
    [5527] = { title = "Un relicario de pureza", summary = "Ve a Silithus a buscar un relicario de pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo al rabino Saturna a Amparo de la Noche, en Claro de la Luna.", desc = "Lo primero es encontrar un contenedor en el que mantener una sustancia extremadamente delicada sin causar daños a quien lo porte. Solo se me ocurre una cosa que pudiera contener algo tan vil como la gangrevid: un relicario de pureza.\n\nEn los eriales de Silithus se encuentran los restos de la aldea de los elfos de la noche de Viento del Sur. Sé que había un relicario allí, hace años. Necesito que vayas a buscarlo entre las ruinas.", objectives = { "Relicario de Pureza" } },
    [5528] = { title = "La cata de los Gordok", summary = "Ahora eres el jefe, ¡así consigues muestras gratis de mis mejores bebidas! ¡Te darán un buen subidón y un potente tirón! Son las buenas, jefe. ¡Prueba y dilo a Kreeg!" },
    [5529] = { title = "Crías infestadas", summary = "Mata a 20 crías de dragón infectadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz.", desc = "¡Alba Argenta ha descubierto hace poco que la Plaga está criando Vuelos infectados por su cuenta! Debemos detenerlos; ¡con una tropa de dragones podrían arrasar Azeroth!\n\nSus necrománticos crían dragones infectados en Scholomance, en pleno Lago Darrowmere.\n\nVe allí y mata tantas crías de dragón como puedas... ¡y mientras puedas!", objectives = { "Trampedor infestado x 20" } },
    [5531] = { title = "Betina Bigglezink", summary = "Lleva los huevos congelados a Betina Bigglezink, que está fuera.", desc = "Los huevos que trajiste eran para un experimento de la Plaga para crear un Vuelo infestado. Estos huevos negros de dragón congelados habrían sido inestimables en su investigación; esto les retrasará.\n\nAcabemos con esto.\n\nLleva los huevos a Betina Bigglezink, que está fuera. Sabe mucho de alchimia y tiene un arma que podemos usar contra la Plaga. Vamos a asestarles un golpe mortal." },
    [5542] = { title = "Perros demoníacos", summary = "Mata 20 cachorros de can de la Peste, 5 canes de la Peste y 5 canes de la Peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Fordring.", desc = "Si vas a quedarte aquí, solo te pido que te ganes tu sustento. Tenemos muchos problemas que podrían necesitar algo de \"disciplina\"\n\nPuedes empezar con los canes de la Peste y sus cachorros.\n\nNo puedo darte mucho a cambio, pero si tienes éxito no te faltará la comida caliente y algo de conversación.", objectives = { "Cachorro de can de la Peste x 20", "Can de la Peste x 5", "Can de la Peste demenciado x 5" } },
    [5543] = { title = "Cielos sangrientos", summary = "Mata 30 murcípestes y vuelve con Tirion Fordring.", desc = "Ay de los que se adentran en las Tierras de la Peste. Todo tipo de inmundicia habita esos bosques, desde la fanática Cruzada Escarlata, que mata a todo el que no porta la marca de la Cruzada, hasta la Plaga asesina, que solo quiere aumentar su número sumando nuevos no-muertos a sus filas.\n\nHasta la naturaleza se ha transformado en bestias feroces, devoradoras de hombres. Te pido que destruyas a aquellos que golpean desde las alturas: los murcípestes.", objectives = { "Murcipeste x 30" } },
    [5544] = { title = "Gusanos carroñeros", summary = "Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Fordring cuando tengas 14 trozos de carne de gusano carroñero.", desc = "Mis suministros de comida se están agotando, <raza>. Me avergüenza reconocer que no tengo bastante comida para compartir contigo.\n\n¿Podrías ayudar a un anciano con una sencilla misión? En los alrededores, la única bestia que no se ha visto afectada por los estragos de la Peste es el gusano carroñero. Aunque tiene un sabor bastante soso, la carne de esos gusanos puede conservarse durante meses. ¡Necesitaré varios cientos de kilos para reponer las reservas para este invierno!", objectives = { "Trozo de carne de gusano carroñero x 15" } },
    [5582] = { title = "Escama sana de dragón", summary = "Lleva la escama sana de dragón a Betina Bigglezink a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este.", desc = "Esto es una escama de cría de dragón infestada, pero no es viscosa como las demás, sino sana y sin marcas.\n\nA Betina Bigglezink le gustará tener una muestra." },
    [5722] = { title = "Buscando la cartera perdida", summary = "Inspecciona la Sima Ígnea en busca del cuerpo de Maur Tótem Siniestro y comprueba si porta algún objeto de interés.", desc = "Los troggs no eran lo único que le interesaba a Magatha de la Sima Ígnea. Ella ha oído decir que uno de sus sirvientes, Maur Tótem Siniestro, encontró algo muy especial en la Sima pero que nunca consiguió salir con vida para enseñárselo. Le gustaría encontrar el cuerpo de Maur, si es que todavía queda algo de él, y cualquier indicio de lo que él había encontrado en su intento de hablar con los troggs.\n\nLlévale a Magatha cualquier objeto que pueda ser de su interés y seguro que te recompensará con generosidad.\n\nDe nuevo, busca la Sima en la zona más oscura de Orgrimmar." },
    [5723] = { title = "Midiendo fuerzas con el enemigo", summary = "Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno.", desc = "En la ciudad de Orgrimmar, robustas criaturas conocidas como troggs comenzaron a salir a la superficie desde las profundidades de los túneles llenos de lava. En su benevolencia, Magatha trató de negociar con las criaturas pero estas se echaron encima de sus diplomáticos y los mataron. No permitiría un trato semejante al pueblo tauren por lo que estas criaturas ahora son consideradas como una amenaza para todos los de la Horda.\n\nElla te pide que pongas fin a la amenaza de los troggs antes de que acaben con la Horda. Encuentra la Sima Ígnea y acaba con todos ellos.", objectives = { "Trogg Furia Ardiente x 8", "Chamán Furia Ardiente x 8" } },
    [5724] = { title = "La vuelta de la cartera perdida", summary = "Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno.", desc = "Encuentras una cartera bajo el cuerpo del tauren. Todavía está fuertemente aprisionada entre sus brazos como si la hubiera estado protegiendo mientras fue atacado por los troggs.\n\nCoges la cartera, la guardas con tu equipo y te dispones a salir de los túneles de vuelta a Rahauro en Cima del Trueno." },
    [5725] = { title = "Poder destructivo", summary = "Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas.", desc = "Muchos integrantes de la Legión ofrecen regalos a sus seguidores, como seguro que ya sabes. La Dama Oscura cree que muchos de estos regalos estarían mejor en su poder que en manos de esos... que no son tan avezados.\n\nUna secta del Consejo de la Sombra, oculta en las cavernas situadas bajo Orgrimmar y conocida como Espada Abrasadora, es un excelente ejemplo. La Dama sabe que los miembros de la secta Espada Abrasadora se han hecho con dos poderosos libros de hechizos que le gustaría \"tomar prestados\". Tú serás quien los consiga para ella.", objectives = { "Hechizos de las Sombras", "Encantamientos desde el infierno" } },
    [5726] = { title = "Enemigos ocultos", summary = "Lleva una insignia de General a Thrall a Orgrimmar.", desc = "No tolero a los traidores, <nombre>. Pero sería necio mostrar mis cartas demasiado pronto; no eliminaría la corrupción de nuestras tierras y la infestación sería aún peor.\n\nPero tú, joven errante, podrías ir hasta donde no llegaron mis agentes y averiguar la verdad.\n\nSi eres lo bastante valiente, ve a Roca del Cráneo, al este de Orgrimmar, consigue una insignia de general de Filo Ardiente y tráemela.", objectives = { "Insignia de Teniente" } },
    [5727] = { title = "Enemigos ocultos", summary = "Lleva la insignia de General a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar.", desc = "Veamos si la insignia vale la pena el esfuerzo.\n\nEn la ciudad hay un brujo que cree que aún confío en él. No sabe que he descubierto su traición: es el jefe de Filo Ardiente. Pero no te enfrentes con él ahora; podemos usarlo contra nuestros enemigos.\n\nLLévale esta insignia; está en el Circo de las Sombras, aquí en Orgrimmar. Vuelve después de hablar con él y dime si ha creído que eras de los suyos.", objectives = { "Decide si Neeru Hojafuego cree que eres miembro de Filo Ardiente" } },
    [5728] = { title = "Enemigos ocultos", summary = "Mata a Bazzalan y a Jergosh el Invocador y ve a ver a Thrall a Orgrimmar.", desc = "Así que jefes de Espada Abrasadora, ¿eh? Interesante... Si son los más cercanos a Neeru, tienen que ser nuestro primer objetivo. El sátiro Bazzalan y el otro que mencionó Neeru, creo que era un brujo, deben ser eliminados.\n\nVuelve al Circo de las Sombras y entra en la Sima Ígnea. Liquida al sátiro y al brujo, pero que Neeru no se entere de que has sido tú. Tiene que seguir creyendo que eres de <los suyos/las suyas>.", objectives = { "Bazzalan", "Jergosh el Conjurador" } },
    [5742] = { title = "Redención", summary = "Escucha lo que Tirion Fordring tiene que contarte.", desc = "Has trabajado duro, <amigo/amiga>. Descansa tus cansados huesos y permite que me presente con propiedad.", objectives = { "Relato de Tirion" } },
    [5761] = { title = "Matar a la bestia", summary = "Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar.", desc = "Mi trabajo principal consiste en erradicar a las criaturas responsables de la infestación demoníaca en nuestra maravillosa ciudad. Filo Ardiente es una amenaza, pero hay otras, como Espada Abrasadora, que reside en la Sima Ígnea e intenta subvertir a miembros de la Horda en secreto.\n\nPara detenerlos debemos eliminar a su jefe, un guardia maldito llamado Taragaman el Hambriento.\n\nMátalo y entrégale su corazón a Thrall; eso lo tranquilizará.", objectives = { "Corazón de Taragaman el Hambriento" } },
    [5781] = { title = "De recuerdos olvidados", summary = "Viaja a La Subgranja, en la sección más meridional de las Tierras de la Peste del Este, y recupera el Martillo de Taelan. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring.", desc = "Para ayudar a Taelan a recuperar lo que ha perdido, debes reunir objetos de su pasado.\n\nEl primero es un juguete que le di el día que cumplió 7 años. Era su posesión más querida: una miniatura de un martillo de guerra, una réplica exacta de uno mío.\n\nCuando fui desterrado por traición su madre le dijo que había muerto. Le llevaron a mi tumba falsa en La Subgranja, y allí enterró el martillo junto con mi recuerdo... para siempre.\n\nDebes ir a La Subgranja y recuperar el martillo de Taelan.", objectives = { "Martillo de Taelan" } },
    [5845] = { title = "Del honor perdido", summary = "Viaja a Vallenorte, en la zona noreste de las Tierras de la Peste del Este, y recupera el Símbolo del Honor Perdido. Cuando hayas cumplido tu objetivo regresa con Tirion Fordring.", desc = "La Orden de la Mano de Plata fue completamente diezmada cuando Uther fue asesinado.\n\nEl muchacho resistió todo lo que pudo. Empujado hasta el poblado de Vallenorte, destrozado por la guerra, ofreció su última resistencia. Pensaba si quedaría alguien de la Orden con vida... y si eso importaba.\n\nCon ese pensamiento Taelan arrojó el estandarte de la Orden y renunció a todo lo que había conocido. Su honor se quedó sobre el suelo bañado de sangre de Vallenorte.\n\nDebes viajar a Vallenorte y recuperar ese símbolo de nuestro honor perdido.", objectives = { "Símbolo de Honor perdido" } },
    [5846] = { title = "De amor y familia", summary = "Viaja a la isla de Castel Darrow, en la región sur del centro de las Tierras de la Peste. Allí, busca pistas sobre el paradero del cuadro.", desc = "Cuando Taelan era un niño, solíamos hacer excursiones en familia a Castel Darrow. En nuestra última visita, un artista que tenía por nombre Renfray, nos hizo un retrato a orillas del mar. Es el recuerdo más dulce que tengo de Taelan y Karandra. Porque fue en ese momento, junto a mi mujer y teniendo a mi hijo en brazos, cuando sentí un vínculo de amor y de apego a la familia que nunca más he vuelto a tener.\n\nSi esa pintura todavía existe, debes encontrarla.\n\nViaja hasta la isla en ruinas de Castel Darrow y averigua si siguen allí el cuadro o el artista." },
    [5848] = { title = "De amor y familia", summary = "Viaja a Stratholme, en la zona norte de las Tierras de la Peste. En El Bastión Escarlata encontrarás el cuadro 'De amor y familia', oculto tras otra pintura que representa las lunas gemelas de nuestro mundo. Devuelve la pintura a Tirion Fordring.", desc = "El cuadro... estuvo colgado en la pared de mi estudio (en los cuarteles de la Orden) durante años.\n\nCuando terminó el juicio de Tirion, supe que no podía seguir teniendo el cuadro a la vista. Lo oculté en un lugar en el que nunca lo buscarían.\n\nViaja a Stratholme, ábrete camino hacia las profundidades de lo que hoy se conoce como El Bastión Escarlata y busca un cuadro de nuestras lunas gemelas. Desprende la pintura hasta que descubras mi obra maestra, \"De amor y familia\".\n\nQue la Luz guíe tus actos.", objectives = { "Del amor y la familia" } },
    [6133] = { title = "La orden del Señor de exploradores", summary = "Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien. También tienes que matar a 8 exploradores, 8 zancaminos y 8 Leñantros.", desc = "Los elfos nobles del Refugio Quel'Lithien poseen algo que me pertenece, <clase>: un documento que detalla mi vida como mortal.\n\nAntes de que preguntes: no, desde luego no compartiré contigo tal información. Haz solo lo que te diga, gusano: recupera el documento.\n\nY, tontolaba, asegúrate de dejar tanta sangre y pena a tu paso como te sea posible. Haz que sufran...", objectives = { "Zancamino x 8", "Especialista x 8", "Leñantro x 8", "Registro de Quel'Thalas" } },
    [6135] = { title = "Alatardecer, cómo te odio…", summary = "Encuentra a Alatardecer y mátalo. Recoge un parche de piel de Alatardecer de su cadáver y llévaselo a Nathanos Clamorinfecto. Se dice que Alatardecer vaga por el campo, al norte de la Hacienda de Marris.", desc = "Hasta ahora, has completado las misiones que te he encomendado, incluso a destiempo.\n\nCreo que ya es hora de ofrecerte un desafío... Sí, imbécil, quizás ya estés <preparado/preparada> para algunas misiones más importantes.\n\nEl murciélago demonio albino, Alatardecer, habita los parajes al norte de aquí. Búscalo y acaba con él. Regresa con un parche de su blanca piel y te recomensaré.", objectives = { "Parche de pelaje de alatardecer" } },
    [6163] = { title = "Ramstein", summary = "Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos.", desc = "Me superaron. Estaba en este mismo lugar... firme, defendiendo el terreno por Lordaeron. La granja fue atacada por una gigante ola de la Plaga.\n\nEsos malditos... Esa escoria... Algo planeó sobre mí... Sus vísceras colgaban de su cavidad torácica...\n\nMe desperté como miembro de la Plaga. Durante tanto tiempo me sentí tan impotente... Mi mente se unió a la del rey Exánime.\n\nElla vino a por mí... de alguna forma, sabía que lo haría. Libre.\n\nY ahora debo cobrar mi venganza. Debo vengarme de lo que se llevó mi vida. Destrúyelo tú.", objectives = { "Cabeza de Ramstein el Glotón" } },
    [6402] = { title = "Tienes un cita en Ventormenta", summary = "Viaja hasta Ventormenta y aventúrate tras las puertas de la ciudad. Habla con el escudero Rowe para que haga saber al alguacil Windsor sobre tu llegada.", desc = "Has de reunirte con Windsor a las puertas de Ventormenta.\n\nLo que Windsor está a punto de revelar ¡hará temblar el Reino desde sus cimientos!\n\nNo lo intentes en solitario, <nombre>. ¡Debes reunir un ejército! Que tus compatriotas se unan a ti. ¡A las armas!" },
    [6403] = { title = "La gran farsa", summary = "Sigue a Reginald Windsor por Ventormenta. ¡Protégele del peligro!", desc = "¡Menuda aventura, <amigo/amiga>! Estoy en deuda contigo. Quizás, cuando todo se haya terminado...\n\nComo habrás adivinado a estas alturas, Lady Prestor es Onyxia: madre de la camada de Alamuerte, gemela del tirano de la Cumbre, Nefarian.\n\nHa tenido dominado nuestro reino durante demasiado tiempo. Incluso controla al Gran Señor como si de un mero títere se tratara. Pero todo terminará hoy... El hechizo se romperá.\n\nNo te preocupes, juntos, conseguiremos la victoria.\n\n¿Estás <listo/lista>?", objectives = { "La marcha de Reginald" } },
    [6501] = { title = "El Ojo del dragón", summary = "Debes buscar por todo el mundo y encontrar un ser capaz de restaurar el poder del fragmento del Ojo del dragón. La única información que tienes sobre dicho ser, es que existe.", desc = "Todo lo que puedo ofrecerte es un fragmento del medallón.\n\nDebes encontrar a otro con sangre de dragón dispuesto a ayudarte a forjar una nueva llave. Cuando consigas la llave, debes ir a la Ciénaga de Fuego, en el Marjal Revolcafango. Allí encontrarás su guarida, <nombre>.\n\n¿Dónde encontrar otros Vuelos dispuestos a ayudarte? Por desgracia, no lo sé... Se dice por ahí que existen. Es posible que algunos, incluso trabajen y vivan entre nosotros, disfrazados de razas humanoides. Te deseo suerte." },
    [6502] = { title = "Amuleto Pirodraco", summary = "Tienes que recuperar la sangre de dragón negro campeón, la tiene el general Drakkisath. Puedes encontrar a Drakkisath en su sala del trono, tras las Salas de la Ascensión, en la Cumbre de Roca Negra.", desc = "Es un objeto del dragón. Una escama, encantada y transformada. Si i estuviera entera, podría haberte concedido el acceso a la guarida de la bestia. Rota, no te sirve para nada.\n\nEs posible reparar el objeto, pero para hacerlo, se necesita la sangre de un campeón dragón negro. Hay uno... Se llama general Drakkisath, líder de los ejércitos de dragauros de Nefarian. Quizás hayas oído hablar de él.\n\nVuelve con su sangre, <raza>, y encantaré el fragmento para que puedas entrar en la guarida de Onyxia.", objectives = { "Sangre de dragón negro campeón" } },
    [6521] = { title = "Una alianza nefasta", summary = "Lleva la cabeza del embajador Malcin a Varimathras, que está en Entrañas.", desc = "Malcin dice estar fuera de Zahúrda Rojocieno. Debe ser eliminado: su misión es un fracaso a los ojos del rey Exánime.\n\nSu presencia allí explica mucho de lo que hemos descubierto en la región; algunos jabaespines han ganado mucho poder y muestran características de la Plaga. Deben de haber llegado a un acuerdo.\n\nAcaba con Malcin y después vuelve.", objectives = { "Cabeza del Embajador Malcin" } },
    [6522] = { title = "Una alianza nefasta", summary = "Lleva el pergamino a Varimathras, que está en Entrañas.", desc = "Estimada señora:\n\ncomo muy bien sabe, le estamos ofreciendo la gran oportunidad de tomar Los Baldíos y tierras circundantes. A cambio, solo pedimos ayuda, y con ello nos referimos a la libertad de acción.\n\nRogamos que lo considere. Tenemos mucho poder y deseamos compartirlo con nuestros aliados. Por el momento me mantendré alejado de Zahúrda Rojocieno.\n\nSaludos,\nEmbajador Malcin" },
    [6561] = { title = "La vileza de Brazanegra", summary = "Llévale la cabeza del Señor Crepuscular Kelris a Bashana Runatótem en Cima del Trueno.", desc = "Las fuerzas me han abandonado. ¡Necesito tu ayuda!\n\nOtrora este lugar era un gran templo de Elune. Pero la desgracia lo ha llevado a la ruina cuando la corrupción de un dios antiguo empezó a calar desde el subsuelo y contaminó la sagrada Poza de la Luna.\n\nAku'Mai, sirviente del dios antiguo, surgió de las aguas.\n\nLos adeptos del Azote del Ocaso se han unido a los nagas para ocupar esas tierras. Esos adeptos, cuyo jefe es Kelris, sacrifican a inocentes a Aku'Mai a cambio de poder.\n\nMata a Kelris y llévale su cabeza a Bashana en Cima del Trueno, <nombre>, te lo ruego.", objectives = { "Cabeza de Kelris" } },
    [6562] = { title = "Problemas en las profundidades", summary = "Habla con Je'neu Sancrea en Vallefresno.", desc = "Je'neu Sancrea necesita ayuda. Se encuentra en la Avanzada de Zoram'gar en Vallefresno. El bosque de los elfos de noche se encuentra al norte de Sierra Espolón. Puedes llegar hasta allí viajando por Risco Cortaviento o dirigiéndote hacia el norte a través de Los Baldíos. La Ensenada de Zoram está bastante al oeste del bosque. Ten cuidado, <nombre>. Allí hay fuerzas que no se tomarán con alegría tu presencia." },
    [6563] = { title = "La esencia de Aku'Mai", summary = "Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno.", desc = "Al principio de los túneles de las Cavernas de Brazanegra, se pueden encontrar grandes bloques de zafiros en las paredes de las cuevas. Recientemente se observó que los nagas estaban reuniendo los cristales. Hasta que se aclare el porqué, presiento que deberíamos impedírselo. Los cristales tienen un gran poder elemental y si este no se usa apropiadamente, podría producir un poderoso componente arcano.\n\n¿Me ayudarás, <nombre>? Las Cavernas de Brazanegra bordean La Ensenada de Zoram al norte de nuestra avanzada.", objectives = { "Zafiro de Aku'Mai x 20" } },
    [6564] = { title = "Lealtad a los dioses antiguos", summary = "Llévale la nota humedecida a Je'neu Sancrea en Vallefresno.", desc = "Hay unas líneas con mala caligrafía garabateadas en la arrugada nota:\n\n\"Sí, decid a todas las sacerdotisas que me traigan los cristales. Los espíritus elementales de agua son fuertes en su interior y ayudarán a nuestros acuamánticos en sus conjuros.\n\nSi controlamos el poder de los cristales, apaciguaremos a Aku'Mai. Algún día tendremos suficiente poder para devolvernos a Aku'Mai ¡y el mundo conocerá una vuelta a su era más grandiosa! ¡Una era de reinado de los dioses antiguos!\"" },
    [6565] = { title = "Lealtad a los dioses antiguos", summary = "Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve junto a Je'neu Sancrea en Vallefresno.", desc = "Debemos impedir que este seguidor del Azote del Ocaso complete su plan. El Azote del Ocaso no entiende a los espíritus de la naturaleza. Creen en los dioses antiguos, unas criaturas del caos y la destrucción que fueron derrotados hace mucho tiempo. No podemos permitir que el tal Lorgus consiga su propósito. Debes detenerlo, <nombre>. No puedo hacerlo personalmente, soy demasiado débil.\n\nDirígete a las Cavernas Anegadas, encuéntralo y mátalo. Vuelve a verme, aquí en Zoram'gar, cuando lo hayas hecho.", objectives = { "Lorgus Jett" } },
    [6566] = { title = "Lo que trae el viento", summary = "Escucha a Thrall.", desc = "Me alegro de volver a verte, <nombre>. El vierno trae noticias de los Reinos del Este.\n\nSiéntate y escucha.", objectives = { "La historia de Thrall" } },
    [6567] = { title = "El Campeón de la Horda", summary = "Busca a Rexxar. El Jefe de Guerra ha dicho que estará en Desolace, entre Sierra Espolón y Feralas.", desc = "Uno de mis campeones me dice que puede haber una forma de entrar en la guarida del dragón; tienes que buscarlo.\n\nSe llama Rexxar y recorre los yermos de Desolace, entre Cima del Espolón y Feralas. Te espera." },
    [6568] = { title = "El testamento de Rexxar", summary = "Entrega el testamento de Rexxar a Myranda la Fada. Está en las Tierras de la Peste del Oeste.", desc = "¿Qué sabes de las ilusiones, <nombre>? Lo pregunto porque es precisamente lo que tienes que crear para burlar las defensas del Vuelo Negro.\n\nSé de una que estará encantada de ayudarte en tu misión. Nos ha ayudado en otras ocasiones. Al menos, cuando consideraba que la causa merecía la pena.\n\nSe llama Myranda la Fada y es una maestra ilusionista, además de una exiliada de la Alianza de Lordaeron. Está en las Tierras de la Peste del Oeste. Viaja hasta allí y lleva contigo este mensaje." },
    [6569] = { title = "Ilusiones oculares", summary = "Viaja a la Cumbre de Roca Negra y recoge 20 ojos de dragauro negro. Cuando hayas terminado tu tarea regresa con Myranda la Fada.", desc = "Así que el <raza> desea convertirse en uno del Vuelo Negro, ¿eh?\n\nCrear la ilusión que necesitas es algo trivial, pero es bastante difícil obtener los componentes necesarios para la adivinación. Rexxar y el Jefe de Guerra han mostrado su confianza en ti encargándote esta misión así que Myranda debe dar por supuesto que estás <capacitado/capacitada>.\n\nViaja a la ciudadela de la Cumbre de Roca Negra y mata tantos dragauros negros como necesites para llenar una de tus talegas con sus ojos.\n\nVuelve con Myranda cuando hayas reunido suficientes componentes.", objectives = { "Ojo de dragauro negro x 20" } },
    [6570] = { title = "Brasaliza", summary = "Viaja a la Ciénaga de Fuego del Marjal Revolcafango y busca el Cubil de Brasaliza. Cuando estés dentro ponte el Amuleto de Subversión Dracónica y habla con Brasaliza.", desc = "He armonizado este medallón con la magia necesaria para crear y mantener una ilusión dentro de los límites del cubil de Brasaliza.\n\nBrasaliza es un draco antiguo; un viejo guardián de Nefarian, encargado de someter a prueba a los dragauros que debían ascender al rango de guardia de élite de Onyxia.\n\nViaja hasta la Ciénaga de Fuego de la Bahía Revolcafango y entra en la guarida de Brasaliza. Cuando estés allí ponte el amuleto ¡y sigue tu destino a donde quiera que te conduzca!" },
    [6582] = { title = "La prueba de las calaveras, Arúspice", summary = "Debes encontrar a Arúspice, el campeón draco del Vuelo Azul y matarlo. Separa su calavera de su cuerpo y llévasela a Brasaliza. Sabes que puedes encontrar a Arúspice en Cuna del Invierno.", desc = "Somos los Hijos de Alamuerte, <mocoso/mocosa>. Debemos ejercer nuestro dominio sobre los Aspectos inferiores.\n\nSi realmente mereces la ascensión, el Vuelo inferior languidecerá en tu presencia.\n\n¡Encuentra a los campeones y acaba con ellos en nombre de nuestro Padre!\n\nViaja a Cuna del Invierno y localiza a Arúspice, el poderoso dragón azul. Aplástalo a él y a todos los Vuelo Azul que te encuentres en el camino. Arráncale la calavera y tráemela.", objectives = { "El cráneo de Sccentenor" } },
    [6583] = { title = "La prueba de las calaveras, Somnus", summary = "Destruye al campeón draco del Vuelo Verde, Somnus. Lleva su calavera a Brasaliza.", desc = "Mientras Padre aplasta a los Aspectos, nosotros debemos encargarnos de envolver en caos y destrucción a su prole.\n\nDebes probar tu habilidad en combate con los insomnes: la prole del Vuelo Verde.\n\nVe al Pantano de las Penas y encuentra a Somnus, el campeón del Vuelo Verde. Da rienda suelta a tu odio; domina a ese insecto... Y vuelve aquí con su calavera...", objectives = { "El cráneo de Somnus" } },
    [6584] = { title = "La prueba de las calaveras, Chronalis", summary = "Chronalis, hijo de Nozdormu, custodia las Cavernas del Tiempo en el Desierto de Tanaris. Destrúyelo y lleva su calavera a Brasaliza.", desc = "Los guardianes del tiempo, los Hijos de Nozdomu, el Señor de los Siglosss...\n\nLos tres custodian las Cavernas del Tiempo, pero solo uno interesa al Vuelo Negro: El Dueño del Tiempo, Chronalis, el favorito de Nozdormu.\n\nGolpea a este campeón. Aséstale un golpe que haga llorar incluso a las estoicas arenas del tiempo. Y vuelve aquí con su calavera...", objectives = { "El cráneo de Chronalis" } },
    [6585] = { title = "La prueba de las calaveras, Axtroz", summary = "Viaja a Grim Batol y encuentra a Axtroz, el campeón draco del Vuelo Rojo. Destrúyelo y hazte con su calavera. Llévasela a Brasaliza.", desc = "Nuestro Padre arremetió contra el poder combinado de los Aspectos en las montañas de Grim Batol. El acto de cobardía de Alexstrasza, la traidora, dio a los demás Aspectos tiempo para escapar de la ira de Padre.\n\nFue un acto vergonzoso...\n\nAhora el Vuelo Rojo guarda Grim Batol. Su teniente, Axtroz, debe ser destruido. Vuelve a mí con la calavera de Axtroz. ¡Por Padre!", objectives = { "El cráneo de Axtroz" } },
    [6601] = { title = "El ascenso", summary = "Diría que se acabaron las charadas. Ya sabes que el Amuleto de Subversión Dracónica que Myranda la Fada creó para ti no funcionará en el interior de la Cumbre de Roca Negra. Quizás deberías buscar a Rexxar y explicarle el apuro en el que te encuentras. Enséñale el amuleto pirodraco apagado. Con un poco de suerte, él sabrá que hay que hacer ahora.", desc = "Las calaveras de nuestros enemigos conforman un medallón. Conoces ese medallón, ¿verdad? Lo habrás visto, sin duda, pues lo llevan tus ancestros.\n\nCógelo, <mocoso/mocosa>. Vuelve a la cumbre y entrégaselo al general Drakkisath. El General imbuirá el encantamiento final al medallón y lo sintonizará con tu espíritu.\n\nLlevarás el medallón acabado como insignia de honor. Una insignia que simbolizará tu ascenso a uno de nuestros rangos más exclusivos: guardián de la madre de la camada.\n\n¡Ve!" },
    [6602] = { title = "La sangre de dragón negro campeón", summary = "Viaja a la Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y llévasela a Rexxar.", desc = "Visitarás al Gran general, sí, pero no como miembro del Vuelo Negro.\n\nEs que, verás, una ceremonia para el Vuelo Negro es lo mismo que una sangría.\n\nEl poder latente del amuleto necesita la sangre del Gran general para activarse. Es uno de sus burdos mecanismos de seguridad.\n\nVuelve a la Cumbre de Roca Negra y elimina a Drakkisath. Trae aquí su sangre y yo activaré la llave de la Guarida de Onyxia.", objectives = { "Sangre de dragón negro campeón" } },
    [6626] = { title = "Un anfitrión del mal", summary = "Mata a 8 guardias de batalla y 8 tejespinas Rajacieno y 8 adeptos Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno.", desc = "Los Renegados no son contagiosos, por así decir. Al parecer, este enviado promete la no-muerte a quien se una a él. Creo que pertenece a la Plaga.\n\nAunque ahora no me preocupa él, sino la gente arracimada a su alrededor. Salen día a día de las sombras, suplicándole más poder.\n\nNo puedo luchar contra ellos sin ayuda, <nombre>. ¿Qué me dices? ¿Te apetece cazar?", objectives = { "Guardia de batalla de Rajacieno x 8", "Tejespina Rajacieno x 8", "Fiel Caramuerte x 8" } },
    [6627] = { title = "Prueba de conocimiento", summary = "Responde la pregunta de Braug Espiritoscuro con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés <listo/lista>.", desc = "Me has traído el libro y es momento de que te plantee la pregunta. ¿Estás <preparado/preparada>?\n\nSin presión, <clase>. Tómate tu tiempo antes de contestar.", objectives = { "Responde correctamente la pregunta de Braug Espiritoscuro." } },
    [6804] = { title = "Agua envenenada", summary = "Aplica el aspecto de Neptulon a los elementales infectados de las Tierras de la Peste del Este. Lleva 12 de sus brazales de vínculo y el aspecto de Neptulon al duque Hydraxis a Azshara.", desc = "Una fuerza de rastreadores elementales enviada a las Tierras de la Peste del Este de Lordaeron fue infectada por la corrupción del lugar. ¡Los Señores del Agua no podemos tolerar este insulto a nuestra pureza!\n\nToma este frasco. Contiene un aspecto de Neptulon. Eliminará el veneno de los elementales infectados. Pero el conflicto interno les conducirá a una enajenación transitoria.\n\nDomina a los descontrolados y tráeme sus brazales de vínculo.", objectives = { "Brazales que no van a juego x 12" } },
    [6805] = { title = "Sirocosos y reptarenas", summary = "Mata a 15 sirocosos y 15 reptarenas y ve a hablar con el duque Hydraxis en Azshara.", desc = "Nosotros, los elementales del agua, estamos en guerra con los seres de los elementos menores. ¡Demuestra que estás de nuestra parte!\n\nMuy lejos hacia el sur, en el desierto de Silithus, viven los siervos del aire y la tierra, en un pedazo de roca llamado La Vega de Cristal. Protegen objetos de poder frente a seres inferiores, mortales, y aunque ignoro por qué lo hacen, deseo contrariarlos.\n\nVe a La Vega de Cristal, en Silithus, y derrota a nuestros enemigos. Después vuelve a verme.", objectives = { "Sirocoso x 15", "Estruendor del desierto x 15" } },
    [6821] = { title = "Ojo de brasadivino", summary = "Lleva el ojo del Piroguardián brasadivino al duque Hydraxis a Azshara.", desc = "Has demostrado que puedes derrotar a nuestros enemigos y encargarte de misiones para la causa de los Señores del Agua. Pero hasta ahora solo te has enfrentado a enemigos menores... ¿Podrás vencer a un enemigo más poderoso?\n\nEsa es tu nueva misión.\n\nLos orcos han apresado a un siervo del fuego, el Piroguardián brasadivino, en Cumbre de Roca Negra. Encuentra dónde lo tienen cautivo, mata a sus captores y luego al piroguardián. Tráeme su ojo; me mostrará tu valor.", objectives = { "Ojo del Brasadivino" } },
    [6921] = { title = "Entre ruinas", summary = "Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.", desc = "El Azote del Ocaso se ha trasladado a las ruinas del Santuario Lunar de las Cavernas Anegadas. Su presencia solo puede servir para forzar los elementos a actuar contra nosotros. Si no nos ocupamos de ella, esta región caerá en sus manos definitivamente.\n\n<nombre>, dirígete a Brazanegra y encuentra la piedra de las profundidades en las ruinas; debería estar cerca del agua. Es un núcleo de sonda, un dispositivo que cuando se lee correctamente, revela la historia de toda actividad elemental. Si lo consigo, y con la ayuda de los miembros del Anillo de la Tierra, ¡quizás podamos detenerlos!", objectives = { "Núcleo de las profundidades" } },
    [6922] = { title = "Barón Aquanis", summary = "Llévale el extraño globo de agua a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.", desc = "El elemental de agua derrotado ha dejado tras de sí un extraño globo de agua. Supones que el objeto de alguna forma alimentó la energía de la bestia. En el interior del globo, una líquida forma repulsiva chapotea. El propio globo parece impermeable a todo tipo de fuerza física.\n\nSi alguien es capaz de interpretar este artilugio, es Je'neu Sancrea del Anillo de la Tierra. Se encuentra en la Avanzada de Zoram'gar de la Horda en Vallefresno." },
    [6981] = { title = "El fragmento brillante", summary = "Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento brillante. Entrega el fragmento como se te indique.", desc = "El fragmento es verde y brillante y, aunque sólido, parece que hubiera humo arremolinándose bajo su superficie. No se puede evitar perder la mirada en las profundidades del cristal y, al mismo tiempo, uno sabe que hay algo muy desconcertante.\n\nQuizás deberías ir a ver si alguien de Trinquete puede decirte algo más sobre este extraño fragmento.", objectives = { "Habla con alguien de Trinquete sobre el fragmento brillante" } },
    [7028] = { title = "Los males de Maraudón", summary = "Recoge 25 tallas de cristal terádrico y llévaselas a Willow a Desolace.", desc = "Las cavernas de cristal de Terramok están al oeste, en pleno corazón de Maraudon... Es un lugar antiguo y cargado de historia. Quiero una parte de esa historia, <clase>. Tras las puertas gigantes hay reliquias de los dioses antiguos.\n\nSi te atreves a enfrentarte a los males de Maraudon, te compensaré generosamente. Tráeme todas las tallas de cristal terádrico que encuentres.\n\nAsí podré... estudiarlas. Los poderes que contienen llevan demasiado tiempo dormidos.", objectives = { "Tallas de cristal terádrico x 25" } },
    [7029] = { title = "La corrupción de Lenguavil", summary = "Llena el vial revestido en el estanque naranja de Maraudon. Aplica el líquido a la hiedra tallovil para que emerja el vástago tóxico. Cura 8 plantas eliminando su vástago tóxico e informa a Vark Marcaguerra en la Aldea Cazasombras.", desc = "Un sátiro llamado Lenguavil ha corrompido las cavernas de Maraudon y ha detenido el desarrollo de muchas de las plantas.\n\nToma este frasco, <nombre>. Llénalo en el estanque de cristal naranja de las cavernas; el relleno del frasco contrarrestará las toxinas y las transformará en agentes sanadores.\n\nEsparce el líquido purificado en la hiedra Tallovil de las cavernas naranja. Aunque se eliminará la corrupción de la planta, debes saber que seguirá bajo el control de Lenguavil. Puede que intente atacarte...", objectives = { "Has curado la hiedra Tallovil x 8", "Vial cerúlea llena" } },
    [7041] = { title = "La corrupción de Lenguavil", summary = "Llena el vial revestido en el estanque naranja de Maraudon. Aplica el líquido a la hiedra tallovil para que emerja el vástago tóxico. Cura 8 plantas eliminando su vástago tóxico e informa a Talendria en Punta de Nijel.", desc = "Un sátiro llamado Lenguavil ha corrompido las cavernas de Maraudon y ha detenido el desarrollo de muchas de las plantas.\n\nToma este vial, <nombre>. Llénalo en el estanque naranja corrupto de las cavernas; el relleno del vial contrarrestará las toxinas y las transformará en agentes sanadores.\n\nEsparce el líquido purificado en la hiedra Tallovil de las cavernas naranja. Aunque se eliminará la corrupción de la planta, debes saber que seguirá bajo el control de Lenguavil. Puede que intente atacarte...", objectives = { "Has curado la hiedra Tallovil x 8", "Vial cerúlea llena" } },
    [7044] = { title = "Leyendas de Maraudón", summary = "Recupera las 2 partes del Cetro de Celebras: la vara y el diamante Celebrian. Encuentra el modo de hablar con Celebras.", desc = "Un siniestro sátiro llamado Lord Lenguavil extiende su maldad por estas cuevas, envenenando las mentes. Sigue viviendo detrás de los cristales púrpura.\n\nTambién creó un símbolo viviente de su corrupción llamado Noxxion, que vive tras los cristales naranja. Han robado las dos piezas del cetro de mi hermano. Celebras, mi hermano, ha caído víctima de la corrupción y deambula ahí dentro.\n\n¡Tienes que ayudarlo! Busca las piezas y encuentra el modo de hablar con mi hermano.", objectives = { "Diamante de Celebras", "Vara de Celebras" } },
    [7046] = { title = "El Cetro de Celebras", summary = "Ayuda a Celebras el Redimido mientras reconstruye el Cetro de Celebras. Habla con él después del ritual.", desc = "Antes, mi cetro era una fuente de esperanza para mí. Su poder me permítía desplazarme rápidamente por estas cavernas. Quería dar paz al espíritu de mi tío... Te paso a ti esa tarea.\n\nNecesito que me ayudes en el ritual para unir las dos piezas. Sigue mis instrucciones mientras canalizo la energía necesaria para unir la vara y el diamante.\n\n¡Reconstruyamos el cetro de Celebras!", objectives = { "Crea el Cetro de Celebras" } },
    [7064] = { title = "Corrupción de la tierra y de la semilla", summary = "Mata a la princesa Theradras y ve a ver a Selendra cerca de la Aldea Cazasombras, en Desolace.", desc = "En las profundidades de Maraudon vive una criatura de gran maldad. La princesa Theradras es una fuerza elemental de la tierra relacionada con los dioses antiguos. Hace eones se unió a Zaetar, el primogénito de Cenarius. El fruto de su relación fueron las criaturas llamadas centauros en Kalimdor. Esas criaturas mataron a Zaetar y se quedaron sus restos. Mi objetivo es encontrar a quien tenga fuerza suficiente para matar a Theradras y recuperar los restos de Zaetar antes de volver a Cima del Espolón.", objectives = { "Princesa Theradras" } },
    [7065] = { title = "Corrupción de la tierra y de la semilla", summary = "Mata a la princesa Theradras y ve a ver al guardián Marandis a Punta de Nijel, en Desolace.", desc = "En las profundidades de Maraudon vive una criatura de gran maldad, <nombre>. La princesa Theradras es una fuerza elemental de la tierra relacionada con los dioses antiguos. Hace eones se unió a Zaetar, el primogénito de Cenarius. El fruto de su relación fueron las criaturas llamadas centauros. Esas criaturas mataron a Zaetar y Theradras guardó sus restos. Mi objetivo es encontrar a quien tenga fuerza suficiente para matar a Theradras y recuperar los restos de Zaetar antes de volver a Cima del Espolón.", objectives = { "Princesa Theradras" } },
    [7066] = { title = "La semilla de la vida", summary = "Busca a Remulos en Claro de la Luna y dale la semilla de la vida.", desc = "Mis hijos e hijas, los desdichados centauros, necesitan a su padre.\n\nMira: este lugar está lleno de esperanza y todas las cosas que venera mi padre, Cenarius. ¡Todo eso salió de mí! Y ahora no voy a quitárselo, ni siquiera por el crimen que cometieron contra mí.\n\nPero voy a pedirte un favor para tranquilizar a mi hermano. Toma; es la primera semilla que nació de la vida alimentada por mis restos. Dile que mi espíritu está aquí y que seguiré viviendo. Lo entenderá." },
    [7067] = { title = "Las instrucciones del Paria", summary = "Lee las instrucciones del Paria. Busca el Amuleto de Unidad en Maraudon y llévaselo al sur de Desolace.", desc = "Aunque me exiliaron por hereje, sé que digo la verdad y eso me anima a seguir adelante. Pero para completar mi destino, necesito la ayuda de alguien que no sea centauro.\n\nHay que entrar en las salas sagradas de Maraudon; mi gente protege la tumba y solo los más devotos pueden entrar.\n\nSi aceptas ayudarme, afirma con la cabeza. Te daré un pergamino con instrucciones. Léelo y considera mi propuesta.", objectives = { "Amuleto de Unidad", "Amuleto de los espíritus" } },
    [7068] = { title = "Fragmentos Oscuros", summary = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos a Uthel'nay a Orgrimmar.", desc = "En Maraudon, el lugar sagrado de los centauros, se concentra una magia muy fuerte. Los centauros de Desolace protegen el lugar con su vida, pero no podrán impedir que cojamos lo que necesitemos.\n\nVe a Maraudon y encuentra a las criaturas de piedra hechas de fragmentos oscuros. Trae los cristales y Uthel'nay te compensará.\n\nEs un sitio peligroso, mejor llévate compañía.", objectives = { "Trozo de fragmento oscuro x 10" } },
    [7070] = { title = "Fragmentos Oscuros", summary = "Recoge 10 fragmentos oscuros en Maraudon y llévaselos al archimago Tervosh a Theramore, en la costa de Marjal Revolcafango.", desc = "He empezado a hacer pruebas con las propiedades arcanas de varios cristales. Lady Valiente me ha autorizado a pedir a los viajeros que se dirigen a Desolace que busquen un lugar llamado Maraudon. En el templo en ruinas hay grandes elementales compuestos por unas piedras moradas que llamo fragmentos oscuros.\n\nTe agradecería que te acercaras e intentaras encontrarme algún cristal. Incluso podría fabricarte un adorno con ellos, si quieres.", objectives = { "Trozo de fragmento oscuro x 10" } },
    [7201] = { title = "El último elemento", summary = "Viaja a las Profundidades de Roca Negra y recupera 10 esencias de los elementos. Tu primer impulso es buscar los golems y a los creadores de golems. Recuerdas que Vivian Latumba también murmuró entre dientes algo sobre los elementales.", desc = "Hay trabajo a mansalva para quien se aventure en las profundidades, <nombre>.\n\nLos Hierro Negro han perfeccionado la creación de golems extremadamente poderosos.\n\nLos primeros informes de nuestros espías indican que los enanos usan una fuente de poder única para conferir a sus creaciones una potencia destructora sin igual.\n\n¡Tan solo imagínate lo que podríamos hacer con nuestras abominaciones si nos hiciéramos con esta esencia de los elementos! No dejes piedra por remover en esa ciudad si es necesario, ¡pero no vuelvas hasta haber encontrado la esencia! Recibirás un justo pago por el riesgo.", objectives = { "Esencia de los elementos x 10" } },
    [7441] = { title = "Pusillín y el ancestro Azj'Tordin", summary = "Viaja a La Masacre y encuentra al diablillo Pusillín. Convence a Pusillín de que te dé el libro de conjuros de Azj'Tordin, por cualquier medio. Si consigues hacerte con el libro de conjuros, vuelve al Pabellón Lariss de Feralas y busca a Azj'Tordin.", desc = "Bajé la guardia un solo momento... Intentaba escapar de las garras del príncipe caído y, en la confusión... me robaron. Un ser abominable, el diablillo Pusillín, me robó el libro de conjuros y la llave de las antaño magníficas salas de Eldre'Thalas.\n\nLa llave ya no me preocupa, pues ya cambié mi inmortalidad por la libertad, pero necesito desesperadamente mi libro de conjuros.\n\nEncuentra a ese diablillo Pusillín y recupera mi libro.\n\nEmpieza a buscarlo en el Barrio Alabeo de La Masacre.", objectives = { "Libro sobre Conjuros" } },
    [7461] = { title = "Locura interior", summary = "Debes destruir a los guardianes que rodean las 5 torres que controlan la Prisión de Immol'thar. Una vez desactivadas las torres, el campo de fuerza que rodea a Immol'thar se disipará. Entra en la Prisión de Immol'thar y erradica al demonio que hace guardia en su interior. Por último, haz frente al príncipe Tortheldrin en El Athenaeum. Si consigues completar esta misión, ve al patio a buscar al Anciano Shen'dralar.", desc = "¿Has oído suficiente? ¿Eres <un hombre/una mujer> de acción?\n\nEsta locura debe acabar. El tiempo de los inmortales expiró hace mucho tiempo. Destruye a los guardianes que rodean las torres para debilitar el campo de fuerza. Una vez hecho eso, destruye a Immol'thar. Cuando el poder del Príncipe esté muy mermado, ataca y acaba con él. Deja que el espíritu de la ciudad descanse.", objectives = { "Immol'thar", "Príncipe Tortheldrin" } },
    [7463] = { title = "El refresco arcano", summary = "Viaja al Barrio Alabeo de La Masacre y mata al elemental de agua, Hidromilecio. Lleva la esencia de Hidromilecio al guardián del Conocimiento Lydros que está en El Athenaeum.", desc = "¡Vaya! Esto es increíble. No he visto a nadie de tu raza en... ¿cuánto? ¡500 años!\n\nTengo algo que saciará tu sed, pero primero tienes que hacer algo por mí.\n\n<Lydros se ríe.>\n\nHay una anomalía en Eldre'Thalas. Un elemental de agua se ha instalado en el ala este. ¡Hay que catalogar su presencia!\n\nVe al Barrio Alabeo y extrae una porción de esencia del elemental del Hidromilecio. Devuélvemelo y te enseñaré un conjuro útil.", objectives = { "Esencia de Hidromilecio" } },
    [7481] = { title = "Leyendas élficas", summary = "Busca a Kariel Winthalus en La Masacre. Vuelve al Campamento Mojache e informa al Sabio Korolusk de cualquier cosa que encuentres.", desc = "Hace muchos años, un solitario maestro elfo llamado Kariel Winthalus huyó de la devastación de su tierra con su remolque lleno de antiguos artefactos élficos.\n\nSeguimos su rastro desde las ruinas de Quel'Thalas hasta Feralas, a través de Las Estepas Ardientes y del ancho mar.\n\nSospechamos que buscó refugio en las salas de Eldre'Thalas (que ahora se conocen como La Masacre).\n\nDebes encontrarlo. Esté vivo o muerto, es necesario recuperar los conocimientos que llevaba consigo.", objectives = { "El maestro Kariel Winthalus ha sido encontrado" } },
    [7482] = { title = "Leyendas élficas", summary = "Busca a Kariel Winthalus en La Masacre. Vuelve al Bastión Plumaluna a informar al erudito Runaespina de lo que hayas encontrado.", desc = "Hace varios años, un solitario maestro elfo llamado Kariel Winthalus huyó de la devastación de su tierra con su remolque lleno de antiguos artefactos élficos.\n\nSeguimos su rastro desde las ruinas de Quel'Thalas hasta Feralas, a través de Las Estepas Ardientes y del ancho mar.\n\nSospechamos que buscó refugio en las salas de Eldre'Thalas (que ahora se conocen como La Masacre).\n\nDebes encontrarlo. Esté vivo o muerto, es necesario recuperar los conocimientos que llevaba consigo.", objectives = { "El maestro Kariel Winthalus ha sido encontrado" } },
    [7488] = { title = "La Membrana de Lethtendris", summary = "Lleva la Membrana de Lethtendris a Latronicus Lanzaluna al Bastión Plumaluna de Feralas.", desc = "La maga Lethtendris, una despiadada elfa sanguinaria cuya brutalidad solo es comparable a su adicción a la magia, se ha refugiado en La Masacre. Ha creado un dispositivo, una red que atrapa la energía mágica de ese lugar y tememos que, si no intervenimos, causará daños irreparables a nuestro mundo.\n\nDetenla, <nombre>. Encuéntrala y arrebátale la red. Probablemente la encontrarás cerca de los sátiros del Barrio Alabeo, en La Masacre. Tráeme la red para que pueda liberar su poder y devolverlo con seguridad a su lugar...", objectives = { "Tela de araña de Lethtendris" } },
    [7489] = { title = "La Membrana de Lethtendris", summary = "Lleva la Membrana de Lethtendris a Talo Pezuñahendida al Campamento Mojache de Feralas.", desc = "Lethtendris, la elfa sanguinaria, ha superado sus límites. Tan ansiosa estaba de acumular poder, que desafió a sus hermanos y creó un instrumento de insidioso diseño... una red destinada a recoger las impías energías mágicas de La Masacre. En este momento sigue reuniendo esas energías y planea lanzarlas contra sus enemigos.\n\nLethtendris ha de ser detenida. Encuéntrala. Estará en el Barrio Alabeo de La Masacre. Derrótala y tráeme su red para que pueda entregarla a elfos sanguinarios más cuerdos para que la estudien.", objectives = { "Tela de araña de Lethtendris" } },
    [7492] = { title = "Campamento Mojache", summary = "Ve al Campamento Mojache de Feralas y habla con Talo Pezuñahendida.", desc = "Talo Thornhoof, un ancestro Tauren de Feralas, envía una petición de ayuda. Dio pocos detalles, pero sí dijo que necesita agentes para un asunto tan delicado como... grave.\n\nSirve a la Horda, <nombre>. Ve al Campamento Mojache de Feralas y habla con Talo." },
    [7494] = { title = "Bastión Plumaluna", summary = "Habla con Latronicus Lanzaluna. Lo encontrarás en el Bastión Plumaluna de Feralas.", desc = "¡<nombre>! ¡Necesitan tu ayuda en Feralas!\n\nUna maga proscrita, Lethtendris, ha huido a las antiguas ruinas élficas de Eldre'Thalas que ahora se conocen como La Masacre. Se cree que lleva consigo un peligroso objeto de gran energía mágica. Debemos recuperarlo.\n\nLatronicus Moonspear solicita agentes para entrar en La Masacre y arrebatar el objeto a Lethtendris.\n\n¡Sirve a la Alianza! Busca a Latronicus en el Bastión Plumaluna de Feralas." },
    [7507] = { title = "Compendio de Foror", summary = "Devuelve el Compendium of Dragon Slaying de Foror a El Athenaeum.", desc = "Has descubierto algo de gran importancia. Este libro no se parece a nada que hayas visto antes.\n\nParece que alguien o algo ha logrado romper el sello de El Athenaeum. El texto es confuso, apenas se puede leer." },
    [7668] = { title = "La amenaza de Atracoscuro", summary = "Usa el augurador que se encuentra en el corazón del sótano de El Gran Osario en Scholomance. Al hacerlo se presentarán los espíritus a los que tienes que enfrentarte. La derrota de estos espíritus invoca al Caballero de la Muerte Atracoscuro, derrótalo. Llévale la cabeza de Atracoscuro a Sagorne Montacresta en el Valle de la Sabiduría, en Orgrimmar.", desc = "El Caballero de la Muerte Atracoscuro campa por sus respectos en El Gran Osario de Scholomance. Amenaza con pervertir el reino del espíritu para hacer lo que se le antoje, ¡hay que detenerlo! Aquí es donde entra en juego el augurador que ayudaste a confeccionar.\n\nUsa el augurador en el corazón de El Gran Osario para convocar a los esbirros del espíritu de Atracoscuro. Derrota a los espíritus y aparecerá el mismísimo Caballero de la Muerte. <nombre>, ¡tráeme su cabeza! ¡Solo su derrota revocará el daño causado al reino del espíritu!", objectives = { "Cabeza de Atracoscuro" } },
    [7703] = { title = "El aunto inacabado de Gordok", summary = "Encuentra el Guante del Poder de Gordok y llévaselo al capitán Kromcrush a La Masacre. Según Kromcrush, una \"historia muy, muy vieja\" dice que Tortheldrin, un elfo \"asqueroso\" que se llamaba a sí mismo príncipe, robó el guantelete a uno de los reyes de Gordok.", desc = "Ahora tú eres Rey… ¡pues igual recuperar artefacto Gordok de asqueroso elfo, él ir de \"Príncipe\"! El rey anterior fracasó, como el resto de reyes desde Tortheldrin, ese asqueroso elfo. ¡Él robar al rey Gordok el artefacto!\n\nArtefacto llamarse Guante del Poder de Gordok. Historias muy, muy viejas decir solo rey verdadero de Gordok puede recuperarlo. Historia muy, muy vieja también dice asqueroso elfo aún estar cerca. Tú encontrar, ¡tú llevar poderoso guante siempre jamás! ¡Ea, yo enseñar tú!", objectives = { "Guante del Poderío de Gordok" } },
    [7761] = { title = "La orden de Puño Negro", summary = "¡Será estúpido ese orco! Al parecer, tienes que encontrar esta señal y ganar la marca de Drakkisath para poder acceder al orbe de orden. Según la carta, el general Drakkisath guarda la señal. Quizás deberías investigarlo.", desc = "¡Imbécil!\n\nTengo muy poca fe en tu capacidad para impedir que los extraños se infiltren en la guarida del maestro. En el muy probable caso de que mueras, este orbe tiene su propio sistema integrado a prueba de fallos para impedir que ningún desconocido se teletransporte directamente a Alanegra.\n\nSolo aquellos con la marca de Drakkisath en la mano pueden usar este orbe. Por suerte, Drakkisath es mucho más competente que tú, intendente. ¡Él mismo guarda la marca!\n\n-Jefe de Guerra Rend Puño Negro\n\nP.S. Destruye esta carta, idiota." },
    [7848] = { title = "Armonización con el Núcleo", summary = "Entra en el Núcleo de Magma de las Profundidades de Roca Negra y recoge un fragmento de núcleo. LLévaselo a Lothos Levantagrietas a la Montaña Roca Negra.", desc = "Se abren y cierran grietas por todas partes, <raza>. A dos pasos de aquí hay una grieta que va a las profundidades de la montaña Roca Negra, a las fauces mismas del Señor del Fuego.\n\n¿Te sorprende? Lástima... Las razas mortales no pueden comprender lo que no pueden tocar, ver o sentir.\n\nPero el portal está aquí y el acceso es posible.\n\n¿He despertado tu curiosidad? La Armonización es muy sencilla. Aventúrate en las Profundidades de Roca Negra y consigue un fragmento del núcleo. Tráemelo y armonizaré tu esencia con el portal.", objectives = { "Fragmento del Núcleo" } },
    [8905] = { title = "Una propuesta seria", summary = "Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de brazales Corazón Salvaje a Deliana a Forjaz.", desc = "Saludos, <clase>. Tengo algo que puede interesarte.\n\nDispongo de una armadura muy parecida a las que se usan en tu profesión, pero de mucha mejor calidad. Te cambiaré los brazales por otros normales a cambio de un favor.\n\nLa sangre de los osos y Sable de Hielo de Cuna de Hielo tiene propiedades que necesito. Tráeme un frasco grande de sangre, los brazales y un poco de oro. Tus esfuerzos se verán recompensados.", objectives = { "Muestra de sangre de Cuna del Invierno x 15", "Brazales Corazón salvaje" } },
    [8921] = { title = "El destilador ectoplásmico", summary = "Vuelve a ver a Mux Montamaná a Gadgetzan cuando tengas 1 convertidor de arcanita fino, 4 esencias eternas superiores, 10 aceites de Escama Tormentosa, 25 cenizas volcánicas y 40 piezas de oro.", desc = "¡Ah! Necesitas mi última creación... ¡el detector de fantasmas extradimensional! Lamentablemente, no tengo ni el dinero ni el personal necesarios.\n\n¿Te apetece echarme una mano? ¡Excelente! Nuestra primera tarea consiste en fabricar un dispositivo capaz de atrapar a la propia muerte. Construir un destilador ectoplásmico no será tarea fácil, <nombre>.\n\nNecesito que me traigas un convertidor de arcanita, algunas esencias eternas superiores y aceite de Escama Tormentosa. También necesitaré cenizas volcánicas de los charcos de lava que se encuentran en Las Estepas Ardientes para fabricar un filtro.", objectives = { "Conversor de arcanita delicado", "Esencia eterna superior x 4", "Aceite de Escama Tormentosa x 10", "Ceniza volcánica x 25" } },
    [8922] = { title = "Un artefacto sobrenatural", summary = "Lleva el frasco sellado de sangre a Mux Montamaná a Gadgetzan, en Tanaris.", desc = "Quiero hablar con Anthion Harmon, o mejor dicho, con su fantasma.\n\nHe oído hablar de un ingeniero que tiene un interés inusitado por lo sobrenatural. ¡Asegura ser capaz de construir una máquina con la que comunicarse con los muertos!\n\nEsta sangre es para él; llévasela a Gadgetzan en pago por sus servicios." },
    [8924] = { title = "Caza de ectoplasmas", summary = "Utiliza el destilador ectoplásmico cerca de los no-muertos incorpóreos y consigue 12 ectoplasmas abrasados en Silithus, 12 ectoplasmas helados en Cuna del Invierno y 12 ectoplasmas sólidos en las Tierras de la Peste del Este. Llévaselos, junto con el destilador ectoplásmico, a Mux Montamaná a Gadgetzan.", desc = "¡Es una obra maestra de ingeniería, modestia aparte! Me temo que tendrás que viajar un poco para encontrar a los no-muertos incorpóreos que necesitamos.\n\nSabes, los distintos climas proporcionan consistencias diferentes a los tejidos espectrales de los muertos. Los torturados elfos de la noche de Silithus, los espíritus de los altonatos de Cuna del Invierno y los fantasmas y almas en pena de las Tierras de la Peste del Este deberían proporcionarnos los diferentes tipos de ectoplasma que necesitamos. ¡Asegúrate de situar el destilador cerca de ellos para poder cazarlos!", objectives = { "Ectoplasma abrasado x 12", "Ectoplasma congelado x 12", "Ectoplasma de establo x 12" } },
    [8925] = { title = "Fuente de energía portátil", summary = "Encuentra al Señor del Magma Bokk en Las Estepas Ardientes, consigue el núcleo de lava y llévaselo a Mux Montamaná a Gadgetzan.", desc = "A continuación, tendremos que encontrar una fuente de energía constante pero fácil de manejar para mantener activo el ectoplasma. He oído hablar de un poderoso elemento llamado Señor de Magma Bokk cuyo corazón es un poderoso núcleo de lava o, lo que es lo mismo, ¡una fuente inagotable de calor!\n\nSe dice que se le puede encontrar en Las Estepas Ardientes, al sur de la Montaña Roca Negra. ¡Tráeme el núcleo de lava y quizás así tengamos combustible suficiente para alimentar el detector de fantasmas extradimensional!", objectives = { "Núcleo de magma" } },
    [8926] = { title = "Una compensación justa", summary = "Lleva 1 cinturón y 1 par de guantes Corazón Salvaje a Deliana a Forjaz.", desc = "Has cumplido tu palabra y me has traído el instrumento que Mux construyó. Debo recompensarte, pues me interesa que sigas protegiéndome. Tráeme el cinturón y los guantes que quieres mejorar. Te prometo que a cambio te daré unos mucho mejores.", objectives = { "Cinturón Corazón salvaje", "Guantes Corazón salvaje" } },
    [8928] = { title = "Un mercader sospechoso", summary = "Busca a un diablillo dentro de una cueva situada a la entrada de la Garganta Negro Rumor en la zona sur de Cuna del Invierno, compra una biela de inferi elemental y vuelve a ver a Mux Montamaná a Gadgetzan.", desc = "El núcleo nos proporcionará el combustible necesario para alimentar nuestro dispositivo. Ahora solo nos falta construir una biela que canalice toda esa energía sin derretirse.\n\nYo conocí a un pillastre en Cuna del Invierno que vendía todo tipo de mercancías exóticas. De hecho, tenía una biela que nos vendría de perlas. ¡Cómo me arrepiento de no haberla comprado!\n\nVive en una cueva a la entrada de la Garganta Negro Rumor. Ve allí e intenta encontrarlo.\n\n¡Y que no te cobre más de 40 piezas de oro, que es el precio que me había dicho a mí!", objectives = { "Biela de inferi elemental" } },
    [8929] = { title = "Buscando a Anthion", summary = "Usa el detector de fantasmas extradimensional en la entrada de Stratholme y habla con el fantasma de Anthion Harmon.", desc = "Bueno, solo nos queda probar el invento del goblin. Se dice que Anthion fue acribillado por las legiones de los no-muertos de Stratholme cuando intentaba cruzar sus puertas.\n\nUtiliza este instrumento para averiguar qué sabía Anthion." },
    [8945] = { title = "La súplica de un muerto", summary = "Ve a Stratholme y rescata a Ysida Harmon del Barón Osahendido.", desc = "Te daré la información que pides, <nombre>. Pero tenemos asuntos más importantes que resolver.\n\nLa escoria no-muerta de Osahendido ha cogido prisionera a mi querida esposa.\n\nMe negué rotundamente a que se uniera a la estúpida cruzada de Alba Argenta, aunque eso ya no importa. Debes conseguir lo que yo he intentado hacer, tienes que rescatar a Ysida de las garras del Barón.", objectives = { "Ysida liberada" } },
    [8977] = { title = "Vuelve con Deliana", summary = "Lleva el detector de fantasmas extra dimensional a Deliana a Forjaz.", desc = "Me ha gustado trabajar contigo, <nombre>. Aquí tienes el producto acabado.\n\nEspero que te ayude en tu misión Y si no te importa, hazme un poco de publicidad. ¡Me iría bien aumentar la clientela!" },
    [92401] = { title = "Una petición aterradora", summary = "Investiga la desaparición de Edward Tejecorazón en las Ruinas de Lordaeron.", desc = "Mi marido, Edward...\n\nNo ha regresado de su viaje semanal al cementerio de las ruinas de Lordaeron. Nuestro hijo falleció cuando Arthas arrasó la ciudad, y a mi querido Edward todavía lo consumen la culpa y la pena de no haber encontrado su cuerpo. He intentado advertirle que no vaya por esas ruinas infestadas, pero se niega a rendirse. Intento no preocuparme, pero han pasado días.\n\nAllí hay cosas a las que no puedo enfrentarme. Si quieres hacerte cargo, me gustaría saber qué ha sido de mi marido.", objectives = { "Investiga la desaparición de Edward Tejecorazón en las Ruinas de Lordaeron." } },
    [92415] = { title = "[Remember That I Love You]", summary = "[Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City.]", desc = "[<A torn and stained bundle of parchment has barely survived the undead trodden grounds of the graveyard. It mentions a missing child of the Heartweaver family. Perhaps the orphan matron in Stormwind City will know more.>]" },
    [92421] = { title = "Justicia de la Luz", summary = "Consigue 25 extremidades intactas en las Ruinas de Lordaeron y llévaselas a Morbin Penívea en Entrañas.", desc = "Como paladín de los Renegados, mi deber es cumplir con la voluntad de la Dama Oscura y atender a las necesidades de nuestra gente. Tenemos una oportunidad de oro para lograr ambas cosas.\n\nLa Plaga campa a sus anchas sobre Entrañas, y nuestras fuerzas están cada vez más mermadas intentando recuperar lo que nos pertenece. La piel putrefacta no se puede volver a coser, necesitas injertos.\n\nSi nuestro glorioso capitán Garek Bandarion siguiera entre nosotros, tengo muy claro cuál sería su deseo: terminar lo que empezamos y curar a nuestra especie. ¡Por Lordaeron!", objectives = { "Extremidades intactas x 25" } },
    [92422] = { title = "La cólera de Rath'mael", summary = "Mata a Rath'mael en las Ruinas de Lordaeron por encargo del guardia de la Muerte Kristof, que espera en Rémol.", desc = "Nos llegan informes del Mirador de Lordamere, un lugar en lo más profundo de las Ruinas de Lordaeron. Una niebla profana se ha asentado en las calles y en el cementerio, cosa que permite que los miembros de la Plaga del lugar puedan moverse con cierto grado de sigilo.\n\nNuestros exploradores confirman que la ha invocado el nuevo líder de esa canalla, el nigromante conocido como Rath'mael. No podemos permitirnos el lujo de esperar a que esto se resuelva por sí solo, <nombre>.\n\nSi tienes aliados, reúnelos y ayudad a los Renegados. Hay que expulsar a esta criatura de nuestras tierras.", objectives = { "Rath'mael" } },
    [92742] = { title = "Probar los pozos", summary = "Usa el equipo de muestras de agua de pozo para conseguir muestras de los pozos de la Finca de Jansen y la Granja de Molsen.", desc = "Debemos determinar el origen y la naturaleza del veneno que corrompe estas tierras. Comencemos con el agua subterránea de las granjas de la zona.\nVe a la Finca de Jansen y la Granja de Molsen y consigue muestras de los pozos.", objectives = { "Muestra de agua de la Finca de Jansen", "Muestra de agua de la Granja de Molsen" } },
    [92744] = { title = "Branquias de múrloc", summary = "Alba Lunajusta quiere que consigas 7 branquias de múrloc de Playa Larga por la cosa de los Páramos de Poniente.", desc = "La corrupción que afecta a los cultivos de los Páramos de Poniente puede haberse filtrado al océano. Si los peces locales terminan afectados también, condenarían a Ventormenta a la hambruna.\nConsigue branquias de los múrlocs de la costa y tráemelas. Estas criaturas son bastante resistentes, pero su fisiología es especialmente sensible a los contaminantes. Sus branquias estarán infectadas de cualquier toxina que haya en el agua del mar.", objectives = { "Branquia de múrloc de Playa Larga x 7" } },
    [92745] = { title = "[The State of the Mines]", summary = "[Slay 4 Kobold Diggers in the Jangolode Mine and 6 Riverpaw Miners in the Gold Coast Quarry.]", desc = "[The well samples you collected contain toxic metals! If we do not put an end to this corruption quickly, it will be decades before crops can grow in this soil again.\nThe Defias have seized the mines of Westfall and use creatures as labor to strip their resources. Disrupt them by slaying their miners in the Jangolode Mine to the north, and the Gold Coast Quarry to the west.]", objectives = { "Cavador kóbold x 4", "Minero Zarparrío x 6" } },
    [92747] = { title = "[Moonbrook Espionage]", summary = "[Collect 8 Suspicious Industrial Supplies from Moonbrook.]", desc = "[Strange - the poison does not seem to originate from the mines you investigated.\n\nI am told the Deadmines under the town of Moonbrook are the largest, deepest mines of Westfall, but they have been abandoned since the First War. Could the Deadmines be active again?\n\nPlease travel to Moonbrook, <nombre>, and look for evidence of mining or industrial activity. This is the last lead we have!]", objectives = { "Suministros industriales sospechosos x 8" } },
    [92748] = { title = "[Explosive Consultation]", summary = "[Travel to the Dwarven District in Stormwind and find an engineer who can help.]", desc = "[The supplies you found point to a massive industrial operation somewhere in the Deadmines. There's no question that this is the source of the toxins plaguing the farmland of Westfall. We need to stop it, quickly.\n\nWhatever's down there will be difficult to destroy. Go to the Dwarven District of Stormwind, and find an engineer who can supply us with some explosives.]" },
    [92749] = { title = "[A Dynamite Plan]", summary = "[Obtain 10 Coarse Dynamite from crafting, trading, or the auction house, then return to Sprite Jumpsprocket in the Dwarven District of Stormwind.]", desc = "[Industrial sabotage? You've got my attention!\nWe'll start with some dynamite...]", objectives = { "Dinamita burda x 10" } },
    [92750] = { title = "[Detonation at a Distance]", summary = "[Talk to someone in Stormwind Intelligence about acquiring a remote detonator.]", desc = "[I assume you want a \"controlled\" explosion? Not as much fun, but a good choice if you want to keep all your limbs.\nI'm afraid I don't have a remote detonator - why don't you go check with the sneaky folks down at Stormwind Intelligence? They should be able to find us something.]" },
    [92751] = { title = "[Detonation at a Distance]", summary = "[Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind.]", desc = "[You need something destroyed? Would this have anything to do with your activities in Moonbrook? Don't look surprised. SI:7 stays apprised of all that goes on in Stormwind's lands.\nIf you're planning to set off an explosion in the caves below Westfall, you'll want to be well outside beforehand. Take this remote detonator - it's a recent prototype from our own engineers.\nOh - and it would be best if you didn't mention my involvement to your elf friend.]" },
    [92752] = { title = "[Explosive Consultation]", summary = "[Return to Alba Fairmoon in Westfall.]", desc = "[That's it - the bomb's ready to go! Careful with that detonator, now.]" },
    [92753] = { title = "[Destruction in Deadmines]", summary = "[Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit.]", desc = "[The source of the poison is likely a large metallurgical forge of some kind. Find a way into the Deadmines and locate the forge, then place the explosives.\nI will wait for you in the hills behind Moonbrook. Once you return, we can detonate the explosives. Hopefully with the forge gone, the land can begin to heal.]", objectives = { "[Explosives placed]" } },
    [92819] = { title = "[Destruction in Deadmines]", summary = "[Use the detonator.]", desc = "[We are almost finished. Use the detonator, and end this.]", objectives = { "[Detonator used]" } },
    [95189] = { title = "[Crest of Lordaeron]", summary = "[Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City.]", desc = "[<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in Stormwind would be very keen to get their hands on this.>]" },
    [95195] = { title = "[Bloodied Insignia]", summary = "[Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City.]", desc = "[<The old Alliance insignia appears to have belonged to a soldier of Lordaeron. These ruins are likely filled with similar medals that living relatives would be grateful to have returned to them.>]" },
    [95204] = { title = "[Crest of Lordaeron]", summary = "[Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity.]", desc = "[<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in the Undercity would be very keen to get their hands on this.>]" },
    [95216] = { title = "La nueva peste", summary = "Consigue la cepa muy tóxica de Colmimarchito en las Ruinas de Lordaeron y llévasela a Theodore Griffs en Entrañas.", desc = "<Bienvenido/Bienvenida> al corazón de Entrañas: ¡El Apothecarium! Aquí estudiamos a los especímenes más exóticos y virulentos de Azeroth.\n\nMe pillas de buen humor, así que te voy a conceder el honor de participar en mi última investigación. Cuentan que un artrópodo venenoso muy especial merodea por las ruinas de nuestra hermosa ciudad, y parece que sus toxinas consumen incluso la piel de los no-muertos. Qué pasada, ¿verdad?\n\nNecesito verificar esa información. Me encantaría que me trajeras una muestra, aunque procura que no te muerda.", objectives = { "Cepa muy tóxica" } },
    [95250] = { title = "[Abominable Creatures]", summary = "[Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman.]", desc = "[What do you want, <raza>? Can't you see there is a war to be won?\n\nMy master has already charged into the fray and has ordered me to maintain my post. It has been quite some time, however.\n\nI doubt you'll survive ten minutes in combat, but if it keeps your simple mind busy, why don't you seek out the Grand Marshal. He is the tallest, most statuesque hero you've ever laid eyes on. You'll know him when you see him.]", objectives = { "Cabeza del barón" } },
    [96391] = { title = "Mapa subterráneo", summary = "Entrega el mapa Hierro Negro al videnterra Farsen en Dun Morogh.", desc = "<El mapa que sostienes parece mostrar una serie de complejos túneles subterráneos y caminos que convergen en un punto bajo la mismísima Forjaz.\n\nNo sabes con seguridad qué dicen las runas, pues están escritas en el idioma de runas rudimentario de los enanos Hierro Negro, pero no es difícil adivinar el propósito de los túneles. Mientras lees el mapa, te sacude una ráfaga de viento que transporta la voz tenue de un enano. El videnterra Farsen tiene que ver esto>." },
    [96393] = { title = "[Old Ironforge Incursion]", summary = "[Enter the Hall of Thanes beneath Old Ironforge and claim the Head of Durgen Dirgehammer.]", desc = "[Gather some allies and head down into the caverns beneath Old Ironforge. Enter the Hall of Thanes there and push to the lower vaults.\n\nMy Dark Iron is a bit rusty, but I can make out a name--one Durgen Dirgehammer. It's likely that he's the commander. Take his head and deliver it to King Magni Bronzebeard.\n\nOh, and when you do, tell him his old friend Farsen sends his regards!]", objectives = { "Cabeza de Durgen Martillo Funesto" } },
    [96394] = { title = "Los muertos sin descanso", summary = "Mata a 15 apariciones iracundas y 10 almas atormentadas, antes de acabar con el espíritu de Yunquemar.", desc = "Algo ha perturbado las tumbas del Salón de los Feudales, y hay quien dice haber oído ruidos extraños procedentes de lo más hondo del mausoleo. Los espíritus de los difuntos tienen el sueño muy ligero, y se conoce que los habrá alterado lo que quiera que se esté removiendo allí abajo.\n\nPonte en camino, a ver qué remedio le ves al asunto. Y, si algún muerto anda deambulando..., ¡se le manda a dormir otra vez!", objectives = { "[Enraged Apparition] x 15", "[Tormented Soul] x 10" } },
    [96395] = { title = "[An Ancient Grudge]", summary = "[Put the spirit of Faldrim Anvilmar to rest in the Hall of Thanes.]", desc = "[The... Thane... my mighty... Thane... he... needs to... rest.\n\nPlease... help him... help him... rest...\n\nConsumed... by... ancient... grudge... No... rest...]", objectives = { "[Faldrim Anvilmar]" } },
    [96403] = { title = "Reliquias importantes", summary = "Recupera 8 reliquias enanas en el Salón de los Feudales.", desc = "Oye, tú... Me vendría muy bien tu ayuda.\n\nEstaba colándome... digo... patrullando por las cámaras cuando surgió de las profundidades un montón de enanos Hierro Negro en máquinas topo. No sé qué harán aquí, pero hay un botín de valor incalculable... esto, mejor dicho... ¡importantes reliquias culturales ahí abajo! Por favor, recupera cualquier reliquia que veas y tráemela.\n\nTe aseguro que todo lo que recuperes se catalogará y se devolverá a su lugar correspondiente.", objectives = { "Reliquia enana x 8" } },
    [97288] = { title = "Tormento interminable", summary = "Entrega la cabeza abominable a alguien de Entrañas.", desc = "<La cabeza de la criatura se desprende mientras cae. Parece que la han vuelto a unir al cuerpo muchas veces, pero la conexión es cada vez más débil.\n\nSeguro que hay alguien en Entrañas que me puede dar más información sobre esta abominación tan extraña>.", objectives = { "Entrega la cabeza abominable a alguien de Entrañas." } },
    [98423] = { title = "[The Treaty of Understanding]", summary = "[Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge.]", desc = "[Inside of the vault you find a tablet detailing the terms of a peace treaty between the Bronzebeard and Wildhammer dwarf clans. It appears to date back to time period just after of the War of the Three Hammers, and is very likely a notable piece of dwarven history. The king of Ironforge would no doubt be interested in this artifact.]" },
  },
}
